_USER_CACHE_TTL = 30  # seconds — bounds how long a role/status change lags
_user_cache = {}      # sub -> (record, ts)
_user_cache_lock = threading.Lock()

# Opaque session lifetime + a tiny lookup cache so a burst of requests on one
# token doesn't hammer the DB. Admin role/status mutations clear this cache so
# changes take effect immediately rather than lagging the TTL.
_SESSION_TTL = 7 * 24 * 3600   # 7 days
_SESSION_CACHE_TTL = 30        # seconds
_session_cache = {}            # token -> (user, ts)
_session_cache_lock = threading.Lock()


def _admin_bootstrap_emails():
    raw = os.environ.get("ADMIN_BOOTSTRAP_EMAILS") or ""
    return {e.strip().lower() for e in raw.split(",") if e.strip()}


def _users_exec(query, params=None, fetch=False):
    """Run a parameterised write/read against the user store (never cached)."""
    pool = _get_pool()
    conn = pool.getconn()
    try:
        conn.autocommit = True
        cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
        # Pass params through as-is (None when absent). Passing an empty tuple
        # instead of None makes psycopg2 attempt %-interpolation, which raises
        # "IndexError: tuple index out of range" on any query containing a
        # literal % (e.g. the IBT late-count SQL) and no bind params.
        cur.execute(query, params)
        rows = [dict(r) for r in cur.fetchall()] if fetch else None
        cur.close()
    except Exception:
        pool.putconn(conn, close=True)
        raise
    else:
        pool.putconn(conn)
    return rows


# Single fixed key for a Postgres transaction-level advisory lock that serializes
# every admin-membership critical section (bootstrap + role/status/delete). This
# turns check-then-write sequences into atomic operations so concurrent requests
# can never both pass a last-admin guard (or both bootstrap a first admin).
_ADMIN_LOCK_KEY = 0x5669766F  # "Vivo"


@contextlib.contextmanager
def _users_tx(lock=False):
    """Run statements atomically against the user store in one transaction.

    When ``lock`` is true, acquire the shared admin advisory lock first so the
    whole critical section is mutually exclusive across requests/threads. The
    advisory lock is transaction-scoped and released automatically on
    commit/rollback. Yields a RealDict cursor; commits on success, rolls back on
    error."""
    pool = _get_pool()
    conn = pool.getconn()
    try:
        conn.autocommit = False
        cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
        if lock:
            cur.execute("SELECT pg_advisory_xact_lock(%s)", (_ADMIN_LOCK_KEY,))
        yield cur
        conn.commit()
        cur.close()
    except Exception:
        try:
            conn.rollback()
            conn.autocommit = True
        except Exception:
            pool.putconn(conn, close=True)
            raise
        pool.putconn(conn)
        raise
    else:
        conn.autocommit = True
        pool.putconn(conn)


def _active_admins_excluding(cur, exclude_user_id=None):
    """Count active admins using an existing transaction cursor (for atomic guards)."""
    if exclude_user_id:
        cur.execute(
            "SELECT COUNT(*) AS n FROM app_users WHERE role='admin' AND status='active' AND user_id <> %s",
            (exclude_user_id,))
    else:
        cur.execute(
            "SELECT COUNT(*) AS n FROM app_users WHERE role='admin' AND status='active'")
    row = cur.fetchone()
    return int(row["n"]) if row else 0


def _ensure_users_table():
    _users_exec("""
        CREATE TABLE IF NOT EXISTS app_users (
            user_id       TEXT PRIMARY KEY,
            email         TEXT UNIQUE NOT NULL,
            name          TEXT,
            role          TEXT NOT NULL DEFAULT 'store_manager',
            status        TEXT NOT NULL DEFAULT 'pending',
            auth_method   TEXT DEFAULT 'google',
            created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
            approved_at   TIMESTAMPTZ,
            approved_by   TEXT,
            last_login_at TIMESTAMPTZ
        )
    """)
    # Local email/password accounts store a PBKDF2 hash here; Google-only
    # identities leave it NULL (they authenticate via OAuth, never a password).
    _users_exec("ALTER TABLE app_users ADD COLUMN IF NOT EXISTS password_hash TEXT")
    # Google profile photo URL, captured from the OAuth userinfo `picture` field
    # at sign-in. Nullable: password-only accounts and pre-existing Google users
    # (until their next Google sign-in) leave it NULL and fall back to initials.
    _users_exec("ALTER TABLE app_users ADD COLUMN IF NOT EXISTS picture TEXT")
    # CRM admin flag: grants manager-level access in the standalone CRM UI without
    # elevating to platform admin. Managed via the Users admin panel.
    _users_exec("ALTER TABLE app_users ADD COLUMN IF NOT EXISTS crm_admin BOOLEAN NOT NULL DEFAULT FALSE")
    # The POS location name this store manager is assigned to. Seeded by
    # admins on the Users page; surfaced via /auth/me so the BI frontend
    # can auto-apply the right channel filter when the user first logs in.
    _users_exec("ALTER TABLE app_users ADD COLUMN IF NOT EXISTS pos_location_name TEXT")
    # One-time seed: promote any existing hardcoded CRM_ADMIN_EMAILS entries into
    # the DB flag so the column immediately reflects the intended state.
    try:
        _users_exec(
            "UPDATE app_users SET crm_admin = TRUE "
            "WHERE lower(email) = ANY(%s) AND crm_admin = FALSE",
            ([e.lower() for e in CRM_ADMIN_EMAILS],)
        )
    except Exception:
        pass
    # Opaque server-side sessions. The token is the bearer/cookie value; we never
    # store anything derivable back to a password here.
    _users_exec("""
        CREATE TABLE IF NOT EXISTS user_sessions (
            session_token TEXT PRIMARY KEY,
            user_id       TEXT NOT NULL REFERENCES app_users(user_id) ON DELETE CASCADE,
            created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
            expires_at    TIMESTAMPTZ NOT NULL
        )
    """)
    _users_exec(
        "CREATE INDEX IF NOT EXISTS idx_user_sessions_user_id ON user_sessions(user_id)")
    # Live-presence tracking: the fabric dashboard (and any future surface) pings
    # POST /api/auth/heartbeat on a short interval which stamps last_active_at +
    # the surface (last_active_page). GET /api/auth/active-viewers reads back the
    # distinct users active within a short recency window. Both columns are added
    # idempotently so an existing prod user_sessions table gains them on deploy.
    _users_exec(
        "ALTER TABLE user_sessions ADD COLUMN IF NOT EXISTS last_active_at TIMESTAMPTZ")
    _users_exec(
        "ALTER TABLE user_sessions ADD COLUMN IF NOT EXISTS last_active_page TEXT")
    # Composite index supports the active-viewers scan (recency window per page).
    _users_exec(
        "CREATE INDEX IF NOT EXISTS idx_user_sessions_presence "
        "ON user_sessions(last_active_page, last_active_at)")
    # Reap expired sessions on boot so the table cannot grow unbounded.
    try:
        _users_exec("DELETE FROM user_sessions WHERE expires_at <= now()")
    except Exception:
        pass


def _resolve_app_user_db(sub, email, name, picture=None):
    rows = _users_exec(
        "SELECT user_id, email, name, role, status, crm_admin, pos_location_name FROM app_users WHERE user_id=%s",
        (sub,), fetch=True)
    if rows:
        rec = rows[0]
        # Refresh last-login + keep email/name/picture in sync with the IdP,
        # throttled by the cache TTL (this only runs on a cache miss, ~once per 30s
        # per user). picture COALESCEs so a non-Google resolve never wipes it.
        try:
            _users_exec(
                "UPDATE app_users SET last_login_at=now(), email=%s, "
                "name=COALESCE(NULLIF(%s,''), name), "
                "picture=COALESCE(NULLIF(%s,''), picture) WHERE user_id=%s",
                (email, name or "", picture or "", sub))
        except Exception:
            pass
        return rec
    # No row keyed by this exact identity. An account may already exist for this
    # email under a different identity key — e.g. an admin-created email/password
    # user (user_id "local:…") who now signs in with Google (sub "google:…"), or a
    # returning Google user. Match on the unique email so we recognize the existing
    # account instead of creating a duplicate. (A blind insert would also violate
    # the email UNIQUE constraint and error, since ON CONFLICT only covers user_id.)
    erows = _users_exec(
        "SELECT user_id, email, name, role, status, crm_admin, pos_location_name FROM app_users WHERE email=%s",
        (email,), fetch=True) if email else None
    if erows:
        rec = erows[0]
        try:
            _users_exec(
                "UPDATE app_users SET last_login_at=now(), "
                "name=COALESCE(NULLIF(%s,''), name), "
                "picture=COALESCE(NULLIF(%s,''), picture) WHERE user_id=%s",
                (name or "", picture or "", rec["user_id"]))
        except Exception:
            pass
        return rec
    # First time we've seen this identity — decide whether to bootstrap an admin.
    # The very first user (or anyone in ADMIN_BOOTSTRAP_EMAILS) becomes an active
    # admin so the system is never left with nobody able to approve others. The
    # "is there an admin yet?" check and the insert run inside one advisory-locked
    # transaction so concurrent first logins cannot each elect themselves admin.
    forced_admin = email.lower() in _admin_bootstrap_emails()
    with _users_tx(lock=True) as cur:
        bootstrap = forced_admin or (_active_admins_excluding(cur) == 0)
        # Non-bootstrap Google self-signups (already domain-checked by the
        # caller) are auto-approved into the minimal "employee" role: they can
        # ONLY reach the salary-advance self-service (API fence in
        # clerk_auth_gate). An admin upgrades the group for dashboard access.
        role = "admin" if bootstrap else SELF_SIGNUP_ROLE
        status = "active"
        approver = "system:bootstrap" if bootstrap else "system:auto-employee"
        cur.execute("""
            INSERT INTO app_users (user_id, email, name, role, status, auth_method,
                                   picture, last_login_at, approved_at, approved_by)
            VALUES (%s, %s, %s, %s, %s, 'google', NULLIF(%s,''), now(),
                    CASE WHEN %s='active' THEN now() ELSE NULL END,
                    CASE WHEN %s='active' THEN %s ELSE NULL END)
            ON CONFLICT (user_id) DO UPDATE SET last_login_at=now(),
                    picture=COALESCE(NULLIF(EXCLUDED.picture,''), app_users.picture)
            RETURNING user_id, email, name, role, status
        """, (sub, email, name or "", role, status, picture or "", status, status, approver))
        row = cur.fetchone()
    return dict(row) if row else {
        "user_id": sub, "email": email, "name": name, "role": role, "status": status,
    }


def resolve_app_user(sub, email, name, picture=None):
    """Return the persisted {user_id,email,name,role,status} for a Clerk identity,
    creating the row on first sight. Cached briefly to spare the DB on request
    bursts; admin mutations invalidate the cache for instant effect. A sign-in that
    carries a profile `picture` always hits the DB so the photo is persisted (the
    cache read is skipped) — sign-ins are rare relative to the cache TTL."""
    now = time.time()
    if not picture:
        with _user_cache_lock:
            cached = _user_cache.get(sub)
            if cached and (now - cached[1]) < _USER_CACHE_TTL:
                return cached[0]
    rec = _resolve_app_user_db(sub, email, name, picture)
    with _user_cache_lock:
        _user_cache[sub] = (rec, now)
    return rec


def _invalidate_user_cache(sub=None):
    with _user_cache_lock:
        if sub:
            _user_cache.pop(sub, None)
        else:
            _user_cache.clear()
    # Sessions are keyed by token (not user_id), so a targeted purge isn't cheap;
    # role/status changes are rare, so clear the whole session cache to guarantee
    # the change is reflected on the next request rather than lagging the TTL.
    with _session_cache_lock:
        _session_cache.clear()


# ── Password hashing (PBKDF2-SHA256, stdlib) ──────────────────────────────────
# We deliberately avoid passlib/bcrypt: their wheels fail to build in this env
# (u-root-cmds shadows coreutils). PBKDF2-SHA256 from hashlib is constant-time
# verified via hmac.compare_digest and is a sound password KDF at high iteration.
_PBKDF2_ITERS = 200_000


def _hash_password(password):
    salt = secrets.token_bytes(16)
    dk = hashlib.pbkdf2_hmac("sha256", password.encode("utf-8"), salt, _PBKDF2_ITERS)
    return "pbkdf2_sha256$%d$%s$%s" % (
        _PBKDF2_ITERS,
        base64.b64encode(salt).decode("ascii"),
        base64.b64encode(dk).decode("ascii"),
    )


def _verify_password(password, stored):
    if not stored:
        return False
    try:
        algo, iters, salt_b64, hash_b64 = stored.split("$")
        if algo != "pbkdf2_sha256":
            return False
        salt = base64.b64decode(salt_b64)
        expected = base64.b64decode(hash_b64)
        dk = hashlib.pbkdf2_hmac("sha256", password.encode("utf-8"), salt, int(iters))
        return hmac.compare_digest(dk, expected)
    except Exception:
        return False


# ── Opaque server-side sessions ───────────────────────────────────────────────
def _create_session(user_id):
    token = secrets.token_urlsafe(32)
    _users_exec(
        "INSERT INTO user_sessions (session_token, user_id, expires_at) "
        "VALUES (%s, %s, now() + make_interval(secs => %s))",
        (token, user_id, _SESSION_TTL))
    return token


def _destroy_session(token):
    if not token:
        return
    try:
        _users_exec("DELETE FROM user_sessions WHERE session_token=%s", (token,))
    except Exception:
        pass
    with _session_cache_lock:
        _session_cache.pop(token, None)


def _user_dict(row):
    return {
        "id": row["user_id"], "user_id": row["user_id"],
        "email": row["email"], "name": row["name"],
        "role": row["role"], "status": row["status"],
        "active": row["status"] == "active", "picture": None,
    }


def _user_for_session(token):
    """Resolve an active session token to a user dict (or None). Briefly cached."""
    if not token:
        return None
    now = time.time()
    with _session_cache_lock:
        cached = _session_cache.get(token)
        if cached and (now - cached[1]) < _SESSION_CACHE_TTL:
            return cached[0]
    rows = _users_exec(
        "SELECT u.user_id, u.email, u.name, u.role, u.status "
        "FROM user_sessions s JOIN app_users u ON u.user_id = s.user_id "
        "WHERE s.session_token=%s AND s.expires_at > now()",
        (token,), fetch=True)
    if not rows:
        return None
    # WS9 T901 — sliding expiry: an active user must never be logged out
    # mid-week just because the fixed 7-day window elapsed. Renew whenever a
    # DB validation happens with less than half the TTL remaining (the 60s
    # session cache above keeps this write infrequent). Best-effort.
    try:
        _users_exec(
            "UPDATE user_sessions SET expires_at = now() + make_interval(secs => %s) "
            "WHERE session_token=%s AND expires_at < now() + make_interval(secs => %s)",
            (_SESSION_TTL, token, _SESSION_TTL // 2))
    except Exception:
        pass
    user = _user_dict(rows[0])
    with _session_cache_lock:
        _session_cache[token] = (user, now)
    return user


def _extract_session_token(request):
    auth = request.headers.get("authorization") or ""
    if auth.lower().startswith("bearer "):
        return auth[7:].strip() or None
    return request.cookies.get("session_token")


def _is_iso_date(v):
    try:
        date.fromisoformat(v)
        return True
    except (ValueError, TypeError):
        return False


@app.middleware("http")
async def clerk_auth_gate(request: Request, call_next):
    path = request.url.path
    # Non-API routes (static assets, SPA fallback) are not gated here.
    if not path.startswith("/api"):
        return await call_next(request)
    # CORS preflight bypasses the gate.
    if request.method == "OPTIONS":
        return await call_next(request)

    # Reject any non-ISO date filter before it reaches a query string literal.
    # This SQL-injection guard runs for every /api request regardless of auth.
    for _k in _DATE_QUERY_PARAMS:
        _v = request.query_params.get(_k)
        if _v not in (None, "") and not _is_iso_date(_v):
            return JSONResponse(
                {"detail": f"Invalid {_k}: expected ISO date (YYYY-MM-DD)"},
                status_code=400,
            )

    # Health/proxy probes and the public auth paths (login + Google OAuth flow)
    # are reachable without a session.
    if path in _AUTH_PUBLIC_EXACT or path.startswith("/api/__clerk"):
        return await call_next(request)
    if path in _AUTH_PUBLIC_AUTH_PATHS:
        return await call_next(request)

    # Customer-facing loyalty endpoints carry their OWN member-token auth (a
    # loyalty card session, not a staff session) so members can enrol, check
    # their tier/points and redeem WITHOUT a staff login. They validate the
    # X-Member-Token header internally and fail closed with 401 when missing.
    if path.startswith("/api/loyalty"):
        return await call_next(request)

    # Customer-facing public lookbook share links (no login): a stylist sends a
    # shopper a tokenised lookbook URL; viewing it and registering interest must
    # work without any staff or member session. The handlers validate the
    # opaque share token internally and 404 on an unknown/expired token.
    if path.startswith("/api/public/"):
        return await call_next(request)

    # Dual-auth endpoints: the internal sync loop may trigger these with a valid
    # X-Internal-Token (no staff session), but they are ALSO reachable by an
    # authenticated staff member from the browser. A valid internal token
    # short-circuits; otherwise we fall through to normal session auth + the
    # per-prefix role gate below (so an anonymous or wrong-token browser hit is
    # still refused). The endpoint itself re-checks the token to decide whether
    # to skip the staff-role assertion.
    if path in _AUTH_INTERNAL_OR_SESSION_PATHS:
        _sec = os.environ.get("SESSION_SECRET") or ""
        _tok = request.headers.get("x-internal-token") or ""
        if _sec and _tok and hmac.compare_digest(_tok, _sec):
            return await call_next(request)
        # else: fall through to session-based auth + role gate.

    # Internal sync jobs (no staff session) write a small set of snapshot
    # endpoints, authenticated by the shared SESSION_SECRET via X-Internal-Token
    # with a constant-time compare. Fails closed when the secret is unset/wrong.
    if path in _AUTH_INTERNAL_TOKEN_PATHS:
        _sec = os.environ.get("SESSION_SECRET") or ""
        _tok = request.headers.get("x-internal-token") or ""
        if _sec and hmac.compare_digest(_tok, _sec):
            return await call_next(request)
        return JSONResponse({"detail": "Not authenticated"}, status_code=401)

    # Resolve the session token (Bearer header or httpOnly cookie) to a user.
    # Fail closed: if the user store is unreachable we cannot prove identity, so
    # refuse with a deterministic 503 rather than leaking a generic 500.
    token = _extract_session_token(request)
    try:
        user = _user_for_session(token) if token else None
    except Exception:
        return JSONResponse(
            {"detail": "auth_store_unavailable"}, status_code=503)
    if not user:
        return JSONResponse({"detail": "Not authenticated"}, status_code=401)
    request.state.user = user

    status = user.get("status")
    # Self-service auth paths are reachable by any signed-in user regardless of
    # approval status (so the frontend can read its own status / sign out).
    if path in _AUTH_SELF_PATHS:
        return await call_next(request)

    # Approval gating: distinct refusals so the frontend can route correctly.
    if status == "pending":
        return JSONResponse({"detail": "account_pending_approval"}, status_code=403)
    if status == "rejected":
        return JSONResponse({"detail": "account_rejected"}, status_code=403)
    if status == "disabled":
        return JSONResponse({"detail": "account_disabled"}, status_code=403)
    if status != "active":
        return JSONResponse({"detail": "account_inactive"}, status_code=403)

    # Employee self-service fence: the auto-approved "employee" role exists ONLY
    # to apply for salary advances. Everything except the salary-advance
    # endpoints is refused server-side, so no BI/HR/CRM data is reachable no
    # matter what the client renders. (Auth self-paths — /me, /logout,
    # /heartbeat — already returned above; public auth paths never reach here.)
    if user.get("role") == "employee" and not path.startswith("/api/hr/salary-advances") \
            and not (_is_crm_admin_user(user)
                     and path.startswith(CRM_ADMIN_EMPLOYEE_PREFIXES)):
        return JSONResponse(
            {"detail": "employee_salary_advance_only"}, status_code=403)

    # Admin-only endpoints require the admin role.
    if path.startswith("/api/admin") and user.get("role") != "admin":
        return JSONResponse({"detail": "Admin access required"}, status_code=403)

    # Fabric Data Quality (the missing-kg-per-metre hygiene tool) is admin-only.
    # The rest of Fabric BI stays broadly accessible; gate only this one path so
    # hiding the tab in the dashboard can't be bypassed via direct API.
    if path.startswith("/api/fabric/data-quality") and user.get("role") != "admin":
        return JSONResponse({"detail": "Admin access required"}, status_code=403)

    # Fabric Rolls tracking: viewing the manual roll counts is broadly accessible
    # (like the rest of Fabric BI), but WRITING a roll count is admin-only. Gate
    # the write method server-side so hiding the edit controls in the dashboard
    # cannot be bypassed via a direct API call.
    if path == "/api/fabric/rolls" and request.method not in ("GET", "HEAD", "OPTIONS") \
            and user.get("role") != "admin":
        return JSONResponse({"detail": "Admin access required"}, status_code=403)

    # Fabric Receiving sheets: recording per-roll QUALITY results
    # (POST .../receiving/{id}/quality) is broadly accessible, but EDITING the
    # rolls/quantities of a saved sheet (PUT .../receiving/{id}) is admin-only.
    # Gate the bare PUT-to-a-sheet path server-side so hiding the admin edit
    # controls in the dashboard cannot be bypassed via a direct API call.
    if re.match(r"^/api/fabric/receiving/\d+$", path) \
            and request.method == "PUT":
        from fabric_router import _fabric_full_admin
        if not _fabric_full_admin(user):
            return JSONResponse({"detail": "Admin access required"}, status_code=403)

    # Product Costing (per-style cost sheets): STRICTLY email-allowlisted —
    # every /api/fabric/costing path (read AND write) is limited to the three
    # named emails in fabric_router._FABRIC_COSTING_EMAILS (single source of
    # truth). The dashboard hides the tab for everyone else; this gate is the
    # actual enforcement, so direct API calls are rejected too.
    if path.startswith("/api/fabric/costing"):
        from fabric_router import _fabric_costing_allowed
        if not _fabric_costing_allowed(user):
            return JSONResponse({"detail": "Costing access restricted"},
                                status_code=403)

    # Support-scope overrides: viewing the rule list is broadly accessible (the
    # Support tab surfaces the active rules), but ADDING/REMOVING a rule is
    # admin-only — same server-side pattern as the rolls write gate above.
    if path.startswith("/api/fabric/support-overrides") \
            and request.method not in ("GET", "HEAD", "OPTIONS") \
            and user.get("role") != "admin":
        return JSONResponse({"detail": "Admin access required"}, status_code=403)

    # CRM is a customer-facing surface (customer service / marketing / leadership
    # / admin). Enforce server-side so client-side nav/route hiding can never be
    # bypassed (e.g. direct API or mobile). Specific CRM mutations still apply
    # their own finer-grained checks (e.g. loyalty adjust / config require admin
    # via _crm_is_admin).
    if path.startswith("/api/crm") and user.get("role") not in (
        "customer_service", "marketing", "leadership", "smt", "admin"
    ) and not _is_crm_admin_user(user):
        return JSONResponse({"detail": "CRM access requires a customer service, marketing, leadership or admin role"}, status_code=403)

    # Order Explorer (/api/orders/*) — same audience as CRM: customer service,
    # marketing, leadership, smt, admin, and CRM-admin allowlisted accounts.
    if path.startswith("/api/orders") and user.get("role") not in (
        "customer_service", "marketing", "leadership", "smt", "admin"
    ) and not _is_crm_admin_user(user):
        return JSONResponse({"detail": "Order Explorer access requires a customer service, marketing, leadership or admin role"}, status_code=403)

    # Social (Facebook Page) management is a marketing action: publishing offers
    # and replying to customers. Marketing + leadership + admin only.
    if path.startswith("/api/social") and user.get("role") not in (
        "marketing", "leadership", "smt", "admin"
    ) and not _is_crm_admin_user(user):
        return JSONResponse({"detail": "Social access requires a marketing, leadership or admin role"}, status_code=403)

    # Production Tracker (/api/production/*) is a work-in-progress board for the
    # product development team to move buying-order quantities through the
    # manufacturing stages. Product development + leadership + admin only;
    # enforced here so hidden web nav can't be bypassed via direct API.
    if path.startswith("/api/production") and user.get("role") not in (
        "product_development", "production", "leadership", "smt", "admin"
    ):
        return JSONResponse({"detail": "Production tracker access requires a production, product development, leadership or admin role"}, status_code=403)

    # Product Development Flow (/api/pd/*) — the pre-production style kanban.
    # Same audience as the production tracker; SLA edits are additionally
    # admin-checked inside pd_flow_router.
    if path.startswith("/api/pd/") and user.get("role") not in (
        "product_development", "production", "leadership", "smt", "admin"
    ):
        return JSONResponse({"detail": "Product Development Flow access requires a production, product development, leadership or admin role"}, status_code=403)

    # HR attendance dashboard (/api/hr/*) is a staff surface. Leadership + admin
    # get the executive/HR-manager view; store managers map to branch managers
    # (own-branch scope); retail gets a read view. Other departments have no HR
    # mandate and are blocked server-side so hidden web nav / mobile routes can't
    # be bypassed. Finer write/branch-scope checks live in hr_attendance.py.
    # EXCEPTION: salary-advance self-service (/api/hr/salary-advances*) is open
    # to EVERY authenticated active staff member — any employee may apply for an
    # advance regardless of dashboard role. Approve/reject stays restricted
    # inside hr_attendance.py via _can_write, and non-reviewers only ever see
    # their own applications, so no HR data leaks through this carve-out.
    if (
        path.startswith("/api/hr")
        and not path.startswith("/api/hr/salary-advances")
        and user.get("role") not in (
            "admin", "leadership", "smt", "store_manager", "retail", "hr"
        )
    ):
        return JSONResponse({"detail": "HR dashboard access requires a staff role"}, status_code=403)

    # Staff Rota (/api/rota/*) is a HR + leadership + admin surface.
    # Enforced server-side so hidden web nav / direct API can't be bypassed.
    if path.startswith("/api/rota") and user.get("role") not in ("admin", "leadership", "hr"):
        return JSONResponse({"detail": "Rota access requires a leadership, HR or admin role"}, status_code=403)

    # Finance Reports Suite (/api/finance/*) is a leadership + admin surface.
    # Enforced server-side so hidden web nav / direct API can't be bypassed by a
    # non-leadership role.
    if path.startswith("/api/finance") and user.get("role") not in ("admin", "leadership"):
        return JSONResponse({"detail": "Finance access requires a leadership or admin role"}, status_code=403)

    # Growth Model (/api/growth/*) is a leadership + admin surface.
    if path.startswith("/api/growth") and user.get("role") not in ("admin", "leadership"):
        return JSONResponse({"detail": "Growth Model access requires a leadership or admin role"}, status_code=403)

    # Retail Desk (/api/retail-desk/*) is a leadership + admin surface.
    if path.startswith("/api/retail-desk") and user.get("role") not in ("admin", "leadership"):
        return JSONResponse({"detail": "Retail Desk access requires a leadership or admin role"}, status_code=403)

    # AI Desks (Phases 4-10) — leadership + admin surfaces.
    if path.startswith("/api/product-desk") and user.get("role") not in ("admin", "leadership"):
        return JSONResponse({"detail": "Product Desk access requires a leadership or admin role"}, status_code=403)
    if path.startswith("/api/workforce-desk") and user.get("role") not in ("admin", "leadership"):
        return JSONResponse({"detail": "Workforce Desk access requires a leadership or admin role"}, status_code=403)
    if path.startswith("/api/customer-desk") and user.get("role") not in ("admin", "leadership"):
        return JSONResponse({"detail": "Customer Desk access requires a leadership or admin role"}, status_code=403)
    if path.startswith("/api/marketing-desk") and user.get("role") not in ("admin", "leadership"):
        return JSONResponse({"detail": "Marketing Desk access requires a leadership or admin role"}, status_code=403)
    if path.startswith("/api/supply-chain-desk") and user.get("role") not in ("admin", "leadership"):
        return JSONResponse({"detail": "Supply Chain Desk access requires a leadership or admin role"}, status_code=403)
    if path.startswith("/api/production-desk") and user.get("role") not in ("admin", "leadership"):
        return JSONResponse({"detail": "Production Desk access requires a leadership or admin role"}, status_code=403)
    if path.startswith("/api/chair") and user.get("role") not in ("admin", "leadership"):
        return JSONResponse({"detail": "The Chair access requires a leadership or admin role"}, status_code=403)

    # L10 Meeting Tracker — leadership + admin surface.
    if path.startswith("/api/l10") and user.get("role") not in ("admin", "leadership"):
        return JSONResponse({"detail": "L10 access requires a leadership or admin role"}, status_code=403)

    # Odoo Reconciliation Agent (/api/recon/*) is the same finance-grade surface
    # (approve/reject + staging write-back) — leadership + admin only.
    if path.startswith("/api/recon") and user.get("role") not in ("admin", "leadership"):
        return JSONResponse({"detail": "Reconciliation access requires a leadership or admin role"}, status_code=403)

    # Quarterly target scorecard (/api/analytics/quarter-scorecard) exposes the
    # leadership revenue budget + per-store goals, so it is leadership + admin
    # only (matching the "quarter-scorecard" page in _LEADERSHIP_PAGES). Only the
    # single exact path is gated — the rest of /api/analytics stays open.
    if path == "/api/analytics/quarter-scorecard" and user.get("role") not in ("admin", "leadership", "smt"):
        return JSONResponse({"detail": "Quarterly scorecard access requires a leadership or admin role"}, status_code=403)

    return await call_next(request)

# --- Deferred startup ------------------------------------------------------
# DB-touching startup hooks (idempotent DDL / seeds / boot logging) used to run
# synchronously inside FastAPI's startup event, which delays uvicorn from
# binding the port until they ALL finish. In production a SIGKILLed previous
# run (deploy restart) can leave orphaned Postgres sessions holding table locks
# for minutes; the next boot's CREATE/ALTER TABLE then blocks silently past the
# deployment's ~60s port timeout and the platform kills the VM in a crash loop.
# Fix: uvicorn binds IMMEDIATELY and this work runs in ONE ordered background
# daemon thread. Every step is individually guarded — a failed step logs and
# the runner moves on; endpoints that need a table either lazily ensure it or
# fail closed until the ensure lands (prod tables already exist, so in practice
# this only matters on a brand-new DB for a few seconds).
_DEFERRED_STARTUP = []


def _deferred_startup(fn):
    _DEFERRED_STARTUP.append(fn)
    return fn


@app.on_event("startup")
def _launch_deferred_startup():
    # NOTE: lifecycle lines log at WARNING because the api_pg logger has no
    # handler configured (INFO is silently dropped by Python's last-resort
    # stderr handler). These few lines are the only startup observability the
    # deployment logs get — keep them visible.
    def _runner():
        t0 = time.time()
        log.warning("Deferred startup: running %d steps in background…",
                    len(_DEFERRED_STARTUP))
        for fn in _DEFERRED_STARTUP:
            name = getattr(fn, "__name__", str(fn))
            step_t0 = time.time()
            try:
                fn()
            except Exception as e:
                log.error("deferred startup step %s failed: %s", name, e)
            step_dt = time.time() - step_t0
            if step_dt > 10:
                log.warning("deferred startup step %s took %.1fs (possible "
                            "lock contention)", name, step_dt)
        log.warning("Deferred startup complete (%d steps, %.1fs)",
                    len(_DEFERRED_STARTUP), time.time() - t0)
    threading.Thread(target=_runner, name="deferred-startup",
                     daemon=True).start()


@_deferred_startup
def _check_report_libraries():
    # Surface missing optional report/export libraries at boot instead of at
    # request time. These are lazily imported inside download endpoints
    # (Excel/PDF builds), so a missing wheel in .pythonlibs otherwise goes
    # unnoticed until a user clicks a download button and gets a 500.
    # DB-free and fast; never raises, never blocks port bind (runs in the
    # deferred-startup background thread).
    import importlib
    optional_libs = {
        "openpyxl": "Excel exports (fabric register, replenishments, reports)",
        "reportlab": "PDF downloads (fabric receiving PDF)",
        "pypdf": "PDF merge/processing",
    }
    missing = []
    for mod, used_for in optional_libs.items():
        try:
            importlib.import_module(mod)
        except Exception as e:
            missing.append(f"{mod} ({used_for}): {e}")
    if missing:
        log.error(
            "MISSING REPORT LIBRARIES — the following download/export "
            "endpoints will 500 until these are installed via "
            "`uv pip install --target .pythonlibs/lib/python3.11/site-packages`:\n  - "
            + "\n  - ".join(missing))
    else:
        log.warning("Report libraries OK: %s", ", ".join(optional_libs))


@_deferred_startup
def _init_user_store():
    # Idempotently create the app_users table so role/approval state has a home.
    try:
        _ensure_users_table()
    except Exception:
        pass


@_deferred_startup
def _migrate_legacy_roles():
    # One-time idempotent migration: map retired technical roles
    # (viewer/analyst/exec/manager/hr) onto the new department groups so existing
    # users keep equivalent access. warehouse/store_manager/admin are unchanged.
    try:
        for old, new in LEGACY_ROLE_MAP.items():
            _users_exec("UPDATE app_users SET role=%s WHERE role=%s", (new, old))
    except Exception as e:
        log.error("Legacy role migration failed: %s", e)


@_deferred_startup
def _seed_fabric_quality_supervisor():
    # Idempotent: ensure marywamuyu@vivofashiongroup.com carries the
    # fabric_quality_supervisor role. Runs on every boot — safe because it only
    # touches her row and only upgrades it (won't demote an admin).
    try:
        rows = _users_exec(
            "SELECT role FROM app_users WHERE LOWER(email)=%s",
            ("marywamuyu@vivofashiongroup.com",), fetch=True)
        if rows:
            current = (rows[0].get("role") or "")
            if current != "admin" and current != "fabric_quality_supervisor":
                _users_exec(
                    "UPDATE app_users SET role=%s WHERE LOWER(email)=%s",
                    ("fabric_quality_supervisor",
                     "marywamuyu@vivofashiongroup.com"))
                log.warning("Seeded fabric_quality_supervisor role for "
                            "marywamuyu@vivofashiongroup.com "
                            "(was: %s)", current)
    except Exception as e:
        log.error("fabric_quality_supervisor seed failed: %s", e)


@_deferred_startup
def _seed_admin():
    # Ensure there is always at least one admin who can sign in and approve
    # others. The seed credentials come from env; the email defaults to the
    # company admin address. Idempotent — re-running keeps the account in sync
    # with the env password so a known-good login always exists.
    email = (os.environ.get("SEED_ADMIN_EMAIL")
             or "admin@vivofashiongroup.com").strip().lower()
    password = os.environ.get("SEED_ADMIN_PASSWORD")
    try:
        # Defensive migration: any legacy row with a NULL status becomes active
        # so it isn't accidentally locked out by the new approval gate.
        _users_exec("UPDATE app_users SET status='active' WHERE status IS NULL")
    except Exception as e:
        log.error("Seed admin: status backfill failed: %s", e)
    if not password:
        log.info("Seed admin: SEED_ADMIN_PASSWORD not set; skipping admin seed "
                 "(set SEED_ADMIN_EMAIL/SEED_ADMIN_PASSWORD to enable).")
        return
    try:
        ph = _hash_password(password)
        _users_exec("""
            INSERT INTO app_users (user_id, email, name, role, status,
                                   auth_method, password_hash, approved_at, approved_by)
            VALUES (%s, %s, %s, 'admin', 'active', 'password', %s, now(), 'system:seed')
            ON CONFLICT (email) DO UPDATE SET
                role='admin', status='active', auth_method='password',
                password_hash=EXCLUDED.password_hash
        """, ("seed:" + email, email, "Administrator", ph))
        _invalidate_user_cache()
        log.info("Seed admin ensured for %s", email)
    except Exception as e:
        log.error("Seed admin failed: %s", e)


@_deferred_startup
def _ensure_perf_indexes():
    # idx_all_sales_loaded_at makes the topbar data-freshness poll
    # (MAX(loaded_at)) an index-tail lookup instead of a full 1.5M-row scan
    # (measured 5s+ under sync-loop contention). Idempotent.
    try:
        _users_exec("CREATE INDEX IF NOT EXISTS idx_all_sales_loaded_at "
                    "ON all_sales (loaded_at)")
    except Exception as e:
        log.error("Perf index ensure failed: %s", e)


@_deferred_startup
def _backfill_receiving_kpm():
    # Repair receiving sheets whose kg_per_mtr was snapshotted as NULL because
    # the product had no Width/GSM in Odoo at creation time. The buying team
    # may have since filled in Width+GSM; this one-shot backfill (NULL-only
    # guard means it is a no-op once all sheets are fixed) repairs those sheets
    # and their rolls so the "Missing Width/GSM" badge disappears without any
    # manual intervention or a full restart. The sync loop also calls it on
    # every fast-fabric extract so the fix applies within ~60s of an Odoo
    # Width/GSM update being synced.
    try:
        from fabric_router import _recv_backfill_missing_kpm
        conn = get_conn()
        try:
            _recv_backfill_missing_kpm(conn)
        finally:
            conn.close()
    except Exception as e:
        log.error("Startup kpm backfill failed: %s", e)


@_deferred_startup
def _start_cache_prewarmer():
    # Background pre-warmer for the heavy whole-history dashboards. These
    # queries take 10-20s cold and are cached HEAVY_DASH_TTL (900s); without
    # warming, the first user of every cycle eats the full cost. This daemon
    # re-computes the default (unfiltered) views every HEAVY_DASH_WARM_INTERVAL
    # (600s) so the cache never lapses. Filtered variants (per-store etc.) still
    # compute on demand but then stay warm for 15 min themselves.
    # NOTE: endpoint functions are called with EXPLICIT kwargs — calling a
    # FastAPI endpoint directly would otherwise pass Query(...) sentinel objects
    # as values.
    def _warm_loop():
        time.sleep(90)  # let boot + first user traffic settle before warming
        while True:
            t0 = time.time()
            # Warm Postgres shared_buffers so cold-start queries hit RAM not disk.
            # all_sales is 962 MB; loading the recent 90-day slice (~150 MB) covers
            # every default filter (7D/30D/90D) and keeps buffer-pool hit rate high.
            try:
                run_query(
                    "SELECT COUNT(*), MAX(sale_date), "
                    "ROUND(SUM(total_sales_kes::numeric)) AS rev "
                    "FROM all_sales WHERE sale_date >= "
                    "to_char(CURRENT_DATE - INTERVAL '90 days', 'YYYY-MM-DD')",
                    ttl=60)
                run_query("SELECT COUNT(*) FROM all_inventory", ttl=60)
                run_query("SELECT COUNT(*) FROM all_products_clean", ttl=60)
            except Exception as _warm_e:
                log.warning("PG buffer warmup failed (non-fatal): %s", _warm_e)
            targets = [
                ("weeks-of-cover", lambda: analytics_weeks_of_cover(
                    date_from=None, date_to=None, country=None)),
                ("aged-stock", lambda: analytics_aged_stock(
                    min_days_since_sale=60, days=None)),
                ("range-classify", lambda: range_mgmt_classify(
                    country=None, channel=None)),
                ("store-tier-mix", lambda: range_mgmt_store_tier_mix(
                    country=None, channel=None)),
                ("store-overstock", lambda: analytics_store_overstock(
                    country=None, channel=None)),
                ("declining-styles", lambda: analytics_declining_styles(
                    country=None, channel=None)),
                ("weekly-sor", lambda: range_mgmt_weekly_sor(
                    country=None, channel=None)),
                ("exec-summary", lambda: exec_summary(
                    country=None, window_days=30, date_from=None,
                    date_to=None, style_status="all")),
                ("excess-inventory", _excess_inventory_dataset),
                ("store-country-map", _store_country_map),
                ("top-customers", lambda: _top_customers_data(
                    date_from=str(date.today().replace(day=1)),
                    date_to=str(date.today()),
                    country=None, channel=None, limit=20)),
                ("ibt-suggestions", lambda: ibt_suggestions(
                    country=None, demand_days=28, limit=300,
                    low_pct=20, high_pct=150, use_clustering=True)),
                # KPI endpoint: warm the four most-used date presets so
                # navigating the filter bar after a restart is instant.
                ("kpis-today", lambda: get_kpis(
                    date_from=str(date.today()),
                    date_to=str(date.today()),
                    country=None, channel=None)),
                ("kpis-mtd", lambda: get_kpis(
                    date_from=str(date.today().replace(day=1)),
                    date_to=str(date.today()),
                    country=None, channel=None)),
                ("kpis-7d", lambda: get_kpis(
                    date_from=str(date.today() - timedelta(days=7)),
                    date_to=str(date.today()),
                    country=None, channel=None)),
                ("kpis-30d", lambda: get_kpis(
                    date_from=str(date.today() - timedelta(days=30)),
                    date_to=str(date.today()),
                    country=None, channel=None)),
                ("production-flow",    lambda: production_flow()),
                ("production-summary", lambda: production_summary()),
                ("retail-desk-overview", retail_desk_router._overview_snapshot),
            ]
            for name, fn in targets:
                try:
                    fn()
                except Exception as e:
                    log.warning("Cache prewarm %s failed: %s", name, e)
            # print (not log.info) so the line is visible in deployed logs,
            # matching the "Deferred startup complete" pattern.
            print("Cache prewarm cycle done in %.1fs" % (time.time() - t0), flush=True)
            time.sleep(max(30, HEAVY_DASH_WARM_INTERVAL - (time.time() - t0)))
    threading.Thread(target=_warm_loop, daemon=True,
                     name="cache-prewarmer").start()


@_deferred_startup
def _startup_health_check():
    # Verify DB connectivity + that every table the BI endpoints rely on exists.
    # Never crash on a missing table (the API still serves what it can — degraded
    # mode); just log a clear summary so deploys surface problems immediately.
    required = ["all_sales", "all_inventory", "all_products_clean", "pos_locations",
                "footfall", "currency_rates", "recommendation_actions",
                "ibt_completions", "allocation_runs", "ibt_transfer",
                "transfer_reservations"]
    db_ok = False
    present = 0
    try:
        pool = _get_pool()
        conn = pool.getconn()
        try:
            conn.autocommit = True
            cur = conn.cursor()
            cur.execute("SELECT 1")
            db_ok = (cur.fetchone()[0] == 1)
            for t in required:
                cur.execute("SELECT to_regclass(%s)", (f"public.{t}",))
                if cur.fetchone()[0] is not None:
                    present += 1
                else:
                    log.error("Startup: required table missing: %s", t)
            cur.close()
        finally:
            pool.putconn(conn)
    except Exception as e:
        log.error("Startup health check failed: %s", e)
    healthy = db_ok and present == len(required)
    summary = ("Startup [%s] | DB connected: %s | Tables: %d/%d | Pool: %d-%d | "
               "Cache: ready") % ("OK" if healthy else "DEGRADED", db_ok, present,
                                  len(required), 2, MAX_DB_CONNECTIONS)
    (log.info if healthy else log.error)(summary)


# Performance indexes for the hot all_sales scans. The base table ships with
# indexes on sale_date / store_id / country, but the customer-analytics paths
# GROUP BY customer_id over the whole table (e.g. global first-purchase in
# exec-summary / churn) which was a full 1.5M-row scan. The partial composite
# below turns the first-purchase + per-customer aggregation into an index scan
# (exec-summary cold load dropped ~25s -> ~10s). Created idempotently so the
# optimisation also applies in production after a fresh DB sync.
# CONCURRENTLY so the build never takes an exclusive lock on the 1.5M-row table
# (a plain CREATE INDEX would block reads AND, critically, block the /api/
# startup healthcheck while it runs — which on a freshly-synced production DB
# made the deployment flap and hang on "Checking session…").
_PERF_INDEXES = [
    ("idx_as_cust_firstpurch",
     "CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_as_cust_firstpurch ON all_sales "
     "(customer_id, sale_date) "
     "WHERE sale_kind IN ('sale','order') AND customer_id IS NOT NULL"),
    ("idx_as_kind_date",
     "CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_as_kind_date ON all_sales (sale_kind, sale_date)"),
    # Phase 7 hot-path coverage. Duplicates of pre-existing indexes (sale_date,
    # products.sku pkey, rec_actions (rec_type,rec_key) unique, sale_kind leading
    # col of idx_as_kind_date) are intentionally omitted to avoid redundant write
    # cost. CONCURRENTLY IF NOT EXISTS so production picks them up online.
    ("idx_all_sales_store_date",
     "CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_all_sales_store_date ON all_sales (store_id, sale_date)"),
    ("idx_all_sales_location_date",
     "CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_all_sales_location_date ON all_sales (pos_location_name, sale_date)"),
    ("idx_all_sales_sku",
     "CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_all_sales_sku ON all_sales (variant_sku)"),
    ("idx_all_sales_country_date",
     "CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_all_sales_country_date ON all_sales (country, sale_date)"),
    ("idx_all_inventory_sku",
     "CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_all_inventory_sku ON all_inventory (sku)"),
    ("idx_all_inventory_location",
     "CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_all_inventory_location ON all_inventory (pos_location_name)"),
    ("idx_all_inventory_country",
     "CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_all_inventory_country ON all_inventory (country)"),
    ("idx_all_products_style",
     "CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_all_products_style ON all_products_clean (style_name)"),
    ("idx_all_products_type",
     "CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_all_products_type ON all_products_clean (product_type)"),
    ("idx_rec_actions_status",
     "CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_rec_actions_status ON recommendation_actions (status)"),
    ("idx_ibt_completions_style",
     "CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_ibt_completions_style ON ibt_completions (style_name)"),
    ("idx_ibt_completions_stores",
     "CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_ibt_completions_stores ON ibt_completions (from_store, to_store)"),
    ("idx_ibt_completions_date",
     "CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_ibt_completions_date ON ibt_completions (transfer_date)"),
    ("idx_footfall_location_time",
     "CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_footfall_location_time ON footfall (pos_location_name, \"time\")"),
    ("idx_sync_health_checked",
     "CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_sync_health_checked ON sync_health_log (checked_at DESC)"),
    # Sales-by-Hour (Overview): the Shopify-history side filters
    # substring(created_at, 1, 10) BETWEEN dates — per-row string parsing over a
    # full scan of raw_shopify_orders (was 6-10s). substring() is IMMUTABLE, so
    # an expression index makes the date-range predicate an index scan.
    ("idx_rso_created_date",
     "CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_rso_created_date ON raw_shopify_orders "
     "(substring(created_at, 1, 10))"),
    ("idx_shopify_sales_day",
     "CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_shopify_sales_day ON shopify_sales (day)"),
    ("idx_shopify_sales_order",
     "CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_shopify_sales_order ON shopify_sales "
     "((order_id::text), store_id)"),
]


def _build_perf_indexes():
    """Create the hot-path indexes. Runs in a background thread (see the startup
    hook) so it NEVER delays uvicorn binding / the production startup healthcheck.
    Each statement is autocommit + CONCURRENTLY, so a slow first build on a fresh
    DB happens online without blocking queries or the health probe."""
    try:
        pool = _get_pool()
        conn = pool.getconn()
    except Exception:
        return
    try:
        conn.autocommit = True
        cur = conn.cursor()
        for _, sql in _PERF_INDEXES:
            try:
                cur.execute(sql)
            except Exception:
                pass
        cur.close()
    except Exception:
        pool.putconn(conn, close=True)
        return
    pool.putconn(conn)


@app.on_event("startup")
def _ensure_perf_indexes():
    # Fire-and-forget: index maintenance must not block the server from serving
    # the startup healthcheck. A daemon thread dies with the process.
    import threading
    threading.Thread(target=_build_perf_indexes, name="perf-index-build",
                     daemon=True).start()


@_deferred_startup
def _ensure_ibt_lifecycle_startup():
    # Eagerly create the Phase-3 lifecycle + reservation ledger so the startup
    # health check finds them on a fresh DB. Best-effort; never blocks boot.
    try:
        _ensure_ibt_lifecycle_tables()
    except Exception as e:
        log.warning("ibt lifecycle startup ensure skipped: %s", e)


@app.on_event("startup")
def _cap_threadpool():
    # Sync endpoints run in Starlette's thread pool (default 40). Each can hold a
    # pooled DB connection, so keep concurrency strictly below MAX_DB_CONNECTIONS
    # to guarantee getconn() never overflows the pool under request bursts.
    try:
        import anyio
        anyio.to_thread.current_default_thread_limiter().total_tokens = MAX_DB_CONNECTIONS - 2
    except Exception:
        pass


@app.on_event("startup")
def _assert_standard_conforming_strings():
    # Fail fast if quote-doubling escaping (csv_to_sql et al.) is not backed by
    # standard_conforming_strings=on. We pin it per-connection via libpq options;
    # this asserts it actually took effect rather than trusting the default.
    pool = _get_pool()
    conn = pool.getconn()
    try:
        cur = conn.cursor()
        cur.execute("SHOW standard_conforming_strings")
        setting = cur.fetchone()[0]
        cur.close()
    finally:
        pool.putconn(conn)
    if setting != "on":
        raise RuntimeError(
            "standard_conforming_strings must be 'on' for SQL-injection escaping "
            f"to be sound, got {setting!r}")

BASE_FILTERS = """
    s.pos_location_name NOT IN ('Staff purchases','Manual Order','Online - vivo-uganda','Online - vivowoman','Online Orders Location')
    AND LOWER(COALESCE(s.product_title,'')) NOT LIKE '%shopping bag%'
    AND LOWER(COALESCE(s.product_title,'')) NOT LIKE '%gift card%'
    AND LOWER(COALESCE(s.product_title,'')) NOT LIKE '%gift voucher%'
    AND LOWER(COALESCE(s.product_title,'')) NOT LIKE '%voucher%'
    AND (
        -- Loyalty/reward discount-carrier lines ("15% on specific products"):
        -- zero revenue, zero units, discount only. They MUST stay in the
        -- reporting universe so Total Sales = total − discounts − returns
        -- picks up the loyalty discount (they can't distort units/revenue —
        -- both are 0). Gift card/voucher redemptions stay excluded above:
        -- redeeming a voucher is a payment method, not a discount.
        LOWER(COALESCE(s.product_title,'')) NOT LIKE '%on specific products%'
        OR (COALESCE(s.total_sales_kes,0)::numeric = 0
            AND COALESCE(s.ordered_item_quantity,0) = 0
            AND COALESCE(s.discounts_kes,0)::numeric <> 0)
    )
    AND LOWER(COALESCE(s.variant_sku,'')) NOT LIKE '%vb00%'
"""

# --- Footfall location-name canonicalisation -------------------------------
# The footfall sensor feed renamed every store on 2026-06-07 (e.g.
# "Vivo Junction" -> "VFGJUNCTION", "Vivo Sarit" -> "Sarit Centre"). The new
# spellings do NOT match all_sales.pos_location_name, so footfall->sales joins
# silently fail: orders fall to 0 for the renamed stores and conversion rate
# collapses (~1% instead of ~12%). The old names stop 2026-06-06 and the new
# names start 2026-06-07 with NO overlap, so folding the new spellings back to
# the canonical sales name is safe (it can never double-count a day). Keys are
# the footfall sensor spellings; values are the canonical all_sales name.
FOOTFALL_LOCATION_ALIASES = {
    "Vivo MoiAV": "Vivo Moi Avenue",
    "Sarit Centre": "Vivo Sarit",
    "VFGJUNCTION": "Vivo Junction",
    "Yaya Centre": "Vivo Yaya",
    "VIVO Mama Ngina": "Vivo Mama Ngina St",
    "VivoKisumu": "Vivo Kisumu",
    "VIVO Gardencity": "Vivo Garden City",
    "Two Rivers": "Vivo Two Rivers",
    "VIVO Capital": "Vivo Capital Centre",
    "VFGGALLERIAMALL": "Vivo Galleria",
    "VFGELDORET": "Vivo Eldoret",
    "VFGTHEHUB": "Vivo Hub",
    "VIVO Mombasa": "Vivo MSA Digo Road",
    "Vivo_MSA_DigoRD": "Vivo MSA Digo Road",
    "Acacia Mall": "Vivo Acacia",
    "VivoVillageMKT": "Vivo Village Market",
    "Vivo Runda Mall": "Vivo Runda",
    "Vivo Kigali ": "Vivo Kigali Heights",
    "VIVO MERU": "Vivo Meru",
    "VFGSIGNATURE": "Vivo Signature Mall",
    "KILELESHWA": "Vivo Kileleshwa",
    "VFG T-MALL": "Vivo T- Mall",
    " Oasis mall": "The Oasis Mall",
}

def ff_canon_sql(col="f.pos_location_name"):
    """Return a SQL expression that maps a footfall location column to its
    canonical all_sales name via FOOTFALL_LOCATION_ALIASES. Alias keys/values
    contain no single quotes, so static interpolation is injection-safe."""
    if not FOOTFALL_LOCATION_ALIASES:
        return col
    whens = " ".join(
        "WHEN '" + a.replace("'", "''") + "' THEN '" + c.replace("'", "''") + "'"
        for a, c in FOOTFALL_LOCATION_ALIASES.items()
    )
    return "CASE " + col + " " + whens + " ELSE " + col + " END"

def ff_store_master_predicate(canon_expr=None):
    """SQL predicate keeping ONLY footfall sensors that map to a real store in
    the canonical sales master (all_sales.pos_location_name). It drops phantom /
    unmapped sensor spellings — e.g. the post-rename 'VIVO Westside' and
    'Shop Zetu_MoiAv' sensors that have NO sales counterpart — so every footfall
    surface (Locations, the footfall chart AND the weekday-pattern heatmap)
    reconciles to ONE store master instead of leaking phantom keys into one view
    only (audit F14). Self-maintaining: any future unmapped sensor is excluded
    automatically. Phantom sensors carry zero sales, so this never changes any
    sales/units figure — only which store rows appear on the footfall surfaces.
    Intended consequence: a brand-new physical store that has footfall but no
    sales rows yet is suppressed from the footfall surfaces until its first sale
    lands in all_sales (the single store master), keeping every view in sync."""
    expr = canon_expr if canon_expr is not None else ff_canon_sql()
    return expr + " IN (SELECT pos_location_name FROM all_sales GROUP BY pos_location_name)"

