@app.get("/api/admin/group-pages")
def admin_group_pages_get(request: Request):
    """Per-group page access — effective list + built-in default for every
    selectable group, so the admin Group Access screen can render the checklist
    and offer a Reset to default."""
    ov = _role_page_overrides()
    custom = _custom_groups()
    groups, defaults, overridden = {}, {}, {}
    for role in list(VALID_ROLES) + sorted(custom):
        groups[role] = _effective_pages_for_role(role)
        defaults[role] = _default_pages_for_role(role)
        overridden[role] = (role != "admin") and (role in ov)
    labels = dict(BUILTIN_GROUP_LABELS)
    labels.update(custom)
    return {
        "groups": groups,
        "defaults": defaults,
        "overridden": overridden,
        "labels": labels,
        "custom": sorted(custom),
        "page_catalog": sorted(ALL_PAGE_IDS),
    }


@app.put("/api/admin/group-pages")
async def admin_group_pages_put(request: Request):
    """Save a single group's allowed pages, or reset it to default. Body:
    {"role": "<group>", "pages": [...]} or {"role": "<group>", "reset": true}."""
    try:
        body = await request.json()
    except Exception:
        body = {}
    role = (body.get("role") or "").strip().lower()
    if not _is_valid_group(role):
        return JSONResponse({"detail": "Unknown group"}, status_code=400)
    if role == "admin":
        return JSONResponse(
            {"detail": "The Admin group always has full access and cannot be restricted"},
            status_code=400)
    try:
        with _groups_lock():
            if body.get("reset"):
                pages = _reset_role_pages(role)
            else:
                raw = body.get("pages")
                if not isinstance(raw, list):
                    return JSONResponse({"detail": "pages must be a list"}, status_code=400)
                pages = _set_role_pages(role, raw)
    except ValueError as e:
        return JSONResponse({"detail": str(e)}, status_code=400)
    return {"ok": True, "role": role, "pages": pages}


@app.post("/api/admin/group-pages/groups")
async def admin_group_create(request: Request):
    """Create a custom department group. Body: {"label": "<name>", "pages": [...]?}.
    The slug is derived from the label; the group starts with no pages unless
    an initial `pages` list is supplied."""
    try:
        body = await request.json()
    except Exception:
        body = {}
    label = str(body.get("label") or "").strip()
    if len(label) < 2 or len(label) > 40:
        return JSONResponse(
            {"detail": "Group name must be 2-40 characters"}, status_code=400)
    slug = _group_slug_for_label(label)
    if not slug or not slug[0].isalpha():
        return JSONResponse(
            {"detail": "Group name must start with a letter"}, status_code=400)
    with _groups_lock():
        custom = _custom_groups()
        if slug in _RESERVED_GROUP_SLUGS or slug in custom:
            return JSONResponse(
                {"detail": f'A group named "{label}" already exists'}, status_code=409)
        lowered = {v.strip().lower() for v in list(BUILTIN_GROUP_LABELS.values()) + list(custom.values())}
        if label.lower() in lowered:
            return JSONResponse(
                {"detail": f'A group named "{label}" already exists'}, status_code=409)
        custom[slug] = label
        _save_custom_groups(custom)
        pages = []
        raw = body.get("pages")
        if isinstance(raw, list) and raw:
            try:
                pages = _set_role_pages(slug, raw)
            except ValueError as e:
                return JSONResponse({"detail": str(e)}, status_code=400)
    return {"ok": True, "role": slug, "label": label, "pages": pages}


@app.delete("/api/admin/group-pages/groups/{slug}")
async def admin_group_delete(slug: str, request: Request):
    """Delete a custom group. Built-in groups can never be deleted, and a
    custom group with members must be reassigned first (409)."""
    slug = (slug or "").strip().lower()
    with _groups_lock():
        custom = _custom_groups()
        if slug not in custom:
            detail = ("Built-in groups cannot be deleted"
                      if slug in VALID_ROLES else "Unknown group")
            return JSONResponse({"detail": detail}, status_code=400)
        rows = _users_exec(
            "SELECT COUNT(*) AS n FROM app_users WHERE lower(role)=%s", (slug,),
            fetch=True)
        n = int(rows[0]["n"]) if rows else 0
        if n > 0:
            return JSONResponse(
                {"detail": f"{n} user{'s' if n != 1 else ''} still assigned to this "
                           f"group — move them to another group first"},
                status_code=409)
        # Drop its saved page override FIRST (while the group still resolves as
        # valid — _role_page_overrides filters unknown groups on read) so a
        # future group reusing the slug starts clean instead of inheriting
        # stale pages.
        ov = _role_page_overrides()
        if slug in ov:
            del ov[slug]
            _save_role_page_overrides(ov)
        del custom[slug]
        _save_custom_groups(custom)
    return {"ok": True}


@app.get("/api/auth/me/status")
def auth_me_status(request: Request):
    u = getattr(request.state, "user", None) or {}
    if u:
        u = dict(u)
        u["allowed_pages"] = _effective_pages_for_role(u.get("role"))
        _apply_crm_admin_grants(u)
    return {"status": u.get("status", "active"), "role": u.get("role"), "user": u}


@app.post("/api/auth/login")
async def auth_login(request: Request):
    try:
        body = await request.json()
    except Exception:
        body = {}
    email = (body.get("email") or "").strip().lower()
    password = body.get("password") or ""
    if not email or not password:
        return JSONResponse({"detail": "Email and password are required"}, status_code=400)
    rows = _users_exec(
        "SELECT user_id, email, name, role, status, password_hash "
        "FROM app_users WHERE email=%s", (email,), fetch=True)
    rec = rows[0] if rows else None
    if not rec or not _verify_password(password, rec.get("password_hash")):
        return JSONResponse({"detail": "Invalid email or password"}, status_code=401)
    if rec["status"] == "rejected":
        return JSONResponse({"detail": "account_rejected"}, status_code=403)
    if rec["status"] == "disabled":
        return JSONResponse({"detail": "account_disabled"}, status_code=403)
    token = _create_session(rec["user_id"])
    try:
        _users_exec("UPDATE app_users SET last_login_at=now() WHERE user_id=%s",
                    (rec["user_id"],))
    except Exception:
        pass
    user = _user_dict(rec)
    user["hidden_pages"] = _hidden_pages()
    user["allowed_pages"] = _effective_pages_for_role(user.get("role"))
    _apply_crm_admin_grants(user)
    resp = JSONResponse({"token": token, "user": user})
    resp.set_cookie("session_token", token, **_login_cookie_kwargs())
    return resp


@app.post("/api/auth/logout")
async def auth_logout(request: Request):
    _destroy_session(_extract_session_token(request))
    resp = JSONResponse({"ok": True})
    resp.delete_cookie("session_token", path="/")
    return resp


# ── Google OAuth (Authorization Code flow, stdlib + requests) ─────────────────
def _google_redirect_uri(request: Request):
    # An explicit override wins (useful if the registered URI differs from the
    # request host). Otherwise derive it from the forwarded host so the same code
    # works in dev and production behind the Replit proxy.
    override = os.environ.get("GOOGLE_REDIRECT_URI")
    if override:
        return override
    proto = request.headers.get("x-forwarded-proto", "https")
    host = request.headers.get("x-forwarded-host") or request.headers.get("host") or ""
    return f"{proto}://{host}/api/auth/google/callback"


def _safe_oauth_return(val):
    """Validate the optional ``return`` target for the OAuth callback.

    Only native-app deep links pointing at our own callback path are allowed
    (the mobile app passes its runtime redirect URL here so the session can be
    handed back). This is deliberately NOT a general web redirect — only the
    Expo/standalone app schemes are accepted, so it cannot be abused as an open
    redirect to an arbitrary website. Web clients omit the param and keep the
    default relative ``/auth/callback`` behavior.
    """
    if not val:
        return None
    val = val.strip()
    if len(val) > 512:
        return None
    if "auth/callback" not in val:
        return None
    # Expo Go uses exp:// (optionally exp+<slug>://), standalone builds use the
    # app's own scheme. Both only open this app, never a website.
    if re.match(r"^(vivo-mobile|exp|exp\+[a-z0-9._-]+)://", val):
        return val
    # Same-origin web path (e.g. "/crm/auth/callback"). Must be server-relative:
    # exactly one leading slash, no scheme/host, not protocol-relative ("//host").
    # This lets path-routed web apps (served under their own base path) get the
    # OAuth result back at their own callback instead of the root SPA's.
    if (val.startswith("/") and not val.startswith("//")
            and re.match(r"^/[A-Za-z0-9._/-]*auth/callback$", val)):
        return val
    return None


@app.get("/api/auth/google/login")
def auth_google_login(request: Request):
    client_id = os.environ.get("GOOGLE_CLIENT_ID")
    if not client_id:
        return JSONResponse(
            {"detail": "Google sign-in is not configured."}, status_code=503)
    state = secrets.token_urlsafe(24)
    return_to = _safe_oauth_return(request.query_params.get("return"))
    params = urlencode({
        "client_id": client_id,
        "redirect_uri": _google_redirect_uri(request),
        "response_type": "code",
        "scope": "openid email profile",
        "state": state,
        "access_type": "online",
        "prompt": "select_account",
    })
    resp = RedirectResponse(
        f"https://accounts.google.com/o/oauth2/v2/auth?{params}")
    # Short-lived state cookie for CSRF protection on the callback.
    resp.set_cookie("g_oauth_state", state, httponly=True, samesite="lax",
                    secure=True, max_age=600, path="/")
    # Remember where to hand the session back (mobile deep link). Absent for web.
    if return_to:
        resp.set_cookie("g_oauth_return", return_to, httponly=True,
                        samesite="lax", secure=True, max_age=600, path="/")
    return resp


@app.get("/api/auth/google/callback")
def auth_google_callback(request: Request):
    client_id = os.environ.get("GOOGLE_CLIENT_ID")
    client_secret = os.environ.get("GOOGLE_CLIENT_SECRET")
    # Where to hand the result back. Web uses the default relative path with a
    # URL fragment; the mobile app passes a native deep link (stored at login),
    # for which query params survive the OS hand-off more reliably than a #frag.
    return_to = _safe_oauth_return(request.cookies.get("g_oauth_return"))
    base = return_to or "/auth/callback"
    # Native deep links carry the token as a query param (survives the OS
    # hand-off more reliably); web targets (default root path or a relative
    # same-origin path like /crm/auth/callback) use a URL fragment, which the
    # SPA reads from window.location.hash.
    is_native = bool(return_to) and "://" in return_to
    sep = "?" if is_native else "#"

    def _back(suffix):
        r = RedirectResponse(f"{base}{sep}{suffix}")
        r.delete_cookie("g_oauth_return", path="/")
        return r

    if not client_id or not client_secret:
        return _back("error=not_configured")
    if request.query_params.get("error"):
        return _back("error=" + quote(request.query_params.get("error")))
    code = request.query_params.get("code")
    state = request.query_params.get("state")
    cookie_state = request.cookies.get("g_oauth_state")
    if not code or not state or not cookie_state or not hmac.compare_digest(state, cookie_state):
        return _back("error=invalid_state")
    redirect_uri = _google_redirect_uri(request)
    try:
        tok = requests.post("https://oauth2.googleapis.com/token", data={
            "code": code, "client_id": client_id, "client_secret": client_secret,
            "redirect_uri": redirect_uri, "grant_type": "authorization_code",
        }, timeout=15)
    except Exception:
        return _back("error=token_exchange")
    if tok.status_code >= 400:
        return _back("error=token_exchange")
    access_token = (tok.json() or {}).get("access_token")
    if not access_token:
        return _back("error=token_exchange")
    try:
        prof = requests.get(
            "https://openidconnect.googleapis.com/v1/userinfo",
            headers={"Authorization": f"Bearer {access_token}"}, timeout=15)
    except Exception:
        return _back("error=profile")
    if prof.status_code >= 400:
        return _back("error=profile")
    info = prof.json() or {}
    email = (info.get("email") or "").strip().lower()
    # Require an explicitly verified email AND an allowed company domain. Treat a
    # missing/false email_verified as untrusted rather than letting it through.
    if info.get("email_verified") is not True or not clerk_auth.email_allowed(email):
        return _back("error=domain_not_allowed")
    sub = "google:" + str(info.get("sub") or email)
    name = info.get("name") or ""
    picture = (info.get("picture") or "").strip()
    # WS9 T901 — a user-store hiccup here used to escape as a raw 500 (the SPA
    # then showed a dead white page). Fail back to the callback with a coded
    # error the login screen can render instead.
    try:
        rec = resolve_app_user(sub, email, name, picture)
        token = _create_session(rec["user_id"])
    except Exception:
        logging.exception("google oauth provisioning failed for %s", email)
        return _back("error=provisioning")
    resp = _back("token=" + quote(token))
    resp.set_cookie("session_token", token, **_login_cookie_kwargs())
    resp.delete_cookie("g_oauth_state", path="/")
    return resp

# ══════════════════════════════════════════════════════════════════════════════
# PART A — REAL DATA endpoints (appended)
# ══════════════════════════════════════════════════════════════════════════════

def _country_summary_q(date_from, date_to, country=None, channel=None):
    if not date_from or not date_to:
        return []
    where = build_filters(date_from, date_to, country, channel)
    return run_query("""
        SELECT s.country,
            COUNT(DISTINCT CASE WHEN s.sale_kind IN ('sale','order') THEN s.order_id END) AS orders,
            SUM(CASE WHEN s.sale_kind IN ('sale','order') THEN s.ordered_item_quantity ELSE 0 END) AS units_sold,
            ROUND(SUM(CASE WHEN s.sale_kind IN ('sale','order') THEN s.total_sales_kes::numeric ELSE 0 END) - SUM(CASE WHEN s.sale_kind IN ('sale','order') THEN s.discounts_kes::numeric ELSE 0 END) - SUM(CASE WHEN s.sale_kind = 'return' THEN s.returns_kes::numeric ELSE 0 END), 0) AS total_sales,
            ROUND(SUM(CASE WHEN s.sale_kind IN ('sale','order') THEN s.gross_sales_kes::numeric ELSE 0 END), 0) AS gross_sales,
            ROUND(SUM(CASE WHEN s.sale_kind IN ('sale','order') THEN s.discounts_kes::numeric ELSE 0 END), 0) AS discounts,
            ROUND(SUM(CASE WHEN s.sale_kind = 'return' THEN s.returns_kes::numeric ELSE 0 END), 0) AS returns,
            ROUND((SUM(CASE WHEN s.sale_kind IN ('sale','order') THEN (s.total_sales_kes::numeric - COALESCE(s.discounts_kes, 0)::numeric) ELSE 0 END) - SUM(CASE WHEN s.sale_kind = 'return' THEN s.returns_kes::numeric ELSE 0 END)) / NULLIF(COUNT(DISTINCT CASE WHEN s.sale_kind IN ('sale','order') THEN s.order_id END), 0), 0) AS avg_basket_size
        FROM all_sales s
        WHERE """ + where + """
        GROUP BY s.country
        ORDER BY total_sales DESC
    """, date_to=date_to)

def _daily_by_country_q(date_from, date_to, country=None, channel=None):
    if not date_from or not date_to:
        return {}
    # Net of returns so the per-country daily series reconciles to the headline
    # (variant A), matching /api/daily-trend. Returns subtract on their own date;
    # orders/units stay sale+order only.
    where = build_filters(date_from, date_to, country, channel)
    rows = run_query("""
        SELECT s.sale_date AS day, s.country,
            COUNT(DISTINCT CASE WHEN s.sale_kind IN ('sale','order') THEN s.order_id END) AS orders,
            SUM(CASE WHEN s.sale_kind IN ('sale','order') THEN s.ordered_item_quantity ELSE 0 END) AS units,
            ROUND(SUM(CASE WHEN s.sale_kind IN ('sale','order') THEN (s.total_sales_kes::numeric - COALESCE(s.discounts_kes, 0)::numeric) ELSE 0 END)
                - SUM(CASE WHEN s.sale_kind = 'return' THEN s.returns_kes::numeric ELSE 0 END), 0) AS total_sales
        FROM all_sales s
        WHERE """ + where + """
        GROUP BY s.sale_date, s.country
        ORDER BY s.sale_date, s.country
    """, date_to=date_to)
    out = {}
    for r in rows:
        c = r.get("country") or "Other"
        out.setdefault(c, []).append({
            "day": r.get("day"),
            "total_sales": r.get("total_sales"),
            "orders": r.get("orders"),
            "units": r.get("units"),
        })
    return out

@app.get("/api/bootstrap/overview")
def bootstrap_overview(
    date_from:    str = Query(default=str(date.today().replace(day=1))),
    date_to:      str = Query(default=str(date.today())),
    country:      str = Query(default=None),
    channel:      str = Query(default=None),
    compare_from: str = Query(default=None),
    compare_to:   str = Query(default=None),
):
    has_prev = bool(compare_from and compare_to)
    return {
        "country_summary":      _country_summary_q(date_from, date_to, country, channel),
        "country_summary_prev": _country_summary_q(compare_from, compare_to, country, channel) if has_prev else [],
        "sales_summary":        get_sales_summary(date_from, date_to, country, channel),
        "sales_summary_prev":   get_sales_summary(compare_from, compare_to, country, channel) if has_prev else [],
        "top_styles":           get_top_skus(date_from, date_to, country, channel, 10),
        "subcategory_sales":      get_subcategory_sales(date_from, date_to, country, channel),
        "subcategory_sales_prev": get_subcategory_sales(compare_from, compare_to, country, channel) if has_prev else [],
        "footfall":             get_footfall(date_from, date_to, channel),
        "footfall_prev":        get_footfall(compare_from, compare_to, channel) if has_prev else [],
        "locations":            get_locations(),
        "daily_by_country":      _daily_by_country_q(date_from, date_to, country, channel),
        "daily_by_country_prev": _daily_by_country_q(compare_from, compare_to, country, channel) if has_prev else {},
    }

# ── Sales by Hour (Overview bottom chart) ────────────────────────────────────
# all_sales.sale_date is date-only, so hour-of-day comes from the RAW order
# headers: raw_odoo_pos_orders.date_order (UTC text, Kenya POS since the
# 2026-03-20 cutover; kept fresh by sync_incremental's header upsert) and
# raw_shopify_orders.created_at (ISO with the store's LOCAL offset — hour is
# already local; vivowoman = Kenya pre-cutover history, vivo-uganda /
# vivo-rwanda = current). The Online channel (raw_shopify_vendor_sales) is
# daily-grain only and is intentionally excluded — no hourly data exists.
_KENYA_POS_CUTOVER = "2026-03-20"
_HOURLY_SHOPIFY_STORE_COUNTRY = {
    "vivowoman": "Kenya",
    "vivo-uganda": "Uganda",
    "vivo-rwanda": "Rwanda",
}

def _hour_label(h):
    if h == 0:
        return "12am"
    if h < 12:
        return f"{h}am"
    if h == 12:
        return "12pm"
    return f"{h - 12}pm"

@app.get("/api/analytics/sales-by-hour")
def analytics_sales_by_hour(
    date_from: str = Query(default=str(date.today().replace(day=1))),
    date_to:   str = Query(default=str(date.today())),
    country:   str = Query(default=None),
    channel:   str = Query(default=None),
):
    """Gross order value by LOCAL hour of day (EAT), hours 8am-11pm.

    Filter contract: date range, country and channel (POS location names) all
    apply. The Kenya Odoo side maps channel → config_name via the sync's
    ODOO_LOCATION_MAP; the Shopify side filters shopify_sales.pos_location_name
    directly. Amounts are order-level gross totals (VAT-incl, before the
    line-level gift-voucher exclusion), so this is a shape/trend view — not
    reconciled to the Total Sales KPI.
    """
    countries = [c.strip() for c in country.split(",") if c.strip()] if country else []
    channels = [c.strip() for c in channel.split(",") if c.strip()] if channel else []

    # Reverse channel (pos_location_name) → Odoo config_name via the shared
    # env-free odoo_locations module (same map the sync loop uses, so the two
    # sides can never drift). Imported at module top — no silent fallback.
    _cfg_to_pos = ODOO_LOCATION_MAP

    buckets = {h: {"total_sales": 0.0, "orders": 0} for h in range(24)}
    sources = []

    # ── Kenya Odoo POS (date_order is UTC → +3h = EAT) ──
    kenya_ok = (not countries) or ("Kenya" in countries)
    odoo_cfg_filter = ""
    if channels:
        cfgs = [cfg for cfg, pos in _cfg_to_pos.items() if pos in channels]
        if cfgs:
            odoo_cfg_filter = "AND o.config_name IN (" + csv_to_sql(",".join(cfgs)) + ")"
        else:
            kenya_ok = False
    if kenya_ok:
        odoo_rows = run_query(f"""
            SELECT EXTRACT(hour FROM ts)::int AS hour,
                   COUNT(*) AS orders,
                   SUM(amount_total) AS total_sales
            FROM (
                SELECT (o.date_order::timestamp + interval '3 hours') AS ts,
                       o.amount_total
                FROM raw_odoo_pos_orders o
                WHERE o.date_order IS NOT NULL AND o.date_order <> ''
                  AND (o.state IS NULL OR o.state IN ('done','paid','invoiced'))
                  AND COALESCE(o.config_name, '') <> 'Shopzetu Online'
                  {odoo_cfg_filter}
            ) t
            WHERE ts::date BETWEEN '{date_from}' AND '{date_to}'
              AND ts::date >= '{_KENYA_POS_CUTOVER}'
            GROUP BY 1
        """, date_to=date_to)
        for r in odoo_rows:
            h = int(r["hour"])
            buckets[h]["total_sales"] += float(r["total_sales"] or 0)
            buckets[h]["orders"] += int(r["orders"] or 0)
        sources.append("kenya_pos")

    # ── Shopify retail history (created_at hour is already store-local) ──
    # raw_shopify_orders.total_price was never populated by the historical
    # extract (all 0.0), so order VALUE comes from joining line-level
    # all_sales on order_id (~100% coverage, total_sales_kes already KES).
    # NOTE: do NOT join shopify_sales here — that table is only populated by
    # the one-time shopify_full_extract (frozen at its target_end, e.g.
    # 2026-06-13 for Uganda/Rwanda), so recent days silently vanish.
    # all_sales is kept fresh by sync_incremental for these stores.
    # all_sales also carries pos_location_name, so the channel filter
    # applies to this side too.
    stores = [s for s, c in _HOURLY_SHOPIFY_STORE_COUNTRY.items()
              if (not countries) or (c in countries)]
    if stores:
        shop_chan_filter = ""
        if channels:
            shop_chan_filter = "AND l.pos_location_name IN (" + csv_to_sql(",".join(channels)) + ")"
        shop_rows = run_query(f"""
            SELECT substring(o.created_at, 12, 2)::int AS hour,
                   COUNT(DISTINCT o.id) AS orders,
                   SUM(l.total_sales_kes) AS total_sales
            FROM raw_shopify_orders o
            JOIN all_sales l
              ON l.order_id = o.id AND l.store_id = o.store_id
            WHERE length(o.created_at) >= 13
              AND substring(o.created_at, 1, 10) BETWEEN '{date_from}' AND '{date_to}'
              AND l.sale_date BETWEEN '{date_from}' AND '{date_to}'
              AND l.sale_kind = 'order'
              AND o.store_id IN ({csv_to_sql(",".join(stores))})
              AND (o.store_id <> 'vivowoman' OR substring(o.created_at, 1, 10) < '{_KENYA_POS_CUTOVER}')
              {shop_chan_filter}
            GROUP BY 1
        """, date_to=date_to)
        for r in shop_rows:
            h = int(r["hour"])
            if 0 <= h <= 23:
                buckets[h]["total_sales"] += float(r["total_sales"] or 0)
                buckets[h]["orders"] += int(r["orders"] or 0)
        sources.append("shopify_retail")

    hours = [
        {
            "hour": h,
            "label": _hour_label(h),
            "total_sales": round(buckets[h]["total_sales"]),
            "orders": buckets[h]["orders"],
        }
        for h in range(8, 24)
    ]
    try:
        n_days = (date.fromisoformat(date_to) - date.fromisoformat(date_from)).days + 1
    except Exception:
        n_days = None
    return {
        "hours": hours,
        "days": max(n_days, 1) if n_days else None,
        "sources": sources,
        "channel_applied": bool(channels),
        "online_excluded": True,
    }

@app.get("/api/analytics/canonical-units-sold")
def analytics_canonical_units_sold(
    date_from: str = Query(default=str(date.today().replace(day=1))),
    date_to:   str = Query(default=str(date.today())),
    country:   str = Query(default=None),
    channel:   str = Query(default=None),
):
    # Total units sold under BASE_FILTERS (which already excludes shopping bags,
    # staff purchases, manual orders and the Uganda online channel). We do NOT
    # restrict by product_type here. The variant_sku -> all_products_clean.sku
    # join is actually sound (~98% of sale rows match), but all_sales.product_type
    # is ~97% NULL and joined product_type only covers ~70% of sold units, so any
    # product_type filter would drop ~30% of real units and contradict the ASP /
    # transactions KPIs computed off the same base.
    #
    # Definition = _UNITS exactly (gross ordered_item_quantity over sale/order
    # rows) so this endpoint equals /api/kpis total_units BY CONSTRUCTION —
    # the old extra "quantity > 0" guard created a second, subtly different
    # units population whenever negative-qty correction rows existed.
    where = build_filters(date_from, date_to, country, channel)
    rows = run_query("""
        SELECT COALESCE(""" + _UNITS + """, 0) AS units_sold
        FROM all_sales s
        WHERE """ + where, date_to=date_to)
    return {"units_sold": int((rows[0].get("units_sold") if rows and rows[0].get("units_sold") is not None else 0))}

@app.get("/api/analytics/inventory-summary")
def analytics_inventory_summary(country: str = Query(default=None), locations: str = Query(default=None)):
    return get_inventory_summary(country, locations)

@app.get("/api/analytics/total-sales-summary")
def analytics_total_sales_summary(
    date_from: str = Query(default=str(date.today().replace(day=1))),
    date_to:   str = Query(default=str(date.today())),
    country:   str = Query(default=None),
    channel:   str = Query(default=None),
):
    where = build_filters(date_from, date_to, country, channel)
    rows = run_query("""
        SELECT
            COALESCE(ROUND(SUM(CASE WHEN s.sale_kind IN ('sale','order') THEN (s.total_sales_kes::numeric - COALESCE(s.discounts_kes, 0)::numeric) ELSE 0 END) - SUM(CASE WHEN s.sale_kind = 'return' THEN s.returns_kes::numeric ELSE 0 END), 0), 0) AS total_sales,
            -- Canonical Net Sales (NET_SALES_CANON): (total − discounts − returns)
            -- ex-VAT — must stay identical to /api/kpis net_sales (the
            -- validation agent reconciles the two to the shilling).
            COALESCE(ROUND(""" + NET_SALES_CANON + """, 0), 0) AS net_sales,
            COALESCE(ROUND(SUM(CASE WHEN s.sale_kind IN ('sale','order') THEN s.gross_sales_kes::numeric ELSE 0 END), 0), 0) AS gross_sales,
            COALESCE(COUNT(DISTINCT CASE WHEN s.sale_kind IN ('sale','order') THEN s.order_id END), 0) AS orders,
            COALESCE(SUM(CASE WHEN s.sale_kind IN ('sale','order') THEN s.ordered_item_quantity ELSE 0 END), 0) AS units
        FROM all_sales s
        WHERE """ + where, date_to=date_to)
    return rows[0] if rows else {"total_sales": 0, "net_sales": 0, "gross_sales": 0, "orders": 0, "units": 0}

@app.get("/api/analytics/active-pos")
def analytics_active_pos(
    n_days:  int = Query(default=30),
    country: str = Query(default=None),
):
    # Active POS detection (business rule 6.4): a physical store that (1) is not an
    # excluded location, (2) whose channel name does NOT contain "online" or
    # "third-party", and (3) sold >= 1 unit in the last N days (default 30). The
    # window is rolling-N-days, NOT the global date filter — the FilterBar POS
    # dropdown should list stores that *currently* trade, regardless of the view.
    date_from = str(date.today() - timedelta(days=max(1, n_days)))
    date_to   = str(date.today())
    where = build_filters(date_from, date_to, country,
        extra="s.sale_kind IN ('sale','order') "
              "AND s.pos_location_name NOT IN (" + WAREHOUSE_LOCATIONS + ") "
              "AND LOWER(s.pos_location_name) NOT LIKE '%online%' "
              "AND LOWER(s.pos_location_name) NOT LIKE '%third-party%' "
              "AND LOWER(s.pos_location_name) NOT LIKE '%third party%' "
              # Holding locations (e.g. 'The Oasis Mall Holding Location') are
              # stock-staging points, not selling stores — keep them out of the
              # Trend/FilterBar store selectors.
              "AND LOWER(s.pos_location_name) NOT LIKE '%holding location%'")
    return run_query("""
        SELECT s.pos_location_name AS channel, s.country,
            COUNT(DISTINCT s.order_id) AS orders,
            COALESCE(ROUND(SUM((s.total_sales_kes::numeric - COALESCE(s.discounts_kes, 0)::numeric)), 0), 0) AS total_sales,
            COALESCE(SUM(s.ordered_item_quantity), 0) AS units_sold
        FROM all_sales s
        WHERE """ + where + """
        GROUP BY s.pos_location_name, s.country
        HAVING SUM(s.ordered_item_quantity) >= 1
        ORDER BY total_sales DESC
    """, ttl=600)

@app.get("/api/analytics/sell-through-by-location")
def analytics_sell_through_by_location(
    date_from: str = Query(default=str(date.today().replace(day=1))),
    date_to:   str = Query(default=str(date.today())),
    country:   str = Query(default=None),
    locations: str = Query(default=None),
    search:    str = Query(default=None),
    brand:     str = Query(default=None),
    product_type: str = Query(default=None),
):
    # Inventory-page local filters (search / brand / subcategory pill) —
    # EXISTS form; applied to BOTH the sales and stock sides.
    sales_scope = _inv_local_scope_exists(search, brand, product_type, sku_expr="s.variant_sku")
    inv_scope = _inv_local_scope_exists(search, brand, product_type, sku_expr="i.sku")
    _loc_extra = (" AND s.pos_location_name IN (" + csv_to_sql(locations) + ")") if locations else ""
    sales_where = build_filters(date_from, date_to, country,
        extra="s.sale_kind IN ('sale','order') AND s.pos_location_name NOT IN (" + WAREHOUSE_LOCATIONS + ")") + _loc_extra + sales_scope
    inv_country_filter = ("AND i.country IN (" + csv_to_sql(country) + ")") if country else ""
    inv_location_filter = ("AND i.pos_location_name IN (" + csv_to_sql(locations) + ")") if locations else ""
    rows = run_query("""
        WITH sales AS (
            SELECT s.pos_location_name AS location, s.country,
                SUM(s.ordered_item_quantity) AS units_sold,
                ROUND(SUM((s.total_sales_kes::numeric - COALESCE(s.discounts_kes, 0)::numeric)), 0) AS total_sales
            FROM all_sales s
            WHERE """ + sales_where + """
            GROUP BY s.pos_location_name, s.country
        ),
        inv AS (
            SELECT i.pos_location_name AS location, i.country,
                SUM(i.available) AS available
            FROM all_inventory i
            WHERE i.pos_location_name NOT IN (""" + WAREHOUSE_LOCATIONS + """)
            """ + inv_country_filter + inv_location_filter + inv_scope + """
            GROUP BY i.pos_location_name, i.country
        )
        SELECT COALESCE(s.location, i.location) AS location,
            COALESCE(s.country, i.country) AS country,
            COALESCE(s.units_sold, 0) AS units_sold,
            COALESCE(s.total_sales, 0) AS total_sales,
            COALESCE(i.available, 0) AS available,
            COALESCE(i.available, 0) AS current_stock,
            ROUND(COALESCE(s.units_sold, 0) * 100.0 /
                NULLIF(COALESCE(s.units_sold, 0) + COALESCE(i.available, 0), 0), 1) AS sell_through,
            ROUND(COALESCE(s.units_sold, 0) * 100.0 /
                NULLIF(COALESCE(s.units_sold, 0) + COALESCE(i.available, 0), 0), 1) AS sell_through_pct,
            CASE
                WHEN COALESCE(s.units_sold, 0) + COALESCE(i.available, 0) = 0 THEN 'no_stock_data'
                WHEN COALESCE(s.units_sold, 0) * 100.0
                    / (COALESCE(s.units_sold, 0) + COALESCE(i.available, 0)) >= 25 THEN 'strong'
                WHEN COALESCE(s.units_sold, 0) * 100.0
                    / (COALESCE(s.units_sold, 0) + COALESCE(i.available, 0)) >= 12 THEN 'healthy'
                WHEN COALESCE(s.units_sold, 0) * 100.0
                    / (COALESCE(s.units_sold, 0) + COALESCE(i.available, 0)) >= 5 THEN 'slow'
                ELSE 'stuck'
            END AS health
        FROM sales s
        FULL OUTER JOIN inv i ON s.location = i.location
        ORDER BY units_sold DESC
    """, date_to=date_to)

    # WS5 — a store with NO rows in all_inventory has no stock feed at all
    # (UG/RW/Online). Sold>0 + available=0 would otherwise compute a fake
    # 100% "strong" sell-through; suppress the ratio and flag the row.
    rows = rows or []
    feed = _stock_feed_locations()
    for r in rows:
        has = r.get("location") in feed
        r["has_stock_data"] = has
        if not has:
            r["available"] = None
            r["current_stock"] = None
            r["sell_through"] = None
            r["sell_through_pct"] = None
            r["health"] = "no_stock_data"
    return rows

def _sor_selected_period(date_from, date_to):
    """Validate the optional custom period for the SOR report's
    "Selected Period" columns. Defaults to the trailing 180 days so the
    columns are always populated even before the user picks dates."""
    today = date.today()
    df = _pa_safe_date(date_from, str(today - timedelta(days=180)))
    dt = _pa_safe_date(date_to, str(today))
    if df > dt:
        df, dt = dt, df
    return df, dt


@app.get("/api/analytics/sor-all-styles")
def analytics_sor_all_styles(
    brand: str = Query(default=None),
    style_status: str = Query(default="all"),
    window_days: int = Query(default=180),
    country: str = Query(default=None),
    channel: str = Query(default=None),
    date_from: str = Query(default=None),
    date_to: str = Query(default=None),
):
    # Catalog-wide SOR audit — same row shape as the L-10 report
    # (SorStylesTable contract) but covering every style in the catalog
    # rather than just the 90-122 day new-style band. "Active" rows are
    # styles that sold a unit in the trailing `window_days`; "retired" are
    # styles with stock but no sales in the window; "all" is the union.
    win = int(window_days) if window_days and int(window_days) > 0 else 180
    sel_from, sel_to = _sor_selected_period(date_from, date_to)
    brand_pf = ""
    if brand:
        brand_pf = " AND LOWER(brand) = '" + brand.strip().lower().replace("'", "''") + "'"
    cf, chf = _style_filters(country, channel, "s")
    raw = run_query(
        """
        WITH prod AS (
            SELECT style_name,
                MAX(brand) AS brand,
                MAX(category) AS category,
                MAX(collection) AS collection,
                MAX(product_type) AS subcategory,
                mode() WITHIN GROUP (ORDER BY style_number) AS style_number,
                -- modal (most common) positive ticket price, robust to a
                -- foreign-currency leak on a few country SKUs (see PA prod CTE)
                mode() WITHIN GROUP (ORDER BY price::numeric) FILTER (WHERE price::numeric > 0) AS original_price
            FROM all_products_clean
            WHERE style_name IS NOT NULL AND style_name <> ''""" + brand_pf + """
            GROUP BY style_name
        ),
        sales AS (
            SELECT p.style_name,
                SUM(s.net_quantity) FILTER (WHERE s.sale_date::date >= CURRENT_DATE - INTERVAL '""" + str(win) + """ days') AS units_6m,
                ROUND(SUM(s.net_sales_kes::numeric) FILTER (WHERE s.sale_date::date >= CURRENT_DATE - INTERVAL '""" + str(win) + """ days')) AS sales_6m,
                SUM(s.net_quantity) FILTER (WHERE s.sale_date::date >= CURRENT_DATE - INTERVAL '21 days') AS units_3w,
                SUM(s.net_quantity) FILTER (WHERE s.sale_date::date >= CURRENT_DATE - INTERVAL '30 days') AS units_30d,
                -- Lifetime ("since launch") totals: no date filter, so they
                -- cover the style's full history (matches the report's "Units
                -- Since Launch" / "SOR Since Launch" columns). Still scoped by
                -- the country/channel filter via cf/chf below.
                SUM(s.net_quantity) AS units_since_launch,
                -- Custom "Selected Period" window (defaults to trailing 180d)
                SUM(s.net_quantity) FILTER (WHERE s.sale_date::date BETWEEN '""" + sel_from + """' AND '""" + sel_to + """') AS units_sel,
                ROUND(SUM(s.net_sales_kes::numeric) FILTER (WHERE s.sale_date::date BETWEEN '""" + sel_from + """' AND '""" + sel_to + """')) AS sales_sel,
                MAX(s.sale_date::date) AS last_sale,
                MIN(s.sale_date::date) AS first_sale
            FROM all_products_clean p
            JOIN all_sales s ON s.variant_sku = p.sku
            WHERE p.style_name IS NOT NULL AND s.sale_kind IN ('sale','order')
              AND """ + BASE_FILTERS + cf + chf + """
            GROUP BY p.style_name
        ),
        stock AS (
            SELECT COALESCE(m.style_name, i.style_name) AS style_name,
                COALESCE(SUM(i.available) FILTER (WHERE i.pos_location_name NOT IN (""" + WAREHOUSE_LOCATIONS + """)), 0) AS soh_stores,
                COALESCE(SUM(i.available) FILTER (WHERE i.pos_location_name = 'Warehouse Finished Goods'), 0) AS soh_warehouse,
                COALESCE(SUM(i.available) FILTER (WHERE i.pos_location_name IN (""" + WAREHOUSE_LOCATIONS + """) AND i.pos_location_name <> 'Finished Goods Production'), 0) AS soh_pipeline
            FROM all_inventory i
            LEFT JOIN """ + SKU_STYLE_MAP + """ m ON m.sku = i.sku
            WHERE COALESCE(m.style_name, i.style_name) IS NOT NULL
            GROUP BY 1
        )
        SELECT p.style_name, p.brand, p.category, p.collection, p.subcategory,
            p.style_number, p.original_price,
            COALESCE(sa.units_6m, 0) AS units_6m, COALESCE(sa.sales_6m, 0) AS sales_6m,
            COALESCE(sa.units_3w, 0) AS units_3w, COALESCE(sa.units_30d, 0) AS units_30d,
            COALESCE(sa.units_since_launch, 0) AS units_since_launch,
            COALESCE(sa.units_sel, 0) AS units_sel,
            COALESCE(sa.sales_sel, 0) AS sales_sel,
            sa.last_sale, sa.first_sale,
            COALESCE(st.soh_stores, 0) AS soh_stores, COALESCE(st.soh_warehouse, 0) AS soh_warehouse,
                COALESCE(st.soh_pipeline, 0) AS soh_pipeline
        FROM prod p
        LEFT JOIN sales sa USING (style_name)
        LEFT JOIN stock st USING (style_name)
        WHERE COALESCE(p.brand, '') NOT ILIKE '%third party%'
          AND (sa.units_6m IS NOT NULL OR st.soh_stores > 0 OR st.soh_warehouse > 0)
        """
    ) or []
    status = (style_status or "all").strip().lower()
    today = date.today()
    out = []
    for r in raw:
        units_6m = int(r["units_6m"] or 0)
        soh_stores = int(r["soh_stores"] or 0)
        soh_warehouse = int(r["soh_warehouse"] or 0)
        soh_pipeline = int(r["soh_pipeline"] or 0)
        soh_total = soh_stores + soh_warehouse  # pipeline NOT in total SOH
        # Style status semantics: active = sold in window; retired = has
        # stock but no sales in window; all = either. A manually-retired
        # style is force-treated as retired (never active, always satisfies
        # the retired filter regardless of stock) for cross-screen consistency.
        manual_retired = _is_manually_retired(r["style_name"])
        if status == "active":
            if units_6m <= 0 or manual_retired:
                continue
        elif status == "retired":
            if not manual_retired and (units_6m > 0 or soh_total <= 0):
                continue
        else:  # all
            if units_6m <= 0 and soh_total <= 0:
                continue
        sales_6m = float(r["sales_6m"] or 0)
        units_30d = int(r["units_30d"] or 0)
        last_sale = r["last_sale"]
        first_sale = r["first_sale"]
        weekly_avg = round(units_30d / (30.0 / 7.0), 1)
        woc = round(soh_total / weekly_avg, 1) if weekly_avg > 0 else None
        denom = units_6m + soh_total
        # Lifetime ("since launch") sell-through: lifetime net units over
        # lifetime units + current stock-on-hand, mirroring the 6m SOR formula.
        units_since_launch = int(r["units_since_launch"] or 0)
        life_denom = units_since_launch + soh_total
        age_days = (today - first_sale).days if first_sale else None
        original_price = r["original_price"]
        units_sel = int(r["units_sel"] or 0)
        sales_sel = float(r["sales_sel"] or 0)
        sel_denom = units_sel + soh_total
        asp_sel = round(sales_sel / units_sel) if units_sel > 0 else None
        op = float(original_price) if original_price is not None else None
        pct_of_full = (
            round(100.0 * asp_sel / op, 1)
            if asp_sel is not None and op and op > 0 else None
        )
        out.append({
            "style_name": r["style_name"],
            "brand": r["brand"],
            "category": r["category"],
            "collection": r["collection"],
            "subcategory": r["subcategory"],
            "style_number": r["style_number"],
            "sales_6m": round(sales_6m),
            "units_6m": units_6m,
            "units_3w": int(r["units_3w"] or 0),
            "units_since_launch": units_since_launch,
            "weekly_avg": weekly_avg,
            "soh_total": soh_total,
            "soh_wh": soh_warehouse,
            "soh_pipeline": soh_pipeline,
            "woc": woc,
            "pct_in_wh": round(100.0 * soh_warehouse / soh_total, 1) if soh_total else 0.0,
            "asp_6m": round(sales_6m / units_6m) if units_6m > 0 else None,
            "original_price": round(float(original_price)) if original_price is not None else None,
            "days_since_last_sale": (today - last_sale).days if last_sale else None,
            "sor_6m": round(100.0 * units_6m / denom, 1) if denom > 0 else None,
            "sor_since_launch": round(100.0 * units_since_launch / life_denom, 1) if life_denom > 0 else None,
            "units_sel": units_sel,
            "sales_sel": round(sales_sel),
            "sor_sel": round(100.0 * units_sel / sel_denom, 1) if sel_denom > 0 else None,
            "asp_sel": asp_sel,
            "pct_of_full": pct_of_full,
            "sel_from": sel_from,
            "sel_to": sel_to,
            "launch_date": str(first_sale) if first_sale else None,
            "style_age_weeks": round(age_days / 7.0) if age_days is not None else 0,
        })
    out.sort(key=lambda x: -(x["sales_6m"] or 0))
    return out


@app.get("/api/analytics/sor-style-colors")
def analytics_sor_style_colors(
    style_name: str = Query(...),
    country: str = Query(default=None),
    channel: str = Query(default=None),
    window_days: int = Query(default=180),
    date_from: str = Query(default=None),
    date_to: str = Query(default=None),
):
    """Per-colour breakdown for ONE style with the SAME column set as the
    catalog-wide /sor-all-styles rows, so the SOR Report's expanded rows can
    mirror the master table exactly. Colour comes from the product master
    (all_products_clean.color_print); sales/stock join on SKU only (triad
    joins are SKU-only — inventory style/colour text is unreliable)."""
    win = int(window_days) if window_days and int(window_days) > 0 else 180
    sel_from, sel_to = _sor_selected_period(date_from, date_to)
    sn = (style_name or "").strip().replace("'", "''")
    if not sn:
        raise HTTPException(status_code=422, detail="style_name is required")
    cf, chf = _style_filters(country, channel, "s")
    raw = run_query(
        """
        WITH prod AS (
            SELECT COALESCE(NULLIF(TRIM(color_print), ''), '—') AS color,
                mode() WITHIN GROUP (ORDER BY price::numeric) FILTER (WHERE price::numeric > 0) AS original_price
            FROM all_products_clean
            WHERE style_name = '""" + sn + """'
            GROUP BY 1
        ),
        skus AS (
            SELECT sku, COALESCE(NULLIF(TRIM(color_print), ''), '—') AS color
            FROM all_products_clean
            WHERE style_name = '""" + sn + """' AND sku IS NOT NULL AND sku <> ''
        ),
        sales AS (
            SELECT k.color,
                SUM(s.net_quantity) FILTER (WHERE s.sale_date::date >= CURRENT_DATE - INTERVAL '""" + str(win) + """ days') AS units_6m,
                ROUND(SUM(s.net_sales_kes::numeric) FILTER (WHERE s.sale_date::date >= CURRENT_DATE - INTERVAL '""" + str(win) + """ days')) AS sales_6m,
                SUM(s.net_quantity) FILTER (WHERE s.sale_date::date >= CURRENT_DATE - INTERVAL '21 days') AS units_3w,
                SUM(s.net_quantity) FILTER (WHERE s.sale_date::date >= CURRENT_DATE - INTERVAL '30 days') AS units_30d,
                SUM(s.net_quantity) AS units_since_launch,
                SUM(s.net_quantity) FILTER (WHERE s.sale_date::date BETWEEN '""" + sel_from + """' AND '""" + sel_to + """') AS units_sel,
                ROUND(SUM(s.net_sales_kes::numeric) FILTER (WHERE s.sale_date::date BETWEEN '""" + sel_from + """' AND '""" + sel_to + """')) AS sales_sel,
                MAX(s.sale_date::date) AS last_sale,
                MIN(s.sale_date::date) AS first_sale
            FROM skus k
            JOIN all_sales s ON s.variant_sku = k.sku
            WHERE s.sale_kind IN ('sale','order')
              AND """ + BASE_FILTERS + cf + chf + """
            GROUP BY k.color
        ),
        stock AS (
            SELECT k.color,
                COALESCE(SUM(i.available) FILTER (WHERE i.pos_location_name NOT IN (""" + WAREHOUSE_LOCATIONS + """)), 0) AS soh_stores,
                COALESCE(SUM(i.available) FILTER (WHERE i.pos_location_name = 'Warehouse Finished Goods'), 0) AS soh_warehouse,
                COALESCE(SUM(i.available) FILTER (WHERE i.pos_location_name IN (""" + WAREHOUSE_LOCATIONS + """) AND i.pos_location_name <> 'Finished Goods Production'), 0) AS soh_pipeline
            FROM skus k
            JOIN all_inventory i ON i.sku = k.sku
            GROUP BY k.color
        )
        SELECT p.color, p.original_price,
            COALESCE(sa.units_6m, 0) AS units_6m, COALESCE(sa.sales_6m, 0) AS sales_6m,
            COALESCE(sa.units_3w, 0) AS units_3w, COALESCE(sa.units_30d, 0) AS units_30d,
            COALESCE(sa.units_since_launch, 0) AS units_since_launch,
            COALESCE(sa.units_sel, 0) AS units_sel, COALESCE(sa.sales_sel, 0) AS sales_sel,
            sa.last_sale, sa.first_sale,
            COALESCE(st.soh_stores, 0) AS soh_stores, COALESCE(st.soh_warehouse, 0) AS soh_warehouse,
            COALESCE(st.soh_pipeline, 0) AS soh_pipeline
        FROM prod p
        LEFT JOIN sales sa USING (color)
        LEFT JOIN stock st USING (color)
        WHERE COALESCE(sa.units_since_launch, 0) > 0
           OR COALESCE(st.soh_stores, 0) > 0 OR COALESCE(st.soh_warehouse, 0) > 0
           OR COALESCE(st.soh_pipeline, 0) > 0
        """
    ) or []
    today = date.today()
    out = []
    for r in raw:
        units_6m = int(r["units_6m"] or 0)
        sales_6m = float(r["sales_6m"] or 0)
        soh_stores = int(r["soh_stores"] or 0)
        soh_warehouse = int(r["soh_warehouse"] or 0)
        soh_pipeline = int(r["soh_pipeline"] or 0)
        soh_total = soh_stores + soh_warehouse  # pipeline NOT in total SOH
        units_30d = int(r["units_30d"] or 0)
        weekly_avg = round(units_30d / (30.0 / 7.0), 1)
        woc = round(soh_total / weekly_avg, 1) if weekly_avg > 0 else None
        denom = units_6m + soh_total
        units_since_launch = int(r["units_since_launch"] or 0)
        life_denom = units_since_launch + soh_total
        last_sale = r["last_sale"]
        first_sale = r["first_sale"]
        age_days = (today - first_sale).days if first_sale else None
        original_price = r["original_price"]
        units_sel = int(r["units_sel"] or 0)
        sales_sel = float(r["sales_sel"] or 0)
        sel_denom = units_sel + soh_total
        asp_sel = round(sales_sel / units_sel) if units_sel > 0 else None
        op = float(original_price) if original_price is not None else None
        pct_of_full = (
            round(100.0 * asp_sel / op, 1)
            if asp_sel is not None and op and op > 0 else None
        )
        out.append({
            "color": r["color"],
            "sales_6m": round(sales_6m),
            "units_6m": units_6m,
            "units_3w": int(r["units_3w"] or 0),
            "units_since_launch": units_since_launch,
            "weekly_avg": weekly_avg,
            "soh_total": soh_total,
            "soh_wh": soh_warehouse,
            "soh_pipeline": soh_pipeline,
            "woc": woc,
            "pct_in_wh": round(100.0 * soh_warehouse / soh_total, 1) if soh_total else 0.0,
            "asp_6m": round(sales_6m / units_6m) if units_6m > 0 else None,
            "original_price": round(op) if op is not None else None,
            "days_since_last_sale": (today - last_sale).days if last_sale else None,
            "sor_6m": round(100.0 * units_6m / denom, 1) if denom > 0 else None,
            "sor_since_launch": round(100.0 * units_since_launch / life_denom, 1) if life_denom > 0 else None,
            "units_sel": units_sel,
            "sales_sel": round(sales_sel),
            "sor_sel": round(100.0 * units_sel / sel_denom, 1) if sel_denom > 0 else None,
            "asp_sel": asp_sel,
            "pct_of_full": pct_of_full,
            "launch_date": str(first_sale) if first_sale else None,
            "style_age_weeks": round(age_days / 7.0) if age_days is not None else 0,
        })
    out.sort(key=lambda x: -(x["sales_6m"] or 0))
    return out


@app.get("/api/analytics/sor-style-sizes")
def analytics_sor_style_sizes(
    style_name: str = Query(...),
    color: str = Query(...),
    country: str = Query(default=None),
    channel: str = Query(default=None),
    window_days: int = Query(default=180),
    date_from: str = Query(default=None),
    date_to: str = Query(default=None),
):
    """Per-SIZE breakdown for ONE style + colour with the SAME column set as
    /sor-all-styles and /sor-style-colors, so the SOR Report's colour rows can
    drill one level further (style → colour → size) with identical columns.
    Size comes from the product master (all_products_clean.size); sales/stock
    join on SKU only (triad joins are SKU-only)."""
    win = int(window_days) if window_days and int(window_days) > 0 else 180
    sel_from, sel_to = _sor_selected_period(date_from, date_to)
    sn = (style_name or "").strip().replace("'", "''")
    if not sn:
        raise HTTPException(status_code=422, detail="style_name is required")
    col_raw = (color or "").strip()
    if not col_raw:
        raise HTTPException(status_code=422, detail="color is required")
    col = col_raw.replace("'", "''")
    # The colour endpoint maps blank/NULL colour to the '—' placeholder;
    # accept that placeholder back and match the blank/NULL rows.
    color_pred = (
        "COALESCE(NULLIF(TRIM(color_print), ''), '—') = '" + col + "'"
    )
    cf, chf = _style_filters(country, channel, "s")
    raw = run_query(
        """
        WITH prod AS (
            SELECT COALESCE(NULLIF(TRIM(size), ''), '—') AS size,
                mode() WITHIN GROUP (ORDER BY price::numeric) FILTER (WHERE price::numeric > 0) AS original_price
            FROM all_products_clean
            WHERE style_name = '""" + sn + """' AND """ + color_pred + """
            GROUP BY 1
        ),
        skus AS (
            SELECT sku, COALESCE(NULLIF(TRIM(size), ''), '—') AS size
            FROM all_products_clean
            WHERE style_name = '""" + sn + """' AND """ + color_pred + """
              AND sku IS NOT NULL AND sku <> ''
        ),
        sales AS (
            SELECT k.size,
                SUM(s.net_quantity) FILTER (WHERE s.sale_date::date >= CURRENT_DATE - INTERVAL '""" + str(win) + """ days') AS units_6m,
                ROUND(SUM(s.net_sales_kes::numeric) FILTER (WHERE s.sale_date::date >= CURRENT_DATE - INTERVAL '""" + str(win) + """ days')) AS sales_6m,
                SUM(s.net_quantity) FILTER (WHERE s.sale_date::date >= CURRENT_DATE - INTERVAL '21 days') AS units_3w,
                SUM(s.net_quantity) FILTER (WHERE s.sale_date::date >= CURRENT_DATE - INTERVAL '30 days') AS units_30d,
                SUM(s.net_quantity) AS units_since_launch,
                SUM(s.net_quantity) FILTER (WHERE s.sale_date::date BETWEEN '""" + sel_from + """' AND '""" + sel_to + """') AS units_sel,
                ROUND(SUM(s.net_sales_kes::numeric) FILTER (WHERE s.sale_date::date BETWEEN '""" + sel_from + """' AND '""" + sel_to + """')) AS sales_sel,
                MAX(s.sale_date::date) AS last_sale,
                MIN(s.sale_date::date) AS first_sale
            FROM skus k
            JOIN all_sales s ON s.variant_sku = k.sku
            WHERE s.sale_kind IN ('sale','order')
              AND """ + BASE_FILTERS + cf + chf + """
            GROUP BY k.size
        ),
        stock AS (
            SELECT k.size,
                COALESCE(SUM(i.available) FILTER (WHERE i.pos_location_name NOT IN (""" + WAREHOUSE_LOCATIONS + """)), 0) AS soh_stores,
                COALESCE(SUM(i.available) FILTER (WHERE i.pos_location_name = 'Warehouse Finished Goods'), 0) AS soh_warehouse,
                COALESCE(SUM(i.available) FILTER (WHERE i.pos_location_name IN (""" + WAREHOUSE_LOCATIONS + """) AND i.pos_location_name <> 'Finished Goods Production'), 0) AS soh_pipeline
            FROM skus k
            JOIN all_inventory i ON i.sku = k.sku
            GROUP BY k.size
        )
        SELECT p.size, p.original_price,
            COALESCE(sa.units_6m, 0) AS units_6m, COALESCE(sa.sales_6m, 0) AS sales_6m,
            COALESCE(sa.units_3w, 0) AS units_3w, COALESCE(sa.units_30d, 0) AS units_30d,
            COALESCE(sa.units_since_launch, 0) AS units_since_launch,
            COALESCE(sa.units_sel, 0) AS units_sel, COALESCE(sa.sales_sel, 0) AS sales_sel,
            sa.last_sale, sa.first_sale,
            COALESCE(st.soh_stores, 0) AS soh_stores, COALESCE(st.soh_warehouse, 0) AS soh_warehouse,
            COALESCE(st.soh_pipeline, 0) AS soh_pipeline
        FROM prod p
        LEFT JOIN sales sa USING (size)
        LEFT JOIN stock st USING (size)
        WHERE COALESCE(sa.units_since_launch, 0) > 0
           OR COALESCE(st.soh_stores, 0) > 0 OR COALESCE(st.soh_warehouse, 0) > 0
           OR COALESCE(st.soh_pipeline, 0) > 0
        """
    ) or []
    today = date.today()
    out = []
    for r in raw:
        units_6m = int(r["units_6m"] or 0)
        sales_6m = float(r["sales_6m"] or 0)
        soh_stores = int(r["soh_stores"] or 0)
        soh_warehouse = int(r["soh_warehouse"] or 0)
        soh_pipeline = int(r["soh_pipeline"] or 0)
        soh_total = soh_stores + soh_warehouse  # pipeline NOT in total SOH
        units_30d = int(r["units_30d"] or 0)
        weekly_avg = round(units_30d / (30.0 / 7.0), 1)
        woc = round(soh_total / weekly_avg, 1) if weekly_avg > 0 else None
        denom = units_6m + soh_total
        units_since_launch = int(r["units_since_launch"] or 0)
        life_denom = units_since_launch + soh_total
        last_sale = r["last_sale"]
        first_sale = r["first_sale"]
        age_days = (today - first_sale).days if first_sale else None
        original_price = r["original_price"]
        units_sel = int(r["units_sel"] or 0)
        sales_sel = float(r["sales_sel"] or 0)
        sel_denom = units_sel + soh_total
        asp_sel = round(sales_sel / units_sel) if units_sel > 0 else None
        op = float(original_price) if original_price is not None else None
        pct_of_full = (
            round(100.0 * asp_sel / op, 1)
            if asp_sel is not None and op and op > 0 else None
        )
        out.append({
            "size": r["size"],
            "sales_6m": round(sales_6m),
            "units_6m": units_6m,
            "units_3w": int(r["units_3w"] or 0),
            "units_since_launch": units_since_launch,
            "weekly_avg": weekly_avg,
            "soh_total": soh_total,
            "soh_wh": soh_warehouse,
            "soh_pipeline": soh_pipeline,
            "woc": woc,
            "pct_in_wh": round(100.0 * soh_warehouse / soh_total, 1) if soh_total else 0.0,
            "asp_6m": round(sales_6m / units_6m) if units_6m > 0 else None,
            "original_price": round(op) if op is not None else None,
            "days_since_last_sale": (today - last_sale).days if last_sale else None,
            "sor_6m": round(100.0 * units_6m / denom, 1) if denom > 0 else None,
            "sor_since_launch": round(100.0 * units_since_launch / life_denom, 1) if life_denom > 0 else None,
            "units_sel": units_sel,
            "sales_sel": round(sales_sel),
            "sor_sel": round(100.0 * units_sel / sel_denom, 1) if sel_denom > 0 else None,
            "asp_sel": asp_sel,
            "pct_of_full": pct_of_full,
            "launch_date": str(first_sale) if first_sale else None,
            "style_age_weeks": round(age_days / 7.0) if age_days is not None else 0,
        })
    out.sort(key=lambda x: -(x["sales_6m"] or 0))
    return out

# ---------------------------------------------------------------------------
# Product Analysis cockpit — one canonical style-level dataset
# ---------------------------------------------------------------------------
# A single read-only endpoint that returns the CEO-grade style master for the
# selected period + scope, with sales AND current stock BOTH scoped by the
# store/country filter (store-scoped current stock, warehouse-excluded when
# "Overall", is the key fix that makes every figure tie out). Revenue defs
# mirror /api/kpis: revenue = SUM(total_sales_kes for sale/order) -
# SUM(returns_kes for return); net revenue likewise on net_sales_kes; ASP =
# revenue / SUM(ordered_item_quantity for sale/order). NOTE: this cockpit's
# `units` deliberately use SUM(net_quantity) (returns-netted, velocity/
# lifecycle-oriented) and therefore differ by the return volume from the gross
# "units sold" headline (/api/kpis.total_units, country-summary, products),
# which all use SUM(ordered_item_quantity for sale/order) = _UNITS.
# WOC + SOR reuse the shared velocity/sell-out shapes used elsewhere. The
# summary band + by-brand + by-sub-category rollups are derived in Python from
# the SAME canonical rows (rolled up to style grain) so they reconcile with
# the table exactly at any grain.

def _pa_safe_date(s, fallback):
    """Validate a YYYY-MM-DD date param before it is interpolated into SQL.
    The /api date-injection middleware already screens these, but we re-parse
    here as defense in depth (and to apply a sane fallback)."""
    try:
        return str(date.fromisoformat((s or "").strip()))
    except (ValueError, TypeError):
        return fallback


def _pa_in_filter(col, val, lower=False):
    """Build an ` AND col IN (...)` clause from a comma-separated filter value.
    Quotes are doubled so values can't break out of the SQL literal."""
    if not val:
        return ""
    vals = [v.strip() for v in str(val).split(",") if v.strip()]
    if not vals:
        return ""
    if lower:
        joined = ",".join("'" + v.lower().replace("'", "''") + "'" for v in vals)
        return " AND LOWER(" + col + ") IN (" + joined + ")"
    joined = ",".join("'" + v.replace("'", "''") + "'" for v in vals)
    return " AND " + col + " IN (" + joined + ")"


# Fixed primary-colour palette every raw colour string is mapped onto.
_PRIMARY_COLORS = [
    "Black", "White", "Grey", "Beige", "Brown", "Red", "Pink", "Orange",
    "Yellow", "Green", "Blue", "Purple", "Gold", "Silver", "Multi", "Other",
]

# Deterministic keyword map: substring -> primary. Checked before the LLM so the
# common long tail never needs a model call (and the page never breaks if the LLM
# is down). Order matters — more specific phrases first.
_PRIMARY_COLOR_RULES = [
    ("multi", "Multi"), ("print", "Multi"), ("floral", "Multi"), ("animal", "Multi"),
    ("stripe", "Multi"), ("check", "Multi"), ("aztec", "Multi"), ("ankara", "Multi"),
    ("leopard", "Multi"), ("camo", "Multi"), ("assorted", "Multi"), ("mixed", "Multi"),
    ("navy", "Blue"), ("denim", "Blue"), ("indigo", "Blue"), ("teal", "Blue"),
    ("turquoise", "Blue"), ("cobalt", "Blue"), ("aqua", "Blue"), ("sky", "Blue"),
    ("royal", "Blue"), ("blue", "Blue"),
    ("maroon", "Red"), ("burgundy", "Red"), ("wine", "Red"), ("crimson", "Red"),
    ("scarlet", "Red"), ("cherry", "Red"), ("red", "Red"),
    ("fuchsia", "Pink"), ("magenta", "Pink"), ("rose", "Pink"), ("blush", "Pink"),
    ("coral", "Pink"), ("salmon", "Pink"), ("pink", "Pink"),
    ("lavender", "Purple"), ("lilac", "Purple"), ("violet", "Purple"),
    ("plum", "Purple"), ("mauve", "Purple"), ("purple", "Purple"),
    ("rust", "Orange"), ("terracotta", "Orange"), ("apricot", "Orange"),
    ("peach", "Orange"), ("tangerine", "Orange"), ("orange", "Orange"),
    ("mustard", "Yellow"), ("buttermilk", "Yellow"), ("lemon", "Yellow"),
    ("ochre", "Yellow"), ("yellow", "Yellow"),
    ("olive", "Green"), ("mint", "Green"), ("lime", "Green"), ("sage", "Green"),
    ("emerald", "Green"), ("khaki", "Green"), ("green", "Green"),
    ("chocolate", "Brown"), ("tan", "Brown"), ("camel", "Brown"), ("coffee", "Brown"),
    ("mocha", "Brown"), ("caramel", "Brown"), ("bronze", "Brown"), ("brown", "Brown"),
    ("cream", "Beige"), ("ivory", "Beige"), ("nude", "Beige"), ("beige", "Beige"),
    ("taupe", "Beige"), ("sand", "Beige"), ("stone", "Beige"), ("oatmeal", "Beige"),
    ("off white", "Beige"), ("offwhite", "Beige"), ("ecru", "Beige"),
    ("charcoal", "Grey"), ("grey", "Grey"), ("gray", "Grey"), ("silver", "Silver"),
    ("gold", "Gold"), ("white", "White"), ("black", "Black"),
]

_PRIMARY_COLOR_MEM = {}  # in-process cache: raw_lower -> primary


def _primary_color_deterministic(raw):
    low = " " + raw.lower().strip() + " "
    for kw, prim in _PRIMARY_COLOR_RULES:
        if kw in low:
            return prim
    return None


def _primary_color_map(raw_colors):
    """Map a set of distinct raw colour strings to the fixed primary palette.

    Layered: in-process memo -> persistent ``color_primary_map`` table ->
    deterministic keyword rules -> a single batched LLM call for the long tail.
    Newly resolved values are persisted so the LLM is only ever consulted once
    per distinct colour. Never raises: any failure falls back to deterministic /
    'Other' so the endpoint always returns."""
    out = {}
    pending = []
    for raw in raw_colors:
        if not raw:
            continue
        key = raw.strip()
        if not key:
            continue
        low = key.lower()
        if low in _PRIMARY_COLOR_MEM:
            out[key] = _PRIMARY_COLOR_MEM[low]
        else:
            pending.append(key)
    if not pending:
        return out

    # Persistent cache lookup.
    try:
        _users_exec("""
            CREATE TABLE IF NOT EXISTS color_primary_map (
                raw_color     TEXT PRIMARY KEY,
                primary_color TEXT NOT NULL,
                source        TEXT,
                created_at    TIMESTAMPTZ NOT NULL DEFAULT now()
            )""")
        lows = sorted({p.lower() for p in pending})
        joined = ",".join("'" + v.replace("'", "''") + "'" for v in lows)
        cached = _users_exec(
            "SELECT raw_color, primary_color FROM color_primary_map"
            " WHERE raw_color IN (" + joined + ")", fetch=True) or []
        cmap = {r["raw_color"]: r["primary_color"] for r in cached}
    except Exception:
        cmap = {}

    still = []
    for key in pending:
        low = key.lower()
        if low in cmap:
            _PRIMARY_COLOR_MEM[low] = cmap[low]
            out[key] = cmap[low]
        else:
            still.append(key)

    # Deterministic rules resolve most of the remaining tail with no LLM call.
    llm_pending = []
    resolved = {}  # low -> (primary, source)
    for key in still:
        det = _primary_color_deterministic(key)
        if det:
            resolved[key.lower()] = (det, "rule")
            out[key] = det
            _PRIMARY_COLOR_MEM[key.lower()] = det
        else:
            llm_pending.append(key)

    # One batched LLM call for whatever the rules could not place.
    if llm_pending:
        ai = {}
        try:
            sample = llm_pending[:300]
            palette = ", ".join(_PRIMARY_COLORS)
            prompt = (
                "You map retail product colour names to a base colour family. "
                "Allowed families (use EXACTLY one per input): " + palette + ". "
                "Use 'Multi' for prints/patterns/multicolour, 'Other' only if truly none fit. "
                "Return ONLY a compact JSON object mapping each input string to its family.\n"
                "Inputs: " + json.dumps(sample)
            )
            txt = _chat_llm([{"role": "user", "content": prompt}], max_tokens=2000)
            if txt:
                s = txt.find("{")
                e = txt.rfind("}")
                if s != -1 and e != -1 and e > s:
                    parsed = json.loads(txt[s:e + 1])
                    valid = {c.lower(): c for c in _PRIMARY_COLORS}
                    for k, v in parsed.items():
                        vc = valid.get(str(v).strip().lower())
                        if vc:
                            ai[k] = vc
        except Exception:
            ai = {}
        for key in llm_pending:
            prim = ai.get(key) or ai.get(key.lower()) or "Other"
            resolved[key.lower()] = (prim, "llm" if key in ai or key.lower() in ai else "fallback")
            out[key] = prim
            _PRIMARY_COLOR_MEM[key.lower()] = prim

    # Persist everything newly resolved (rules + llm + fallback) so it is cheap
    # next time. Fallback 'Other' is persisted too but tagged so it can be
    # re-derived later if rules improve.
    if resolved:
        try:
            vals = ",".join(
                "('" + low.replace("'", "''") + "','" + prim.replace("'", "''") +
                "','" + src + "')"
                for low, (prim, src) in resolved.items())
            _users_exec(
                "INSERT INTO color_primary_map (raw_color, primary_color, source) VALUES "
                + vals + " ON CONFLICT (raw_color) DO NOTHING")
        except Exception:
            pass
    return out


def _split_colors(s):
    """Split an aggregated colour cell ('Gold, Green') into its tokens."""
    if not s:
        return []
    return [t.strip() for t in str(s).split(",") if t.strip()]


@app.get("/api/analytics/product-analysis")
def analytics_product_analysis(
    date_from: str = Query(default=None),
    date_to: str = Query(default=None),
    country: str = Query(default=None),
    store: str = Query(default=None),
    brand: str = Query(default=None),
    category: str = Query(default=None),
    subcategory: str = Query(default=None),
    tier: str = Query(default=None),
    rev_pct: float = Query(default=None),
    style_status: str = Query(default="all"),
    grain: str = Query(default="style"),
    dims: str = Query(default=None),
    velocity_days: int = Query(default=30),
    include_warehouse: bool = Query(default=False),
):
    df = _pa_safe_date(date_from, str(date.today() - timedelta(days=89)))
    dt = _pa_safe_date(date_to, str(date.today()))
    vel = velocity_days if isinstance(velocity_days, int) and velocity_days > 0 else 30
    vel = min(vel, 3650)
    grain = (grain or "style").strip().lower()
    # Row-explosion model: the table can be exploded to one value per row for any
    # subset of {colour, print, size} via the `dims` CSV param (driven by the
    # column picker). Each selected dimension becomes a GROUP BY key so a style
    # with several colours / prints / sizes returns one row per combination.
    # `grain` (legacy single dimension) is honoured as a fallback for old callers.
    DIM_SPECS = {
        # key -> (output column, source column in all_products_clean / all_inventory)
        "color": ("color", "color_print"),
        "print": ("print_plain", "print_plain"),
        "size": ("size", "size"),
    }
    DIM_ORDER = ["color", "print", "size"]
    if dims is not None:
        req = {x.strip().lower() for x in dims.split(",")} - {""}
    elif grain in ("color", "size"):
        req = {grain}
    else:
        req = set()
    sel_dims = [d for d in DIM_ORDER if d in req]
    # POS location is a special dimension: it does not live on the product master
    # (all_products_clean) but on the sales / inventory rows. When it is exploded
    # the final assembly switches from "prod-driven" joins to a sales⟗stock key
    # spine joined back to prod on style (see from_join below) so a style returns
    # one row per selling point — exactly like colour / print / size.
    pos_exploded = "pos_location" in req
    all_sel = sel_dims + (["pos_location"] if pos_exploded else [])

    style_status = (style_status or "all").strip().lower()
    if style_status not in ("active", "retired", "all"):
        style_status = "all"

    # Response cache: this endpoint runs a heavy lifetime full-scan of all_sales
    # (~1.6M rows). The result is identical for every user and changes slowly, so
    # cache the fully-computed response for 10 min keyed on all filter params.
    # (run_query also caches the SQL, but only ~120s; this keeps the page warm.)
    # The key ALSO carries the inventory snapshot version (_inventory_version):
    # the style universe is stock-driven and all_inventory refreshes every ~5 min,
    # so without it each style_status slice could stay frozen on a DIFFERENT
    # snapshot for up to 10 min — the [active]/[retired] slices then disagree
    # with the [all] summary (and with Range Management, which computes live).
    # Keying on the snapshot keeps every slice coherent with the same data.
    _pa_ck = "pa:" + _inventory_version() + ":" + "|".join(str(x) for x in (
        df, dt, country, store, brand, category, subcategory, tier, rev_pct,
        style_status, grain, ",".join(all_sel), vel, int(include_warehouse)))
    _pa_cached, _pa_fresh = cache_get_swr(_pa_ck)
    if _pa_cached is not None:
        if not _pa_fresh:
            swr_refresh(_pa_ck, lambda: analytics_product_analysis(
                date_from=date_from, date_to=date_to, country=country,
                store=store, brand=brand, category=category,
                subcategory=subcategory, tier=tier, rev_pct=rev_pct,
                style_status=style_status, grain=grain, dims=dims,
                velocity_days=velocity_days,
                include_warehouse=include_warehouse), label="pa")
        return _pa_cached

    cf, chf = _style_filters(country, store, "s")   # sales scope (store -> pos_location_name)
    icf, _ = _style_filters(country, None, "i")      # inventory country scope
    if store:
        current_loc_clause = "i.pos_location_name IN (" + csv_to_sql(store) + ")"
    elif include_warehouse:
        # Explicit "include warehouse" toggle: count stock in EVERY location
        # (retail stores + warehouse / holding locations) in the current scope.
        current_loc_clause = "i.pos_location_name IS NOT NULL"
    else:
        current_loc_clause = "i.pos_location_name NOT IN (" + WAREHOUSE_LOCATIONS + ")"

    brand_pf = _pa_in_filter("brand", brand, lower=True)
    cat_pf = _pa_in_filter("category", category)
    subcat_pf = _pa_in_filter("product_type", subcategory)

    # Build the per-CTE dimension fragments. A selected dim is a group key in
    # prod / sales / stock and a USING join key; the colour / print / size
    # display columns are the group key when selected, else aggregated (colour /
    # print) or NULL (size). all_inventory has no print_plain, so when print is
    # exploded the stock CTE joins all_products_clean by sku (sku is unique there,
    # so no fan-out).
    prod_grp = ""
    sales_dim_sel = sales_dim_grp = ""
    stock_dim_sel = stock_dim_grp = ""
    join_dims = []
    need_stock_pc = False
    for d in sel_dims:
        out, src = DIM_SPECS[d]
        expr_p = "COALESCE(NULLIF(TRIM(" + src + "),''),'(none)')"
        expr_sa = "COALESCE(NULLIF(TRIM(p." + src + "),''),'(none)')"
        if d == "print":
            expr_st = "COALESCE(NULLIF(TRIM(pc.print_plain),''),'(none)')"
            need_stock_pc = True
        elif d == "color":
            # all_inventory.color_print is ~93% NULL and UPPERCASE where present
            # ('BLACK'), so it does NOT match all_products_clean.color_print
            # ('Black'). Joining stock on i.color_print collapses the colour
            # explosion to a handful of '(none)' rows (the "blank Colour" bug).
            # Derive the stock colour from the product master via sku instead, so
            # all three CTEs share one consistent colour key.
            expr_st = "COALESCE(NULLIF(TRIM(pc.color_print),''),'(none)')"
            need_stock_pc = True
        elif d == "size":
            # all_inventory.size is 100% NULL (verified 0 of ~41k rows), so
            # joining stock on i.size collapses every stock row to '(none)',
            # the USING join misses, soh reads 0 and the holds-stock filter
            # drops nearly all rows (the "everything zero when Size is added"
            # bug — same failure mode as colour). Derive size from the product
            # master via sku, like colour/print.
            expr_st = "COALESCE(NULLIF(TRIM(pc.size),''),'(none)')"
            need_stock_pc = True
        else:
            expr_st = "COALESCE(NULLIF(TRIM(i." + src + "),''),'(none)')"
        prod_grp += ", " + expr_p
        sales_dim_sel += ", " + expr_sa + " AS " + out
        sales_dim_grp += ", " + expr_sa
        stock_dim_sel += ", " + expr_st + " AS " + out
        stock_dim_grp += ", " + expr_st
        join_dims.append(out)

    def _disp(key):
        out, src = DIM_SPECS[key]
        if key in sel_dims:
            return "COALESCE(NULLIF(TRIM(" + src + "),''),'(none)') AS " + out
        if key == "color":
            return "string_agg(DISTINCT NULLIF(TRIM(color_print),''), ', ') AS color"
        if key == "print":
            return "string_agg(DISTINCT NULLIF(TRIM(print_plain),''), ', ') AS print_plain"
        return "NULL::text AS size"

    prod_disp = ", " + _disp("color") + ", " + _disp("print") + ", " + _disp("size")
    stock_from = " FROM all_inventory i LEFT JOIN " + SKU_STYLE_MAP + " m ON m.sku = i.sku"
    if need_stock_pc:
        stock_from += " JOIN all_products_clean pc ON pc.sku = i.sku"
    join_keys = " USING (style_name" + ("".join(", " + j for j in join_dims)) + ")"

    # POS explosion: add pos_location_name as a group key in the sales & stock
    # CTEs only (it is not a product attribute), drop warehouse rows from stock so
    # only real selling points become rows, and switch the final FROM to a
    # sales⟗stock spine joined back to prod on style (+ any product dims).
    sales_pos_sel = sales_pos_grp = sales_pos_where = ""
    stock_pos_sel = stock_pos_grp = stock_pos_where = ""
    if pos_exploded:
        sales_pos_sel = ", s.pos_location_name AS pos_location"
        sales_pos_grp = ", s.pos_location_name"
        stock_pos_sel = ", i.pos_location_name AS pos_location"
        stock_pos_grp = ", i.pos_location_name"
        # Only real selling points become rows: drop warehouse / holding locations
        # from stock (current_loc_clause) and from sales (a store filter already
        # restricts sales; otherwise exclude the same warehouse set).
        stock_pos_where = " AND (" + current_loc_clause + ")"
        if not store and not include_warehouse:
            sales_pos_where = " AND s.pos_location_name NOT IN (" + WAREHOUSE_LOCATIONS + ")"
        spine_keys = " USING (style_name" + ("".join(", " + j for j in join_dims)) + ", pos_location)"
        prod_keys = " USING (style_name" + ("".join(", " + j for j in join_dims)) + ")"
        from_join = (" FROM sales sa FULL OUTER JOIN stock st" + spine_keys +
                     " JOIN prod p" + prod_keys)
        pos_out = " pos_location,"
        # Only selling points that currently hold inventory become rows (a style
        # with no stock at a POS is not part of that location's live range).
        activity_where = " WHERE COALESCE(st.soh_current,0) > 0"
    else:
        from_join = (" FROM prod p LEFT JOIN sales sa" + join_keys +
                     " LEFT JOIN stock st" + join_keys)
        pos_out = " st.store_locations AS pos_location,"
        # Only styles that currently hold inventory (stores or warehouse) are in scope.
        # Match RM's universe: styles with stock in stores OR warehouse only.
        # soh_current can include pipeline locations; using soh_stores/soh_warehouse
        # directly excludes pipeline-only styles, aligning the PA style count
        # with the Range Management total (xsurf_pa_vs_rm_total invariant).
        activity_where = (" WHERE (COALESCE(st.soh_stores,0) > 0"
                          " OR COALESCE(st.soh_warehouse,0) > 0)")

    # months_active_12 = the count of DISTINCT calendar months (trailing 365d) in
    # which the style recorded a sale/order. Drives the unified Tier-1 ("NOOS",
    # sold in >= 11 of the last 12 months) gate in _lifecycle_tier. Style-grain,
    # respects the same country/store sales scope (cf/chf) as the sales CTE. It is
    # its own CTE because the pa_style rollup does not materialise it.
    nos_cte = (
        "nos AS ("
        " SELECT p.style_name,"
        " COUNT(DISTINCT to_char(s.sale_date::date,'YYYY-MM')) AS months_active_12"
        " FROM all_products_clean p JOIN all_sales s ON s.variant_sku = p.sku"
        " WHERE p.style_name IS NOT NULL AND p.style_name <> ''"
        " AND s.sale_kind IN ('sale','order')"
        " AND s.sale_date::date >= CURRENT_DATE - INTERVAL '365 days'"
        " AND " + BASE_FILTERS + cf + chf +
        " GROUP BY p.style_name"
        ")"
    )
    from_join += " LEFT JOIN nos ON nos.style_name = p.style_name"

    # The sales CTE is the heavy lifetime full-scan. When the table is NOT exploded
    # by any product dim / POS, is not store-scoped, and uses the default 30-day
    # velocity window, the lifetime / trailing-window measures (units_vel, life,
    # 6m, 24m, current_price) are exactly what the pa_style rollup materialises, so
    # we serve them from the rollup and keep only the cheap date-bounded period
    # measures live. The split: period_sales = a date-bounded live scan (only the
    # df..dt window), life = the rollup re-aggregated per country, FULL OUTER JOINed
    # on style. KES sums are stored unrounded and ROUNDed after re-aggregation so
    # the All total matches the live round-of-sum; current_price merges across
    # countries by most-recent valid-price date (parity-verified except inherent
    # same-date ties). Any explosion / store / non-default velocity → live path.
    pa_use_rollup = (not sel_dims and not pos_exploded and not store
                     and vel == 30 and _rollup_fresh("pa_style"))
    if pa_use_rollup:
        pa_sales_block = (
            "period_sales AS ("
            " SELECT p.style_name,"
            " COALESCE(SUM(s.net_quantity),0) AS units_period,"
            " COALESCE(ROUND(SUM(" + _PA_KES_CASE + ")),0) AS revenue_period,"
            " COALESCE(ROUND(" + NET_SALES_CANON + "),0) AS net_revenue_period,"
            " COALESCE(SUM(" + _PA_GROSS_CASE + "),0) AS gross_units_period,"
            " COUNT(DISTINCT s.order_id) FILTER (WHERE s.sale_kind IN ('sale','order')) AS orders_period"
            " FROM all_products_clean p JOIN all_sales s ON s.variant_sku = p.sku"
            " WHERE p.style_name IS NOT NULL AND p.style_name <> ''"
            " AND COALESCE(p.brand,'') NOT ILIKE '%third party%'"
            " AND s.sale_date BETWEEN '" + df + "' AND '" + dt + "' AND " + BASE_FILTERS + cf + chf +
            " GROUP BY p.style_name"
            "),"
            "life AS ("
            " SELECT style_name,"
            " COALESCE(SUM(units_vel),0) AS units_vel,"
            " SUM(units_life) AS units_life,"
            " COALESCE(ROUND(SUM(sales_life)),0) AS sales_life,"
            " COALESCE(SUM(units_6m),0) AS units_6m,"
            " COALESCE(ROUND(SUM(revenue_6m)),0) AS revenue_6m,"
            " COALESCE(SUM(gross_units_6m),0) AS gross_units_6m,"
            " COALESCE(SUM(units_24m),0) AS units_24m,"
            " COALESCE(ROUND(SUM(revenue_24m)),0) AS revenue_24m,"
            " COALESCE(SUM(gross_units_24m),0) AS gross_units_24m,"
            " MAX(last_sale) AS last_sale,"
            " MIN(first_sale) AS first_sale,"
            " (array_agg(current_price ORDER BY current_price_date DESC NULLS LAST)"
            " FILTER (WHERE current_price IS NOT NULL))[1] AS current_price"
            " FROM rollup_pa_style" + _rollup_country_where(country) +
            " GROUP BY style_name"
            "),"
            "sales AS ("
            " SELECT COALESCE(ps.style_name, life.style_name) AS style_name,"
            " COALESCE(ps.units_period,0) AS units_period, COALESCE(ps.revenue_period,0) AS revenue_period,"
            " COALESCE(ps.net_revenue_period,0) AS net_revenue_period,"
            " COALESCE(ps.gross_units_period,0) AS gross_units_period,"
            " COALESCE(ps.orders_period,0) AS orders_period,"
            " COALESCE(life.units_vel,0) AS units_vel, life.units_life, COALESCE(life.sales_life,0) AS sales_life,"
            " COALESCE(life.units_6m,0) AS units_6m, COALESCE(life.revenue_6m,0) AS revenue_6m,"
            " COALESCE(life.gross_units_6m,0) AS gross_units_6m,"
            " COALESCE(life.units_24m,0) AS units_24m, COALESCE(life.revenue_24m,0) AS revenue_24m,"
            " COALESCE(life.gross_units_24m,0) AS gross_units_24m,"
            " life.last_sale, life.first_sale, life.current_price"
            " FROM period_sales ps FULL OUTER JOIN life ON life.style_name = ps.style_name"
            "),"
        )
    else:
        pa_sales_block = (
            "sales AS ("
            " SELECT p.style_name" + sales_dim_sel + sales_pos_sel + ","
            " COALESCE(SUM(s.net_quantity) FILTER (WHERE s.sale_date BETWEEN '" + df + "' AND '" + dt + "'),0) AS units_period,"
            " COALESCE(ROUND(SUM(CASE WHEN s.sale_kind IN ('sale','order') THEN s.total_sales_kes"
            " WHEN s.sale_kind='return' THEN -s.returns_kes ELSE 0 END)"
            " FILTER (WHERE s.sale_date BETWEEN '" + df + "' AND '" + dt + "')),0) AS revenue_period,"
            " COALESCE(ROUND(SUM(CASE WHEN s.sale_kind IN ('sale','order') THEN (s.total_sales_kes::numeric - s.discounts_kes::numeric) / " + _VAT_DIV +
            " WHEN s.sale_kind='return' THEN -s.returns_kes::numeric / " + _VAT_DIV + " ELSE 0 END)"
            " FILTER (WHERE s.sale_date BETWEEN '" + df + "' AND '" + dt + "')),0) AS net_revenue_period,"
            " COALESCE(SUM(CASE WHEN s.sale_kind IN ('sale','order') THEN s.ordered_item_quantity ELSE 0 END)"
            " FILTER (WHERE s.sale_date BETWEEN '" + df + "' AND '" + dt + "'),0) AS gross_units_period,"
            " COUNT(DISTINCT s.order_id) FILTER (WHERE s.sale_kind IN ('sale','order')"
            " AND s.sale_date BETWEEN '" + df + "' AND '" + dt + "') AS orders_period,"
            " COALESCE(SUM(s.net_quantity) FILTER (WHERE s.sale_date::date >= CURRENT_DATE - INTERVAL '" + str(vel) + " days'),0) AS units_vel,"
            " SUM(s.net_quantity) AS units_life,"
            " COALESCE(ROUND(SUM(CASE WHEN s.sale_kind IN ('sale','order') THEN s.total_sales_kes WHEN s.sale_kind='return' THEN -s.returns_kes ELSE 0 END)),0) AS sales_life,"
            " COALESCE(SUM(s.net_quantity) FILTER (WHERE s.sale_date::date >= CURRENT_DATE - INTERVAL '180 days'),0) AS units_6m,"
            " COALESCE(ROUND(SUM(CASE WHEN s.sale_kind IN ('sale','order') THEN s.total_sales_kes WHEN s.sale_kind='return' THEN -s.returns_kes ELSE 0 END) FILTER (WHERE s.sale_date::date >= CURRENT_DATE - INTERVAL '180 days')),0) AS revenue_6m,"
            " COALESCE(SUM(CASE WHEN s.sale_kind IN ('sale','order') THEN s.ordered_item_quantity ELSE 0 END) FILTER (WHERE s.sale_date::date >= CURRENT_DATE - INTERVAL '180 days'),0) AS gross_units_6m,"
            " COALESCE(SUM(s.net_quantity) FILTER (WHERE s.sale_date::date >= CURRENT_DATE - INTERVAL '730 days'),0) AS units_24m,"
            " COALESCE(ROUND(SUM(CASE WHEN s.sale_kind IN ('sale','order') THEN s.total_sales_kes WHEN s.sale_kind='return' THEN -s.returns_kes ELSE 0 END) FILTER (WHERE s.sale_date::date >= CURRENT_DATE - INTERVAL '730 days')),0) AS revenue_24m,"
            " COALESCE(SUM(CASE WHEN s.sale_kind IN ('sale','order') THEN s.ordered_item_quantity ELSE 0 END) FILTER (WHERE s.sale_date::date >= CURRENT_DATE - INTERVAL '730 days'),0) AS gross_units_24m,"
            " MAX(s.sale_date::date) AS last_sale,"
            " MIN(s.sale_date::date) FILTER (WHERE s.sale_kind IN ('sale','order')) AS first_sale,"
            " (array_agg(s.product_price_kes ORDER BY s.sale_date DESC) FILTER ("
            " WHERE s.sale_kind IN ('sale','order') AND s.product_price_kes IS NOT NULL"
            " AND s.product_price_kes > 0))[1] AS current_price"
            " FROM all_products_clean p JOIN all_sales s ON s.variant_sku = p.sku"
            " WHERE p.style_name IS NOT NULL AND p.style_name <> ''"
            " AND COALESCE(p.brand,'') NOT ILIKE '%third party%' AND " + BASE_FILTERS + cf + chf + sales_pos_where +
            " GROUP BY p.style_name" + sales_dim_grp + sales_pos_grp +
            "),"
        )

    sql = (
        "WITH prod AS ("
        " SELECT style_name,"
        " MAX(brand) AS brand, MAX(category) AS category, MAX(product_type) AS subcategory,"
        " MAX(collection) AS collection, MAX(season) AS season,"
        " mode() WITHIN GROUP (ORDER BY style_number) AS style_number,"
        # full_price = the MODAL (most common) positive ticket price across the
        # style's SKUs, NOT MAX(price). The product master occasionally carries a
        # foreign-currency leak on a few country SKUs (the KES price duplicated in
        # local currency, e.g. one SKU at 181,000), which MAX would surface as the
        # "full price". The mode is immune to a handful of contaminated rows.
        " mode() WITHIN GROUP (ORDER BY price) FILTER (WHERE price > 0) AS full_price,"
        " MIN(price) FILTER (WHERE price > 0) AS price_min, MAX(price) AS price_max,"
        " MIN(substring(style_launch_date,1,10)) FILTER ("
        " WHERE substring(style_launch_date,1,10) ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$') AS launch_date,"
        " COUNT(DISTINCT NULLIF(TRIM(size),'')) AS sizes_count,"
        " COUNT(DISTINCT NULLIF(TRIM(color_print),'')) AS colors_count,"
        # Representative SKU for the row's product image. Prefer a SKU that
        # actually has an image (Odoo image_512 OR a Shopify image URL, matched
        # V-prefix-insensitively the same way the image endpoints expand), so a
        # style/colour with photos never shows a placeholder just because the
        # alphabetically-first SKU happens to lack one. Deterministic MIN(sku)
        # tiebreak keeps the choice stable.
        " (array_agg(sku ORDER BY (im.norm_sku IS NOT NULL) DESC, sku ASC))[1] AS rep_sku"
        + prod_disp +
        " FROM all_products_clean"
        " LEFT JOIN (SELECT DISTINCT norm_sku FROM ("
        "   SELECT regexp_replace(m.sku,'^[Vv]','') AS norm_sku"
        "     FROM product_image_map m JOIN product_images i ON i.tmpl_id = m.tmpl_id"
        "     WHERE i.image_512 IS NOT NULL AND i.image_512 <> ''"
        "   UNION"
        "   SELECT regexp_replace(sku,'^[Vv]','') AS norm_sku FROM product_image_urls"
        " ) z) im ON im.norm_sku = regexp_replace(sku,'^[Vv]','')"
        " WHERE style_name IS NOT NULL AND style_name <> ''"
        " AND COALESCE(brand,'') NOT ILIKE '%third party%'" + brand_pf + cat_pf + subcat_pf +
        " GROUP BY style_name" + prod_grp +
        "),"
        + pa_sales_block +
        "stock AS ("
        " SELECT COALESCE(m.style_name, i.style_name) AS style_name" + stock_dim_sel + stock_pos_sel + ","
        " COALESCE(SUM(i.available) FILTER (WHERE " + current_loc_clause + "),0) AS soh_current,"
        " COALESCE(SUM(i.available) FILTER (WHERE i.pos_location_name = 'Warehouse Finished Goods'),0) AS soh_warehouse,"
        " COALESCE(SUM(i.available) FILTER (WHERE i.pos_location_name IN (" + WAREHOUSE_LOCATIONS + ") AND i.pos_location_name <> 'Finished Goods Production'),0) AS soh_pipeline,"
        " COALESCE(SUM(i.available) FILTER (WHERE i.pos_location_name NOT IN (" + WAREHOUSE_LOCATIONS + ")),0) AS soh_stores,"
        " string_agg(DISTINCT i.pos_location_name, ', ' ORDER BY i.pos_location_name)"
        " FILTER (WHERE i.available > 0 AND (" + current_loc_clause + ")) AS store_locations"
        + stock_from + " WHERE COALESCE(m.style_name, i.style_name) IS NOT NULL AND COALESCE(m.style_name, i.style_name) <> ''" + icf + stock_pos_where +
        " GROUP BY 1" + stock_dim_grp + stock_pos_grp +
        "),"
        + nos_cte +
        " SELECT p.style_name, p.rep_sku,"
        " p.brand, p.category, p.subcategory, p.collection, p.season, p.style_number,"
        " p.color, p.print_plain, p.size,"
        " p.full_price, p.price_min, p.price_max, p.launch_date, p.sizes_count, p.colors_count,"
        " COALESCE(sa.units_period,0) AS units_period, COALESCE(sa.revenue_period,0) AS revenue_period,"
        " COALESCE(sa.net_revenue_period,0) AS net_revenue_period, COALESCE(sa.gross_units_period,0) AS gross_units_period,"
        " COALESCE(sa.orders_period,0) AS orders_period, COALESCE(sa.units_vel,0) AS units_vel,"
        " COALESCE(sa.units_life,0) AS units_life, COALESCE(sa.sales_life,0) AS sales_life,"
        " COALESCE(sa.units_6m,0) AS units_6m, COALESCE(sa.revenue_6m,0) AS revenue_6m, COALESCE(sa.gross_units_6m,0) AS gross_units_6m,"
        " COALESCE(sa.units_24m,0) AS units_24m, COALESCE(sa.revenue_24m,0) AS revenue_24m, COALESCE(sa.gross_units_24m,0) AS gross_units_24m,"
        " sa.last_sale, sa.first_sale,"
        " COALESCE(st.soh_current,0) AS soh_current, COALESCE(st.soh_warehouse,0) AS soh_warehouse,"
        " COALESCE(st.soh_pipeline,0) AS soh_pipeline,"
        " COALESCE(st.soh_stores,0) AS soh_stores," + pos_out + " sa.current_price,"
        " COALESCE(nos.months_active_12,0) AS months_active_12"
        + from_join + activity_where
    )

    raw = run_query(sql)
    today = date.today()
    wk = vel / 7.0

    def _woc(stock, uvel):
        wa = (uvel / wk) if wk > 0 else 0
        return round(stock / wa, 1) if wa > 0 else None

    def _sor(units, stock):
        denom = units + stock
        return round(units * 100.0 / denom, 1) if denom > 0 else None

    def _life_cycle(tier):
        # Descriptive word for the UNIFIED lifecycle tier (_lifecycle_tier) — the
        # same no-SOR, dashboard-wide model as Range Management (Retired = manual
        # list / Zoya; Tier 1..4 by NOOS-consistency / reorder cycles). Mapped to
        # words so it is not confused with the Pareto revenue "Tier" column.
        return {
            "Tier 1": "Core",
            "Tier 2": "Core Performer",
            "Tier 3": "Recent Performer",
            "Tier 4": "New / Test",
            "Retired": "Retired",
        }.get(tier, "New / Test")

    rows = []
    for r in raw:
        units = int(r["units_period"] or 0)
        revenue = float(r["revenue_period"] or 0)
        net_rev = float(r["net_revenue_period"] or 0)
        gross_units = int(r["gross_units_period"] or 0)
        units_vel = int(r["units_vel"] or 0)
        units_life = int(r["units_life"] or 0)
        months_active_12 = int(r["months_active_12"] or 0)
        stock = int(r["soh_current"] or 0)
        first_sale = r["first_sale"]
        launch = _parse_iso_date(r["launch_date"]) or first_sale
        age_weeks = round((today - launch).days / 7.0) if launch else None
        full_price = round(float(r["full_price"])) if r["full_price"] is not None else None
        current_price = round(float(r["current_price"])) if r["current_price"] is not None else None
        asp = round(revenue / gross_units) if gross_units > 0 else None
        units_6m = int(r["units_6m"] or 0)
        revenue_6m = float(r["revenue_6m"] or 0)
        gross_units_6m = int(r["gross_units_6m"] or 0)
        units_24m = int(r["units_24m"] or 0)
        revenue_24m = float(r["revenue_24m"] or 0)
        gross_units_24m = int(r["gross_units_24m"] or 0)
        sales_life = float(r["sales_life"] or 0)
        asp_6m = round(revenue_6m / gross_units_6m) if gross_units_6m > 0 else None
        asp_24m = round(revenue_24m / gross_units_24m) if gross_units_24m > 0 else None
        avg_price_life = round(sales_life / units_life) if units_life > 0 else None
        # Full Price % = lifetime avg selling price ÷ full ticket price (capped at
        # 100), matching the Range Management report's definition.
        full_price_pct = round(min(100.0, avg_price_life * 100.0 / full_price), 1) \
            if (avg_price_life is not None and full_price not in (None, 0)) else None
        days_since_launch = (today - launch).days if launch else None
        weeks_since_launch = round(days_since_launch / 7.0) if days_since_launch is not None else None
        age_years = round(days_since_launch / 365.25, 1) if days_since_launch is not None else None
        units_per_week = round(units_vel / wk, 1) if wk > 0 else None
        reorder_count = int(age_weeks // 12) if age_weeks else 0
        price_min = round(float(r["price_min"])) if r["price_min"] is not None else None
        price_max = round(float(r["price_max"])) if r["price_max"] is not None else None
        # The displayed "Price Range" top comes from MAX(price), which a
        # foreign-currency-leaked SKU can inflate (e.g. 181,000). full_price
        # already uses the modal price; clamp a grossly-outlying price_max to it
        # so the range never surfaces a local-currency outlier either.
        if full_price and price_max and price_max > full_price * 3:
            price_max = full_price
        sor_6m = _sor(units_6m, stock)
        life_cycle = _life_cycle(_lifecycle_tier(
            r["style_name"], r["brand"], age_weeks, reorder_count, months_active_12))
        rows.append({
            "style_name": r["style_name"],
            "sku": r["rep_sku"],
            "style_number": r["style_number"],
            "brand": r["brand"],
            "category": r["category"],
            "subcategory": r["subcategory"],
            "color": r["color"],
            "print": r["print_plain"],
            "size": r["size"],
            "collection": r["collection"],
            "season": r["season"],
            "units_sold": units,
            "gross_units_period": gross_units,
            "revenue": round(revenue),
            "net_revenue": round(net_rev),
            "orders": int(r["orders_period"] or 0),
            "current_stock": stock,
            "warehouse_stock": int(r["soh_warehouse"] or 0),
            "pipeline_stock": int(r["soh_pipeline"] or 0),
            "store_stock": int(r["soh_stores"] or 0),
            "pos_location": r["pos_location"] or None,
            "units_vel": units_vel,
            "units_life": units_life,
            "woc": _woc(stock, units_vel),
            "sor": _sor(units, stock),
            "sor_since_launch": _sor(units_life, stock),
            "asp": asp,
            "full_price": full_price,
            "current_price": current_price,
            "launch_date": str(launch) if launch else None,
            "age_weeks": age_weeks,
            "age_years": age_years,
            "days_since_launch": days_since_launch,
            "weeks_since_launch": weeks_since_launch,
            "units_per_week": units_per_week,
            "reorder_count": reorder_count,
            "life_cycle": life_cycle,
            "units_6m": units_6m,
            "revenue_6m": round(revenue_6m),
            "asp_6m": asp_6m,
            "sor_6m": sor_6m,
            "units_24m": units_24m,
            "revenue_24m": round(revenue_24m),
            "asp_24m": asp_24m,
            "sales_life": round(sales_life),
            "avg_price_life": avg_price_life,
            "full_price_pct": full_price_pct,
            "price_min": price_min,
            "price_max": price_max,
            "last_sale": str(r["last_sale"]) if r["last_sale"] else None,
            "sizes_count": int(r["sizes_count"] or 0),
            "colors_count": int(r["colors_count"] or 0),
            "months_active_12": months_active_12,
        })

    # Roll the (possibly dim-grain) rows up to STYLE grain so the status filter
    # and the summary/by-brand/by-subcategory rollups are computed consistently
    # and reconcile with the table at any grain.
    styles = {}
    for row in rows:
        k = row["style_name"]
        g = styles.get(k)
        if not g:
            g = {"units": 0, "gross_units_period": 0, "revenue": 0, "net_revenue": 0, "stock": 0, "units_vel": 0,
                 "units_life": 0, "units_6m": 0, "sales_life": 0, "months_active_12": 0,
                 "age_weeks": None, "full_price": None, "last_sale": None,
                 "brand": row["brand"], "category": row["category"], "subcategory": row["subcategory"]}
            styles[k] = g
        g["units"] += row["units_sold"]
        g["gross_units_period"] += row["gross_units_period"]
        g["revenue"] += row["revenue"]
        g["net_revenue"] += row["net_revenue"]
        g["stock"] += row["current_stock"]
        g["units_vel"] += row["units_vel"]
        g["units_life"] += row["units_life"] or 0
        g["units_6m"] += row["units_6m"] or 0
        g["sales_life"] += row["sales_life"] or 0
        # months_active_12 is a style-level constant (same across dim rows).
        g["months_active_12"] = max(g["months_active_12"], row.get("months_active_12") or 0)
        # age_weeks / full_price are style-level constants (same across dim rows);
        # last_sale we carry as the most-recent across dim rows. These feed the
        # style-grain lifecycle gate below.
        if row["age_weeks"] is not None:
            g["age_weeks"] = row["age_weeks"] if g["age_weeks"] is None else max(g["age_weeks"], row["age_weeks"])
        if row["full_price"] is not None:
            g["full_price"] = row["full_price"] if g["full_price"] is None else max(g["full_price"], row["full_price"])
        if row["last_sale"] is not None:
            g["last_sale"] = row["last_sale"] if g["last_sale"] is None else max(g["last_sale"], row["last_sale"])

    # Active vs Retired + the displayed Tier both come from the UNIFIED
    # _lifecycle_tier model shared with Range Management (Retired = manual list /
    # Zoya only; Tier 1..4 by NOOS-consistency / reorder cycles). Every style in
    # the (inventory-only) universe gets exactly one bucket, so Active [Tier 1..4]
    # + Retired == Total. A manual tier override (_RANGE_OVERRIDES, Tier 1..4 only)
    # re-buckets within the active range, exactly like Range Management.
    # "Actively selling" (units_vel > 0) is a separate overlay, NOT part of the
    # Active/Retired partition.
    keep = set()
    status_by_style = {}
    selling_by_style = {}
    tier_by_style = {}
    for k, g in styles.items():
        aw = g["age_weeks"]
        rc = int(aw // 12) if aw else 0
        t = _lifecycle_tier(k, g["brand"], aw, rc, g.get("months_active_12", 0))
        if t != "Retired":
            ov = _RANGE_OVERRIDES.get(k)
            ov_tier = ov["tier"] if (ov and ov.get("tier") in
                                     ("Tier 1", "Tier 2", "Tier 3", "Tier 4")) else None
            if ov_tier:
                t = ov_tier
        retired = (t == "Retired")
        status_by_style[k] = "Retired" if retired else "Active"
        tier_by_style[k] = t
        g["tier"] = t
        selling_by_style[k] = g["gross_units_period"] > 0
        if style_status == "active" and retired:
            continue
        if style_status == "retired" and not retired:
            continue
        keep.add(k)

    rows = [r for r in rows if r["style_name"] in keep]
    for r in rows:
        r["style_status"] = status_by_style.get(r["style_name"])
        r["tier"] = tier_by_style.get(r["style_name"])
        # Keep the Life Cycle word in lockstep with the final (possibly
        # override-adjusted) unified tier so the two columns never disagree.
        r["life_cycle"] = _life_cycle(tier_by_style.get(r["style_name"]))
    kept = {k: g for k, g in styles.items() if k in keep}

    # Tier filter — the unified lifecycle Tier 1..4 / Retired. Legacy "T1".."T4"
    # callers are aliased to the new labels so old bookmarks keep working.
    _tier_alias = {"T1": "Tier 1", "T2": "Tier 2", "T3": "Tier 3", "T4": "Tier 4",
                   "RETIRED": "Retired"}
    tier_sel = {x.strip() for x in str(tier).split(",")} - {""} if tier else set()
    tier_sel = {_tier_alias.get(x.upper(), x) for x in tier_sel}
    if tier_sel:
        rows = [r for r in rows if (r.get("tier") in tier_sel)]
        kept = {k: g for k, g in kept.items() if tier_by_style.get(k) in tier_sel}

    # Separate "top revenue contributors" Pareto filter (rev_pct): keep the
    # smallest set of highest-revenue styles whose cumulative revenue reaches
    # rev_pct% of the current selection's total (always keeps at least the #1
    # style). Applied AFTER the tier filter so the two compose.
    if rev_pct is not None:
        thr = max(0.0, min(100.0, float(rev_pct))) / 100.0
        ranked = sorted(kept.items(), key=lambda kv: -(kv[1]["revenue"] or 0))
        tot_rev_all = sum((g["revenue"] or 0) for _, g in ranked)
        pareto_keep = set()
        cum = 0.0
        for k, g in ranked:
            cum += (g["revenue"] or 0)
            pareto_keep.add(k)
            share = (cum / tot_rev_all) if tot_rev_all > 0 else 1.0
            if share >= thr:
                break
        rows = [r for r in rows if r["style_name"] in pareto_keep]
        kept = {k: g for k, g in kept.items() if k in pareto_keep}

    tot_units = sum(g["units"] for g in kept.values())
    tot_rev = sum(g["revenue"] for g in kept.values())
    tot_net = sum(g["net_revenue"] for g in kept.values())
    tot_stock = sum(g["stock"] for g in kept.values())
    tot_vel = sum(g["units_vel"] for g in kept.values())

    # Canonical Net Sales for the SAME date/country/store window over ALL sales
    # (no product-master join, no style scoping) — identical to /api/kpis
    # net_sales so the PA header ties out to Overview / Margin / Sales Export to
    # the shilling. Only meaningful when the style universe is NOT narrowed
    # (brand / category / subcategory / tier / pareto / status all default);
    # otherwise omitted (None) and the UI falls back to the styles-scope sum.
    net_revenue_canonical = None
    units_canonical = None
    if (not brand and not category and not subcategory and not tier
            and rev_pct is None and style_status == "all"):
        try:
            _canon_where = build_filters(df, dt, country, store)
            _canon_rows = run_query(
                "SELECT ROUND(" + NET_SALES_CANON + ", 0) AS net, "
                + _UNITS + " AS units FROM all_sales s WHERE " + _canon_where,
                date_to=dt)
            if _canon_rows and _canon_rows[0].get("net") is not None:
                net_revenue_canonical = float(_canon_rows[0]["net"])
            if _canon_rows and _canon_rows[0].get("units") is not None:
                units_canonical = int(_canon_rows[0]["units"])
        except Exception:
            net_revenue_canonical = None
            units_canonical = None

    summary = {
        "styles": len(kept),
        # Lifecycle status counts over the kept set (Active + Retired == styles).
        "active_styles": sum(1 for k in kept if status_by_style.get(k) == "Active"),
        "retired_styles": sum(1 for k in kept if status_by_style.get(k) == "Retired"),
        # Overlay (NOT part of the Active/Retired partition): styles that sold at
        # least one unit within the velocity window, scoped to the kept set — so
        # with Retired selected this is "retired styles that still sold".
        "actively_selling": sum(1 for k in kept if selling_by_style.get(k)),
        "units": tot_units,
        # Canonical Units Sold over the full window scope (same query as
        # /api/analytics/canonical-units-sold); None when the style universe is
        # narrowed and equality is not expected. Lets the UI quantify the gap
        # between the styles-scope units sum and the company-wide headline.
        "units_canonical": units_canonical,
        "revenue": tot_rev,
        "net_revenue": tot_net,
        # Canonical Net Sales over the full window scope (see above); None when
        # the style universe is narrowed and equality is not expected.
        "net_revenue_canonical": net_revenue_canonical,
        "stock_units": tot_stock,
        "avg_sor": _sor(tot_units, tot_stock),
        "avg_woc": _woc(tot_stock, tot_vel),
    }

    brands_map = {}
    for g in kept.values():
        b = g["brand"] or "Unknown"
        bb = brands_map.setdefault(b, {"brand": b, "styles": 0, "units": 0, "revenue": 0, "stock": 0, "units_vel": 0})
        bb["styles"] += 1
        bb["units"] += g["units"]
        bb["revenue"] += g["revenue"]
        bb["stock"] += g["stock"]
        bb["units_vel"] += g["units_vel"]
    by_brand = []
    for bb in brands_map.values():
        bb["sor"] = _sor(bb["units"], bb["stock"])
        bb["woc"] = _woc(bb["stock"], bb["units_vel"])
        by_brand.append(bb)
    by_brand.sort(key=lambda x: -x["revenue"])

    total_styles = len(kept) or 1
    sub_map = {}
    for g in kept.values():
        sc = g["subcategory"] or "Unknown"
        ss = sub_map.setdefault(sc, {"subcategory": sc, "category": g["category"], "styles": 0,
                                     "units": 0, "revenue": 0, "stock": 0, "units_vel": 0})
        ss["styles"] += 1
        ss["units"] += g["units"]
        ss["revenue"] += g["revenue"]
        ss["stock"] += g["stock"]
        ss["units_vel"] += g["units_vel"]
    by_subcategory = []
    for ss in sub_map.values():
        ss["pct_range"] = round(ss["styles"] * 100.0 / total_styles, 1)
        ss["pct_stock"] = round(ss["stock"] * 100.0 / tot_stock, 1) if tot_stock else 0.0
        ss["pct_units"] = round(ss["units"] * 100.0 / tot_units, 1) if tot_units else 0.0
        ss["pct_revenue"] = round(ss["revenue"] * 100.0 / tot_rev, 1) if tot_rev else 0.0
        ss["woc"] = _woc(ss["stock"], ss["units_vel"])
        by_subcategory.append(ss)
    by_subcategory.sort(key=lambda x: -x["revenue"])

    # Primary colour (AI-assisted): map each row's raw colour string(s) onto a
    # fixed base palette. Done over the final kept rows so we only classify the
    # colours actually returned. Results are cached so the LLM is consulted at
    # most once per distinct colour ever.
    try:
        tokens = set()
        for r in rows:
            for t in _split_colors(r.get("color")):
                tokens.add(t)
        cmap = _primary_color_map(tokens) if tokens else {}
        for r in rows:
            prims = []
            for t in _split_colors(r.get("color")):
                p = cmap.get(t) or cmap.get(t.strip())
                if p and p not in prims:
                    prims.append(p)
            r["primary_color"] = ", ".join(prims) if prims else None
    except Exception:
        for r in rows:
            r.setdefault("primary_color", None)

    resp = {
        "rows": rows,
        "summary": summary,
        "by_brand": by_brand,
        "by_subcategory": by_subcategory,
        "scope": {
            "store": store or None, "country": country or None,
            "date_from": df, "date_to": dt, "velocity_days": vel,
            "grain": grain, "dims": ",".join(all_sel), "style_status": style_status,
        },
    }
    cache_set(_pa_ck, resp, ttl=600)
    return resp


@app.get("/api/analytics/product-analysis/style")
def analytics_product_analysis_style(
    style: str = Query(...),
    date_from: str = Query(default=None),
    date_to: str = Query(default=None),
    country: str = Query(default=None),
    store: str = Query(default=None),
):
    """Per-style drill-down: size breakdown, colour breakdown, and current stock
    by store location ("what's sitting where"). Sales are period/scope-scoped;
    the location view shows ALL locations (country-scoped) so transfers can be
    reasoned about, with the warehouse flagged."""
    df = _pa_safe_date(date_from, str(date.today() - timedelta(days=89)))
    dt = _pa_safe_date(date_to, str(date.today()))
    st_lit = "'" + (style or "").replace("'", "''") + "'"
    cf, chf = _style_filters(country, store, "s")
    icf, _ = _style_filters(country, None, "i")
    if store:
        current_loc_clause = "i.pos_location_name IN (" + csv_to_sql(store) + ")"
    else:
        current_loc_clause = "i.pos_location_name NOT IN (" + WAREHOUSE_LOCATIONS + ")"

    def _dim_break(dim_col):
        return run_query(
            "WITH sales AS ("
            " SELECT COALESCE(NULLIF(TRIM(p." + dim_col + "),''),'(none)') AS k,"
            " COALESCE(SUM(s.net_quantity) FILTER (WHERE s.sale_date BETWEEN '" + df + "' AND '" + dt + "'),0) AS units,"
            " COALESCE(ROUND(SUM(CASE WHEN s.sale_kind IN ('sale','order') THEN s.net_sales_kes"
            " WHEN s.sale_kind='return' THEN -s.returns_kes ELSE 0 END)"
            " FILTER (WHERE s.sale_date BETWEEN '" + df + "' AND '" + dt + "')),0) AS revenue"
            " FROM all_products_clean p JOIN all_sales s ON s.variant_sku = p.sku"
            " WHERE p.style_name = " + st_lit + " AND " + BASE_FILTERS + cf + chf +
            " GROUP BY 1"
            "), stock AS ("
            " SELECT COALESCE(NULLIF(TRIM(p2." + dim_col + "),''),'(none)') AS k,"
            " COALESCE(SUM(i.available) FILTER (WHERE " + current_loc_clause + "),0) AS stock"
            " FROM all_inventory i JOIN all_products_clean p2 ON p2.sku = i.sku"
            " WHERE p2.style_name = " + st_lit + icf +
            " GROUP BY 1"
            ") SELECT COALESCE(sa.k, st.k) AS k, COALESCE(sa.units,0) AS units,"
            " COALESCE(sa.revenue,0) AS revenue, COALESCE(st.stock,0) AS stock"
            " FROM sales sa FULL OUTER JOIN stock st USING (k)"
            " ORDER BY units DESC, stock DESC"
        )

    by_size = [{"size": x["k"], "units": int(x["units"] or 0),
                "revenue": int(float(x["revenue"] or 0)), "stock": int(x["stock"] or 0)}
               for x in _dim_break("size")]
    by_color = [{"color": x["k"], "units": int(x["units"] or 0),
                 "revenue": int(float(x["revenue"] or 0)), "stock": int(x["stock"] or 0)}
                for x in _dim_break("color_print")]

    loc = run_query(
        "WITH stock AS ("
        " SELECT i.pos_location_name AS location, MAX(i.country) AS country,"
        " COALESCE(SUM(i.available),0) AS stock"
        " FROM all_inventory i JOIN all_products_clean p2 ON p2.sku = i.sku"
        " WHERE p2.style_name = " + st_lit + icf +
        " GROUP BY i.pos_location_name"
        "), sales AS ("
        " SELECT s.pos_location_name AS location,"
        " COALESCE(SUM(s.net_quantity) FILTER (WHERE s.sale_date BETWEEN '" + df + "' AND '" + dt + "'),0) AS units,"
        " COALESCE(ROUND(SUM(CASE WHEN s.sale_kind IN ('sale','order') THEN s.net_sales_kes"
        " WHEN s.sale_kind='return' THEN -s.returns_kes ELSE 0 END)"
        " FILTER (WHERE s.sale_date BETWEEN '" + df + "' AND '" + dt + "')),0) AS revenue"
        " FROM all_products_clean p JOIN all_sales s ON s.variant_sku = p.sku"
        " WHERE p.style_name = " + st_lit + " AND " + BASE_FILTERS + cf +
        " GROUP BY s.pos_location_name"
        ") SELECT COALESCE(st.location, sa.location) AS location,"
        " st.country AS country,"
        " COALESCE(st.stock,0) AS stock,"
        " COALESCE(sa.units,0) AS units,"
        " COALESCE(sa.revenue,0) AS revenue,"
        " (COALESCE(st.location, sa.location) IN (" + WAREHOUSE_LOCATIONS + ")) AS is_warehouse"
        " FROM stock st FULL OUTER JOIN sales sa ON st.location = sa.location"
        " WHERE COALESCE(st.stock,0) <> 0 OR COALESCE(sa.units,0) <> 0 OR COALESCE(sa.revenue,0) <> 0"
        " ORDER BY units DESC, stock DESC"
    )
    by_location = [{"location": x["location"], "country": x["country"],
                    "stock": int(x["stock"] or 0), "units": int(x["units"] or 0),
                    "revenue": int(float(x["revenue"] or 0)),
                    "is_warehouse": bool(x["is_warehouse"])}
                   for x in loc]

    return {
        "style": style,
        "by_size": by_size,
        "by_color": by_color,
        "by_location": by_location,
        "scope": {"store": store or None, "country": country or None, "date_from": df, "date_to": dt},
    }


def _product_ai_core(body):
    """Grounded "what to act on" narrative for the Product Analysis range. The
    client posts the canonical summary + a few short lists (overstock / top
    sellers / slow movers) computed from the same rows; we format the facts and
    ask the LLM for a concise executive read. Plain text, never JSON."""
    scope = str(body.get("scope_label") or "the range").strip()[:120]
    date_label = str(body.get("date_label") or "").strip()[:80]
    s = body.get("summary") or {}

    def _g(k):
        try:
            v = s.get(k)
            return None if v is None else float(v)
        except (TypeError, ValueError):
            return None

    def _money(v):
        return "KES %s" % format(round(v), ",") if v is not None else "n/a"

    def _num(v):
        return format(round(v), ",") if v is not None else "n/a"

    def _lst(items, fmt):
        out = []
        for it in (items or [])[:8]:
            try:
                out.append(fmt(it))
            except (TypeError, ValueError, KeyError, AttributeError):
                continue
        return "; ".join(out) if out else "none"

    overstock = _lst(
        body.get("overstock"),
        lambda it: "%s (WOC %s, %s units stock)" % (
            str(it.get("style_name") or it.get("style") or "")[:48],
            ("%.0f" % float(it.get("woc"))) if it.get("woc") is not None else "n/a",
            _num(float(it.get("current_stock") or it.get("stock") or 0)),
        ),
    )
    top_sellers = _lst(
        body.get("top_sellers"),
        lambda it: "%s (%s units, %s)" % (
            str(it.get("style_name") or it.get("style") or "")[:48],
            _num(float(it.get("units_sold") or it.get("units") or 0)),
            _money(float(it.get("revenue") or 0)),
        ),
    )
    slow = _lst(
        body.get("slow_movers"),
        lambda it: "%s (SOR %s%%, %s units stock)" % (
            str(it.get("style_name") or it.get("style") or "")[:48],
            ("%.0f" % float(it.get("sor"))) if it.get("sor") is not None else "n/a",
            _num(float(it.get("current_stock") or it.get("stock") or 0)),
        ),
    )

    facts = (
        "Scope: %s. Period: %s.\n"
        "Range summary: %s active styles, %s units sold, %s revenue, %s units of current stock, "
        "average sell-out rate %s%%, average weeks-of-cover %s.\n"
        "Overstocked (high weeks-of-cover): %s.\n"
        "Top sellers: %s.\n"
        "Slow movers (low sell-out, stock on hand): %s."
    ) % (
        scope, date_label or "selected period",
        _num(_g("active_styles") if _g("active_styles") is not None else _g("styles")),
        _num(_g("units")), _money(_g("revenue")), _num(_g("stock_units")),
        ("%.0f" % _g("avg_sor")) if _g("avg_sor") is not None else "n/a",
        ("%.1f" % _g("avg_woc")) if _g("avg_woc") is not None else "n/a",
        overstock, top_sellers, slow,
    )
    sys = (
        "You are a retail merchandising analyst for Vivo Fashion Group, a "
        "multi-brand fashion retailer in East Africa (Kenya/Uganda/Rwanda + "
        "Online). All money is in Kenyan Shillings (KES). You are given a "
        "snapshot of a product range: a summary plus lists of overstocked, "
        "best-selling, and slow-moving styles. Write a concise, decision-useful "
        "'what to act on' narrative (4-6 sentences, <=140 words): what to "
        "reorder or chase, what to mark down or clear, and where stock is "
        "imbalanced. Use the exact figures and style names provided; do not "
        "invent numbers. Plain prose, no markdown headers, no bullet lists, no "
        "emojis."
    )
    narrative = (_chat_llm(
        [{"role": "system", "content": sys},
         {"role": "user", "content": facts}],
        max_tokens=380,
    ) or "").strip()
    if not narrative:
        return {"available": False, "reason": "empty"}
    return {"available": True, "narrative": narrative}


@app.post("/api/analytics/product-analysis/ai")
async def product_analysis_ai_post(request: Request):
    """AI range narrative for the Product Analysis page. Mirrors the trend/
    projection AI pattern: the AI key is server-only, so the client posts the
    grounded summary and we run the LLM here. Always returns gracefully — the
    narrative is an enhancement, never a blocker."""
    try:
        body = await request.json()
    except Exception:
        body = {}
    if not (os.environ.get("AI_INTEGRATIONS_OPENAI_BASE_URL")
            and os.environ.get("AI_INTEGRATIONS_OPENAI_API_KEY")):
        return {"available": False, "reason": "ai_not_configured"}
    try:
        return await _chat_run_in_threadpool(_product_ai_core, body or {})
    except Exception:
        return {"available": False, "reason": "ai_error"}


def _catalogue_ask_core(body):
    """Map a natural-language question to the best dashboard page using the
    catalogue index the client posts (frontend is the single source of truth)."""
    question = (body.get("question") or "").strip()
    pages = body.get("pages") or []
    if not question:
        return {"available": False, "reason": "empty_question"}
    if not isinstance(pages, list) or not pages:
        return {"available": False, "reason": "no_catalogue"}
    lines = []
    for p in pages[:120]:
        if not isinstance(p, dict):
            continue
        route = str(p.get("route") or "").strip()
        label = str(p.get("label") or "").strip()
        purpose = str(p.get("purpose") or "").strip()
        reports = p.get("reports") or []
        if isinstance(reports, list):
            rep = "; ".join(str(r)[:90] for r in reports[:14])
        else:
            rep = str(reports)[:280]
        lines.append("- route=%s | page=%s | purpose=%s | reports: %s"
                     % (route, label, purpose, rep))
    catalog_txt = "\n".join(lines)
    sys = (
        "You are the report finder for the Vivo Fashion Group BI dashboard, a "
        "multi-brand fashion retailer in East Africa (money in KES). You are given "
        "a CATALOGUE of dashboard pages — each with its route, name, purpose and the "
        "reports/metrics it contains. Given the user's question, pick the SINGLE best "
        "page that answers it, plus up to 2 genuinely related pages. Only choose "
        "routes that appear in the catalogue. Reply with STRICT JSON only (no markdown, "
        "no prose around it), shaped exactly: "
        '{"route": "/x", "label": "Page Name", '
        '"answer": "one or two sentences telling the user exactly where to look and which report to open", '
        '"related": [{"route": "/y", "label": "Other Page"}]}. '
        "If nothing in the catalogue fits, set route to null and say so briefly in answer."
    )
    usr = "CATALOGUE:\n%s\n\nQUESTION: %s" % (catalog_txt, question)
    raw = _chat_llm(
        [{"role": "system", "content": sys},
         {"role": "user", "content": usr}],
        max_tokens=320,
    )
    data = _chat_extract_json(raw or "")
    if not isinstance(data, dict):
        return {"available": False, "reason": "parse_error"}
    valid_routes = {str(p.get("route") or "") for p in pages if isinstance(p, dict)}
    route = data.get("route")
    if route and route not in valid_routes:
        route = None
    related = []
    for r in (data.get("related") or []):
        if isinstance(r, dict) and str(r.get("route") or "") in valid_routes:
            related.append({"route": r.get("route"), "label": r.get("label")})
        if len(related) >= 2:
            break
    return {
        "available": True,
        "route": route,
        "label": data.get("label"),
        "answer": (data.get("answer") or "").strip(),
        "related": related,
    }


@app.post("/api/catalogue/ask")
async def catalogue_ask_post(request: Request):
    """AI report-finder for the Catalogue page. The client posts its question plus
    the catalogue index; we run the LLM server-side (the AI key is server-only) and
    return the best-matching page + route. Always returns gracefully — the AI hint
    is an enhancement on top of the client-side keyword search, never a blocker."""
    try:
        body = await request.json()
    except Exception:
        body = {}
    if not (os.environ.get("AI_INTEGRATIONS_OPENAI_BASE_URL")
            and os.environ.get("AI_INTEGRATIONS_OPENAI_API_KEY")):
        return {"available": False, "reason": "ai_not_configured"}
    try:
        return await _chat_run_in_threadpool(_catalogue_ask_core, body or {})
    except Exception:
        return {"available": False, "reason": "ai_error"}


@app.get("/api/analytics/stock-to-sales-by-category")
def analytics_sts_by_category(
    date_from: str = Query(default=str(date.today().replace(day=1))),
    date_to:   str = Query(default=str(date.today())),
    country:   str = Query(default=None),
    channel:   str = Query(default=None),
    locations: str = Query(default=None),
    search:    str = Query(default=None),
    brand:     str = Query(default=None),
    product_type: str = Query(default=None),
):
    # The Inventory page sends `locations` (plural); other callers send `channel`.
    # Accept both — `locations` wins when set.
    _chan = locations or channel
    # Inventory-page local filters (search / brand / subcategory pill) scope
    # BOTH the sales and stock sides so the table reflects only the matching
    # products, not category-wide totals.
    local_scope = _inv_local_scope_sql(search, brand, product_type, alias="p")
    where = build_filters(date_from, date_to, country, _chan,
        extra="s.sale_kind IN ('sale','order') AND s.ordered_item_quantity > 0 AND p.category IS NOT NULL AND p.category <> ''") + local_scope
    # The filter-bar country / POS-location selection must scope the STOCK side
    # too, not just sales — otherwise the store-scoped Units Sold was matched
    # against catalog-wide Inventory and the category-total Inventory column
    # ignored the POS filter (mirrors the subcategory helper).
    inv_country_filter = ("AND i.country IN (" + csv_to_sql(country) + ")") if country else ""
    inv_loc_filter = ("AND i.pos_location_name IN (" + csv_to_sql(_chan) + ")") if _chan else ""
    return run_query("""
        WITH sales AS (
            SELECT p.category AS category,
                SUM(s.ordered_item_quantity) AS units_sold,
                COUNT(DISTINCT s.order_id) AS orders,
                ROUND(SUM((s.total_sales_kes::numeric - COALESCE(s.discounts_kes, 0)::numeric)), 0) AS total_sales
            FROM all_sales s
            LEFT JOIN all_products_clean p ON s.variant_sku = p.sku
            WHERE """ + where + """
            GROUP BY p.category
        ),
        stock AS (
            SELECT p.category AS category, SUM(i.available) AS current_stock
            FROM all_inventory i
            LEFT JOIN all_products_clean p ON i.sku = p.sku
            WHERE i.pos_location_name NOT IN (""" + WAREHOUSE_LOCATIONS + """)
            AND p.category IS NOT NULL AND p.category <> ''
            """ + inv_country_filter + " " + inv_loc_filter + local_scope + """
            GROUP BY p.category
        )
        SELECT COALESCE(s.category, st.category) AS category,
            COALESCE(s.units_sold, 0) AS units_sold,
            COALESCE(s.orders, 0) AS orders,
            COALESCE(s.total_sales, 0) AS total_sales,
            COALESCE(st.current_stock, 0) AS current_stock,
            ROUND(COALESCE(s.units_sold,0)*100.0/NULLIF(SUM(COALESCE(s.units_sold,0)) OVER(),0),2) AS pct_of_total_sold,
            ROUND(COALESCE(st.current_stock,0)*100.0/NULLIF(SUM(COALESCE(st.current_stock,0)) OVER(),0),2) AS pct_of_total_stock,
            ROUND(COALESCE(s.units_sold,0)*100.0/NULLIF(COALESCE(s.units_sold,0)+COALESCE(st.current_stock,0),0),1) AS sor_percent,
            ROUND(
                COALESCE(s.units_sold,0)*100.0/NULLIF(SUM(COALESCE(s.units_sold,0)) OVER(),0)
                - COALESCE(st.current_stock,0)*100.0/NULLIF(SUM(COALESCE(st.current_stock,0)) OVER(),0)
            , 2) AS variance
        FROM sales s
        FULL OUTER JOIN stock st ON s.category = st.category
        WHERE COALESCE(s.category, st.category) IS NOT NULL
        ORDER BY units_sold DESC
    """, date_to=date_to)

@app.get("/api/analytics/stock-to-sales-by-subcat")
def analytics_sts_by_subcat(
    date_from: str = Query(default=str(date.today().replace(day=1))),
    date_to:   str = Query(default=str(date.today())),
    country:   str = Query(default=None),
    channel:   str = Query(default=None),
    locations: str = Query(default=None),
    search:    str = Query(default=None),
    brand:     str = Query(default=None),
    product_type: str = Query(default=None),
):
    rows = get_subcategory_stock_sales(date_from, date_to, country, channel,
                                       search, brand, product_type,
                                       locations=locations)
    for r in rows:
        sold = r.get("pct_of_total_sold") or 0
        stock = r.get("pct_of_total_stock") or 0
        try:
            r["variance"] = round(float(sold) - float(stock), 2)
        except (TypeError, ValueError):
            r["variance"] = 0
    return rows

def _period_weeks(date_from, date_to):
    # Number of whole-ish weeks covered by the selected range (inclusive),
    # floored at 1 so rate-of-sale never divides by zero. Computed in Python
    # and injected as a literal — sale_date is TEXT so SQL date math on it is
    # avoided here.
    try:
        d0 = date.fromisoformat(str(date_from)[:10])
        d1 = date.fromisoformat(str(date_to)[:10])
        return f"{max(1.0, ((d1 - d0).days + 1) / 7.0):.4f}"
    except Exception:
        return "1.0"

@app.get("/api/analytics/velocity")
def analytics_velocity(
    date_from: str = Query(default=str(date.today().replace(day=1))),
    date_to:   str = Query(default=str(date.today())),
    country:   str = Query(default=None),
    channel:   str = Query(default=None),
):
    # Sell-through velocity by style. rate_of_sale = units sold / weeks in the
    # selected period; weeks_of_cover = current store stock / rate_of_sale.
    # sell_through follows the SOR convention (sold / (sold + current stock)).
    # Current stock excludes warehouses, matching every other stock breakdown.
    # NOTE: no "ordered_item_quantity > 0" guard — units_sold must be the same
    # gross sale/order-row population as /api/top-skus and /api/sor so the SAME
    # style shows the SAME units on Products, Velocity and Catalog SOR.
    where = build_filters(date_from, date_to, country, channel,
        extra="s.sale_kind IN ('sale','order') AND p.style_name IS NOT NULL")
    # Phase 2 A6/A1 — rate_of_sale & weeks_of_cover use the standardized
    # recency-weighted weekly velocity (last 28 days double-weighted over a
    # 12-week-equivalent denominator, computed on a trailing 56-day window) so
    # cover figures agree with /weeks-of-cover and /replenish-by-color. The
    # selected-period units_sold / total_sales remain for the displayed totals.
    vel_cc = _country_channel_filter(country, channel)
    rows = run_query("""
        WITH sales AS (
            SELECT p.style_name, MAX(p.brand) AS brand, MAX(p.product_type) AS product_type,
                SUM(s.ordered_item_quantity) AS units_sold,
                ROUND(SUM((s.total_sales_kes::numeric - COALESCE(s.discounts_kes, 0)::numeric)), 0) AS total_sales
            FROM all_sales s
            JOIN all_products_clean p ON s.variant_sku = p.sku
            WHERE """ + where + """
            GROUP BY p.style_name
        ),
        vel AS (
            SELECT p.style_name,
                SUM(s.ordered_item_quantity) FILTER (
                    WHERE s.sale_date::date >= CURRENT_DATE - INTERVAL '28 days') AS u28,
                SUM(s.ordered_item_quantity) AS u56
            FROM all_sales s
            JOIN all_products_clean p ON s.variant_sku = p.sku
            WHERE s.sale_kind IN ('sale','order') AND p.style_name IS NOT NULL
              AND s.sale_date::date >= CURRENT_DATE - INTERVAL '56 days'
              AND """ + vel_cc + """
            GROUP BY p.style_name
        ),
        stock AS (
            SELECT p.style_name, SUM(i.available) AS current_stock
            FROM all_inventory i
            JOIN all_products_clean p ON i.sku = p.sku
            WHERE i.pos_location_name NOT IN (""" + WAREHOUSE_LOCATIONS + """)
            GROUP BY p.style_name
        ),
        base AS (
            -- sales rows are (style, product_type) grain but stock/velocity are
            -- style grain: joining directly duplicated the full stock figure
            -- onto every subcategory row of a style (Satin Kaftan bug). Instead
            -- apportion stock and weekly velocity across a style's rows by
            -- units-sold share; a zero-units style gives everything to its
            -- first row so totals still reconcile.
            SELECT sa.style_name, sa.brand, sa.product_type,
                sa.units_sold, sa.total_sales,
                CASE
                    WHEN SUM(sa.units_sold) OVER (PARTITION BY sa.style_name) > 0
                    THEN ROUND(COALESCE(st.current_stock, 0)
                         * sa.units_sold::numeric
                         / SUM(sa.units_sold) OVER (PARTITION BY sa.style_name))
                    WHEN ROW_NUMBER() OVER (PARTITION BY sa.style_name
                                            ORDER BY sa.product_type NULLS LAST) = 1
                    THEN COALESCE(st.current_stock, 0)
                    ELSE 0
                END AS current_stock,
                CASE
                    WHEN SUM(sa.units_sold) OVER (PARTITION BY sa.style_name) > 0
                    THEN (((COALESCE(v.u28, 0) * 2)
                          + GREATEST(COALESCE(v.u56, 0) - COALESCE(v.u28, 0), 0)) / 12.0)
                         * sa.units_sold::numeric
                         / SUM(sa.units_sold) OVER (PARTITION BY sa.style_name)
                    WHEN ROW_NUMBER() OVER (PARTITION BY sa.style_name
                                            ORDER BY sa.product_type NULLS LAST) = 1
                    THEN ((COALESCE(v.u28, 0) * 2)
                          + GREATEST(COALESCE(v.u56, 0) - COALESCE(v.u28, 0), 0)) / 12.0
                    ELSE 0
                END AS weekly_units
            FROM sales sa
            LEFT JOIN vel v ON v.style_name = sa.style_name
            LEFT JOIN stock st ON sa.style_name = st.style_name
        )
        SELECT style_name, brand, product_type, units_sold, total_sales, current_stock,
            ROUND(weekly_units, 1) AS rate_of_sale,
            ROUND(current_stock / NULLIF(weekly_units, 0), 1) AS weeks_of_cover,
            ROUND(units_sold * 100.0 /
                NULLIF(units_sold + current_stock, 0), 1) AS sell_through
        FROM base
        ORDER BY rate_of_sale DESC NULLS LAST
        LIMIT 5000
    """, date_to=date_to)
    for r in rows:
        r["velocity_method"] = "ewma_56d"
    return rows

@app.get("/api/analytics/size-curve")
def analytics_size_curve(
    date_from: str = Query(default=str(date.today().replace(day=1))),
    date_to:   str = Query(default=str(date.today())),
    country:   str = Query(default=None),
    channel:   str = Query(default=None),
):
    # Size-curve health by style: how many of a style's catalogued sizes are
    # currently in stock across selling locations (warehouses excluded). A
    # "broken" curve = catalogued sizes that are out of stock. units_sold over
    # the selected period is attached so best-sellers with broken curves surface
    # first. Only styles with a real size run (>= 2 sizes) are returned.
    where = build_filters(date_from, date_to, country, channel,
        extra="s.sale_kind IN ('sale','order') AND s.ordered_item_quantity > 0 AND p.style_name IS NOT NULL")
    return run_query("""
        WITH sales AS (
            SELECT p.style_name, SUM(s.ordered_item_quantity) AS units_sold
            FROM all_sales s
            JOIN all_products_clean p ON s.variant_sku = p.sku
            WHERE """ + where + """
            GROUP BY p.style_name
        ),
        catalog AS (
            SELECT style_name, NULLIF(TRIM(size), '') AS size
            FROM all_products_clean
            WHERE style_name IS NOT NULL AND NULLIF(TRIM(size), '') IS NOT NULL
            GROUP BY style_name, NULLIF(TRIM(size), '')
        ),
        stock AS (
            SELECT p.style_name, NULLIF(TRIM(p.size), '') AS size, SUM(i.available) AS avail
            FROM all_inventory i
            JOIN all_products_clean p ON i.sku = p.sku
            WHERE i.pos_location_name NOT IN (""" + WAREHOUSE_LOCATIONS + """)
              AND p.style_name IS NOT NULL AND NULLIF(TRIM(p.size), '') IS NOT NULL
            GROUP BY p.style_name, NULLIF(TRIM(p.size), '')
        ),
        dem AS (
            SELECT p.style_name, NULLIF(TRIM(p.size), '') AS size, SUM(s.net_quantity) AS u
            FROM all_sales s
            JOIN all_products_clean p ON p.sku = s.variant_sku
            WHERE s.sale_kind IN ('sale','order')
              AND s.sale_date >= (CURRENT_DATE - INTERVAL '90 days')::text
              AND p.style_name IS NOT NULL AND NULLIF(TRIM(p.size), '') IS NOT NULL
            GROUP BY p.style_name, NULLIF(TRIM(p.size), '')
        ),
        whstock AS (
            SELECT p.style_name, NULLIF(TRIM(p.size), '') AS size, SUM(i.available) AS a
            FROM all_inventory i
            JOIN all_products_clean p ON i.sku = p.sku
            WHERE i.pos_location_name IN (""" + WAREHOUSE_LOCATIONS + """)
              AND i.available > 0
              AND p.style_name IS NOT NULL AND NULLIF(TRIM(p.size), '') IS NOT NULL
            GROUP BY p.style_name, NULLIF(TRIM(p.size), '')
        ),
        curve AS (
            SELECT c.style_name,
                COUNT(*) AS total_sizes,
                COUNT(*) FILTER (WHERE COALESCE(st.avail, 0) > 0) AS sizes_in_stock,
                string_agg(CASE WHEN COALESCE(st.avail, 0) <= 0 THEN c.size END, ', ' ORDER BY c.size) AS missing_sizes,
                SUM(COALESCE(d.u, 0) * (CASE WHEN COALESCE(st.avail, 0) > 0 THEN 1 ELSE 0 END)) AS dem_in_stock,
                SUM(COALESCE(d.u, 0)) AS dem_total,
                bool_or(COALESCE(st.avail, 0) <= 0 AND COALESCE(w.a, 0) > 0) AS ibt_opportunity,
                -- A style with zero availability at EVERY selling location AND
                -- zero warehouse stock has no size data to assess (dead /
                -- retired / fully sold out of the network) — it must not count
                -- as a "broken curve" nor drag the average health down.
                (COUNT(*) FILTER (WHERE COALESCE(st.avail, 0) > 0) = 0
                 AND NOT bool_or(COALESCE(w.a, 0) > 0)) AS no_size_data
            FROM catalog c
            LEFT JOIN stock st ON c.style_name = st.style_name AND c.size = st.size
            LEFT JOIN dem d ON c.style_name = d.style_name AND c.size = d.size
            LEFT JOIN whstock w ON c.style_name = w.style_name AND c.size = w.size
            GROUP BY c.style_name
        ),
        meta AS (
            SELECT style_name, MAX(brand) AS brand, MAX(category) AS category,
                MAX(product_type) AS product_type
            FROM all_products_clean WHERE style_name IS NOT NULL GROUP BY style_name
        )
        SELECT cu.style_name, m.brand, m.category, m.product_type,
            COALESCE(sa.units_sold, 0) AS units_sold,
            cu.total_sizes,
            cu.sizes_in_stock,
            cu.no_size_data,
            CASE WHEN cu.no_size_data THEN NULL
                 ELSE cu.total_sizes - cu.sizes_in_stock END AS broken_sizes,
            CASE WHEN cu.no_size_data THEN NULL
                 ELSE ROUND(cu.sizes_in_stock * 100.0 / NULLIF(cu.total_sizes, 0), 0)
            END AS health_pct,
            CASE WHEN cu.no_size_data THEN NULL ELSE COALESCE(
                ROUND(cu.dem_in_stock * 100.0 / NULLIF(cu.dem_total, 0), 0),
                ROUND(cu.sizes_in_stock * 100.0 / NULLIF(cu.total_sizes, 0), 0)
            ) END AS demand_weighted_health,
            COALESCE(cu.ibt_opportunity, false) AS ibt_opportunity,
            CASE WHEN cu.no_size_data THEN NULL ELSE cu.missing_sizes END AS missing_sizes
        FROM curve cu
        LEFT JOIN sales sa ON cu.style_name = sa.style_name
        LEFT JOIN meta m ON cu.style_name = m.style_name
        WHERE cu.total_sizes >= 2
        -- Usable rows (styles with stock somewhere) fill the LIMIT first; the
        -- old "broken_sizes DESC" tiebreak flooded the cap with dead styles on
        -- a fresh catalog-heavy DB, making every returned row read broken.
        ORDER BY cu.no_size_data ASC, units_sold DESC, cu.dem_total DESC NULLS LAST, cu.style_name
        LIMIT 3000
    """, date_to=date_to)

_MARGIN_DIMS = {
    "category":    "p.category",
    "subcategory": "p.product_type",
    "brand":       "p.brand",
    "store":       "s.pos_location_name",
    "month":       "to_char(s.sale_date::date,'YYYY-MM')",
}

@app.get("/api/analytics/margin")
def analytics_margin(
    dim:       str = Query(default="category"),
    date_from: str = Query(default=str(date.today().replace(day=1))),
    date_to:   str = Query(default=str(date.today())),
    country:   str = Query(default=None),
    channel:   str = Query(default=None),
):
    # Markdown / discount impact on gross margin. COGS uses
    # all_products_clean.cost (per-unit landed cost). cost is not known for every
    # SKU, so gross_margin / margin_pct are computed over the COSTED subset only
    # (lines with cost > 0) and cost_coverage (% of units with a known cost) is
    # returned so the margin figure is read honestly. discount_rate =
    # discounts / gross (pre-discount). net_revenue = canonical Net Sales
    # ((total − discounts − returns) ex-VAT — see NET_SALES_CANON); this page
    # joins the product master so its rows cover catalog-matched SKUs only.
    # costed_net (margin math) stays on the ex-VAT figure deliberately.
    col = _MARGIN_DIMS.get(dim, _MARGIN_DIMS["category"])
    where = build_filters(date_from, date_to, country, channel,
        extra="s.sale_kind IN ('sale','order','return') AND COALESCE(" + col + ", '') <> ''")
    return run_query("""
        WITH base AS (
            SELECT """ + col + """ AS dim,
                SUM(CASE WHEN s.sale_kind IN ('sale','order') THEN s.ordered_item_quantity ELSE 0 END) AS units,
                SUM(CASE WHEN s.sale_kind IN ('sale','order') THEN s.gross_sales_kes::numeric ELSE 0 END) AS gross,
                SUM(CASE WHEN s.sale_kind IN ('sale','order') THEN s.discounts_kes::numeric ELSE 0 END) AS discounts,
                """ + NET_SALES_CANON + """ AS net_revenue,
                SUM(CASE WHEN s.sale_kind IN ('sale','order') AND p.cost IS NOT NULL AND p.cost > 0
                         THEN s.ordered_item_quantity ELSE 0 END) AS costed_units,
                SUM(CASE WHEN s.sale_kind IN ('sale','order') AND p.cost IS NOT NULL AND p.cost > 0
                         THEN s.net_sales_kes::numeric ELSE 0 END) AS costed_net,
                SUM(CASE WHEN s.sale_kind IN ('sale','order') AND p.cost IS NOT NULL AND p.cost > 0
                         THEN s.ordered_item_quantity * p.cost ELSE 0 END) AS cogs
            FROM all_sales s
            JOIN all_products_clean p ON s.variant_sku = p.sku
            WHERE """ + where + """
            GROUP BY """ + col + """
        )
        SELECT dim,
            units,
            ROUND(gross, 0) AS gross,
            ROUND(discounts, 0) AS discounts,
            ROUND(discounts * 100.0 / NULLIF(gross, 0), 1) AS discount_rate,
            ROUND(net_revenue, 0) AS net_revenue,
            ROUND(cogs, 0) AS cogs,
            ROUND(costed_net - cogs, 0) AS gross_margin,
            ROUND((costed_net - cogs) * 100.0 / NULLIF(costed_net, 0), 1) AS margin_pct,
            ROUND(costed_units * 100.0 / NULLIF(units, 0), 0) AS cost_coverage
        FROM base
        WHERE units > 0
        ORDER BY net_revenue DESC
        LIMIT 2000
    """, date_to=date_to)

def _finance_missing_relation(exc):
    """True only when a finance query failed because its Odoo-derived view/table is
    absent on this DB (e.g. a freshly published prod that hasn't materialised the
    finance objects yet). Lets the WIP /finance page degrade to an empty state with
    a 200 instead of a hard 500. Deliberately NARROW — only a missing relation or
    schema qualifies; a bad column or any other error still re-raises (→ 500) so a
    real finance-SQL regression stays visible rather than silently returning empty."""
    if isinstance(exc, (psycopg2.errors.UndefinedTable,
                        psycopg2.errors.InvalidSchemaName)):
        log.warning("finance endpoint degrading to empty — missing relation/schema: %s", exc)
        return True
    return False


@app.get("/api/finance/pl")
def finance_pl(
    date_from: str = Query(default=str(date(date.today().year - 1, date.today().month, 1))),
    date_to:   str = Query(default=str(date.today())),
):
    """Monthly Profit & Loss from the finance_pl_summary view — the official Odoo
    P&L structure: Revenue (revenue_odoo) → Less Costs of Revenue
    (cogs / production / purchases → total_costs_of_revenue) → Gross Profit → Less
    Operating Expenses (employment / admin / establishment / selling / marketing /
    finance_charges / other_opex → total_operating_expenses) → Operating Income
    (DERIVED = gross_profit - total_operating_expenses) → Plus Other Income → Net
    Profit. Also carries net_revenue_pipeline (sales-pipeline revenue, for the
    Odoo-vs-pipeline variance report) and the data-integrity flags is_closed /
    has_cost_anomaly.

    Returns the FULL month history (`months`) as a constant query → cached by
    run_query so the expensive finance_pl_summary view is computed ONCE rather than
    re-scanned per period change. The frontend windows the rows to the selected
    [date_from, date_to] client-side and uses the full list to populate its
    month-range selector. date_from/date_to are accepted for API symmetry and
    validated, but the query is intentionally un-windowed (do NOT add a second
    full-view scan — it doubles the cost). Read-only; reuses the shared pool."""
    _ = _validate_date_param(date_from), _validate_date_param(date_to)
    try:
        months = run_query("""
            SELECT month, gross_sales, returns, net_revenue_pipeline, revenue_odoo,
                   cogs, production, purchases, total_costs_of_revenue, gross_profit,
                   employment, admin, establishment, selling, marketing,
                   finance_charges, other_opex, total_operating_expenses,
                   (gross_profit - total_operating_expenses) AS operating_income,
                   other_income, net_profit, is_closed, has_cost_anomaly
            FROM finance_pl_summary
            ORDER BY month
        """)
    except Exception as e:
        if _finance_missing_relation(e):
            months = []
        else:
            raise
    return {"months": months}


@app.get("/api/finance/pl-detail")
def finance_pl_detail(
    date_from: str = Query(default=str(date(date.today().year - 1, date.today().month, 1))),
    date_to:   str = Query(default=str(date.today())),
):
    """Account-level P&L detail for the selected month window. Joins
    raw_account_move_lines to finance_account_map and sums each account with the
    correct sign convention (revenue / other_income = credit - debit; costs &
    operating expenses = debit - credit) so figures reconcile to
    finance_pl_summary. Grouped by pl_section, pl_group, account_code,
    account_name; flat array ordered by section, group, amount desc. Powers the
    group→account drill-downs on the P&L statement, the Operating-Expenses
    analysis and the Cost-of-Revenue report. Windowed server-side (cheap vs the
    full view). Date params validated by the /api edge middleware AND here."""
    df = _validate_date_param(date_from) or str(date(date.today().year - 1, date.today().month, 1))
    dt = _validate_date_param(date_to) or str(date.today())
    sign = ("CASE WHEN m.pl_section IN ('revenue','other_income') "
            "THEN l.credit - l.debit ELSE l.debit - l.credit END")
    try:
        rows = run_query("""
            SELECT m.pl_section, m.pl_group, l.account_code, l.account_name,
                   ROUND(SUM(""" + sign + """), 0) AS amount
            FROM raw_account_move_lines l
            JOIN finance_account_map m ON m.account_code = l.account_code
            WHERE l.date >= date_trunc('month', DATE '""" + df + """')
              AND l.date <  date_trunc('month', DATE '""" + dt + """') + INTERVAL '1 month'
            GROUP BY m.pl_section, m.pl_group, l.account_code, l.account_name
            HAVING ROUND(SUM(""" + sign + """), 0) <> 0
            ORDER BY m.pl_section, m.pl_group, amount DESC
        """, date_to=dt)
    except Exception as e:
        if _finance_missing_relation(e):
            rows = []
        else:
            raise
    return {"detail": rows}


@app.get("/api/finance/expense-by-vendor")
def finance_expense_by_vendor(
    date_from: str = Query(default=str(date(date.today().year - 1, date.today().month, 1))),
    date_to:   str = Query(default=str(date.today())),
    category:  str = Query(default=None),
    limit:     int = Query(default=50),
):
    """Top vendors / suppliers by spend over the selected month window. Sums
    debit - credit on raw_account_move_lines for cost-of-revenue + operating-
    expense accounts, grouped by partner_name, excluding null/blank partners,
    ordered desc. Optional `category` narrows to a single pl_group (whitelisted to
    keep it un-injectable). Windowed server-side. Read-only."""
    df = _validate_date_param(date_from) or str(date(date.today().year - 1, date.today().month, 1))
    dt = _validate_date_param(date_to) or str(date.today())
    lim = max(1, min(int(limit or 50), 500))
    cat = (category or "").strip()
    valid_groups = {"cogs", "production", "purchases", "employment", "admin",
                    "establishment", "selling", "marketing", "finance_charges", "other_opex"}
    cat_sql = (" AND m.pl_group = '" + cat + "'") if cat in valid_groups else ""
    try:
        rows = run_query("""
            SELECT l.partner_name AS vendor,
                   ROUND(SUM(l.debit - l.credit), 0) AS spend
            FROM raw_account_move_lines l
            JOIN finance_account_map m ON m.account_code = l.account_code
            WHERE m.pl_section IN ('costs_of_revenue','operating_expenses')""" + cat_sql + """
              AND l.partner_name IS NOT NULL AND btrim(l.partner_name) <> ''
              AND l.date >= date_trunc('month', DATE '""" + df + """')
              AND l.date <  date_trunc('month', DATE '""" + dt + """') + INTERVAL '1 month'
            GROUP BY l.partner_name
            HAVING ROUND(SUM(l.debit - l.credit), 0) <> 0
            ORDER BY spend DESC
            LIMIT """ + str(lim) + """
        """, date_to=dt)
    except Exception as e:
        if _finance_missing_relation(e):
            rows = []
        else:
            raise
    return {"vendors": rows}


@app.get("/api/analytics/rfm")
def analytics_rfm(
    date_from: str = Query(default=str(date.today().replace(day=1))),
    date_to:   str = Query(default=str(date.today())),
    country:   str = Query(default=None),
    channel:   str = Query(default=None),
    limit:     int = Query(default=2000),
):
    # RFM segmentation over customers active in the selected period. Recency is
    # measured against date_to; R/F/M each scored 1-5 via quintiles (NTILE) and
    # combined into the canonical RFM segment grid (FM = avg of F and M). Returns
    # a per-segment summary over the FULL base plus the top customers by monetary
    # value (capped). monetary nets returns like /api/kpis.
    lim = max(1, min(int(limit or 2000), 5000))
    ref = str(date_to)[:10]
    where = build_filters(date_from, date_to, country, channel,
        extra="s.sale_kind IN ('sale','order','return') AND s.customer_id IS NOT NULL AND s.customer_id <> '' AND " + _not_walkin_pseudo_sql())
    monetary_expr = NET_SALES_CANON
    freq_expr = "COUNT(DISTINCT CASE WHEN s.sale_kind IN ('sale','order') THEN s.order_id END)"
    base_cte = """
        WITH cust AS (
            SELECT s.customer_id,
                MAX(s.sale_date::date) AS last_purchase,
                """ + freq_expr + """ AS frequency,
                """ + monetary_expr + """ AS monetary
            FROM all_sales s
            WHERE """ + where + """
            GROUP BY s.customer_id
            HAVING """ + monetary_expr + """ > 0 AND """ + freq_expr + """ > 0
        ),
        scored AS (
            SELECT customer_id, last_purchase, frequency, monetary,
                ('""" + ref + """'::date - last_purchase) AS recency_days,
                NTILE(5) OVER (ORDER BY ('""" + ref + """'::date - last_purchase) DESC) AS r_score,
                NTILE(5) OVER (ORDER BY frequency ASC) AS f_score,
                NTILE(5) OVER (ORDER BY monetary ASC) AS m_score
            FROM cust
        ),
        seg AS (
            SELECT customer_id, last_purchase, frequency, monetary, recency_days,
                r_score, f_score, m_score,
                ROUND((f_score + m_score) / 2.0) AS fm,
                CASE
                    WHEN r_score >= 4 AND ROUND((f_score + m_score) / 2.0) >= 4 THEN 'Champions'
                    WHEN r_score >= 3 AND ROUND((f_score + m_score) / 2.0) >= 3 THEN 'Loyal'
                    WHEN r_score >= 4 AND ROUND((f_score + m_score) / 2.0) BETWEEN 2 AND 3 THEN 'Potential Loyalist'
                    WHEN r_score >= 4 AND ROUND((f_score + m_score) / 2.0) <= 1 THEN 'New'
                    WHEN r_score = 3 AND ROUND((f_score + m_score) / 2.0) <= 2 THEN 'Promising'
                    WHEN r_score <= 2 AND ROUND((f_score + m_score) / 2.0) >= 4 THEN 'Cant Lose Them'
                    WHEN r_score = 2 AND ROUND((f_score + m_score) / 2.0) >= 3 THEN 'At Risk'
                    WHEN r_score <= 2 AND ROUND((f_score + m_score) / 2.0) = 2 THEN 'Hibernating'
                    ELSE 'Lost'
                END AS segment
            FROM scored
        )
    """
    summary = run_query(base_cte + """
        SELECT segment,
            COUNT(*) AS customers,
            ROUND(SUM(monetary), 0) AS monetary,
            ROUND(AVG(recency_days), 0) AS avg_recency_days,
            ROUND(AVG(frequency), 1) AS avg_frequency,
            ROUND(AVG(monetary), 0) AS avg_monetary
        FROM seg
        GROUP BY segment
        ORDER BY monetary DESC
    """, date_to=date_to)
    customers = run_query(base_cte + """
        SELECT customer_id, segment, recency_days, frequency,
            ROUND(monetary, 0) AS monetary,
            r_score, f_score, m_score
        FROM seg
        ORDER BY monetary DESC
        LIMIT """ + str(lim) + """
    """, date_to=date_to)
    return {"summary": summary, "customers": customers}

@app.get("/api/analytics/new-styles")
def analytics_new_styles(
    days:  int = Query(default=90),
    limit: int = Query(default=200),
    date_from: str = Query(default=None),
    date_to:   str = Query(default=None),
    country:   str = Query(default=None),
    channel:   str = Query(default=None),
):
    # Sell-Out Rate is computed launch-to-date (units sold since launch vs the
    # units sold plus current store stock), so the re-order list reflects how
    # much of the launch buy has already sold through.
    if date_from and date_to:
        period_extra = "s2.sale_date BETWEEN '" + date_from + "' AND '" + date_to + "'"
    else:
        period_extra = "TRUE"
    return run_query("""
        WITH new_styles AS (
            SELECT p.style_name,
                MAX(p.brand) AS brand,
                MAX(p.product_type) AS product_type,
                MAX(p.product_type) AS subcategory,
                MIN(p.style_launch_date) AS style_launch_date
            FROM all_products_clean p
            WHERE p.style_name IS NOT NULL
              AND p.style_launch_date IS NOT NULL
              AND substring(p.style_launch_date, 1, 10) ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
              AND substring(p.style_launch_date, 1, 10)::date >= CURRENT_DATE - (""" + str(int(days)) + """ || ' days')::interval
            GROUP BY p.style_name
        ),
        launch AS (
            SELECT p.style_name,
                COALESCE(SUM(s.net_quantity), 0) AS units_sold_launch,
                COALESCE(ROUND(SUM(s.net_sales_kes::numeric)), 0) AS total_sales_launch
            FROM all_products_clean p
            JOIN all_sales s ON s.variant_sku = p.sku AND s.sale_kind IN ('sale','order')
            WHERE p.style_name IN (SELECT style_name FROM new_styles)
            GROUP BY p.style_name
        ),
        period AS (
            -- WS4 T401: also return the PERIOD units — the frontend's
            -- "Units (Period)" column reads units_sold_period, which this
            -- endpoint previously never emitted (showed 0 next to sales>0).
            SELECT p.style_name,
                COALESCE(ROUND(SUM(s2.net_sales_kes::numeric)), 0) AS total_sales_period,
                COALESCE(SUM(s2.net_quantity), 0) AS units_sold_period
            FROM all_products_clean p
            JOIN all_sales s2 ON s2.variant_sku = p.sku AND s2.sale_kind IN ('sale','order')
            WHERE p.style_name IN (SELECT style_name FROM new_styles) AND """ + period_extra + """
            GROUP BY p.style_name
        ),
        stock AS (
            SELECT p.style_name, COALESCE(SUM(i.available), 0) AS current_stock
            FROM all_products_clean p
            JOIN all_inventory i ON i.sku = p.sku
            WHERE p.style_name IN (SELECT style_name FROM new_styles)
              AND i.pos_location_name NOT IN (""" + WAREHOUSE_LOCATIONS + """)
            GROUP BY p.style_name
        )
        SELECT ns.style_name, ns.brand, ns.product_type, ns.subcategory, ns.style_launch_date,
            COALESCE(l.units_sold_launch, 0) AS units_sold,
            COALESCE(l.total_sales_launch, 0) AS total_sales,
            COALESCE(l.units_sold_launch, 0) AS units_sold_launch,
            COALESCE(l.total_sales_launch, 0) AS total_sales_launch,
            COALESCE(pr.total_sales_period, 0) AS total_sales_period,
            COALESCE(pr.units_sold_period, 0) AS units_sold_period,
            COALESCE(st.current_stock, 0) AS current_stock,
            COALESCE(st.current_stock, 0) AS stock_available,
            ROUND(100.0 * COALESCE(l.units_sold_launch, 0)
                  / NULLIF(COALESCE(l.units_sold_launch, 0) + COALESCE(st.current_stock, 0), 0), 1) AS sor_percent
        FROM new_styles ns
        LEFT JOIN launch l USING (style_name)
        LEFT JOIN period pr USING (style_name)
        LEFT JOIN stock st USING (style_name)
        ORDER BY ns.style_launch_date DESC, units_sold_launch DESC
        LIMIT """ + str(int(limit)))


def _norm_ppf(p):
    """Acklam's rational approximation of the inverse standard-normal CDF.
    Pure-stdlib (no scipy in this env). Good to ~1e-9 over (0,1)."""
    import math as _m
    if p <= 0.0:
        return -8.0
    if p >= 1.0:
        return 8.0
    a = [-3.969683028665376e+01, 2.209460984245205e+02, -2.759285104469687e+02,
         1.383577518672690e+02, -3.066479806614716e+01, 2.506628277459239e+00]
    b = [-5.447609879822406e+01, 1.615858368580409e+02, -1.556989798598866e+02,
         6.680131188771972e+01, -1.328068155288572e+01]
    c = [-7.784894002430293e-03, -3.223964580411365e-01, -2.400758277161838e+00,
         -2.549732539343734e+00, 4.374664141464968e+00, 2.938163982698783e+00]
    d = [7.784695709041462e-03, 3.224671290700398e-01, 2.445134137142996e+00,
         3.754408661907416e+00]
    plow, phigh = 0.02425, 1 - 0.02425
    if p < plow:
        q = _m.sqrt(-2 * _m.log(p))
        return (((((c[0]*q+c[1])*q+c[2])*q+c[3])*q+c[4])*q+c[5]) / \
               ((((d[0]*q+d[1])*q+d[2])*q+d[3])*q+1)
    if p <= phigh:
        q = p - 0.5
        r = q*q
        return (((((a[0]*r+a[1])*r+a[2])*r+a[3])*r+a[4])*r+a[5])*q / \
               (((((b[0]*r+b[1])*r+b[2])*r+b[3])*r+b[4])*r+1)
    q = _m.sqrt(-2 * _m.log(1 - p))
    return -(((((c[0]*q+c[1])*q+c[2])*q+c[3])*q+c[4])*q+c[5]) / \
            ((((d[0]*q+d[1])*q+d[2])*q+d[3])*q+1)


def _gamma_quantile(shape, rate, p):
    """Wilson-Hilferty quantile of a Gamma(shape, rate) variate (mean=shape/rate).
    Used for the demand-rate posterior band (p10/p50/p90 + the critical fractile)
    without a scipy dependency."""
    import math as _m
    if shape <= 0 or rate <= 0:
        return 0.0
    z = _norm_ppf(p)
    v = 1.0 - 1.0/(9.0*shape) + z*_m.sqrt(1.0/(9.0*shape))
    return max(0.0, (shape/rate) * (v**3))


@app.get("/api/analytics/buy-candidates")
def analytics_buy_candidates(
    lead_weeks:       int = Query(default=6),
    cover_weeks:      int = Query(default=8),
    confidence_floor: int = Query(default=30),
    aged_days:        int = Query(default=60),
    limit:            int = Query(default=300),
):
    """Phase-1 buy-decision engine for the Re-Order / Buying page.

    Universe = every MERCHANDISE style with demand in the last 56 days (NOT just
    new launches): a 95-day-old style selling 679 units must be able to outrank
    an 8-day-old style selling 2. Per style we estimate a *posterior* weekly
    demand rate (Gamma-Poisson shrinkage toward the category-median rate, so
    small-n noise collapses to the category and proven winners barely move),
    report a p10/p50/p90 band, size the buy at the critical fractile
    Q* = Cu/(Cu+Co) (high-margin winners buy deep, thin/noisy styles shallow or
    skip), net it against on-hand + warehouse + WIP, gate on a confidence floor
    and on aged stock held elsewhere, and rank by OPPORTUNITY VALUE
    (margin x demand) — never by raw SOR%.

    HARD CONSTRAINT: canonical SOR (units_sold / (units_sold + store_stock)) is
    reported only, never redefined.

    Censored-demand correction is APPROXIMATE: no per-day stock-on-hand history
    is retained in this DB, so stock-out days are inferred from recent at-risk
    snapshots + current sub-1-week cover. Labelled as such in the response.
    """
    import math as _m
    from statistics import median as _median
    from datetime import date as _date, datetime as _dt

    merch_in = ",".join("'" + str(s).replace("'", "''") + "'" for s in MERCH_SUBCATEGORIES)
    aged_n = max(1, int(aged_days))

    rows = run_query("""
        WITH base AS (
            SELECT p.style_name,
                MAX(p.brand) AS brand,
                MAX(p.product_type) AS subcategory,
                MIN(p.style_launch_date) AS style_launch_date,
                AVG(NULLIF(p.price, 0)) AS price,
                AVG(NULLIF(p.cost, 0))  AS cost
            FROM all_products_clean p
            WHERE p.style_name IS NOT NULL
              AND p.product_type IN (""" + merch_in + """)
            GROUP BY p.style_name
        ),
        sales AS (
            SELECT p.style_name,
                COALESCE(SUM(s.net_quantity), 0) AS lifetime_units,
                COALESCE(ROUND(SUM(s.net_sales_kes::numeric)), 0) AS lifetime_sales,
                MIN(s.sale_date) AS first_sale,
                COALESCE(SUM(CASE WHEN s.sale_date::date >= CURRENT_DATE - INTERVAL '28 days'
                                  THEN s.net_quantity ELSE 0 END), 0) AS u28,
                COALESCE(SUM(CASE WHEN s.sale_date::date >= CURRENT_DATE - INTERVAL '56 days'
                                  THEN s.net_quantity ELSE 0 END), 0) AS u56
            FROM all_products_clean p
            JOIN all_sales s ON s.variant_sku = p.sku AND s.sale_kind IN ('sale','order')
            WHERE p.style_name IN (SELECT style_name FROM base)
            GROUP BY p.style_name
        ),
        stock AS (
            SELECT p.style_name,
                SUM(CASE WHEN i.pos_location_name NOT IN (""" + WAREHOUSE_LOCATIONS + """)
                         THEN i.available ELSE 0 END) AS store_stock,
                SUM(CASE WHEN i.pos_location_name IN (""" + WAREHOUSE_LOCATIONS + """)
                         THEN i.available ELSE 0 END) AS warehouse_stock
            FROM all_products_clean p
            JOIN all_inventory i ON i.sku = p.sku
            WHERE p.style_name IN (SELECT style_name FROM base)
            GROUP BY p.style_name
        ),
        wip AS (
            SELECT po.style_name, SUM(b.qty_here) AS wip_units
            FROM production_orders po
            JOIN v_stage_balances b ON b.order_ref = po.order_ref
            WHERE b.stage NOT IN ('warehouse', 'waiting_sewing', 'sewing', 'finishing') AND po.style_name IS NOT NULL
            GROUP BY po.style_name
        ),
        recent_store AS (
            -- (pos, sku) pairs that HAVE sold at that store within aged_n days.
            -- "last sale older than aged_n OR never sold" is equivalent to
            -- "no sale at that store within aged_n days", so a recent-window
            -- semi-join replaces the full-history MAX(sale_date) per (pos,sku)
            -- aggregate (which scanned all of all_sales and spilled ~190MB to
            -- temp). Same result, ~half the time, no temp spill.
            SELECT DISTINCT pos_location_name AS pos, variant_sku AS sku
            FROM all_sales
            WHERE sale_kind IN ('sale','order')
              AND sale_date::date >= CURRENT_DATE - (""" + str(aged_n) + """ || ' days')::interval
        ),
        aged AS (
            SELECT p.style_name, SUM(i.available) AS aged_units
            FROM all_inventory i
            JOIN all_products_clean p ON p.sku = i.sku
            LEFT JOIN recent_store r ON r.pos = i.pos_location_name AND r.sku = i.sku
            WHERE i.available > 0
              AND i.pos_location_name NOT IN (""" + WAREHOUSE_LOCATIONS + """)
              AND r.pos IS NULL
            GROUP BY p.style_name
        )
        SELECT b.style_name, b.brand, b.subcategory, b.style_launch_date,
            b.price, b.cost,
            COALESCE(sa.lifetime_units, 0) AS lifetime_units,
            COALESCE(sa.lifetime_sales, 0) AS lifetime_sales,
            sa.first_sale,
            COALESCE(sa.u28, 0) AS u28,
            COALESCE(sa.u56, 0) AS u56,
            COALESCE(st.store_stock, 0) AS store_stock,
            COALESCE(st.warehouse_stock, 0) AS warehouse_stock,
            COALESCE(w.wip_units, 0) AS wip_units,
            COALESCE(ag.aged_units, 0) AS aged_units
        FROM base b
        LEFT JOIN sales sa USING (style_name)
        LEFT JOIN stock st USING (style_name)
        LEFT JOIN wip   w  USING (style_name)
        LEFT JOIN aged  ag USING (style_name)
        WHERE COALESCE(sa.u56, 0) > 0
    """) or []

    # Censoring signal (approx): styles recently flagged at-risk (low weeks-of-
    # cover) in the weekly stockout snapshot. No daily SOH history exists, so this
    # plus sub-1-week current cover is our right-censoring proxy.
    try:
        atr = _users_exec(
            "SELECT DISTINCT style_name FROM stockout_snapshots "
            "WHERE at_risk = true AND snapshot_date >= CURRENT_DATE - 21",
            fetch=True) or []
        at_risk = {r.get("style_name") for r in atr if r.get("style_name")}
    except Exception:
        at_risk = set()

    today = _date.today()

    def _weeks_live(r):
        for k in ("first_sale", "style_launch_date"):
            v = r.get(k)
            if v:
                try:
                    d = _dt.fromisoformat(str(v)[:10]).date()
                    return max(1.0, (today - d).days / 7.0)
                except Exception:
                    pass
        return 8.0

    # Category prior = median weekly rate (u56/8) across styles in the same
    # subcategory; global median as the fallback.
    cat_obs, all_obs = {}, []
    for r in rows:
        wk = float(r.get("u56") or 0) / 8.0
        if wk > 0:
            cat_obs.setdefault(r.get("subcategory") or "_", []).append(wk)
            all_obs.append(wk)
    cat_prior = {k: _median(v) for k, v in cat_obs.items() if v}
    g_prior = _median(all_obs) if all_obs else 0.5

    K = 3.0          # prior strength, in weeks of pseudo-observation
    HOLD_FRAC = 0.25 # Co = unit_cost x (holding + markdown + cash) over the horizon
    LEAD = max(0, int(lead_weeks))
    COVER = max(1, int(cover_weeks))
    H = LEAD + COVER
    floor = max(0, int(confidence_floor))

    out = []
    for r in rows:
        sub = r.get("subcategory") or "_"
        prior = cat_prior.get(sub, g_prior) or g_prior
        u28 = float(r.get("u28") or 0)
        u56 = float(r.get("u56") or 0)
        lifetime = float(r.get("lifetime_units") or 0)
        wlive = _weeks_live(r)
        exposure = min(4.0, max(1.0, wlive))
        a_post = prior * K + u28
        b_post = K + exposure
        rate = (a_post / b_post) if b_post > 0 else 0.0  # posterior weekly mean

        store = float(r.get("store_stock") or 0)
        wh = float(r.get("warehouse_stock") or 0)
        wip = float(r.get("wip_units") or 0)
        aged = float(r.get("aged_units") or 0)
        net_pos = store + wh + wip

        cover_now = (store / rate) if rate > 0 else 999.0
        censored = (r.get("style_name") in at_risk) or (rate > 0 and cover_now < 1.0)
        cfac = 1.3 if censored else 1.0

        price = float(r.get("price") or 0)
        cost = float(r.get("cost") or 0)
        if price > 0 and 0 < cost < price:
            margin_kes, cost_eff = price - cost, cost
        elif price > 0:
            margin_kes, cost_eff = price * 0.5, price * 0.5
        else:
            margin_kes, cost_eff = 0.0, 0.0

        Cu = margin_kes
        Co = cost_eff * HOLD_FRAC
        qstar = (Cu / (Cu + Co)) if (Cu + Co) > 0 else 0.7
        qstar = min(0.95, max(0.5, qstar))

        p10 = _gamma_quantile(a_post, b_post, 0.10) * H * cfac
        p50 = _gamma_quantile(a_post, b_post, 0.50) * H * cfac
        p90 = _gamma_quantile(a_post, b_post, 0.90) * H * cfac
        target = _gamma_quantile(a_post, b_post, qstar) * H * cfac

        rec = max(0, int(round(target - net_pos)))
        eligible = lifetime >= floor
        gate = None
        if not eligible:
            rec = 0
            gate = "below_confidence_floor"
        # Advisory only (store_stock already nets these dead units out of the
        # buy): flag when there is an actual cut to make AND the aged stock is a
        # material share of on-hand, i.e. redistribution could offset the re-cut.
        aged_block = bool(rec > 0 and aged >= 10 and aged >= 0.25 * store)
        if eligible and aged_block:
            gate = "aged_stock_elsewhere"

        opp = margin_kes * rate * cfac
        opportunity_value = int(round(opp * COVER))
        exp_margin = int(round(margin_kes * p50))
        inv_val = cost_eff * max(net_pos, 1.0)
        gmroi = round(min(99.0, (margin_kes * rate * 52.0) / inv_val), 1) if inv_val > 0 else 0.0
        payback = None
        if rec > 0 and margin_kes > 0 and rate > 0:
            payback = int(round((rec * cost_eff) / (margin_kes * (rate / 7.0))))

        r28, r56 = u28 / 4.0, u56 / 8.0
        if r56 > 0 and r28 >= r56 * 1.15:
            trend = "accelerating"
        elif r56 > 0 and r28 <= r56 * 0.85:
            trend = "decelerating"
        else:
            trend = "stable"

        is_new = wlive <= (90.0 / 7.0)
        sor = round(100.0 * lifetime / (lifetime + store), 1) if (lifetime + store) > 0 else 0.0
        conf = "High" if lifetime >= 200 else ("Medium" if eligible else "Low")

        d_lead = p50 * (LEAD / float(H)) if H > 0 else 0.0
        lost_units = max(0.0, d_lead - net_pos)
        at_risk_row = int(round(lost_units * (price if price > 0 else cost_eff * 2)))

        out.append({
            "style_name": r.get("style_name"),
            "brand": r.get("brand"),
            "subcategory": r.get("subcategory"),
            "product_type": r.get("subcategory"),
            "style_launch_date": r.get("style_launch_date"),
            "bucket": "newness" if is_new else "core",
            "is_new": is_new,
            "eligible": eligible,
            "gate": gate,
            "confidence": conf,
            "lifetime_units": int(lifetime),
            "lifetime_sales": float(r.get("lifetime_sales") or 0),
            "u28": int(u28),
            "u56": int(u56),
            "weekly_rate": round(rate, 2),
            "censored": bool(censored),
            "trend": trend,
            "sor_percent": sor,
            "store_stock": int(store),
            "warehouse_stock": int(wh),
            "wip_units": int(wip),
            "open_po": int(wip),
            "net_position": int(net_pos),
            "aged_units": int(aged),
            "aged_block": aged_block,
            "demand_p10": int(round(p10)),
            "demand_p50": int(round(p50)),
            "demand_p90": int(round(p90)),
            "qstar": round(qstar, 2),
            "recommended_buy": rec,
            "margin_per_unit": int(round(margin_kes)),
            "expected_margin_kes": exp_margin,
            "opportunity_value": opportunity_value,
            "gmroi": gmroi,
            "payback_days": payback,
            "kes_committed": int(round(rec * cost_eff)),
            "at_risk_kes": at_risk_row,
            "price": int(round(price)),
            "cost": int(round(cost_eff)),
        })

    # Re-Order population rule: NEW styles only (launched in the last 90 days)
    # with a strong launch Sell-Out Rate (>= 50%) — "strong launch performance,
    # likely to stock-out without replenishment". Established/core styles are
    # handled by the replenishment flow, not this buy list.
    out = [x for x in out
           if x.get("bucket") == "newness" and (x.get("sor_percent") or 0) >= 50.0]

    out.sort(key=lambda x: (0 if x["eligible"] else 1, -(x["opportunity_value"] or 0)))
    for i, x in enumerate(out):
        x["rank"] = i + 1
    out = out[:max(1, int(limit))]

    elig = [x for x in out if x["eligible"]]
    rec_value = sum(x["kes_committed"] for x in elig)
    tot_w = sum(x["kes_committed"] for x in elig)
    if tot_w > 0:
        blended_gmroi = round(sum(x["gmroi"] * x["kes_committed"] for x in elig) / tot_w, 1)
    elif elig:
        blended_gmroi = round(sum(x["gmroi"] for x in elig) / len(elig), 1)
    else:
        blended_gmroi = 0.0

    summary = {
        "candidates": len(out),
        "eligible": len(elig),
        "watch": len(out) - len(elig),
        "recommended_buy_value_kes": int(rec_value),
        "at_risk_sor_kes": int(round(sum(x["at_risk_kes"] for x in elig))),
        "blended_gmroi": blended_gmroi,
        "buy_units_total": int(sum(x["recommended_buy"] for x in elig)),
        "lead_weeks": LEAD,
        "cover_weeks": COVER,
        "horizon_weeks": H,
        "confidence_floor": floor,
        "aged_days": aged_n,
        "censored_note": ("Censored-demand correction is approximate: no per-day "
                          "stock-on-hand history is retained, so stock-out days are "
                          "inferred from recent at-risk snapshots and current "
                          "sub-1-week cover."),
    }
    return {"summary": summary, "candidates": out}


@app.get("/api/analytics/aged-stock")
def analytics_aged_stock(
    min_days_since_sale: int = Query(default=60),
    days:                int = Query(default=None),
):
    # Per SKU-store row of store stock that hasn't sold in >= N days at that
    # store. Shape matches AgedStockReport.jsx. `days` kept as a back-compat alias
    # for the min-days threshold. Never-sold SKUs surface with the 999 sentinel so
    # the frontend renders "Never". soh = store on-hand, soh_warehouse = WH on-hand
    # for the same SKU so the merchandiser sees the full replenishable footprint.
    n = int(days) if days is not None else int(min_days_since_sale)
    # Phase 2 A6 — weekly_units per SKU uses the standardized recency-weighted
    # velocity (28d ×2 over a 12-week-equivalent denominator on a trailing 56d
    # window). For aged stock it is near-zero by definition, which is the point:
    # it quantifies how slowly each SKU is actually moving.
    rows = run_query("""
        WITH last_sale AS (
            SELECT variant_sku AS sku, MAX(sale_date) AS last_sold,
                SUM(CASE WHEN sale_date::date >= CURRENT_DATE - INTERVAL '180 days'
                         THEN ordered_item_quantity ELSE 0 END) AS units_180,
                SUM(CASE WHEN sale_date::date >= CURRENT_DATE - INTERVAL '28 days'
                         THEN ordered_item_quantity ELSE 0 END) AS u28,
                SUM(CASE WHEN sale_date::date >= CURRENT_DATE - INTERVAL '56 days'
                         THEN ordered_item_quantity ELSE 0 END) AS u56
            FROM all_sales
            WHERE sale_kind IN ('sale','order')
            GROUP BY variant_sku
        ),
        wh AS (
            SELECT sku, SUM(available) AS soh_warehouse
            FROM all_inventory
            WHERE pos_location_name = 'Warehouse Finished Goods'
            GROUP BY sku
        )
        SELECT i.pos_location_name AS pos_location,
            i.sku,
            COALESCE(NULLIF(MAX(p.product_name), ''), MAX(i.product_name)) AS product_name,
            MAX(p.size) AS size,
            MAX(p.barcode) AS barcode,
            MAX(i.color_print) AS color,
            COALESCE(MAX(ls.units_180), 0) AS units_sold_180d,
            SUM(i.available) AS soh,
            COALESCE(MAX(wh.soh_warehouse), 0) AS soh_warehouse,
            ROUND(((COALESCE(MAX(ls.u28), 0) * 2)
                   + GREATEST(COALESCE(MAX(ls.u56), 0) - COALESCE(MAX(ls.u28), 0), 0)) / 12.0, 2) AS weekly_units,
            CASE WHEN MAX(ls.last_sold) IS NULL THEN 999
                 ELSE (CURRENT_DATE - MAX(ls.last_sold)::date) END AS days_since_last_sale,
            MAX(ls.last_sold) AS last_sale_date
        FROM all_inventory i
        LEFT JOIN last_sale ls ON i.sku = ls.sku
        LEFT JOIN wh ON i.sku = wh.sku
        LEFT JOIN all_products_clean p ON i.sku = p.sku
        WHERE i.available > 0
        AND i.pos_location_name NOT IN (""" + WAREHOUSE_LOCATIONS + """)
        AND (ls.last_sold IS NULL
             OR ls.last_sold::date < CURRENT_DATE - (""" + str(n) + """ || ' days')::interval)
        GROUP BY i.pos_location_name, i.sku
        ORDER BY days_since_last_sale DESC, soh DESC
        LIMIT 1000
    """, ttl=HEAVY_DASH_TTL)
    for r in rows:
        r["velocity_method"] = "ewma_56d"
    return rows

@app.get("/api/analytics/warehouse-return-candidates")
def analytics_warehouse_return_candidates(
    mode:     str = Query(default="aged"),
    min_days: int = Query(default=30),
):
    """Store SKUs that are candidates to be returned to the warehouse, for the
    Warehouse Returns page. Two modes:

      * 'aged'    — stock that has not sold AT ITS STORE in >= min_days days
                    (never-sold SKUs included, surfaced with the 999 sentinel).
      * 'retired' — stock of RETIRED styles: no company-wide sales in the last
                    182 days, OR marked Retired in Odoo (force-included even
                    if they still sell, honouring _odoo_retired_styles so
                    this page agrees with Range Mgmt / Product Analysis).

    One row per SKU-store with store SOH (soh), warehouse SOH (soh_warehouse),
    days-since-last-sale and `already_marked` (true once it has been marked for a
    warehouse return). Warehouses themselves are excluded as the destination."""
    m = "retired" if str(mode).lower() == "retired" else "aged"
    n = max(0, int(min_days))
    # WS9 T902 — this scan (all_inventory x last-sale semi-join) is heavy enough
    # to feel like a hang on first load; serve from a snapshot-coherent cache so
    # repeat visits are instant. Keyed on the inventory snapshot version like
    # the Product Analysis cache, so a new stock snapshot invalidates it.
    _wr_ck = "wrc:" + _inventory_version() + f":{m}:{n}"
    _wr_cached, _wr_fresh = cache_get_swr(_wr_ck)
    if _wr_cached is not None:
        if not _wr_fresh:
            swr_refresh(_wr_ck, lambda: analytics_warehouse_return_candidates(
                mode=mode, min_days=min_days), label="wrc")
        return _wr_cached
    if m == "aged":
        # Aged = not sold AT ITS STORE in >= n days. Make Aged and Retired
        # mutually exclusive (a SKU must land in exactly one bucket): exclude
        # styles that qualify as Retired (no company-wide sales in 182d OR on
        # Retired in Odoo) so a retired-and-also-stale SKU only shows
        # under Retired, never both.
        where_extra = ("AND (ls.last_sold IS NULL "
                       "OR ls.last_sold::date < CURRENT_DATE - ("
                       + str(n) + " || ' days')::interval) "
                       "AND COALESCE(ss.units_182, 0) > 0 "
                       "AND p.style_name NOT IN (" + _ODOO_RETIRED_STYLES_SQL + ")")
    else:
        where_extra = ("AND (COALESCE(ss.units_182, 0) = 0 "
                       "OR p.style_name IN (" + _ODOO_RETIRED_STYLES_SQL + "))")
    rows = run_query("""
        WITH last_sale AS (
            SELECT pos_location_name AS pos_location, variant_sku AS sku,
                MAX(sale_date) AS last_sold,
                SUM(CASE WHEN sale_date::date >= CURRENT_DATE - INTERVAL '180 days'
                         THEN ordered_item_quantity ELSE 0 END) AS units_180
            FROM all_sales
            WHERE sale_kind IN ('sale','order')
            GROUP BY pos_location_name, variant_sku
        ),
        style_sales AS (
            SELECT p.style_name,
                SUM(CASE WHEN s.sale_date::date >= CURRENT_DATE - INTERVAL '182 days'
                         THEN s.ordered_item_quantity ELSE 0 END) AS units_182
            FROM all_sales s
            JOIN all_products_clean p ON s.variant_sku = p.sku
            WHERE s.sale_kind IN ('sale','order')
            GROUP BY p.style_name
        ),
        wh AS (
            SELECT sku, SUM(available) AS soh_warehouse
            FROM all_inventory
            WHERE pos_location_name = 'Warehouse Finished Goods'
            GROUP BY sku
        ),
        marked AS (
            SELECT split_part(rec_key,'|',1) AS pos_location,
                   split_part(rec_key,'|',3) AS sku
            FROM recommendation_actions
            WHERE rec_type='warehouse_return' AND status='done'
        )
        SELECT i.pos_location_name AS pos_location,
            i.sku,
            COALESCE(NULLIF(MAX(p.product_name), ''), NULLIF(MAX(i.product_name), ''), MAX(p.style_name)) AS product_name,
            MAX(p.size) AS size,
            MAX(p.barcode) AS barcode,
            MAX(i.color_print) AS color,
            MAX(p.style_name) AS style_name,
            COALESCE(MAX(ls.units_180), 0) AS units_sold_180d,
            SUM(i.available) AS soh,
            COALESCE(MAX(wh.soh_warehouse), 0) AS soh_warehouse,
            CASE WHEN MAX(ls.last_sold) IS NULL THEN 999
                 ELSE (CURRENT_DATE - MAX(ls.last_sold)::date) END AS days_since_last_sale,
            MAX(ls.last_sold) AS last_sale_date,
            BOOL_OR(m.sku IS NOT NULL) AS already_marked
        FROM all_inventory i
        LEFT JOIN last_sale ls
            ON i.sku = ls.sku AND i.pos_location_name = ls.pos_location
        LEFT JOIN wh ON i.sku = wh.sku
        LEFT JOIN all_products_clean p ON i.sku = p.sku
        LEFT JOIN style_sales ss ON p.style_name = ss.style_name
        LEFT JOIN marked m
            ON m.pos_location = i.pos_location_name AND m.sku = i.sku
        WHERE i.available > 0
        AND i.pos_location_name NOT IN (""" + WAREHOUSE_LOCATIONS + """)
        """ + where_extra + """
        GROUP BY i.pos_location_name, i.sku
        ORDER BY days_since_last_sale DESC, soh DESC
        LIMIT 1500
    """)
    out = {"mode": m, "min_days": n, "rows": rows}
    cache_set(_wr_ck, out, ttl=600)
    return out


# ── Excess Inventory report ───────────────────────────────────────────────────
# Business rule (provided by merchandising as a per-brand, per-size allowance
# table): a store should hold AT MOST this many units of any single SKU of the
# given brand-line + size. Anything above the allowance is EXCESS and the row is
# flagged "Return" (return the excess to the warehouse); at-or-below allowance,
# or a size/brand with no rule, is "Keep".
#   • "VIVO"          = brand 'Vivo' EXCLUDING the Vivo Studio line
#   • "SAFARI X VIVO" = brands 'Safari' + 'Safari by Vivo'
#   • "STUDIO"        = the Vivo Studio line (product_name 'Vivo Studio …')
# Other brands (Zoya, third-party) have no allowance ⇒ always "Keep".
EXCESS_ALLOWANCE = {
    "VIVO":          {"S": 2, "M": 3, "L": 3, "1X": 2, "2X": 1, "F": 4,
                      "XS/S": 2, "M/L": 2, "1X/2X": 1, "S/M": 2, "L/1X": 1},
    "SAFARI X VIVO": {"S": 2, "M": 3, "L": 2, "1X": 1, "2X": 1, "F": 4,
                      "XS/S": 2, "M/L": 2, "1X/2X": 1},
    "STUDIO":        {"XS": 1, "S": 2, "M": 3, "L": 2, "1X": 1, "F": 4,
                      "XS/S": 2, "M/L": 2, "1X/2X": 1},
}

# Packs carried per store (business-supplied, July 2026): a store carrying 2
# packs of a size may hold DOUBLE the per-size allowance (allowed = base × packs).
# Stores not listed here carry 1 pack (multiplier 1). Names match
# all_inventory.pos_location_name exactly ("Online" = 'Online - Shop Zetu';
# 'Safari Sarit' & 'Zoya Sarit' are 1-pack, i.e. the default).
EXCESS_STORE_PACKS = {
    "Vivo Mama Ngina St":  2,
    "Vivo Junction":       2,
    "Vivo Moi Avenue":     2,
    "Vivo Sarit":          2,
    "Online - Shop Zetu":  2,
    "Vivo Village Market": 2,
    "Vivo Yaya":           2,
}

_EXCESS_ROW_CAP = 4000  # generous safety bound for one response, NOT a ranking

# Some Odoo product records (mostly samples, sets and legacy SKUs) genuinely
# have NO size on the master record — but the size is usually encoded at the
# end of the SKU (e.g. LILI000192GRNS → S, 1021158NABM → M). Conservative
# fallback: match a known size token at the SKU end, ONLY when preceded by a
# letter (so hash-like SKUs such as '695cb4d4a788f' don't parse as size F).
_SKU_SIZE_TOKENS = ["1X/2X", "XS/S", "S/M", "M/L", "L/1X",
                    "XXS", "XXL", "XS", "XL", "1X", "2X", "3X", "4X",
                    "S", "M", "L", "F"]
_SKU_SIZE_RE = re.compile(
    r"[A-Za-z](" + "|".join(re.escape(t) for t in _SKU_SIZE_TOKENS) + r")$",
    re.IGNORECASE)


def _size_from_sku(sku):
    """Best-effort size recovery from the SKU suffix; None when not confident."""
    m = _SKU_SIZE_RE.search((sku or "").strip())
    return m.group(1).upper() if m else None

_excess_actions_ready = False


def _ensure_excess_actions_table():
    """Lazy-create the fillable-fields table (fresh prod DB safe)."""
    global _excess_actions_ready
    if _excess_actions_ready:
        return
    _users_exec("""
        CREATE TABLE IF NOT EXISTS excess_inventory_actions (
            pos_location TEXT NOT NULL,
            sku          TEXT NOT NULL,
            qty_returned INTEGER,
            transfer_ref TEXT,
            updated_by   TEXT,
            updated_at   TIMESTAMPTZ DEFAULT now(),
            PRIMARY KEY (pos_location, sku)
        )""")
    _users_exec("ALTER TABLE excess_inventory_actions "
                "ADD COLUMN IF NOT EXISTS done_at TIMESTAMPTZ")
    _excess_actions_ready = True


def _excess_actions_map():
    """(pos_location, sku) -> {qty_returned, transfer_ref}. Never cached — these
    are operator-entered values that must reflect immediately."""
    _ensure_excess_actions_table()
    rows = _users_exec(
        "SELECT pos_location, sku, qty_returned, transfer_ref, done_at "
        "FROM excess_inventory_actions", fetch=True) or []
    return {(r["pos_location"], r["sku"]):
            {"qty_returned": r["qty_returned"], "transfer_ref": r["transfer_ref"],
             "done": r["done_at"] is not None}
            for r in rows}


def _excess_inventory_dataset():
    """Full store-level excess dataset (all POS, all flags), snapshot-cached.

    One row per (store, SKU) with available stock in a store (store = NOT IN
    WAREHOUSE_LOCATIONS; the Online location is INCLUDED per business request).
    Flags are computed here so every filtered view and the per-POS summary
    agree."""
    ck = "excessinv:" + _inventory_version()
    cached, fresh = cache_get_swr(ck)
    if cached is not None:
        if not fresh:
            swr_refresh(ck, _excess_inventory_dataset, label="excessinv")
        return cached
    rows = run_query("""
        SELECT i.pos_location_name AS pos_location,
            i.sku,
            COALESCE(NULLIF(MAX(p.product_name), ''), NULLIF(MAX(i.product_name), ''), MAX(p.style_name)) AS product_name,
            MAX(p.barcode) AS barcode,
            UPPER(TRIM(COALESCE(MAX(p.size), ''))) AS size,
            MAX(p.brand) AS brand,
            BOOL_OR(p.product_name ILIKE 'vivo studio%') AS is_studio,
            SUM(i.available) AS inventory
        FROM all_inventory i
        LEFT JOIN all_products_clean p ON i.sku = p.sku
        WHERE i.available > 0
          AND i.pos_location_name NOT IN (""" + WAREHOUSE_LOCATIONS + """)
        GROUP BY i.pos_location_name, i.sku
    """)
    out = []
    for r in rows:
        brand = (r.get("brand") or "").strip()
        if r.get("is_studio"):
            group = "STUDIO"
        elif brand in ("Safari", "Safari by Vivo"):
            group = "SAFARI X VIVO"
        elif brand == "Vivo":
            group = "VIVO"
        else:
            group = "OTHER"
        size = (r.get("size") or "").strip() or _size_from_sku(r.get("sku"))
        allowed = EXCESS_ALLOWANCE.get(group, {}).get(size or "")
        packs = EXCESS_STORE_PACKS.get(r["pos_location"], 1)
        if allowed is not None:
            allowed = allowed * packs
        inv = int(r.get("inventory") or 0)
        excess = max(0, inv - allowed) if allowed is not None else 0
        out.append({
            "pos_location": r["pos_location"],
            "sku": r["sku"],
            "product_name": r.get("product_name"),
            "barcode": r.get("barcode"),
            "size": size or None,
            "brand_group": group,
            "inventory": inv,
            "packs": packs,
            "allowed": allowed,
            "excess": excess,
            "flag": "Return" if excess > 0 else "Keep",
        })
    cache_set(ck, out, ttl=600)
    return out


@app.get("/api/analytics/excess-inventory")
def analytics_excess_inventory(
    pos:  str = Query(default=""),
    flag: str = Query(default=""),
):
    """Excess Inventory report: store × SKU rows flagged Keep/Return against the
    per-brand per-size allowance table, plus a per-POS summary (total inventory
    and excess inventory = sum of each SKU-size's excess)."""
    data = _excess_inventory_dataset()
    pos = (pos or "").strip()
    flag = (flag or "").strip().capitalize()
    if flag not in ("Keep", "Return"):
        flag = ""

    scoped = [r for r in data if r["pos_location"] == pos] if pos else data

    # Per-POS summary (respects the POS filter, ignores the flag filter so the
    # Keep/Return split always reconciles to the same totals). "Done" figures
    # come from the operator ledger (excess_inventory_actions.done_at).
    actions = _excess_actions_map()
    by_pos = {}
    for r in scoped:
        s = by_pos.setdefault(r["pos_location"], {
            "pos_location": r["pos_location"], "skus": 0,
            "total_inventory": 0, "excess_inventory": 0, "return_skus": 0,
            "done_units": 0, "done_skus": 0})
        s["skus"] += 1
        s["total_inventory"] += r["inventory"]
        s["excess_inventory"] += r["excess"]
        if r["excess"] > 0:
            s["return_skus"] += 1
            a = actions.get((r["pos_location"], r["sku"]))
            if a and a.get("done"):
                s["done_units"] += r["excess"]
                s["done_skus"] += 1
    summary = sorted(by_pos.values(), key=lambda s: -s["excess_inventory"])
    totals = {
        "skus": sum(s["skus"] for s in summary),
        "total_inventory": sum(s["total_inventory"] for s in summary),
        "excess_inventory": sum(s["excess_inventory"] for s in summary),
        "return_skus": sum(s["return_skus"] for s in summary),
        "done_units": sum(s["done_units"] for s in summary),
        "done_skus": sum(s["done_skus"] for s in summary),
    }

    filtered = [r for r in scoped if r["flag"] == flag] if flag else scoped
    filtered = sorted(filtered, key=lambda r: (-r["excess"], -r["inventory"]))
    truncated = len(filtered) > _EXCESS_ROW_CAP

    # Merge operator-entered fields (qty returned / transfer no. / done) into
    # the visible page only. COPY each cached dict before annotating — the
    # snapshot cache returns rows by reference and must never be mutated.
    page = []
    for r in filtered[:_EXCESS_ROW_CAP]:
        row = dict(r)
        a = actions.get((r["pos_location"], r["sku"]))
        row["qty_returned"] = a["qty_returned"] if a else None
        row["transfer_ref"] = a["transfer_ref"] if a else None
        row["done"] = bool(a and a.get("done"))
        page.append(row)
    return {
        "rows": page,
        "row_count": len(filtered),
        "truncated": truncated,
        "summary": summary,
        "totals": totals,
        "pos_locations": sorted(by_pos.keys()) if not pos else sorted({r["pos_location"] for r in data}),
        "allowance": EXCESS_ALLOWANCE,
        "store_packs": EXCESS_STORE_PACKS,
    }


@app.post("/api/analytics/excess-inventory/action")
async def analytics_excess_inventory_action(request: Request):
    """Save the operator-filled fields for one (store, SKU) row: quantity
    actually returned and/or the Odoo transfer number. Blank values clear the
    field; a row with both fields blank is deleted."""
    from fastapi import HTTPException
    body = await request.json()
    pos_location = (body.get("pos_location") or "").strip()
    sku = (body.get("sku") or "").strip()
    if not pos_location or not sku:
        raise HTTPException(status_code=400, detail="pos_location and sku are required")
    qty_raw = body.get("qty_returned")
    qty = None
    if qty_raw is not None and str(qty_raw).strip() != "":
        try:
            qty = int(str(qty_raw).strip())
        except ValueError:
            raise HTTPException(status_code=400, detail="qty_returned must be a whole number")
        if qty < 0:
            raise HTTPException(status_code=400, detail="qty_returned cannot be negative")
    transfer_ref = (body.get("transfer_ref") or "").strip() or None
    user = getattr(request.state, "user", None) or {}
    updated_by = user.get("email") or user.get("user_id")

    _ensure_excess_actions_table()
    if qty is None and transfer_ref is None:
        # Clear the fields but PRESERVE a done mark; drop the row only when
        # nothing is left on it at all.
        _users_exec(
            "UPDATE excess_inventory_actions SET qty_returned=NULL, transfer_ref=NULL, "
            "  updated_by=%s, updated_at=now() WHERE pos_location=%s AND sku=%s",
            (updated_by, pos_location, sku))
        _users_exec(
            "DELETE FROM excess_inventory_actions "
            "WHERE pos_location=%s AND sku=%s AND done_at IS NULL",
            (pos_location, sku))
    else:
        _users_exec(
            "INSERT INTO excess_inventory_actions "
            "  (pos_location, sku, qty_returned, transfer_ref, updated_by, updated_at) "
            "VALUES (%s,%s,%s,%s,%s,now()) "
            "ON CONFLICT (pos_location, sku) DO UPDATE SET "
            "  qty_returned=EXCLUDED.qty_returned, transfer_ref=EXCLUDED.transfer_ref, "
            "  updated_by=EXCLUDED.updated_by, updated_at=now()",
            (pos_location, sku, qty, transfer_ref, updated_by))
    return {"ok": True, "pos_location": pos_location, "sku": sku,
            "qty_returned": qty, "transfer_ref": transfer_ref}


@app.post("/api/analytics/excess-inventory/done")
async def analytics_excess_inventory_done(request: Request):
    """Toggle the Done mark for one (store, SKU) excess row. Marking done
    stamps done_at (the row stays visible in the list); un-marking clears it.
    Other operator fields (qty returned / transfer no.) are preserved."""
    from fastapi import HTTPException
    body = await request.json()
    pos_location = (body.get("pos_location") or "").strip()
    sku = (body.get("sku") or "").strip()
    if not pos_location or not sku:
        raise HTTPException(status_code=400, detail="pos_location and sku are required")
    done_raw = body.get("done", True)
    if isinstance(done_raw, str):
        done = done_raw.strip().lower() not in ("false", "0", "no", "")
    else:
        done = bool(done_raw)
    user = getattr(request.state, "user", None) or {}
    updated_by = user.get("email") or user.get("user_id")

    _ensure_excess_actions_table()
    if done:
        _users_exec(
            "INSERT INTO excess_inventory_actions "
            "  (pos_location, sku, done_at, updated_by, updated_at) "
            "VALUES (%s,%s,now(),%s,now()) "
            "ON CONFLICT (pos_location, sku) DO UPDATE SET "
            "  done_at=now(), updated_by=EXCLUDED.updated_by, updated_at=now()",
            (pos_location, sku, updated_by))
    else:
        _users_exec(
            "UPDATE excess_inventory_actions SET done_at=NULL, "
            "  updated_by=%s, updated_at=now() WHERE pos_location=%s AND sku=%s",
            (updated_by, pos_location, sku))
        _users_exec(
            "DELETE FROM excess_inventory_actions "
            "WHERE pos_location=%s AND sku=%s "
            "  AND qty_returned IS NULL AND transfer_ref IS NULL AND done_at IS NULL",
            (pos_location, sku))
    return {"ok": True, "pos_location": pos_location, "sku": sku, "done": done}


@app.get("/api/analytics/rebalancing")
def analytics_rebalancing():
    """Store Rebalancing report — one row per (store, SKU) showing stock that
    should be returned to the warehouse.

    Three sources, each (store, SKU) appears at most once (priority: Retired > Excess > Slow Mover):
      * Retired    — Odoo-retired OR no company-wide sales in 182 days. Return ALL store units.
      * Excess     — units above the brand × size allowance. Return the excess qty only.
      * Slow Mover — not sold AT THIS STORE in >= 45 days (not already Retired or Excess). Return ALL.

    Columns: store, product_title, sku, barcode, size, brand, inventory,
             proposed_return, reason, days_since_last_sale.
    """
    ck = "rebalancing:" + _inventory_version()
    cached, fresh = cache_get_swr(ck)
    if cached is not None:
        if not fresh:
            swr_refresh(ck, analytics_rebalancing, label="rebalancing")
        return cached

    # Build excess lookup from the shared snapshot (already snapshot-cached)
    excess_raw = _excess_inventory_dataset()
    excess_map = {(r["pos_location"], r["sku"]): r
                  for r in excess_raw if (r.get("excess") or 0) > 0}

    # One SQL: all store SKUs that are retired OR not sold at-store in 45+ days.
    # Excess-only rows (still selling but overstocked) are added in Python below.
    rows = run_query("""
        WITH store_inv AS (
            SELECT i.pos_location_name                                           AS store,
                   i.sku,
                   SUM(i.available)                                              AS inventory,
                   COALESCE(NULLIF(MAX(p.product_name),''), MAX(p.style_name))   AS product_title,
                   MAX(p.barcode)                                                 AS barcode,
                   UPPER(TRIM(COALESCE(MAX(p.size),'')))                          AS size,
                   MAX(p.brand)                                                   AS brand,
                   MAX(p.style_name)                                              AS style_name
            FROM all_inventory i
            LEFT JOIN all_products_clean p ON i.sku = p.sku
            WHERE i.available > 0
              AND i.pos_location_name NOT IN (""" + WAREHOUSE_LOCATIONS + """)
            GROUP BY i.pos_location_name, i.sku
        ),
        last_sale AS (
            SELECT pos_location_name AS store, variant_sku AS sku,
                   MAX(sale_date::date) AS last_sold
            FROM all_sales
            WHERE sale_kind IN ('sale','order')
            GROUP BY pos_location_name, variant_sku
        ),
        style_sales_182 AS (
            SELECT p.style_name,
                   SUM(CASE WHEN s.sale_date::date >= CURRENT_DATE - 182
                            THEN s.ordered_item_quantity ELSE 0 END) AS units_182
            FROM all_sales s
            JOIN all_products_clean p ON s.variant_sku = p.sku
            WHERE s.sale_kind IN ('sale','order')
            GROUP BY p.style_name
        )
        SELECT si.store, si.sku, si.product_title, si.barcode, si.size, si.brand,
               si.inventory, si.style_name, ls.last_sold,
               CASE WHEN ls.last_sold IS NULL THEN 999
                    ELSE (CURRENT_DATE - ls.last_sold) END AS days_since_last_sale,
               (COALESCE(ss.units_182, 0) = 0
                OR si.style_name IN (""" + _ODOO_RETIRED_STYLES_SQL + """)) AS is_retired
        FROM store_inv si
        LEFT JOIN last_sale        ls ON ls.store = si.store AND ls.sku = si.sku
        LEFT JOIN style_sales_182  ss ON ss.style_name = si.style_name
        WHERE
            COALESCE(ss.units_182, 0) = 0
            OR si.style_name IN (""" + _ODOO_RETIRED_STYLES_SQL + """)
            OR (ls.last_sold IS NULL OR ls.last_sold < CURRENT_DATE - 45)
        ORDER BY is_retired DESC, days_since_last_sale DESC, si.inventory DESC
    """)

    seen: set = set()
    out = []

    for r in (rows or []):
        key = (r["store"], r["sku"])
        if key in seen:
            continue
        seen.add(key)
        inventory  = int(r.get("inventory") or 0)
        is_retired = bool(r.get("is_retired"))
        exc_row    = excess_map.get(key)
        size = (r.get("size") or "").strip() or _size_from_sku(r.get("sku"))
        if is_retired:
            reason, proposed = "Retired", inventory
        elif exc_row:
            reason, proposed = "Excess", int(exc_row.get("excess") or 0)
        else:
            reason, proposed = "Slow Mover", inventory
        out.append({
            "store":                r["store"],
            "product_title":        r.get("product_title"),
            "sku":                  r.get("sku"),
            "barcode":              r.get("barcode"),
            "size":                 size or None,
            "brand":                r.get("brand"),
            "inventory":            inventory,
            "proposed_return":      proposed,
            "reason":               reason,
            "days_since_last_sale": int(r.get("days_since_last_sale") or 0),
        })

    # Excess-only rows (selling well but overstocked) not captured by the SQL above
    for (store, sku), exc_row in excess_map.items():
        if (store, sku) in seen:
            continue
        seen.add((store, sku))
        size = (exc_row.get("size") or "").strip() or _size_from_sku(sku)
        out.append({
            "store":                store,
            "product_title":        exc_row.get("product_name"),
            "sku":                  sku,
            "barcode":              exc_row.get("barcode"),
            "size":                 size or None,
            "brand":                exc_row.get("brand_group"),
            "inventory":            int(exc_row.get("inventory") or 0),
            "proposed_return":      int(exc_row.get("excess") or 0),
            "reason":               "Excess",
            "days_since_last_sale": None,
        })

    result = {"rows": out}
    cache_set(ck, result, ttl=600)
    return result


@app.get("/api/inventory/freshness")
def inventory_freshness():
    rows = _users_exec("""
        SELECT pos_location_name,
            MAX(_loaded_at) AS last_updated,
            ROUND((EXTRACT(EPOCH FROM (now() - MAX(_loaded_at))) / 3600.0)::numeric, 1) AS hours_since_update,
            (now() - MAX(_loaded_at) > INTERVAL '24 hours') AS stale
        FROM all_inventory
        GROUP BY pos_location_name
        ORDER BY last_updated ASC NULLS FIRST
    """, fetch=True) or []
    for r in rows:
        if r.get("last_updated") is not None:
            r["last_updated"] = r["last_updated"].isoformat()
        if r.get("hours_since_update") is not None:
            r["hours_since_update"] = float(r["hours_since_update"])
    return rows

@app.get("/api/analytics/store-flow")
def analytics_store_flow(
    date_from: str = Query(default=str(date.today().replace(day=1))),
    date_to:   str = Query(default=str(date.today())),
    country:   str = Query(default=None),
):
    """Store Flow: per POS location over the selected period — Units Sold
    (canonical GROSS units, = _UNITS), Units Transferred In (stock_transfers
    done rows by completion day, EAT), units still in transit toward the
    store, and Current Stock (all_inventory available, pre-aggregated).

    Transfer history only ACCUMULATES from the first synced done picking
    onward (the extract keeps a rolling 7-day done window but the table now
    retains older done rows), so `transfer_history_from` tells the frontend
    the earliest day with complete transfer data."""
    where = build_filters(date_from, date_to, country)
    sales = run_query("""
        SELECT s.pos_location_name AS pos_location,
               MAX(s.country) AS country,
               """ + _UNITS + """ AS units_sold
        FROM all_sales s
        WHERE """ + where + """
        GROUP BY s.pos_location_name
    """, date_to=date_to)

    ctry_t = " AND t.to_country IN (" + csv_to_sql(country) + ")" if country else ""
    # Units Transferred = warehouse→store pickings dispatched in the period,
    # counted the moment they leave the warehouse (scheduled_date), regardless
    # of whether the store has validated receipt yet.  For done pickings use
    # qty_done (actual); for ready/assigned use qty_planned (confirmed dispatch).
    # Units Incoming = open pickings with no date filter (all in-transit stock).
    transfers = run_query("""
        SELECT t.to_store_name AS pos_location,
               MAX(t.to_country) AS country,
               COALESCE(SUM(
                   CASE WHEN t.state = 'done' THEN t.qty_done ELSE t.qty_planned END
               ) FILTER (
                   WHERE t.scheduled_date::date
                         BETWEEN '""" + date_from + """' AND '""" + date_to + """'), 0) AS units_transferred,
               COALESCE(SUM(t.qty_planned) FILTER (
                   WHERE t.state != 'done'), 0) AS units_incoming
        FROM stock_transfers t
        WHERE t.to_store_name NOT IN (""" + WAREHOUSE_LOCATIONS + """)
          AND """ + _WAREHOUSE_ORIGIN_FILTER + """
        """ + ctry_t + """
        GROUP BY t.to_store_name
    """, date_to=date_to)

    ctry_i = " AND i.country IN (" + csv_to_sql(country) + ")" if country else ""
    inventory = run_query("""
        SELECT i.pos_location_name AS pos_location,
               MAX(i.country) AS country,
               COALESCE(SUM(i.available), 0) AS current_stock
        FROM all_inventory i
        WHERE i.pos_location_name NOT IN (""" + WAREHOUSE_LOCATIONS + """)
        """ + ctry_i + """
        GROUP BY i.pos_location_name
    """, date_to=date_to)

    by = {}
    def _slot(name, ctry):
        r = by.setdefault(name, {
            "pos_location": name, "country": ctry or None,
            "units_sold": 0, "units_transferred": 0,
            "units_incoming": 0, "current_stock": 0})
        if ctry and not r["country"]:
            r["country"] = ctry
        return r
    for r in sales:
        _slot(r["pos_location"], r.get("country"))["units_sold"] = int(r["units_sold"] or 0)
    for r in transfers:
        s = _slot(r["pos_location"], r.get("country"))
        s["units_transferred"] = int(r["units_transferred"] or 0)
        s["units_incoming"] = int(r["units_incoming"] or 0)
    for r in inventory:
        _slot(r["pos_location"], r.get("country"))["current_stock"] = int(r["current_stock"] or 0)

    # WOC support: last-4-weeks sales per store (independent of the page's
    # selected period) so WOC = SOH / (units_4w / 4) stays a stable read.
    d28_from = str(date.today() - timedelta(days=28))
    d28_to = str(date.today())
    where_4w = build_filters(d28_from, d28_to, country)
    sales_4w = run_query("""
        SELECT s.pos_location_name AS pos_location,
               """ + _UNITS + """ AS units_4w
        FROM all_sales s
        WHERE """ + where_4w + """
        GROUP BY s.pos_location_name
    """, date_to=d28_to)
    u4w = {r["pos_location"]: int(r["units_4w"] or 0) for r in sales_4w}

    # Previous week (last Mon–Sun) sales per store — used as the transfer
    # pacing benchmark: target ±10% of prev-week sold.
    today_d = date.today()
    _pw_mon = today_d - timedelta(days=today_d.weekday() + 7)
    _pw_sun = _pw_mon + timedelta(days=6)
    where_pw = build_filters(str(_pw_mon), str(_pw_sun), country)
    sales_pw = run_query("""
        SELECT s.pos_location_name AS pos_location,
               """ + _UNITS + """ AS prev_week_sold
        FROM all_sales s
        WHERE """ + where_pw + """
        GROUP BY s.pos_location_name
    """, date_to=str(_pw_sun))
    pw_map = {r["pos_location"]: int(r["prev_week_sold"] or 0) for r in sales_pw}

    # Daily transfer breakdown by ISODOW (1=Mon … 7=Sun, EAT) for the
    # selected period so the UI can show a Mon–Sun column view.
    daily_xfr = run_query("""
        SELECT t.to_store_name AS pos_location,
               EXTRACT(ISODOW FROM t.scheduled_date::date)::int AS dow,
               SUM(CASE WHEN t.state = 'done' THEN t.qty_done ELSE t.qty_planned END) AS units
        FROM stock_transfers t
        WHERE t.scheduled_date::date
              BETWEEN '""" + date_from + """' AND '""" + date_to + """'
          AND t.to_store_name NOT IN (""" + WAREHOUSE_LOCATIONS + """)
          AND """ + _WAREHOUSE_ORIGIN_FILTER + """
        """ + ctry_t + """
        GROUP BY t.to_store_name, dow
    """, date_to=date_to)
    daily_map = {}
    for r in daily_xfr:
        loc = r["pos_location"]
        if loc not in daily_map:
            daily_map[loc] = {}
        daily_map[loc][int(r["dow"])] = int(r["units"] or 0)

    # Units sold in weeks 5–8 ago (days 29–56) for WOC trend
    d56_from = str(date.today() - timedelta(days=56))
    d56_to   = str(date.today() - timedelta(days=29))
    where_p4w = build_filters(d56_from, d56_to, country)
    sales_p4w = run_query("""
        SELECT s.pos_location_name AS pos_location,
               """ + _UNITS + """ AS units_prev_4w
        FROM all_sales s
        WHERE """ + where_p4w + """
        GROUP BY s.pos_location_name
    """, date_to=d56_to)
    up4w = {r["pos_location"]: int(r["units_prev_4w"] or 0) for r in sales_p4w}

    for name, r in by.items():
        r["units_4w"] = u4w.get(name, 0)
        weekly = r["units_4w"] / 4.0
        r["woc"] = round(r["current_stock"] / weekly, 1) if weekly > 0 else None
        # WOC 4 weeks ago: approximate SOH 4w ago = current_stock + units_4w (what sold since)
        r["units_prev_4w"] = up4w.get(name, 0)
        prev_weekly = r["units_prev_4w"] / 4.0
        soh_4w_ago = r["current_stock"] + r["units_4w"]
        r["woc_4w_ago"] = round(soh_4w_ago / prev_weekly, 1) if prev_weekly > 0 else None
        r["prev_week_sold"] = pw_map.get(name, 0)
        r["daily_transfers"] = daily_map.get(name, {})

    rows = sorted(by.values(), key=lambda r: (-r["prev_week_sold"], -r["units_transferred"]))
    totals = {
        "units_sold": sum(r["units_sold"] for r in rows),
        "units_transferred": sum(r["units_transferred"] for r in rows),
        "units_incoming": sum(r["units_incoming"] for r in rows),
        "current_stock": sum(r["current_stock"] for r in rows),
        "prev_week_sold": sum(r["prev_week_sold"] for r in rows),
        "stores": len(rows),
    }
    cov = run_query("""
        SELECT MIN(scheduled_date::date)::text AS first_done
        FROM stock_transfers
        WHERE state = 'done'
          AND from_location_name IN ('HWHFN/Stock','FGPRD/Stock','WHFIN/Stock','WHREC/Stock')
          AND sku NOT LIKE 'VB001%%'
    """, date_to=date_to)
    return {
        "rows": rows,
        "totals": totals,
        "transfer_history_from": (cov[0]["first_done"] if cov else None),
        "prev_week_label": f"{_pw_mon} → {_pw_sun}",
    }


@app.get("/api/analytics/weeks-of-cover")
def analytics_weeks_of_cover(
    date_from: str = Query(default=None),
    date_to:   str = Query(default=None),
    country:   str = Query(default=None),
):
    subcat_list = "'" + "','".join(PRODUCT_SUBCATS) + "'"
    reorder_weeks = str(REORDER_COVER_WEEKS)
    # Recency-weighted weekly velocity (Phase 1 audit A1): the last 28 days count
    # double, the prior 28 days single, over a 12-week-equivalent denominator.
    return run_query("""
        WITH sales AS (
            SELECT p.product_type AS subcategory, p.style_name,
                SUM(s.ordered_item_quantity) FILTER (
                    WHERE s.sale_date::date >= CURRENT_DATE - INTERVAL '28 days') AS units_28,
                SUM(s.ordered_item_quantity) AS units_56,
                -- Previous complete calendar month (e.g. June 1–30 when today is July 22).
                -- Window extends to 62 days so the 1st of last month is always in range.
                SUM(s.ordered_item_quantity) FILTER (
                    WHERE s.sale_date::date >= date_trunc('month', CURRENT_DATE - INTERVAL '1 month')
                    AND   s.sale_date::date <  date_trunc('month', CURRENT_DATE)
                ) AS units_prev_month
            FROM all_sales s
            LEFT JOIN all_products_clean p ON s.variant_sku = p.sku
            WHERE s.sale_kind IN ('sale','order')
            AND s.sale_date::date >= CURRENT_DATE - INTERVAL '62 days'
            AND """ + BASE_FILTERS + """
            AND p.product_type IN (""" + subcat_list + """)
            GROUP BY p.product_type, p.style_name
        ),
        stock AS (
            SELECT p.product_type AS subcategory, p.style_name,
                SUM(i.available) AS available,
                -- Odoo product status for the Active/Retired toggle
                MAX(p.status) AS odoo_status
            FROM all_inventory i
            LEFT JOIN all_products_clean p ON i.sku = p.sku
            WHERE i.pos_location_name NOT IN (""" + WAREHOUSE_LOCATIONS + """)
            AND p.product_type IN (""" + subcat_list + """)
            GROUP BY p.product_type, p.style_name
        ),
        base AS (
            SELECT COALESCE(st.subcategory, sa.subcategory) AS subcategory,
                COALESCE(st.style_name, sa.style_name) AS style_name,
                COALESCE(st.available, 0) AS available,
                COALESCE(sa.units_28, 0) AS units_28,
                COALESCE(sa.units_56, 0) AS units_56,
                COALESCE(sa.units_prev_month, 0) AS units_prev_month,
                st.odoo_status,
                ((COALESCE(sa.units_28, 0) * 2)
                  + GREATEST(COALESCE(sa.units_56, 0) - COALESCE(sa.units_28, 0), 0)) / 12.0
                  AS weekly_units
            FROM stock st
            FULL OUTER JOIN sales sa
                ON st.subcategory = sa.subcategory AND st.style_name = sa.style_name
            WHERE COALESCE(st.style_name, sa.style_name) IS NOT NULL
        )
        SELECT subcategory, style_name, available,
            available AS current_stock,
            ROUND(weekly_units, 2) AS weekly_units,
            units_28 AS units_sold_28d,
            units_prev_month,
            ROUND(available / NULLIF(weekly_units, 0), 1) AS weeks_of_cover,
            ROUND(weekly_units * """ + reorder_weeks + """)::int AS reorder_point,
            (available < weekly_units * """ + reorder_weeks + """) AS at_risk,
            CASE WHEN COALESCE(odoo_status, '') = 'Retired' THEN 'Retired' ELSE 'Active' END
                AS style_status
        FROM base
        ORDER BY available DESC
        LIMIT 2000
    """, ttl=HEAVY_DASH_TTL)

@app.get("/api/analytics/repeat-customers")
def analytics_repeat_customers(
    date_from: str = Query(default=str(date.today().replace(day=1))),
    date_to:   str = Query(default=str(date.today())),
    country:   str = Query(default=None),
    channel:   str = Query(default=None),
):
    where = build_filters(date_from, date_to, country, channel,
        extra="s.sale_kind IN ('sale','order') AND s.customer_id IS NOT NULL AND s.customer_id NOT IN ('None','null','') AND " + _not_walkin_pseudo_sql())
    return run_query("""
        WITH cust AS (
            SELECT s.customer_id,
                COUNT(DISTINCT s.order_id) AS order_count,
                ROUND(SUM((s.total_sales_kes::numeric - COALESCE(s.discounts_kes, 0)::numeric)), 0) AS total_spend_kes,
                MIN(s.sale_date) AS first_order_date,
                MAX(s.sale_date) AS last_order_date,
                SUM(s.ordered_item_quantity) AS total_units
            FROM all_sales s
            WHERE """ + where + """
            GROUP BY s.customer_id
            HAVING COUNT(DISTINCT s.order_id) >= 2
        )
        SELECT c.customer_id,
            CONCAT(COALESCE(cu.first_name,''), ' ', COALESCE(cu.last_name,'')) AS customer_name,
            COALESCE(cu.phone,'') AS mobile,
            cu.email,
            c.order_count, c.total_spend_kes, c.total_units,
            c.first_order_date, c.last_order_date,
            COUNT(*) OVER() AS total_repeat_count
        FROM cust c
        LEFT JOIN all_customers cu ON c.customer_id = cu.customer_id
        ORDER BY c.total_spend_kes DESC
        LIMIT 500
    """, date_to=date_to)

@app.get("/api/analytics/customer-retention")
def analytics_customer_retention(
    date_from: str = Query(default=str(date.today().replace(day=1))),
    date_to:   str = Query(default=str(date.today())),
    country:   str = Query(default=None),
    channel:   str = Query(default=None),
):
    cust = get_customers(date_from, date_to, country, channel)
    total = cust.get("total_customers") or 0
    # "Repeat rate" = share of active customers who had a prior purchase before
    # this window (returning buyers). The legacy `repeat_customers` field is
    # hard-coded to 0 in get_customers (the universe was refactored to
    # new/returning only), so the real repeat-buyer count is returning_customers.
    repeat = cust.get("returning_customers") or 0
    new = cust.get("new_customers") or 0
    try:
        repeat_rate = round(float(repeat) * 100.0 / float(total), 2) if total else 0.0
    except (TypeError, ValueError, ZeroDivisionError):
        repeat_rate = 0.0
    where = build_filters(date_from, date_to, country, channel,
        extra="s.sale_kind IN ('sale','order') AND s.customer_id IS NOT NULL AND s.customer_id NOT IN ('None','null','') AND " + _not_walkin_pseudo_sql())
    months = run_query("""
        SELECT substring(s.sale_date, 1, 7) AS month,
            COUNT(DISTINCT s.customer_id) AS customers
        FROM all_sales s
        WHERE """ + where + """
        GROUP BY substring(s.sale_date, 1, 7)
        ORDER BY month
    """, date_to=date_to)
    return {
        "repeat_rate_pct": repeat_rate,
        "repeat_customers": repeat,
        "new_customers": new,
        "total_customers": total,
        "months": months,
    }

@app.get("/api/analytics/customer-crosswalk")
def analytics_customer_crosswalk(
    date_from: str = Query(default=str(date.today().replace(day=1))),
    date_to:   str = Query(default=str(date.today())),
    country:   str = Query(default=None),
    top:       int = Query(default=15),
):
    where = build_filters(date_from, date_to, country,
        extra="s.sale_kind IN ('sale','order') AND s.customer_id IS NOT NULL AND s.customer_id NOT IN ('None','null','') AND s.pos_location_name NOT IN (" + WAREHOUSE_LOCATIONS + ") AND " + _not_walkin_pseudo_sql())
    return run_query("""
        WITH cust_stores AS (
            SELECT DISTINCT s.customer_id, s.pos_location_name
            FROM all_sales s
            WHERE """ + where + """
        ),
        totals AS (
            SELECT pos_location_name, COUNT(DISTINCT customer_id) AS n
            FROM cust_stores GROUP BY pos_location_name
        )
        SELECT a.pos_location_name AS store_a,
            b.pos_location_name AS store_b,
            COUNT(DISTINCT a.customer_id) AS shared_customers,
            ROUND(COUNT(DISTINCT a.customer_id) * 100.0 / NULLIF(LEAST(ta.n, tb.n), 0), 2) AS pct_overlap
        FROM cust_stores a
        JOIN cust_stores b
            ON a.customer_id = b.customer_id AND a.pos_location_name < b.pos_location_name
        JOIN totals ta ON ta.pos_location_name = a.pos_location_name
        JOIN totals tb ON tb.pos_location_name = b.pos_location_name
        GROUP BY a.pos_location_name, b.pos_location_name, ta.n, tb.n
        ORDER BY shared_customers DESC
        LIMIT 100
    """, date_to=date_to)

@app.get("/api/customers/churn-rate")
def customers_churn_rate():
    rows = run_query("""
        -- Churn (doc 03.6.2): churned = no transaction in the last 90 days.
        -- Rate = churned / eligible base (customers whose first purchase was
        -- before the 90-day cutoff, i.e. old enough to be assessed).
        WITH per_customer AS (
            SELECT customer_id,
                MAX(sale_date::date) AS last_sale,
                MIN(sale_date::date) AS first_sale
            FROM all_sales
            WHERE sale_kind IN ('sale','order') AND customer_id IS NOT NULL
              AND customer_id NOT IN ('None','null','')
              AND """ + _not_walkin_pseudo_sql(alias="all_sales") + """
            GROUP BY customer_id
        ),
        agg AS (
            SELECT
                COUNT(*) FILTER (WHERE last_sale < CURRENT_DATE - INTERVAL '90 days') AS churned_count,
                COUNT(*) AS eligible_base
            FROM per_customer
            WHERE first_sale < CURRENT_DATE - INTERVAL '90 days'
        )
        SELECT churned_count, eligible_base AS base,
            ROUND(churned_count * 100.0 / NULLIF(eligible_base, 0), 2) AS churn_rate
        FROM agg
    """)
    if not rows:
        return {"churn_rate": 0, "churned_count": 0, "churned_customers": 0, "base": 0}
    r = rows[0]
    r["churned_customers"] = r.get("churned_count")
    return r

@app.get("/api/customers/walk-ins")
def customers_walk_ins(
    date_from: str = Query(default=str(date.today().replace(day=1))),
    date_to:   str = Query(default=str(date.today())),
    country:   str = Query(default=None),
    channel:   str = Query(default=None),
):
    # ── Walk-in (anonymous transaction) definition ─────────────────────────────
    # An "anonymous transaction" = a sale with no real identified customer profile
    # attached: in-store walk-ins for Retail + guest checkouts for Online.
    # Counting rule: each anonymous TRANSACTION (order) counts as 1 walk-in
    # customer. A transaction is anonymous when ANY of the following holds:
    #   (a) customer_id is missing ('', NULL, 'None', 'null'),
    #   (b) customer_type is the literal 'walk-in', or
    #   (c) customer_id resolves to a placeholder / brand pseudo-account
    #       (name matches _WALKIN_NAME_REGEX) — the SAME accounts /api/customers
    #       excludes from the identified universe, so walk-ins + identified = total.
    # (Counting only customer_id IS NULL — the old logic — missed buckets (b)/(c)
    #  and surfaced as a near-zero walk-in count on the dashboard.)
    where = build_filters(date_from, date_to, country, channel,
        extra="s.sale_kind IN ('sale','order')")
    anon_expr = (
        "(s.customer_id IS NULL OR s.customer_id IN ('None','null','') "
        "OR s.customer_type ILIKE 'walk-in' "
        "OR ps.customer_id IS NOT NULL)"
    )
    pseudo_cte = (
        "pseudo AS (SELECT DISTINCT customer_id FROM all_customers "
        "WHERE customer_id IS NOT NULL AND " + _WALKIN_PSEUDO_COND + ")"
    )

    def _shares(r):
        wi, tot = r.get("walk_in_orders") or 0, r.get("total_orders") or 0
        ws, ts = float(r.get("walk_in_sales") or 0), float(r.get("total_sales") or 0)
        r["walk_in_customers"] = wi
        r["walk_in_share_orders_pct"] = round(wi * 100.0 / tot, 4) if tot else 0
        r["walk_in_share_sales_pct"] = round(ws * 100.0 / ts, 4) if ts else 0
        r["walk_in_avg_basket_kes"] = round(ws / wi, 0) if wi else 0
        r["capture_rate_pct"] = round(100.0 - (wi * 100.0 / tot), 2) if tot else None
        return r

    agg_sql = "WITH " + pseudo_cte + """
        SELECT
            COUNT(DISTINCT s.order_id) AS total_orders,
            COUNT(DISTINCT s.order_id) FILTER (WHERE """ + anon_expr + """) AS walk_in_orders,
            COALESCE(ROUND(SUM((s.total_sales_kes::numeric - COALESCE(s.discounts_kes, 0)::numeric)), 0), 0) AS total_sales,
            COALESCE(ROUND(SUM((s.total_sales_kes::numeric - COALESCE(s.discounts_kes, 0)::numeric)) FILTER (WHERE """ + anon_expr + """), 0), 0) AS walk_in_sales
        FROM all_sales s
        LEFT JOIN pseudo ps ON ps.customer_id = s.customer_id
        WHERE """ + where
    top = run_query(agg_sql, date_to=date_to)
    summary = _shares(top[0]) if top else {
        "total_orders": 0, "walk_in_orders": 0, "total_sales": 0, "walk_in_sales": 0,
        "walk_in_customers": 0, "walk_in_share_orders_pct": 0,
        "walk_in_share_sales_pct": 0, "walk_in_avg_basket_kes": 0, "capture_rate_pct": None,
    }

    by_country = [
        _shares(r) for r in run_query("WITH " + pseudo_cte + """
            SELECT s.country AS country,
                COUNT(DISTINCT s.order_id) AS total_orders,
                COUNT(DISTINCT s.order_id) FILTER (WHERE """ + anon_expr + """) AS walk_in_orders,
                COALESCE(ROUND(SUM((s.total_sales_kes::numeric - COALESCE(s.discounts_kes, 0)::numeric)), 0), 0) AS total_sales,
                COALESCE(ROUND(SUM((s.total_sales_kes::numeric - COALESCE(s.discounts_kes, 0)::numeric)) FILTER (WHERE """ + anon_expr + """), 0), 0) AS walk_in_sales
            FROM all_sales s
            LEFT JOIN pseudo ps ON ps.customer_id = s.customer_id
            WHERE """ + where + """ AND COALESCE(s.country,'') <> ''
            GROUP BY s.country
            HAVING COUNT(DISTINCT s.order_id) FILTER (WHERE """ + anon_expr + """) > 0
            ORDER BY walk_in_orders DESC""", date_to=date_to)
    ]

    by_location = [
        _shares(r) for r in run_query("WITH " + pseudo_cte + """
            SELECT s.pos_location_name AS channel, MAX(s.country) AS country,
                COUNT(DISTINCT s.order_id) AS total_orders,
                COUNT(DISTINCT s.order_id) FILTER (WHERE """ + anon_expr + """) AS walk_in_orders,
                COALESCE(ROUND(SUM((s.total_sales_kes::numeric - COALESCE(s.discounts_kes, 0)::numeric)), 0), 0) AS total_sales,
                COALESCE(ROUND(SUM((s.total_sales_kes::numeric - COALESCE(s.discounts_kes, 0)::numeric)) FILTER (WHERE """ + anon_expr + """), 0), 0) AS walk_in_sales
            FROM all_sales s
            LEFT JOIN pseudo ps ON ps.customer_id = s.customer_id
            WHERE """ + where + """ AND COALESCE(s.pos_location_name,'') <> ''
            GROUP BY s.pos_location_name
            HAVING COUNT(DISTINCT s.order_id) FILTER (WHERE """ + anon_expr + """) > 0
            ORDER BY walk_in_orders DESC""", date_to=date_to)
    ]

    # ── Incomplete profile (identified customers missing name/phone/email) ──────
    # Identified = real customers active in the period (have a customer_id, not a
    # null/pseudo placeholder). Reuses the same exclusion as /api/customers so the
    # "of N identified" denominator matches the Total Identified Customers tile.
    country_filter = ("AND s.country IN (" + csv_to_sql(country) + ")") if country else ""
    channel_filter = ("AND s.pos_location_name IN (" + csv_to_sql(channel) + ")") if channel else ""
    ip_rows = run_query("""
        WITH excluded AS (
            SELECT DISTINCT customer_id FROM all_customers
            WHERE customer_id IS NOT NULL
              AND """ + _WALKIN_PSEUDO_COND + """
        ),
        cust_profile AS (
            SELECT customer_id,
                MAX(NULLIF(TRIM(COALESCE(first_name,'') || ' ' || COALESCE(last_name,'')), '')) AS prof_name,
                MAX(NULLIF(TRIM(COALESCE(phone,'')), '')) AS prof_phone,
                MAX(NULLIF(TRIM(COALESCE(email,'')), '')) AS prof_email
            FROM all_customers WHERE customer_id IS NOT NULL GROUP BY customer_id
        ),
        period_customers AS (
            SELECT DISTINCT s.customer_id
            FROM all_sales s
            WHERE s.sale_date BETWEEN '""" + date_from + """' AND '""" + date_to + """'
              AND s.sale_kind IN ('sale','order')
              AND s.customer_id IS NOT NULL AND s.customer_id NOT IN ('None','null','')
              AND s.customer_id NOT IN (SELECT customer_id FROM excluded)
              AND """ + BASE_FILTERS + " " + country_filter + " " + channel_filter + """
        )
        SELECT
            COUNT(*) AS identified_total,
            COUNT(*) FILTER (WHERE cp.customer_id IS NULL
                OR cp.prof_name IS NULL OR cp.prof_phone IS NULL OR cp.prof_email IS NULL) AS customers,
            COUNT(*) FILTER (WHERE cp.customer_id IS NULL OR cp.prof_name  IS NULL) AS no_name,
            COUNT(*) FILTER (WHERE cp.customer_id IS NULL OR cp.prof_phone IS NULL) AS no_phone,
            COUNT(*) FILTER (WHERE cp.customer_id IS NULL OR cp.prof_email IS NULL) AS no_email
        FROM period_customers p
        LEFT JOIN cust_profile cp ON cp.customer_id = p.customer_id
    """, date_to=date_to)
    ip = ip_rows[0] if ip_rows else {"identified_total": 0, "customers": 0, "no_name": 0, "no_phone": 0, "no_email": 0}
    ip_total = ip.get("identified_total") or 0
    ip["share_pct"] = round((ip.get("customers") or 0) * 100.0 / ip_total, 1) if ip_total else 0

    return {
        **summary,
        "walk_in_sales_kes": summary.get("walk_in_sales", 0),
        "total_sales_kes": summary.get("total_sales", 0),
        "detection_rule": "customer_id missing OR customer_type='walk-in' OR placeholder/brand pseudo-account",
        "truncated": False,
        "degraded": False,
        "by_country": by_country,
        "by_location": by_location,
        "incomplete_profile": ip,
    }


# ══════════════════════════════════════════════════════════════════════════════
# IBT (Inter-Branch Transfer) — real data
#   Store-to-store moves a SKU from a store where the style is barely selling
#   (≤ low_pct of the style's per-store average) but has stock, to a store
#   selling strongly (≥ high_pct of average) but running low. Warehouses are
#   excluded. Warehouse-to-store covers shop-floor gaps from warehouse stock.
# ══════════════════════════════════════════════════════════════════════════════

def _sql_str(s):
    return (s or "").replace("'", "''")


def _inv_local_scope_sql(search=None, brand=None, product_type=None, alias="p"):
    """SQL fragment (prefixed with AND) scoping a query to the Inventory
    page's LOCAL filters (search box / brand pill / subcategory pill) via the
    product master. `alias` is the all_products_clean alias in the query.

    The search blob mirrors the frontend's client-side `_search` blob
    (product_name + style_name + sku + barcode) so server-scoped tables agree
    with the client-filtered SKU table. ILIKE wildcards in the user's input
    are escaped so a literal "%"/"_" can't blow the match wide open.
    """
    a = alias
    parts = []
    if search:
        pat = (search or "").replace("\\", "\\\\").replace("%", "\\%").replace("_", "\\_")
        pat = _sql_str(pat)
        blob = ("(COALESCE(" + a + ".product_name,'') || ' ' || COALESCE(" + a + ".style_name,'') || ' ' || "
                "COALESCE(" + a + ".sku,'') || ' ' || COALESCE(" + a + ".barcode,''))")
        parts.append(blob + " ILIKE '%" + pat + "%' ESCAPE '\\'")
    if brand:
        parts.append(a + ".brand = '" + _sql_str(brand) + "'")
    if product_type:
        parts.append(a + ".product_type = '" + _sql_str(product_type) + "'")
    return (" AND " + " AND ".join(parts)) if parts else ""


def _inv_local_scope_exists(search=None, brand=None, product_type=None, sku_expr="s.variant_sku"):
    """EXISTS form of _inv_local_scope_sql for queries that don't already
    join all_products_clean (e.g. per-location stock-to-sales)."""
    scope = _inv_local_scope_sql(search, brand, product_type, alias="pxx")
    if not scope:
        return ""
    return (" AND EXISTS (SELECT 1 FROM all_products_clean pxx WHERE pxx.sku = "
            + sku_expr + scope + ")")

# ── IBT global-solve knobs (Phase 1) ──────────────────────────────────────
# Minimum bundle size below which a from->to transfer is not worth the pick +
# logistics overhead. Domestic moves are cheap; cross-border moves clear
# customs/duty so they must consolidate a much larger bundle to be worthwhile.
# These are knobs (spec §5 "minimum transfer"); Phase 2 makes them per-corridor.
IBT_MIN_TRANSFER_DOMESTIC = 4
IBT_MIN_TRANSFER_CROSS = 24


def _ibt_base_ctes(date_from, date_to, country, low, high, use_clustering=True):
    """Shared IBT candidate-qualification CTE chain (WITH ... scored).

    Builds the donor/recipient qualification used by BOTH the legacy pair-level
    SQL and the Phase-1 sku-grain edge SQL. Emits CTEs through `scored` (the set
    of eligible (style, from_store, to_store) pairs that pass dead-stock,
    per-size-pack donor/receiver unit thresholds (with a lower donor bar for
    styles <= 21 days old — regular rules start at 22 days), cluster-adjacency,
    demonstrated-demand and >=3-projected-SKU minimum-range guards). The canonical SOR formula is never used or changed
    here — this only chooses WHICH pairs are eligible to move stock."""
    c_sales = ("AND s.country = '" + _sql_str(country) + "'") if country else ""
    c_inv = ("AND i.country = '" + _sql_str(country) + "'") if country else ""
    if use_clustering:
        avg_expr = "COALESCE(NULLIF(cs.avg_u, 0), st.avg_u)"
        cs_join = ("LEFT JOIN cluster_stats cs ON cs.style = f.style "
                   "AND cs.tier_n = t.tier_n AND cs.country = t.country")
        adj_filter = "AND ABS(f.tier_n - t.tier_n) <= 1"
    else:
        avg_expr = "st.avg_u"
        cs_join = ""
        adj_filter = ""
    return f"""
    WITH sv AS (
      SELECT p.style_name AS style, s.pos_location_name AS store,
             MAX(s.country) AS country,
             SUM(s.net_quantity) AS units_sold,
             CASE WHEN SUM(s.net_quantity) > 0
                  THEN SUM(s.net_sales_kes) / SUM(s.net_quantity) END AS asp
      FROM all_sales s
      JOIN all_products_clean p ON p.sku = s.variant_sku
      WHERE s.sale_date BETWEEN '{date_from}' AND '{date_to}'
        AND s.sale_kind IN ('sale','order')
        AND s.pos_location_name NOT IN ({WAREHOUSE_LOCATIONS})
        AND s.pos_location_name NOT IN ('Manual Order','Online - vivo-uganda')
        AND COALESCE(p.style_name,'') <> '' {c_sales}
      GROUP BY 1, 2
    ),
    inv AS (
      SELECT p.style_name AS style, i.pos_location_name AS store,
             MAX(i.country) AS country,
             SUM(i.available) AS available
      FROM all_inventory i
      JOIN all_products_clean p ON p.sku = i.sku
      WHERE i.pos_location_name NOT IN ({WAREHOUSE_LOCATIONS})
        AND COALESCE(i.pos_location_name,'') <> ''
        AND COALESCE(p.style_name,'') <> '' {c_inv}
      GROUP BY 1, 2
    ),
    combined AS (
      SELECT COALESCE(sv.style, inv.style) AS style,
             COALESCE(sv.store, inv.store) AS store,
             COALESCE(sv.country, inv.country) AS country,
             COALESCE(sv.units_sold, 0) AS units_sold,
             COALESCE(inv.available, 0) AS available, sv.asp
      FROM sv FULL OUTER JOIN inv ON sv.style = inv.style AND sv.store = inv.store
    ),
    stats AS (
      SELECT style, AVG(units_sold) AS avg_u, MAX(asp) AS asp
      FROM combined GROUP BY style HAVING COUNT(*) >= 2 AND AVG(units_sold) > 0
    ),
    store_rev AS (
      SELECT s.pos_location_name AS store, s.country AS country,
             SUM(s.net_sales_kes::numeric) AS rev90
      FROM all_sales s
      WHERE s.sale_kind IN ('sale','order')
        AND s.sale_date >= (CURRENT_DATE - INTERVAL '90 days')::text
        AND {BASE_FILTERS}
        AND s.pos_location_name NOT IN ({WAREHOUSE_LOCATIONS})
        AND s.pos_location_name NOT ILIKE '%online%' {c_sales}
      GROUP BY 1, 2
    ),
    -- Tier stores WITHIN their own country (PARTITION BY country). A store's
    -- cluster (A/B/C) must reflect its rank in its OWN market, not a network-wide
    -- revenue rank — otherwise the "All countries" view tiers, say, Kenya stores
    -- against Uganda/Rwanda revenue and the tier-adjacency + cluster-average
    -- thresholds suppress valid intra-country transfers that appear when the view
    -- is scoped to one country. This partition is a NO-OP for any single-country
    -- view (one partition), so it only makes "All countries" a proper superset.
    store_tier AS (
      SELECT store, country,
             NTILE(3) OVER (PARTITION BY country ORDER BY rev90 DESC) AS tier_n
      FROM store_rev
    ),
    cluster_stats AS (
      SELECT c.style, c.country, COALESCE(t.tier_n, 3) AS tier_n,
             AVG(c.units_sold) AS avg_u
      FROM combined c
      LEFT JOIN store_tier t ON t.store = c.store AND t.country = c.country
      GROUP BY c.style, c.country, COALESCE(t.tier_n, 3)
    ),
    style_inv AS (
      SELECT p.style_name AS style, SUM(i.available) AS avail
      FROM all_inventory i
      JOIN all_products_clean p ON p.sku = i.sku
      WHERE i.pos_location_name NOT IN ({WAREHOUSE_LOCATIONS})
        AND COALESCE(p.style_name,'') <> '' {c_inv}
      GROUP BY 1
    ),
    style_sales56 AS (
      SELECT p.style_name AS style, SUM(s.net_quantity) AS u56
      FROM all_sales s
      JOIN all_products_clean p ON p.sku = s.variant_sku
      WHERE s.sale_date >= (CURRENT_DATE - INTERVAL '56 days')::text
        AND s.sale_kind IN ('sale','order')
        AND s.pos_location_name NOT IN ({WAREHOUSE_LOCATIONS})
        AND COALESCE(p.style_name,'') <> '' {c_sales}
      GROUP BY 1
    ),
    dead AS (
      SELECT iv.style
      FROM style_inv iv
      LEFT JOIN style_sales56 sa ON sa.style = iv.style
      WHERE (COALESCE(sa.u56, 0) = 0
             OR (iv.avail::numeric * 8.0 / NULLIF(sa.u56, 0)) > 16.0)
        AND (COALESCE(sa.u56, 0)::numeric
             / NULLIF(COALESCE(sa.u56, 0) + iv.avail, 0) < 0.05
             OR (COALESCE(sa.u56, 0) + iv.avail) = 0)
    ),
    -- Style age: regular IBT rules start once a style reaches 22 days of age.
    -- Retail inventory carries no per-store received date, so the catalogue
    -- launch date is the reliable proxy for how long the item has been in the
    -- stores. Styles <= 21 days old use the LOWER "If New style" donor
    -- threshold (they can still be redistributed when clearly overstocked).
    -- A missing/unparseable launch date is treated as established (so the
    -- guard never silently drops legitimate, established styles).
    style_age AS (
      SELECT style_name AS style,
             MIN(substring(style_launch_date,1,10)) FILTER (
               WHERE substring(style_launch_date,1,10) ~ '^[0-9]{{4}}-[0-9]{{2}}-[0-9]{{2}}$'
             )::date AS launch
      FROM all_products_clean
      WHERE COALESCE(style_name,'') <> ''
      GROUP BY 1
    ),
    too_new AS (
      -- "New style" = launched within the last 21 days (regular IBT rules start
      -- at 22 days of age). New styles are NOT excluded outright: they may still
      -- DONATE under the lower per-size-pack "If New style" donor threshold.
      SELECT style FROM style_age
      WHERE launch IS NOT NULL
        AND launch >= (CURRENT_DATE - INTERVAL '21 days')
    ),
    -- ── Size-pack thresholds (user rule table) ─────────────────────────────
    -- Classify each style's size structure from its master SKU size labels and
    -- pick the donor/receiver style-level unit thresholds accordingly:
    --   pack                        receiver<=  donor>=  new-style donor>=
    --   S,M,L,1X,2X (regular)            4         6            5
    --   F / free size                    2         4            3
    --   S/M,L/1X   (2 combined sizes)    1         3            2
    --   XS/S,M/L,1X/2X (3+ combined)     2         4            3
    -- Combined sizes embed a slash (e.g. "M/L", "1X/2X"); free size = single
    -- size or an F/OS/Free-Size label. Unknown/missing → regular thresholds.
    style_pack AS (
      SELECT style_name AS style,
             COUNT(DISTINCT NULLIF(size,'')) AS n_sizes,
             BOOL_OR(COALESCE(size,'') LIKE '%/%') AS combined,
             BOOL_OR(TRIM(COALESCE(size,'')) ~* '^(f|os|free ?size|one ?size)$') AS freesize
      FROM all_products_clean
      WHERE COALESCE(style_name,'') <> ''
      GROUP BY 1
    ),
    pack_rules AS (
      -- Only an EXPLICIT free-size label maps to the free-size thresholds;
      -- unknown/ambiguous size structures fall back to REGULAR thresholds.
      SELECT style,
        CASE WHEN freesize THEN 2
             WHEN combined AND n_sizes <= 2 THEN 1
             WHEN combined THEN 2
             ELSE 4 END AS recv_max,
        CASE WHEN freesize THEN 4
             WHEN combined AND n_sizes <= 2 THEN 3
             WHEN combined THEN 4
             ELSE 6 END AS donor_min,
        CASE WHEN freesize THEN 3
             WHEN combined AND n_sizes <= 2 THEN 2
             WHEN combined THEN 3
             ELSE 5 END AS new_donor_min
      FROM style_pack
    ),
    froms AS (
      SELECT c.style, c.store, c.country, c.available, c.units_sold,
             COALESCE(stt.tier_n, 3) AS tier_n
      FROM combined c
      JOIN stats st ON st.style = c.style
      LEFT JOIN store_tier stt ON stt.store = c.store AND stt.country = c.country
      LEFT JOIN pack_rules pk ON pk.style = c.style
      WHERE c.available >= CASE
              WHEN EXISTS (SELECT 1 FROM too_new tn WHERE tn.style = c.style)
                THEN COALESCE(pk.new_donor_min, 5)
              ELSE COALESCE(pk.donor_min, 6) END
        AND NOT EXISTS (SELECT 1 FROM dead d WHERE d.style = c.style)
    ),
    tos AS (
      SELECT c.style, c.store, c.country, c.available, c.units_sold,
             COALESCE(stt.tier_n, 3) AS tier_n
      FROM combined c
      JOIN stats st ON st.style = c.style
      LEFT JOIN store_tier stt ON stt.store = c.store AND stt.country = c.country
      LEFT JOIN pack_rules pk ON pk.style = c.style
      WHERE c.available <= COALESCE(pk.recv_max, 4)
        -- New styles (<=21 days) may only DONATE — never receive.
        AND NOT EXISTS (SELECT 1 FROM too_new tn WHERE tn.style = c.style)
        -- WS5: a receiver must be covered by the stock feed. Stores with ZERO
        -- rows in all_inventory (UG/RW/Online) look like "available = 0" but
        -- their true stock is unknown — never ship into a blind store.
        AND EXISTS (SELECT 1 FROM all_inventory sfl
                    WHERE sfl.pos_location_name = c.store)
        AND NOT EXISTS (SELECT 1 FROM dead d WHERE d.style = c.style)
    ),
    pairs AS (
      SELECT f.style,
             f.store AS from_store, f.available AS from_avail,
             f.units_sold AS from_sold, f.tier_n AS from_tier,
             t.store AS to_store, t.available AS to_avail,
             t.units_sold AS to_sold, t.tier_n AS to_tier,
             {avg_expr} AS avg_u, st.asp AS asp
      FROM froms f
      JOIN tos t ON t.style = f.style AND t.store <> f.store
      JOIN stats st ON st.style = f.style
      {cs_join}
      WHERE f.units_sold <= {low} * {avg_expr}
        AND t.units_sold >= {high} * {avg_expr}
        {adj_filter}
    ),
    -- ── Minimum range guard (≥ 3 distinct SKUs at the receiver post-transfer) ──
    -- A style is only allocated to a receiving store if, AFTER the transfer, that
    -- store will hold at least 3 distinct SKUs of the style. Post-transfer SKUs =
    -- SKUs the receiver already stocks (av >= 1) UNION SKUs the donor will send
    -- (donor av >= 2 so it keeps ≥1, and receiver currently has <= 1) — the same
    -- per-SKU rule the SKU-breakdown applies (suggested_qty > 0 ⇔ from>=2,to<=1).
    sku_av AS (
      SELECT p.style_name AS style, i.pos_location_name AS store, i.sku AS sku,
             SUM(i.available) AS av
      FROM all_inventory i
      JOIN all_products_clean p ON p.sku = i.sku
      WHERE i.pos_location_name NOT IN ({WAREHOUSE_LOCATIONS})
        AND COALESCE(i.pos_location_name,'') <> ''
        AND COALESCE(p.style_name,'') <> '' {c_inv}
      GROUP BY 1, 2, 3
    ),
    cand AS (SELECT DISTINCT style, from_store, to_store FROM pairs),
    recv_have AS (
      SELECT c.style, c.from_store, c.to_store, sa.sku
      FROM cand c
      JOIN sku_av sa ON sa.style = c.style AND sa.store = c.to_store AND sa.av >= 1
    ),
    recv_get AS (
      SELECT c.style, c.from_store, c.to_store, df.sku
      FROM cand c
      JOIN sku_av df ON df.style = c.style AND df.store = c.from_store AND df.av >= 2
      LEFT JOIN sku_av dt ON dt.style = c.style AND dt.store = c.to_store AND dt.sku = df.sku
      WHERE COALESCE(dt.av, 0) <= 1
    ),
    recv_proj AS (
      SELECT style, from_store, to_store, COUNT(DISTINCT sku) AS projected_skus
      FROM (SELECT * FROM recv_have UNION SELECT * FROM recv_get) u
      GROUP BY 1, 2, 3
    ),
    scored AS (
      SELECT pr.*,
        ROUND(100 * (
          0.4 * (LEAST(pr.from_avail::numeric / NULLIF(pr.avg_u, 0), 3.0) / 3.0)
        + 0.4 * (LEAST(pr.to_sold::numeric / NULLIF(GREATEST(pr.to_avail, 0) + 1, 0), 5.0) / 5.0)
        + 0.2 * COALESCE(pr.to_sold::numeric / NULLIF(pr.to_sold + pr.to_avail, 0), 0)
        ))::int AS score
      FROM pairs pr
      JOIN recv_proj rp
        ON rp.style = pr.style AND rp.from_store = pr.from_store AND rp.to_store = pr.to_store
      WHERE rp.projected_skus >= 3
    )
    """


def _ibt_suggestions_sql(date_from, date_to, country, low, high, lim, use_clustering=True):
    """Legacy pair-level IBT suggestions builder. Builds the shared
    qualification chain then sizes each eligible pair INDEPENDENTLY (so it can
    over-fill a hot destination / over-commit a donor across pairs). Superseded
    for /analytics/ibt-suggestions, /ibt/export/operations and /ibt/late-count
    by _ibt_global_solve, which shares decrementing budgets across all pairs.
    Retained only for ad-hoc/diagnostic use."""
    return _ibt_base_ctes(date_from, date_to, country, low, high, use_clustering) + f"""
    SELECT sc.style AS style_name, pp.brand, pp.category AS subcategory,
           sc.from_store, sc.to_store,
           CASE sc.from_tier WHEN 1 THEN 'A' WHEN 2 THEN 'B' ELSE 'C' END AS from_cluster,
           CASE sc.to_tier   WHEN 1 THEN 'A' WHEN 2 THEN 'B' ELSE 'C' END AS to_cluster,
           sc.score,
           COUNT(*) OVER (PARTITION BY sc.style)::int AS pair_count,
           GREATEST(LEAST(sc.from_avail - 2, GREATEST(sc.to_sold - sc.to_avail, 1)), 1)::int AS units_to_move,
           ROUND(GREATEST(LEAST(sc.from_avail - 2, GREATEST(sc.to_sold - sc.to_avail, 1)), 1)
                 * COALESCE(sc.asp, 0))::numeric AS estimated_uplift,
           sc.from_sold::int AS from_qty_sold_28d,
           sc.to_sold::int AS to_qty_sold_28d
    FROM scored sc
    LEFT JOIN LATERAL (
      SELECT brand, category FROM all_products_clean WHERE style_name = sc.style LIMIT 1
    ) pp ON TRUE
    ORDER BY sc.score DESC, sc.style, estimated_uplift DESC NULLS LAST
    LIMIT {lim}
    """


def _ibt_edge_sql(date_from, date_to, country, low, high, use_clustering=True):
    """Phase-1 sku-grain candidate edges for the global solve.

    Reuses the shared qualification chain, then explodes each eligible
    (style, from_store, to_store) pair to the individual SKU rows the donor can
    actually ship: donor availability >= 2 (so the size-run keeps >= 1 on the
    donor shelf) and receiver availability <= 1. Emits per-side availability,
    colour/size/barcode/bin and the store countries. Online/Shop Zetu and
    Zoya/third-party brand are excluded as BOTH donor and receiver. The Python
    solver then debits a shared destination budget + donor ledger per sku."""
    return _ibt_base_ctes(date_from, date_to, country, low, high, use_clustering) + """
    SELECT sc.style AS style_name, pp.brand, pp.category AS subcategory,
           sc.from_store, sc.from_tier, sc.to_store, sc.to_tier, sc.score,
           COALESCE(sc.asp, 0)::numeric AS asp,
           sc.from_sold::int AS from_qty_sold_28d,
           sc.to_sold::int   AS to_qty_sold_28d,
           fav.sku AS sku, skd.color_print AS color, skd.size AS size,
           skd.barcode AS barcode, COALESCE(wb.bin, '') AS bin,
           fav.av::int AS from_sku_avail,
           COALESCE(tav.av, 0)::int AS to_sku_avail,
           fc.country AS from_country, tc.country AS to_country
    FROM scored sc
    JOIN sku_av fav ON fav.style = sc.style AND fav.store = sc.from_store AND fav.av >= 2
    LEFT JOIN sku_av tav ON tav.style = sc.style AND tav.store = sc.to_store AND tav.sku = fav.sku
    JOIN LATERAL (
      SELECT color_print, size, barcode FROM all_products_clean WHERE sku = fav.sku LIMIT 1
    ) skd ON TRUE
    LEFT JOIN warehouse_bins wb ON wb.barcode = skd.barcode
    LEFT JOIN LATERAL (
      SELECT brand, category FROM all_products_clean WHERE style_name = sc.style LIMIT 1
    ) pp ON TRUE
    LEFT JOIN LATERAL (
      SELECT country FROM all_inventory WHERE pos_location_name = sc.from_store
        AND COALESCE(country, '') <> '' LIMIT 1
    ) fc ON TRUE
    LEFT JOIN LATERAL (
      SELECT country FROM all_inventory WHERE pos_location_name = sc.to_store
        AND COALESCE(country, '') <> '' LIMIT 1
    ) tc ON TRUE
    WHERE COALESCE(tav.av, 0) <= 1
      AND COALESCE(pp.brand, '') NOT ILIKE '%zoya%'
      AND COALESCE(pp.brand, '') NOT ILIKE '%third party%'
      AND sc.from_store NOT ILIKE '%online%'
      AND sc.to_store NOT ILIKE '%online%'
      AND sc.from_store NOT ILIKE '%zetu%'
      AND sc.to_store NOT ILIKE '%zetu%'
    ORDER BY sc.score DESC, sc.style, fav.sku
    """


# ── Phase 2 (Value & Coordination): cost knobs + corridor lead-time + velocity ─
# Per-unit move economics (spec §5/§8 — KES redeployed net of transport + duty).
# Knobs only; sensible East-Africa starting points. value_kes(move) =
#   qty * asp  -  qty * transport_per_unit  -  (cross-border ? value * duty_pct : 0)
IBT_TRANSPORT_PER_UNIT_DOMESTIC = 40.0    # KES/unit intra-country pick+freight
IBT_TRANSPORT_PER_UNIT_CROSS    = 180.0   # KES/unit cross-border freight+clearing
IBT_DUTY_PCT_CROSS              = 0.25     # ad-valorem duty/VAT drag on cross-border
# Cap on source-days-freed so a non-selling donor cell (velocity ~ 0) cannot
# return an unbounded cash-conversion benefit — bounded at one selling season.
IBT_SOURCE_DAYS_CAP            = 120.0

# Persisted from_country -> to_country transit days. Seeded with defaults and
# refreshed from observed dispatch->receipt where ibt_completions carries both
# stamps. Feeds the in-transit-days term of net-CCC scoring. Created lazily
# (fabric-reservations pattern) so a fresh prod DB self-bootstraps on first solve.
_IBT_LEADTIME_DOMESTIC_DEFAULT = 2.0
_IBT_LEADTIME_CROSS_DEFAULT    = 7.0
_ibt_leadtime_ready = False


def _ensure_ibt_phase2_tables():
    """Idempotently create + seed corridor_leadtime. Never raises (best-effort —
    scoring falls back to the domestic/cross defaults if the table is absent)."""
    global _ibt_leadtime_ready
    if _ibt_leadtime_ready:
        return
    try:
        _users_exec(
            "CREATE TABLE IF NOT EXISTS corridor_leadtime ("
            " from_country TEXT NOT NULL,"
            " to_country   TEXT NOT NULL,"
            " lead_days    NUMERIC NOT NULL DEFAULT 2,"
            " via_hub      TEXT,"
            " source       TEXT NOT NULL DEFAULT 'default',"
            " n_obs        INTEGER NOT NULL DEFAULT 0,"
            " updated_at   TIMESTAMP NOT NULL DEFAULT now(),"
            " PRIMARY KEY (from_country, to_country))")
        # Seed sensible defaults for every store-network country pair (domestic 2d,
        # cross-border 7d), ON CONFLICT DO NOTHING so observed rows + reruns win.
        _users_exec(f"""
            INSERT INTO corridor_leadtime (from_country, to_country, lead_days, source)
            SELECT a.country, b.country,
                   CASE WHEN a.country = b.country THEN {_IBT_LEADTIME_DOMESTIC_DEFAULT}
                        ELSE {_IBT_LEADTIME_CROSS_DEFAULT} END,
                   'default'
            FROM (SELECT DISTINCT country FROM all_inventory
                  WHERE COALESCE(country,'') <> ''
                    AND pos_location_name NOT IN ({WAREHOUSE_LOCATIONS})) a
            CROSS JOIN (SELECT DISTINCT country FROM all_inventory
                  WHERE COALESCE(country,'') <> ''
                    AND pos_location_name NOT IN ({WAREHOUSE_LOCATIONS})) b
            ON CONFLICT (from_country, to_country) DO NOTHING
        """)
        # Refresh observed dispatch->receipt averages from completed moves (see
        # _ibt_refresh_corridor_observed — shared with the nightly reconcile hook).
        _ibt_refresh_corridor_observed()
        _ibt_leadtime_ready = True
    except Exception as e:
        log.warning("corridor_leadtime ensure/refresh skipped: %s", e)


def _ibt_refresh_corridor_observed():
    """Recompute observed corridor lead times from completed moves that carry both a
    suggested_at (dispatch proxy) and a transfer_date (receipt proxy). Idempotent
    upsert; only overwrites a pair with source='observed' when a real signal exists
    (>=3 obs), so seeded defaults survive on a fresh DB. Re-runnable on every nightly
    cycle (unlike _ensure_ibt_phase2_tables which is process-guarded). Never raises;
    returns the number of pairs refreshed (or None on error)."""
    try:
        rows = _users_exec("""
            INSERT INTO corridor_leadtime (from_country, to_country, lead_days, source, n_obs, updated_at)
            SELECT fc.country, tc.country,
                   GREATEST(1, ROUND(AVG(c.transfer_date - c.suggested_at))::numeric),
                   'observed', COUNT(*), now()
            FROM ibt_completions c
            JOIN LATERAL (SELECT country FROM all_inventory
                          WHERE pos_location_name = c.from_store
                            AND COALESCE(country,'') <> '' LIMIT 1) fc ON TRUE
            JOIN LATERAL (SELECT country FROM all_inventory
                          WHERE pos_location_name = c.to_store
                            AND COALESCE(country,'') <> '' LIMIT 1) tc ON TRUE
            WHERE c.suggested_at IS NOT NULL AND c.transfer_date IS NOT NULL
              AND c.transfer_date >= c.suggested_at
            GROUP BY fc.country, tc.country
            HAVING COUNT(*) >= 3
            ON CONFLICT (from_country, to_country) DO UPDATE
              SET lead_days = EXCLUDED.lead_days, source = 'observed',
                  n_obs = EXCLUDED.n_obs, updated_at = now()
            RETURNING from_country
        """, fetch=True)
        return len(rows or [])
    except Exception as e:
        log.warning("corridor observed refresh skipped: %s", e)
        return None


# ── Phase 3 (Flow & Proof): hub routing, lifecycle ledger, reservations ───────
# Spec §6/§12.4: moves route hub-THROUGH-WAREHOUSE by DEFAULT — the warehouse is
# the only node with packing/scanning/reconciliation. A NAMED same-mall exception
# lets two stores in the same mall do a same-day walk-over that bypasses the hub.
# These pairs are an operational knob (open decision §12.4): add real pairs as
# frozenset({"Store A", "Store B"}). Empty = everything routes via the hub (the
# spec default — the safe, fully-tracked path).
IBT_SAME_MALL_PAIRS = set()      # e.g. {frozenset({"Vivo Sarit", "Shop Zetu Sarit"})}
IBT_SAME_MALL_LEAD_DAYS = 0.5    # same-day walk-over transit when the hub is bypassed
IBT_FRESHNESS_SLA_MIN   = 30.0   # soft-lock destructive actions past this sync lag (min)
_IBT_OVERDUE_DAYS       = 7      # an in_transit consignment older than this is overdue
_IBT_INFLIGHT_HOLD_HOURS = 36   # how long a CONSUMED donor hold keeps netting the unit out
                                # of availability (covers the Odoo stock-extract lag before
                                # all_inventory drops the dispatched on-hand); then it stops
                                # being subtracted and the nightly sweep releases it

# IBT projection calibration (realised/projected, rolling median, clamped). Mirrors
# the replenishment calibration. The canonical SOR FORMULA is NEVER touched — only
# the forward PROJECTION (sor_uplift_pp / inventory-days-removed) is scaled.
_IBT_CALIB_MIN  = 0.25
_IBT_CALIB_MAX  = 2.0
_IBT_CALIB_KEEP = 10             # rolling-median window of recent landed-run samples

_ibt_hub_country_cache = None
_ibt_lifecycle_ready = False


def _ibt_is_same_mall(from_store, to_store):
    """True when (from_store, to_store) is on the named same-mall exception list and
    may bypass the warehouse hub for a same-day walk-over."""
    if not from_store or not to_store:
        return False
    return frozenset({from_store, to_store}) in IBT_SAME_MALL_PAIRS


def _ibt_hub_country():
    """Country of the central warehouse hub (defaults to Kenya). Cached; never raises."""
    global _ibt_hub_country_cache
    if _ibt_hub_country_cache is not None:
        return _ibt_hub_country_cache
    c = "Kenya"
    try:
        rows = run_query(
            f"SELECT country, COUNT(*) AS n FROM all_inventory "
            f"WHERE pos_location_name IN ({WAREHOUSE_LOCATIONS}) "
            f"AND COALESCE(country,'') <> '' GROUP BY country "
            f"ORDER BY n DESC LIMIT 1")
        if rows and rows[0].get("country"):
            c = rows[0]["country"]
    except Exception:
        pass
    _ibt_hub_country_cache = c
    return c


def _ensure_ibt_lifecycle_tables():
    """Idempotently create the Phase-3 two-sided transfer lifecycle ledger
    (ibt_transfer) + the shared soft-reservation ledger (transfer_reservations).
    Fabric-reservations pattern: created lazily so a fresh prod DB self-bootstraps
    on first scan/solve. Never raises (callers fall back gracefully)."""
    global _ibt_lifecycle_ready
    if _ibt_lifecycle_ready:
        return
    try:
        _users_exec(
            "CREATE TABLE IF NOT EXISTS ibt_transfer ("
            " consignment_id TEXT PRIMARY KEY,"
            " run_id TEXT,"
            " from_store TEXT, from_country TEXT,"
            " to_store TEXT, to_country TEXT,"
            " via_hub BOOLEAN NOT NULL DEFAULT TRUE,"
            " route TEXT,"
            " style_name TEXT, brand TEXT, subcategory TEXT,"
            " sku TEXT, color TEXT, size TEXT, barcode TEXT,"
            " qty INTEGER NOT NULL DEFAULT 0,"
            " received_qty INTEGER,"
            " source_onhand_at_calc INTEGER,"
            " dest_gap_at_calc INTEGER,"
            " net_ccc_days NUMERIC,"
            " value_kes NUMERIC,"
            " curve_complete BOOLEAN,"
            " status TEXT NOT NULL DEFAULT 'in_transit',"
            " odoo_transfer_id TEXT,"
            " dispatch_ts TIMESTAMP NOT NULL DEFAULT now(),"
            " received_ts TIMESTAMP,"
            " scanned_out_by TEXT, received_by TEXT,"
            " created_at TIMESTAMP NOT NULL DEFAULT now(),"
            " updated_at TIMESTAMP NOT NULL DEFAULT now())")
        _users_exec("CREATE INDEX IF NOT EXISTS idx_ibt_transfer_status "
                    "ON ibt_transfer (status)")
        _users_exec("CREATE INDEX IF NOT EXISTS idx_ibt_transfer_keys "
                    "ON ibt_transfer (to_store, sku)")
        _users_exec("CREATE INDEX IF NOT EXISTS idx_ibt_transfer_dispatch "
                    "ON ibt_transfer (dispatch_ts)")
        # Operator resolution of a stuck/overdue in_transit consignment (lost
        # parcel, mis-scan): an operator can CANCEL it (ownership returns to the
        # donor — its SOR never moved) or FORCE-RECEIVE it. Columns are added
        # idempotently so an existing table picks them up. status grows two new
        # terminal values: 'cancelled' (and force-receive reuses received/discrepancy).
        for _ddl in (
            "ALTER TABLE ibt_transfer ADD COLUMN IF NOT EXISTS resolution_reason TEXT",
            "ALTER TABLE ibt_transfer ADD COLUMN IF NOT EXISTS resolution_action TEXT",
            "ALTER TABLE ibt_transfer ADD COLUMN IF NOT EXISTS resolved_by TEXT",
            "ALTER TABLE ibt_transfer ADD COLUMN IF NOT EXISTS resolved_ts TIMESTAMP",
        ):
            try:
                _users_exec(_ddl)
            except Exception:
                pass
        # Append-only audit of stuck-consignment resolutions (cancel / force-receive).
        _users_exec(
            "CREATE TABLE IF NOT EXISTS ibt_audit ("
            " id BIGSERIAL PRIMARY KEY,"
            " consignment_id TEXT,"
            " action TEXT,"
            " reason TEXT,"
            " detail TEXT,"
            " user_id TEXT, user_name TEXT,"
            " created_at TIMESTAMP NOT NULL DEFAULT now())")
        _users_exec("CREATE INDEX IF NOT EXISTS idx_ibt_audit_cid "
                    "ON ibt_audit (consignment_id)")
        # Shared soft-reservation ledger — the coordination point between IBT and
        # Replenishment (source column distinguishes them). Replenishment continues
        # to coordinate via its own in-transit quarantine; this table lets a
        # reserved donor unit be netted out of the next solve's available stock.
        _users_exec(
            "CREATE TABLE IF NOT EXISTS transfer_reservations ("
            " id BIGSERIAL PRIMARY KEY,"
            " source TEXT NOT NULL,"
            " pos_location TEXT NOT NULL,"
            " sku TEXT NOT NULL,"
            " qty INTEGER NOT NULL DEFAULT 0,"
            " run_id TEXT,"
            " consignment_id TEXT,"
            " status TEXT NOT NULL DEFAULT 'active',"
            " reserved_at TIMESTAMP NOT NULL DEFAULT now(),"
            " expires_at TIMESTAMP)")
        _users_exec("CREATE INDEX IF NOT EXISTS idx_transfer_resv_active "
                    "ON transfer_reservations (pos_location, sku) "
                    "WHERE status = 'active'")
        _ibt_lifecycle_ready = True
    except Exception as e:
        log.warning("ibt lifecycle tables ensure skipped: %s", e)


def _ibt_audit(consignment_id, action, reason, detail, request):
    """Append an audit row for a stuck-consignment resolution. Never raises."""
    acting = getattr(request, "state", None)
    acting = getattr(acting, "user", None) or {}
    uid = acting.get("user_id") or acting.get("sub") or acting.get("email")
    name = acting.get("name") or acting.get("email")
    try:
        _users_exec(
            "INSERT INTO ibt_audit "
            "(consignment_id, action, reason, detail, user_id, user_name) "
            "VALUES (%s,%s,%s,%s,%s,%s)",
            (consignment_id, action, (reason or "")[:1000],
             (detail or "")[:1000], uid, name))
    except Exception:
        pass


def _ibt_reserved_units(pos_location, sku):
    """Sum of IN-FLIGHT soft-reservations on (pos_location, sku) across IBT +
    Replenishment — both 'active' pre-dispatch HOLDS and 'consumed' dispatched
    units whose stock has NOT yet been reflected in all_inventory.

    Why count 'consumed' too: scan-out writes a 'consumed' hold immediately, but
    the donor's all_inventory on-hand only drops once the next Odoo stock extract
    lands. During that lag the unit has left the shelf yet still shows as on-hand;
    if we did not subtract it a second scan-out could promise the SAME unit twice
    (double-dispatch). Each consumed hold carries a bounded expires_at (set at
    scan-out to cover the extract lag); once it expires we stop subtracting so we
    do not double-penalise the donor after inventory has caught up, and the
    nightly sweep releases it. Best-effort; 0 on any error or before the ledger
    exists."""
    _ensure_ibt_lifecycle_tables()
    try:
        rows = _users_exec(
            "SELECT COALESCE(SUM(qty),0) AS q FROM transfer_reservations "
            "WHERE pos_location=%s AND sku=%s AND status IN ('active','consumed') "
            "AND (expires_at IS NULL OR expires_at > now())",
            (pos_location, sku), fetch=True)
        if rows:
            return int(rows[0].get("q") or 0)
    except Exception:
        pass
    return 0


def _ibt_donor_available(store, sku):
    """Live donor on-hand (available units) for (store, sku), warehouse rows
    excluded. Used for action-time re-validation at scan-out. -1 sentinel when the
    lookup itself fails (treat as 'unknown', not 'zero')."""
    try:
        rows = _users_exec(
            "SELECT COALESCE(SUM(available),0) AS av FROM all_inventory "
            f"WHERE pos_location_name=%s AND sku=%s "
            f"AND pos_location_name NOT IN ({WAREHOUSE_LOCATIONS})",
            (store, sku), fetch=True)
        if rows:
            return int(rows[0].get("av") or 0)
    except Exception:
        return -1
    return 0


def _ibt_proj_calibration():
    """Active IBT projection calibration factor (rolling median of realised/projected,
    clamped [0.25, 2.0]). Defaults to 1.0 until reconciliation has run. Never raises."""
    try:
        rows = _users_exec(
            "SELECT value FROM app_config WHERE key='ibt_proj_calibration'",
            fetch=True)
        if rows:
            val = rows[0].get("value")
            if isinstance(val, str):
                val = json.loads(val)
            if isinstance(val, dict) and val.get("value") is not None:
                c = float(val["value"])
                return min(_IBT_CALIB_MAX, max(_IBT_CALIB_MIN, c))
    except Exception:
        pass
    return 1.0


def _ibt_record_calibration(sample, run_id=None):
    """Append one realised/projected sample to the rolling window and persist the new
    median as the active IBT calibration. Best-effort; returns the resulting median
    (or the prior/neutral value on failure). Idempotent per landed run: each `run_id`
    contributes AT MOST one sample (the reconciliation endpoint is read on every page
    refresh, so without this guard the median would track page traffic, not runs)."""
    try:
        sample = min(_IBT_CALIB_MAX, max(_IBT_CALIB_MIN, float(sample)))
    except (TypeError, ValueError):
        return _ibt_proj_calibration()
    samples = []
    try:
        rows = _users_exec(
            "SELECT value FROM app_config WHERE key='ibt_proj_calibration'",
            fetch=True)
        if rows:
            val = rows[0].get("value")
            if isinstance(val, str):
                val = json.loads(val)
            if isinstance(val, dict):
                if (run_id is not None and val.get("last_run_id") == run_id
                        and val.get("value") is not None):
                    return min(_IBT_CALIB_MAX,
                               max(_IBT_CALIB_MIN, float(val["value"])))
                if isinstance(val.get("samples"), list):
                    samples = [float(x) for x in val["samples"]]
    except Exception:
        samples = []
    samples.append(round(sample, 4))
    samples = samples[-_IBT_CALIB_KEEP:]
    ssorted = sorted(samples)
    n = len(ssorted)
    med = (ssorted[n // 2] if n % 2
           else (ssorted[n // 2 - 1] + ssorted[n // 2]) / 2.0)
    med = round(min(_IBT_CALIB_MAX, max(_IBT_CALIB_MIN, med)), 4)
    try:
        _users_exec(
            "INSERT INTO app_config (key, value, updated_at) "
            "VALUES ('ibt_proj_calibration', %s::jsonb, now()) "
            "ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, "
            "updated_at = now()",
            (json.dumps({"samples": samples, "value": med,
                         "last_run_id": run_id}),))
    except Exception:
        pass
    return med


def _ibt_freshness():
    """As-of EAT clock + sales-sync lag for the IBT worklist. Reads the sync-loop
    heartbeat (sync_heartbeat.last_cycle_at); stale beyond the SLA soft-locks
    destructive actions client-side. Never raises."""
    from datetime import datetime, timezone
    now_utc = datetime.now(timezone.utc)
    as_of_eat = (now_utc + timedelta(hours=3)).strftime("%H:%M:%S")
    last_sync, mins = None, None
    try:
        rows = _users_exec(
            "SELECT last_cycle_at FROM sync_heartbeat WHERE id = 1", fetch=True)
        if rows and rows[0].get("last_cycle_at"):
            ts = rows[0]["last_cycle_at"]
            if ts.tzinfo is None:
                ts = ts.replace(tzinfo=timezone.utc)
            last_sync = ts.isoformat()
            mins = round((now_utc - ts).total_seconds() / 60.0, 1)
    except Exception:
        pass
    stale = (mins is None) or (mins > IBT_FRESHNESS_SLA_MIN)
    return {"as_of_eat": as_of_eat, "last_sync_at": last_sync,
            "sync_lag_min": mins, "stale": bool(stale),
            "sla_min": IBT_FRESHNESS_SLA_MIN}


def _ibt_leadtime_map():
    """{(from_country, to_country): lead_days} from corridor_leadtime. Never
    raises; missing pairs fall back to the domestic/cross default at lookup."""
    _ensure_ibt_phase2_tables()
    out = {}
    try:
        rows = _users_exec(
            "SELECT from_country, to_country, lead_days FROM corridor_leadtime",
            fetch=True) or []
        for r in rows:
            out[(r.get("from_country") or "", r.get("to_country") or "")] = \
                float(r.get("lead_days") or 0)
    except Exception:
        pass
    return out


def _ibt_lead_days(lt_map, from_country, to_country):
    fc, tc = (from_country or ""), (to_country or "")
    if (fc, tc) in lt_map:
        return lt_map[(fc, tc)]
    if fc and tc and fc != tc:
        return _IBT_LEADTIME_CROSS_DEFAULT
    return _IBT_LEADTIME_DOMESTIC_DEFAULT


def _ibt_store_sku_velocity(date_from, date_to, country):
    """Per (store, sku) recency-weighted weekly velocity with category-level
    shrinkage so sparse cells don't produce garbage. Returns
      {(store, sku): {"vel": weekly_units, "has_stock": bool, "sold": units}}
    using the shared formula ((u28*2)+max(u56-u28,0))/12 on a trailing 56-day
    window (warehouse/online excluded). Shrinkage distinguishes:
      - cell SOLD over the window -> trust the observed rate, lightly shrunk
        toward the category rate to stabilise tiny counts;
      - cell HAS STOCK but ZERO sales -> a genuine slow cell (tiny floor), so
        source-days-freed stays large (we WANT to move it);
      - cell has NO stock and NO sales -> no signal -> category prior rate.
    The canonical SOR formula is not used or changed here."""
    c_sales = ("AND s.country = '" + _sql_str(country) + "'") if country else ""
    c_inv = ("AND i.country = '" + _sql_str(country) + "'") if country else ""
    q = f"""
    WITH vel AS (
      SELECT s.pos_location_name AS store, s.variant_sku AS sku,
             MAX(p.category) AS category,
             SUM(s.net_quantity) FILTER (
               WHERE s.sale_date::date >= CURRENT_DATE - INTERVAL '28 days') AS u28,
             SUM(s.net_quantity) AS u56
      FROM all_sales s
      JOIN all_products_clean p ON p.sku = s.variant_sku
      WHERE s.sale_date::date >= CURRENT_DATE - INTERVAL '56 days'
        AND s.sale_kind IN ('sale','order')
        AND s.pos_location_name NOT IN ({WAREHOUSE_LOCATIONS})
        AND s.pos_location_name NOT ILIKE '%online%'
        AND COALESCE(s.variant_sku,'') <> '' {c_sales}
      GROUP BY 1, 2
    ),
    stock AS (
      SELECT i.pos_location_name AS store, i.sku AS sku,
             MAX(p.category) AS category, SUM(i.available) AS soh
      FROM all_inventory i
      JOIN all_products_clean p ON p.sku = i.sku
      WHERE i.pos_location_name NOT IN ({WAREHOUSE_LOCATIONS})
        AND i.pos_location_name NOT ILIKE '%online%'
        AND COALESCE(i.sku,'') <> '' {c_inv}
      GROUP BY 1, 2
    )
    SELECT COALESCE(v.store, k.store) AS store,
           COALESCE(v.sku, k.sku) AS sku,
           COALESCE(v.category, k.category) AS category,
           COALESCE(v.u28, 0)::numeric AS u28,
           COALESCE(v.u56, 0)::numeric AS u56,
           COALESCE(k.soh, 0)::numeric AS soh
    FROM vel v
    FULL OUTER JOIN stock k ON k.store = v.store AND k.sku = v.sku
    """
    rows = run_query(q) or []
    # Category prior = mean weekly velocity over SELLING cells in the category
    # (so the prior reflects real demand, not the many zero-stock-zero-sale cells).
    cat_sum, cat_n = {}, {}
    raw = []
    for r in rows:
        u28 = float(r.get("u28") or 0)
        u56 = float(r.get("u56") or 0)
        soh = float(r.get("soh") or 0)
        cat = r.get("category") or ""
        wk = ((u28 * 2.0) + max(u56 - u28, 0.0)) / 12.0
        if u56 > 0:
            cat_sum[cat] = cat_sum.get(cat, 0.0) + wk
            cat_n[cat] = cat_n.get(cat, 0) + 1
        raw.append((r.get("store"), r.get("sku"), cat, wk, soh, u56))
    out = {}
    for store, sku, cat, wk, soh, u56 in raw:
        cat_rate = (cat_sum.get(cat, 0.0) / cat_n[cat]) if cat_n.get(cat) else 0.0
        if u56 > 0:
            # Light empirical-Bayes shrink toward the category rate (W=8 wk window,
            # K=2 prior weight) so a single fluke sale doesn't dominate.
            vel = (wk * 8.0 + cat_rate * 2.0) / 10.0
        elif soh > 0:
            # Genuine slow cell: had stock, didn't sell -> tiny floor (NOT the
            # category prior) so source-days-freed stays large.
            vel = 0.02
        else:
            # No signal at all -> fall back to the category prior.
            vel = cat_rate if cat_rate > 0 else 0.02
        out[(store, sku)] = {"vel": vel, "has_stock": soh > 0, "sold": u56}
    return out


def _ibt_warehouse_avail(country):
    """{sku: available_units} in the central warehouse(s). Used by the
    warehouse-deploy-first waterfall so IBT only fires on the residual demand
    Replenishment won't already satisfy from the warehouse."""
    c_inv = ("AND i.country = '" + _sql_str(country) + "'") if country else ""
    q = f"""
      SELECT i.sku AS sku, SUM(i.available)::numeric AS av
      FROM all_inventory i
      WHERE i.pos_location_name IN ({WAREHOUSE_LOCATIONS})
        AND COALESCE(i.sku,'') <> '' {c_inv}
      GROUP BY 1 HAVING SUM(i.available) > 0
    """
    out = {}
    for r in (run_query(q) or []):
        out[r.get("sku")] = float(r.get("av") or 0)
    return out


def _ibt_network_sor_base(styles, date_from, date_to, country):
    """Network SOR denominator base (units_sold over the demand window + current
    store stock, warehouse + online excluded) across the involved styles. Used
    only to bound the honest forward SOR-uplift estimate — the canonical SOR
    formula itself is unchanged."""
    if not styles:
        return 0.0
    style_in = ",".join("'" + _sql_str(s) + "'" for s in styles)
    c_sales = ("AND s.country = '" + _sql_str(country) + "'") if country else ""
    c_inv = ("AND i.country = '" + _sql_str(country) + "'") if country else ""
    q = f"""
      SELECT
        COALESCE((SELECT SUM(s.net_quantity) FROM all_sales s
                  JOIN all_products_clean p ON p.sku = s.variant_sku
                  WHERE p.style_name IN ({style_in})
                    AND s.sale_kind IN ('sale','order')
                    AND s.sale_date BETWEEN '{date_from}' AND '{date_to}'
                    AND s.pos_location_name NOT IN ({WAREHOUSE_LOCATIONS})
                    AND s.pos_location_name NOT ILIKE '%online%' {c_sales}), 0)
      + COALESCE((SELECT SUM(i.available) FROM all_inventory i
                  JOIN all_products_clean p ON p.sku = i.sku
                  WHERE p.style_name IN ({style_in})
                    AND i.pos_location_name NOT IN ({WAREHOUSE_LOCATIONS})
                    AND i.pos_location_name NOT ILIKE '%online%' {c_inv}), 0)
        AS base
    """
    rows = run_query(q)
    try:
        return float(rows[0]["base"] or 0)
    except Exception:
        return 0.0


def _ibt_global_solve(date_from, date_to, country, low, high,
                      use_clustering=True, bundle_limit=300):
    """Phase-1 global IBT solve.

    Replaces the legacy per-pair cross-join sizing with ONE pass over two
    decrementing tables so the same stock is never promised twice and no
    destination is filled past its gap:
      - dest_budget[(to_store, sku)] = max(2 - to_sku_avail, 0)  (shared across
        every donor competing for that destination sku)
      - donor_ledger[(from_store, sku)] = from_sku_avail - 1     (shared across
        every destination pulling from that donor sku; the -1 keeps >= 1 of the
        size on the donor shelf -> size-run integrity)
    Edges are taken best-first (composite score, then demonstrated destination
    demand); each assignment debits BOTH sides atomically. Assigned sku moves
    are then consolidated into one bundle per (from_store -> to_store) and the
    minimum-transfer gate is applied per bundle. The canonical SOR formula is
    never used or changed here."""
    _warehouse_bins_refresh()
    edges = run_query(_ibt_edge_sql(date_from, date_to, country, low, high,
                                    use_clustering=use_clustering)) or []
    # Code-level hard-retirement list (Zoya brand already excluded in SQL): a
    # manually-retired style must never be a receiver (nor donor) here.
    edges = [e for e in edges if not _is_manually_retired(e.get("style_name"))]

    # ── Phase 2 inputs: per-cell velocity, corridor lead-time, warehouse pool ──
    velmap = _ibt_store_sku_velocity(date_from, date_to, country)
    lt_map = _ibt_leadtime_map()
    wh_pool = _ibt_warehouse_avail(country)  # {sku: warehouse on-hand} (mutated)

    def _vel(store, sku):
        v = velmap.get((store, sku))
        return float(v["vel"]) if v and v.get("vel") else 0.02

    def _days_to_sell(store, sku, cap=None):
        v = _vel(store, sku)
        d = 7.0 / v if v > 0 else IBT_SOURCE_DAYS_CAP
        return min(d, cap) if cap else d

    dest_budget = {}
    donor_ledger = {}
    for e in edges:
        dk = (e["to_store"], e["sku"])
        if dk not in dest_budget:
            dest_budget[dk] = max(2 - int(e.get("to_sku_avail") or 0), 0)
        lk = (e["from_store"], e["sku"])
        if lk not in donor_ledger:
            donor_ledger[lk] = max(int(e.get("from_sku_avail") or 0) - 1, 0)

    # ── Warehouse-deploy-first waterfall (spec §6) ────────────────────────────
    # Replenishment can already satisfy a destination gap from the central
    # warehouse without any store-to-store move. So BEFORE the IBT solve, net the
    # warehouse on-hand per sku off each destination gap in demand-strength order
    # (strongest demonstrated demand first). IBT then only fires on the RESIDUAL
    # gap the warehouse cannot cover — this stops IBT double-shipping against the
    # warehouse replenishment path.
    wh_covered = {}  # (to_store, sku) -> units the warehouse will cover
    dest_demand = {}
    for e in edges:
        dk = (e["to_store"], e["sku"])
        dem = int(e.get("to_qty_sold_28d") or 0)
        if dk not in dest_demand or dem > dest_demand[dk]:
            dest_demand[dk] = dem
    for dk in sorted(dest_budget, key=lambda k: (-dest_demand.get(k, 0), k[0], k[1])):
        gap = dest_budget[dk]
        if gap <= 0:
            continue
        sku = dk[1]
        pool = wh_pool.get(sku, 0)
        if pool <= 0:
            continue
        take = gap if gap < pool else pool
        wh_pool[sku] = pool - take
        dest_budget[dk] = gap - take
        if take > 0:
            wh_covered[dk] = take

    def _value_per_unit(asp, cross):
        tpu = IBT_TRANSPORT_PER_UNIT_CROSS if cross else IBT_TRANSPORT_PER_UNIT_DOMESTIC
        v = float(asp or 0) - tpu
        if cross:
            v -= float(asp or 0) * IBT_DUTY_PCT_CROSS
        return v

    # Per-edge economics (qty-independent), used for ranking + the markdown fork.
    hub_country = _ibt_hub_country()
    for e in edges:
        fc, tc = e.get("from_country") or "", e.get("to_country") or ""
        cross = bool(fc and tc and fc != tc)
        # Phase 3 §6: route hub-THROUGH-WAREHOUSE by default — transit is the sum of
        # the donor->hub and hub->dest legs (which honestly RAISES net-CCC vs a
        # direct hop). A named same-mall pair bypasses the hub for a same-day
        # walk-over. The canonical SOR formula is untouched; only the CCC term moves.
        same_mall = _ibt_is_same_mall(e["from_store"], e["to_store"])
        via_hub = not same_mall
        if via_hub:
            transit = (_ibt_lead_days(lt_map, fc, hub_country)
                       + _ibt_lead_days(lt_map, hub_country, tc))
            route = f"{e['from_store']} → Warehouse hub → {e['to_store']}"
        else:
            transit = IBT_SAME_MALL_LEAD_DAYS
            route = f"{e['from_store']} → {e['to_store']} (same-mall walk-over)"
        src_days = _days_to_sell(e["from_store"], e["sku"], cap=IBT_SOURCE_DAYS_CAP)
        dst_days = _days_to_sell(e["to_store"], e["sku"])
        e["_cross"] = cross
        e["_via_hub"] = via_hub
        e["_route"] = route
        e["_transit_days"] = transit
        e["_src_days"] = src_days
        e["_dst_days"] = dst_days
        e["_net_ccc_per_unit"] = src_days - dst_days - transit
        e["_value_per_unit"] = _value_per_unit(e.get("asp"), cross)
        e["_curve_complete"] = int(e.get("to_sku_avail") or 0) == 0
        e["_pays"] = (e["_net_ccc_per_unit"] > 0 and e["_value_per_unit"] > 0)

    # Rank: size-curve completion first (filling an empty destination size keeps a
    # buyable run on the floor), then by net-CCC × value, then composite score.
    edges.sort(key=lambda e: (
        0 if e["_curve_complete"] else 1,
        -(e["_net_ccc_per_unit"] * max(e["_value_per_unit"], 0.0)),
        -(int(e.get("score") or 0)),
        -(int(e.get("to_qty_sold_28d") or 0)),
        e.get("style_name") or "", e.get("sku") or ""))

    # Pass 1 — assignment. Walk the ranked edges (curve-completers first, then
    # net-CCC x value) and assign only the moves that PAY against the shared
    # destination budget + donor ledger. Track which donor SKUs actually ship so the
    # markdown pass below can tell stuck stock from redeployed stock.
    assigned = []
    shipped_skus = set()  # (from_store, sku) that received >= 1 assigned unit
    for e in edges:
        dk = (e["to_store"], e["sku"])
        lk = (e["from_store"], e["sku"])
        b = dest_budget.get(dk, 0)
        d = donor_ledger.get(lk, 0)
        q = b if b < d else d
        if q <= 0:
            # No assignable qty on this edge (destination gap already filled by a
            # higher-ranked donor / warehouse, or the donor is committed elsewhere).
            # The markdown pass handles the no-qualified-demand case.
            continue
        if not e["_pays"]:
            # Qualifies on stock balance but does NOT pay — net cash-conversion
            # benefit <= 0 or value after transport+duty <= 0. Skip; the markdown
            # pass surfaces it.
            continue
        dest_budget[dk] = b - q
        donor_ledger[lk] = d - q
        shipped_skus.add(lk)
        rec = dict(e)
        rec["suggested_qty"] = int(q)
        rec["source_onhand_at_calc"] = int(e.get("from_sku_avail") or 0)
        rec["dest_gap_at_calc"] = max(2 - int(e.get("to_sku_avail") or 0), 0)
        rec["net_ccc_days"] = round(e["_net_ccc_per_unit"] * q, 1)
        rec["value_kes"] = round(e["_value_per_unit"] * q, 0)
        rec["via_hub"] = bool(e["_via_hub"])
        rec["route"] = e["_route"]
        assigned.append(rec)

    # Pass 2 — markdown fork (spec §7). A donor SKU that qualifies on stock balance
    # (it is a slow-seller-with-stock by construction of the edge query) but NEVER
    # ships is stuck and should be cleared locally rather than relocated. Two causes,
    # both required by the spec:
    #   * the move doesn't pay (net CCC <= 0 / value after freight+duty <= 0), OR
    #   * there is NO qualified destination demand left for it (every receiver gap was
    #     filled by higher-ranked donors or warehouse stock -> the edge never assigned).
    # A donor SKU that DID ship (even partially to one destination) is excluded — its
    # on-hand is being redeployed, not stuck.
    markdown = {}  # (from_store, style_name) -> markdown candidate
    for e in edges:
        lk = (e["from_store"], e["sku"])
        if lk in shipped_skus:
            continue
        if e["_pays"]:
            reason = "no_demand"      # could pay, but no destination gap remained
        elif e["_value_per_unit"] <= 0:
            reason = "no_value"       # freight/duty wipes the value
        else:
            reason = "no_ccc_gain"    # dest sells no faster once transit is paid
        mk = (e["from_store"], e.get("style_name"))
        cur = markdown.get(mk)
        if cur is None:
            cur = {
                "from_store": e["from_store"],
                "from_country": e.get("from_country") or "",
                "style_name": e.get("style_name"), "brand": e.get("brand"),
                "subcategory": e.get("subcategory"),
                "donor_onhand": 0,
                "sku_count": 0,
                "reason": reason,
                "src_days_to_sell": round(e["_src_days"], 1),
                "_skus": set(),
                "_reasons": set(),
            }
            markdown[mk] = cur
        # The same (from_store, sku) appears on multiple candidate edges (one per
        # destination); count each donor SKU's on-hand exactly once so the stuck-stock
        # total isn't inflated by the number of would-be receivers.
        if e["sku"] not in cur["_skus"]:
            cur["_skus"].add(e["sku"])
            cur["donor_onhand"] += int(e.get("from_sku_avail") or 0)
            cur["sku_count"] += 1
        cur["_reasons"].add(reason)
    # Collapse the per-style reason set to the single most actionable reason
    # (value loss > no CCC gain > no demand) for the inline badge / panel copy.
    for cur in markdown.values():
        rs = cur.pop("_reasons", set())
        cur["reason"] = ("no_value" if "no_value" in rs
                         else "no_ccc_gain" if "no_ccc_gain" in rs
                         else "no_demand")

    TIER = {1: "A", 2: "B", 3: "C"}
    bundles = {}
    for r in assigned:
        key = (r["from_store"], r["to_store"])
        bd = bundles.get(key)
        if bd is None:
            fc = r.get("from_country") or ""
            tc = r.get("to_country") or ""
            cross = bool(fc and tc and fc != tc)
            bd = {
                "bundle_id": (r["from_store"] or "") + " -> " + (r["to_store"] or ""),
                "from_store": r["from_store"], "from_country": fc,
                "from_cluster": TIER.get(int(r.get("from_tier") or 3), "C"),
                "to_store": r["to_store"], "to_country": tc,
                "to_cluster": TIER.get(int(r.get("to_tier") or 3), "C"),
                "cross_border": cross,
                "corridor": "Cross-border" if cross else "Domestic",
                "via_hub": bool(r.get("via_hub", True)),
                "route": r.get("route"),
                "units": 0, "sku_count": 0, "score": 0,
                "net_ccc_days": 0.0, "value_kes": 0.0, "curve_completions": 0,
                "_styles": set(), "skus": [],
            }
            bundles[key] = bd
        bd["units"] += r["suggested_qty"]
        bd["sku_count"] += 1
        bd["net_ccc_days"] += r["net_ccc_days"]
        bd["value_kes"] += r["value_kes"]
        if r["_curve_complete"]:
            bd["curve_completions"] += 1
        sc = int(r.get("score") or 0)
        if sc > bd["score"]:
            bd["score"] = sc
        bd["_styles"].add(r.get("style_name"))
        bd["skus"].append({
            "style_name": r.get("style_name"), "brand": r.get("brand"),
            "subcategory": r.get("subcategory"), "sku": r.get("sku"),
            "color": r.get("color"), "size": r.get("size"),
            "barcode": r.get("barcode"), "bin": r.get("bin"),
            "from_available": int(r.get("from_sku_avail") or 0),
            "to_available": int(r.get("to_sku_avail") or 0),
            "suggested_qty": r["suggested_qty"],
            "source_onhand_at_calc": r["source_onhand_at_calc"],
            "dest_gap_at_calc": r["dest_gap_at_calc"],
            "from_qty_sold_28d": int(r.get("from_qty_sold_28d") or 0),
            "to_qty_sold_28d": int(r.get("to_qty_sold_28d") or 0),
            "net_ccc_days": r["net_ccc_days"],
            "value_kes": r["value_kes"],
            "curve_complete": bool(r["_curve_complete"]),
        })

    out = []
    for bd in bundles.values():
        min_units = IBT_MIN_TRANSFER_CROSS if bd["cross_border"] else IBT_MIN_TRANSFER_DOMESTIC
        if bd["units"] < min_units:
            continue
        bd["style_count"] = len(bd["_styles"])
        del bd["_styles"]
        bd["net_ccc_days"] = round(bd["net_ccc_days"], 1)
        bd["value_kes"] = round(bd["value_kes"], 0)
        bd["skus"].sort(key=lambda s: (-(s["suggested_qty"]),
                                       s.get("style_name") or "", s.get("sku") or ""))
        out.append(bd)

    # Bundle ranking (spec §6): size-curve completions FIRST — a move that fills an
    # empty destination size is the highest-conviction redeploy — then the most
    # value-dense corridors (value redeployed, then inventory-days removed), falling
    # back to the composite score + units.
    out.sort(key=lambda b: (-(b["curve_completions"]), -(b["value_kes"]),
                            -(b["net_ccc_days"]), -(b["score"]), -(b["units"])))
    out = out[:bundle_limit]

    units_total = sum(b["units"] for b in out)
    sku_total = sum(b["sku_count"] for b in out)
    stores = set()
    for b in out:
        stores.add(b["from_store"])
        stores.add(b["to_store"])
    cross_n = sum(1 for b in out if b["cross_border"])
    value_total = sum(b["value_kes"] for b in out)
    ccc_total = sum(b["net_ccc_days"] for b in out)
    avg_ccc_per_unit = round(ccc_total / units_total, 1) if units_total > 0 else 0.0
    curve_total = sum(b["curve_completions"] for b in out)
    wh_units = sum(wh_covered.values())

    # Markdown fork: only surface a candidate once it carries meaningful stuck
    # stock (>= the domestic minimum), sorted by the most stock to clear.
    markdown_out = [m for m in markdown.values()
                    if m["donor_onhand"] >= IBT_MIN_TRANSFER_DOMESTIC]
    for m in markdown_out:
        m.pop("_skus", None)
    markdown_out.sort(key=lambda m: (-(m["donor_onhand"]), m.get("from_store") or "",
                                     m.get("style_name") or ""))
    markdown_out = markdown_out[:bundle_limit]

    # Honest bounded forward SOR uplift (pp): if every redeployed unit sells at
    # its demonstrated-demand destination, the network SOR over the involved
    # styles rises by units / (network_sold + network_stock). Bounded by the
    # pickable assigned units; never overstates because the denominator is the
    # full involved-style network base.
    styles_involved = sorted({s["style_name"] for b in out
                              for s in b["skus"] if s.get("style_name")})
    sor_pp = 0.0
    if styles_involved and units_total > 0:
        denom = _ibt_network_sor_base(styles_involved, date_from, date_to, country)
        if denom and denom > 0:
            sor_pp = round(100.0 * units_total / denom, 2)

    # Phase 3 realisation feedback: scale the forward PROJECTION (SOR uplift +
    # inventory-days-removed) by the learned realised/projected calibration factor
    # (1.0 until reconciliation has landed samples). The canonical SOR FORMULA and
    # the per-edge ranking are untouched — calibration only tempers the headline
    # projections so the proof strip reads against demonstrated realisation.
    calib = _ibt_proj_calibration()
    sor_pp_cal = round(sor_pp * calib, 2)
    inv_days_cal = round(ccc_total * calib, 0)
    avg_ccc_cal = (round((ccc_total * calib) / units_total, 1)
                   if units_total > 0 else 0.0)
    fresh = _ibt_freshness()

    return {
        "as_of": date.today().isoformat(),
        "run_id": date.today().isoformat(),
        "as_of_eat": fresh["as_of_eat"],
        "freshness": fresh,
        "calibration": calib,
        "summary": {
            "bundles": len(out), "units": units_total, "skus": sku_total,
            "stores": len(stores), "cross_border_bundles": cross_n,
            "sor_uplift_pp": sor_pp_cal,
            "sor_uplift_pp_raw": sor_pp,
            "value_kes": round(value_total, 0),
            "inventory_days_removed": inv_days_cal,
            "inventory_days_removed_raw": round(ccc_total, 0),
            "avg_net_ccc_days_per_unit": avg_ccc_cal,
            "avg_net_ccc_days_per_unit_raw": avg_ccc_per_unit,
            "calibration": calib,
            "curve_completions": curve_total,
            "warehouse_covered_units": int(wh_units),
            "markdown_candidates": len(markdown_out),
        },
        "bundles": out,
        "markdown_candidates": markdown_out,
    }


@app.get("/api/analytics/ibt-suggestions")
def ibt_suggestions(
    country:     str = Query(default=None),
    demand_days: int = Query(default=28),
    limit:       int = Query(default=300),
    low_pct:     float = Query(default=20),
    high_pct:    float = Query(default=150),
    use_clustering: bool = Query(default=True),
):
    # Phase 1: an as-of-TODAY worklist. The demand window is a labelled
    # trailing-N-days lookback for the velocity/sell-rate signal (default 28d);
    # it is NOT the global date filter. The engine returns from->to BUNDLES.
    today = date.today()
    dd = max(7, min(int(demand_days or 28), 120))
    date_to = today.isoformat()
    date_from = (today - timedelta(days=dd)).isoformat()
    low = float(low_pct) / 100.0
    high = float(high_pct) / 100.0
    lim = max(1, min(int(limit), 1000))
    res = _ibt_global_solve(date_from, date_to, country, low, high,
                            use_clustering=use_clustering, bundle_limit=lim)
    res["demand_days"] = dd
    return res


@app.get("/api/analytics/ibt-sku-breakdown")
def ibt_sku_breakdown(
    style_name:    str = Query(...),
    from_store:    str = Query(...),
    to_store:      str = Query(...),
    units_to_move: int = Query(default=0),
):
    _warehouse_bins_refresh()
    st = _sql_str(style_name)
    fs = _sql_str(from_store)
    ts = _sql_str(to_store)
    # Phase 2 A5 — size-run integrity guard. Every size the donor still stocks
    # keeps at least 1 unit on the shelf, so a transfer can never zero out a size
    # and break the donor's size run (qty is capped at from_available - 1). A SKU
    # whose only available unit would otherwise move (and the destination is not
    # already covered) is held back and flagged size_run_protected = true.
    q = f"""
    WITH skus AS (
      SELECT DISTINCT p.sku, p.color_print AS color, p.size, p.barcode
      FROM all_products_clean p WHERE p.style_name = '{st}'
    ),
    fi AS (SELECT sku, SUM(available) AS av FROM all_inventory WHERE pos_location_name = '{fs}' GROUP BY sku),
    ti AS (SELECT sku, SUM(available) AS av FROM all_inventory WHERE pos_location_name = '{ts}' GROUP BY sku)
    SELECT s.sku, s.color, s.size, s.barcode,
           COALESCE(wb.bin, '') AS bin,
           COALESCE(fi.av, 0)::int AS from_available,
           COALESCE(ti.av, 0)::int AS to_available,
           LEAST(
             GREATEST(COALESCE(fi.av,0) - 1, 0),
             GREATEST(2 - COALESCE(ti.av,0), 0)
           )::int AS suggested_qty,
           (COALESCE(fi.av,0) >= 1
            AND COALESCE(ti.av,0) < 2
            AND LEAST(
                  GREATEST(COALESCE(fi.av,0) - 1, 0),
                  GREATEST(2 - COALESCE(ti.av,0), 0)
                ) = 0) AS size_run_protected
    FROM skus s
    LEFT JOIN fi ON fi.sku = s.sku
    LEFT JOIN ti ON ti.sku = s.sku
    LEFT JOIN warehouse_bins wb ON wb.barcode = s.barcode
    WHERE COALESCE(fi.av,0) > 0 OR COALESCE(ti.av,0) > 0
    ORDER BY suggested_qty DESC, from_available DESC
    """
    skus = run_query(q)
    return {
        "from_store": from_store,
        "to_store": to_store,
        "from_total": sum(r["from_available"] for r in skus),
        "to_total": sum(r["to_available"] for r in skus),
        "suggested_total": sum(r["suggested_qty"] for r in skus),
        "skus": skus,
    }


@app.get("/api/analytics/ibt-warehouse-to-store")
def ibt_warehouse_to_store(
    date_from: str = Query(default=None),
    date_to:   str = Query(default=None),
    country:   str = Query(default=None),
    limit:     int = Query(default=300),
):
    _warehouse_bins_refresh()
    today = date.today()
    date_to = date_to or today.isoformat()
    date_from = date_from or (today - timedelta(days=30)).isoformat()
    lim = max(1, min(int(limit), 1000))
    c_sales = ("AND s.country = '" + _sql_str(country) + "'") if country else ""
    c_inv = ("AND i.country = '" + _sql_str(country) + "'") if country else ""
    q = f"""
    WITH sv AS (
      SELECT p.style_name AS style, s.pos_location_name AS store,
             SUM(s.net_quantity) AS units_sold
      FROM all_sales s
      JOIN all_products_clean p ON p.sku = s.variant_sku
      WHERE s.sale_date BETWEEN '{date_from}' AND '{date_to}'
        AND s.sale_kind IN ('sale','order')
        AND s.pos_location_name NOT IN ({WAREHOUSE_LOCATIONS})
        AND s.pos_location_name NOT IN ('Manual Order','Online - vivo-uganda')
        AND COALESCE(p.style_name,'') <> '' {c_sales}
      GROUP BY 1, 2 HAVING SUM(s.net_quantity) >= 3
    ),
    si AS (
      SELECT p.style_name AS style, i.pos_location_name AS store,
             SUM(i.available) AS available
      FROM all_inventory i
      JOIN all_products_clean p ON p.sku = i.sku
      WHERE i.pos_location_name NOT IN ({WAREHOUSE_LOCATIONS})
        AND COALESCE(i.pos_location_name,'') <> ''
        AND COALESCE(p.style_name,'') <> '' {c_inv}
      GROUP BY 1, 2
    ),
    wh AS (
      SELECT p.style_name AS style, SUM(i.available) AS available
      FROM all_inventory i
      JOIN all_products_clean p ON p.sku = i.sku
      WHERE i.pos_location_name = 'Warehouse Finished Goods'
        AND COALESCE(p.style_name,'') <> ''
      GROUP BY 1
    ),
    sb AS (
      SELECT p.style_name AS style,
             string_agg(DISTINCT wb.bin, ', ' ORDER BY wb.bin) AS bins
      FROM warehouse_bins wb
      JOIN all_products_clean p ON p.barcode = wb.barcode
      WHERE COALESCE(wb.bin,'') <> '' AND COALESCE(p.style_name,'') <> ''
      GROUP BY 1
    ),
    -- ── Minimum range guard (≥ 3 distinct SKUs at the receiver post-transfer) ──
    -- Only allocate a style to a store if, AFTER the warehouse transfer, the store
    -- will hold ≥ 3 distinct SKUs of it. Post-transfer SKUs = SKUs the store already
    -- stocks (av >= 1) UNION SKUs the warehouse will send (warehouse av >= 2 and the
    -- store currently has <= 1) — matching the SKU-breakdown's suggested_qty > 0 rule.
    sku_av AS (
      SELECT p.style_name AS style, i.pos_location_name AS store, i.sku AS sku,
             SUM(i.available) AS av
      FROM all_inventory i
      JOIN all_products_clean p ON p.sku = i.sku
      WHERE i.pos_location_name NOT IN ({WAREHOUSE_LOCATIONS})
        AND COALESCE(i.pos_location_name,'') <> ''
        AND COALESCE(p.style_name,'') <> '' {c_inv}
      GROUP BY 1, 2, 3
    ),
    wh_sku AS (
      SELECT p.style_name AS style, i.sku AS sku, SUM(i.available) AS av
      FROM all_inventory i
      JOIN all_products_clean p ON p.sku = i.sku
      WHERE i.pos_location_name = 'Warehouse Finished Goods'
        AND COALESCE(p.style_name,'') <> ''
      GROUP BY 1, 2
    ),
    cand AS (SELECT DISTINCT style, store FROM sv),
    recv_have AS (
      SELECT c.style, c.store, sa.sku
      FROM cand c
      JOIN sku_av sa ON sa.style = c.style AND sa.store = c.store AND sa.av >= 1
    ),
    recv_get AS (
      SELECT c.style, c.store, w.sku
      FROM cand c
      JOIN wh_sku w ON w.style = c.style AND w.av >= 2
      LEFT JOIN sku_av dt ON dt.style = c.style AND dt.store = c.store AND dt.sku = w.sku
      WHERE COALESCE(dt.av, 0) <= 1
    ),
    recv_proj AS (
      SELECT style, store, COUNT(DISTINCT sku) AS projected_skus
      FROM (SELECT * FROM recv_have UNION SELECT * FROM recv_get) u
      GROUP BY 1, 2
    )
    SELECT sv.style AS style_name, pp.brand, pp.category AS subcategory,
           sv.store AS to_store,
           GREATEST(LEAST(wh.available, sv.units_sold - COALESCE(si.available, 0)), 1)::int AS suggested_qty,
           sv.units_sold::int AS to_qty_sold_28d,
           COALESCE(sb.bins, '') AS bins
    FROM sv
    JOIN wh ON wh.style = sv.style AND wh.available > 0
    LEFT JOIN si ON si.style = sv.style AND si.store = sv.store
    LEFT JOIN sb ON sb.style = sv.style
    LEFT JOIN LATERAL (
      SELECT brand, category FROM all_products_clean WHERE style_name = sv.style LIMIT 1
    ) pp ON TRUE
    JOIN recv_proj rp ON rp.style = sv.style AND rp.store = sv.store
    WHERE COALESCE(si.available, 0) <= 2
      AND rp.projected_skus >= 3
    ORDER BY suggested_qty DESC
    LIMIT {lim}
    """
    rows = run_query(q, date_to=date_to)
    # Attach the per-destination-store picker from the persisted roster map so
    # the Owner column reflects the same store→owner assignment as the
    # replenishment reports (recomputed only on an explicit redistribute).
    store_map = _replen_store_owner_map()
    for r in (rows or []):
        r["owner"] = store_map.get(r.get("to_store")) or "—"
    return rows


