def _seed_finance_account_map():
    """Idempotently bootstrap finance_account_map when it is incomplete.

    Same boot-safe pattern as the targets budget seed: the emptiness check and
    the insert run in ONE advisory-locked transaction (so concurrent boots
    serialize and a crash can't leave a permanently partial map — the next boot
    heals it). The guard is completeness-based (expects the full mapping count)
    and inserts ON CONFLICT (account_code) DO NOTHING, so it only ADDS missing
    account codes and NEVER overwrites a mapping edited directly in production.
    """
    rows = []
    for (pl_group, pl_section), codes in _FINANCE_ACCOUNT_MAP_SEED.items():
        for code in codes:
            rows.append((code, pl_group, pl_section))
    expected = len(rows)
    conn = None
    try:
        conn = get_conn()
        conn.autocommit = False
        cur = conn.cursor()
        cur.execute("SELECT pg_advisory_xact_lock(%s)",
                    (_FINANCE_MAP_SEED_LOCK_KEY,))
        cur.execute("SELECT COUNT(*) FROM finance_account_map")
        have = (cur.fetchone() or [0])[0]
        if have >= expected:
            conn.rollback()  # complete — nothing to do (releases the lock)
            cur.close()
            return
        cur.executemany(
            "INSERT INTO finance_account_map (account_code, pl_group, pl_section) "
            "VALUES (%s, %s, %s) "
            "ON CONFLICT (account_code) DO NOTHING",
            rows,
        )
        cur.execute("SELECT COUNT(*) FROM finance_account_map")
        now_have = (cur.fetchone() or [0])[0]
        conn.commit()
        print(f"[finance] account_map seed: had {have}, now {now_have} "
              f"(added {now_have - have})", flush=True)
        cur.close()
    except Exception as e:  # pragma: no cover - best effort, never block boot
        if conn is not None:
            try:
                conn.rollback()
            except Exception:
                pass
        print(f"[finance] seed account_map failed: {e}", flush=True)
    finally:
        if conn is not None:
            conn.close()


@_deferred_startup
def _targets_startup():
    _ensure_targets_table()
    _seed_targets_budget_2026()
    _ensure_finance_account_map()
    _seed_finance_account_map()
    # Optional free-text transfer/PO reference attached when a replenishment is
    # marked done (IBT moves already carry po_number in ibt_completions).
    try:
        _users_exec("ALTER TABLE recommendation_actions "
                    "ADD COLUMN IF NOT EXISTS transfer_ref TEXT")
    except Exception as e:  # pragma: no cover - best effort
        print(f"[targets] ensure transfer_ref column failed: {e}", flush=True)


@app.get("/api/analytics/annual-targets")
def analytics_annual_targets(year: int = Query(default=None)):
    # Targets come from the stored leadership budget (targets_monthly,
    # scope='region', source='budget'). When no budget exists for a year (e.g.
    # the prior-year YoY lookup), we fall back to prior-year actuals + a 15%
    # stretch so the comparison column still renders.
    yr = int(year) if year else date.today().year
    growth = 1.15

    def actuals(y):
        return run_query("""
            SELECT """ + _ACTUAL_BUCKET_CASE + """ AS bucket,
                EXTRACT(QUARTER FROM s.sale_date::date)::int AS q,
                ROUND(""" + _TARGET_REVENUE + """) AS net
            FROM all_sales s
            WHERE s.sale_date BETWEEN '""" + str(y) + """-01-01' AND '""" + str(y) + """-12-31'
              AND s.sale_kind IN ('sale','order','return') AND """ + BASE_FILTERS + """
            GROUP BY 1, 2
        """)

    def to_map(rows):
        m = {}
        for r in rows:
            q = int(r["q"]) if r["q"] else 0
            m.setdefault(r["bucket"], {1: 0, 2: 0, 3: 0, 4: 0})
            if q in (1, 2, 3, 4):
                m[r["bucket"]][q] += float(r["net"] or 0)
        return m

    cur_m, prev_m = to_map(actuals(yr)), to_map(actuals(yr - 1))

    # Stored budget targets for this year, summed into quarters per bucket.
    budget = {}
    for r in run_query(
        "SELECT name, EXTRACT(QUARTER FROM month)::int AS q, "
        "SUM(target_kes)::numeric AS tgt FROM targets_monthly "
        "WHERE scope = 'region' AND source = 'budget' "
        "AND EXTRACT(YEAR FROM month) = " + str(yr) + " GROUP BY 1, 2"
    ):
        q = int(r["q"]) if r["q"] else 0
        if q in (1, 2, 3, 4):
            budget.setdefault(r["name"], {1: 0, 2: 0, 3: 0, 4: 0})[q] += float(r["tgt"] or 0)

    start, end = date(yr, 1, 1), date(yr, 12, 31)
    days_total = (end - start).days + 1
    today = date.today()
    days_elapsed = 0 if today < start else days_total if today > end else (today - start).days + 1
    frac = days_elapsed / days_total if days_total else 1

    # Prior-year YTD bounded to the SAME calendar date as today, so the YoY
    # comparison is apples-to-apples (this-year Jan 1..today vs last-year
    # Jan 1..same MM-DD). Without this the frontend compared this-year-YTD
    # against last-year's FULL year, making YoY read ~-55% mid-year. For a
    # year that is fully in the past we use last year's whole span; for a
    # year that has not started yet there is no YTD to compare.
    if today > end:
        ly_to = date(yr - 1, 12, 31)
    elif today < start:
        ly_to = None
    else:
        try:
            ly_to = date(yr - 1, today.month, today.day)
        except ValueError:
            ly_to = date(yr - 1, 2, 28)  # Feb 29 in a non-leap prior year
    ytd_ly = {}
    if ly_to is not None:
        for r in run_query(
            "SELECT " + _ACTUAL_BUCKET_CASE + " AS bucket, "
            "ROUND(" + _TARGET_REVENUE + ") AS net FROM all_sales s "
            "WHERE s.sale_date BETWEEN '" + str(date(yr - 1, 1, 1)) + "' AND '" + str(ly_to) + "' "
            "AND s.sale_kind IN ('sale','order','return') AND " + BASE_FILTERS + " GROUP BY 1"
        ):
            ytd_ly[r["bucket"]] = float(r["net"] or 0)

    def make_bucket(name):
        pq = prev_m.get(name, {1: 0, 2: 0, 3: 0, 4: 0})
        cq = cur_m.get(name, {1: 0, 2: 0, 3: 0, 4: 0})
        bq = budget.get(name)
        # Quarter targets: stored budget when present, else prior-year + 15%.
        tq = {q: (round(bq.get(q, 0)) if bq is not None else round(pq[q] * growth))
              for q in (1, 2, 3, 4)}
        target_annual = sum(tq.values())
        actual_ytd = round(sum(cq.values()))
        projected_year = round(actual_ytd / frac) if frac else actual_ytd
        return {
            "bucket": name, "target_annual": target_annual, "actual_ytd": actual_ytd,
            "actual_ytd_ly": round(ytd_ly.get(name, 0)),
            "pct_of_target_ytd": round(100.0 * actual_ytd / target_annual, 1) if target_annual else 0.0,
            "projected_year": projected_year,
            "pct_of_target_projected": round(100.0 * projected_year / target_annual, 1) if target_annual else 0.0,
            "variance_projected": projected_year - target_annual,
            "quarters": {("Q%d" % q): tq[q] for q in (1, 2, 3, 4)},
            "actual_quarters": {("Q%d" % q): round(cq[q]) for q in (1, 2, 3, 4)},
        }

    # Always emit the 4 canonical buckets in order (matches the budget + the
    # frontend bucket list). 'Other' actuals (mislabeled rows) are dropped so
    # the page reconciles to the budget total.
    buckets = [make_bucket(n) for n in _TARGET_BUCKETS]
    tt_target = sum(b["target_annual"] for b in buckets)
    tt_actual = sum(b["actual_ytd"] for b in buckets)
    tt_actual_ly = sum(b["actual_ytd_ly"] for b in buckets)
    tt_proj = round(tt_actual / frac) if frac else tt_actual
    total = {
        "target_annual": tt_target, "actual_ytd": tt_actual,
        "actual_ytd_ly": tt_actual_ly,
        "pct_of_target_ytd": round(100.0 * tt_actual / tt_target, 1) if tt_target else 0.0,
        "projected_year": tt_proj,
        "pct_of_target_projected": round(100.0 * tt_proj / tt_target, 1) if tt_target else 0.0,
        "variance_projected": tt_proj - tt_target,
    }
    return {
        "total": total, "buckets": buckets,
        "completion_pct": round(100.0 * days_elapsed / days_total, 1),
        "days_elapsed": days_elapsed, "days_total": days_total, "as_of": today.isoformat(),
    }


# ── Quarterly target scorecard (leadership) ────────────────────────────────
# A single-quarter cockpit for the leadership team: revenue targets (from the
# seeded budget) broken by market/channel, plus AUTO-DERIVED targets for the
# operational metrics on the leadership sheet, and a per-store breakdown that
# splits each market's targets by the store's historical share of sales.
#
# Money basis mirrors the rest of the dashboard exactly: net-of-returns via
# _TARGET_REVENUE (needs sale_kind IN ('sale','order','return')) + BASE_FILTERS,
# so revenue figures reconcile with the Executive Summary and the annual
# Targets page. Derived targets are LY-same-quarter actual × an implied growth
# factor (rev target ÷ LY rev actual, fallback +15%) for COUNT metrics, and the
# LY rate held/nudged by a small capped uplift for RATE metrics. Metrics with no
# trustworthy historical quarterly actual (Qty to Buy = forward-looking; Qty to
# Produce = production board only carries recent orders) are returned as an
# explicit "not available" state so the UI never shows a fabricated number.
#
# Read-only. Registered under /api/analytics (no extra gate here); the page id
# ("quarter-scorecard") is leadership+admin in the page-access sets so the nav
# and route are gated, and the underlying figures are the same public BI reads.
def _quarter_bounds(yr, q):
    m0 = {1: 1, 2: 4, 3: 7, 4: 10}[q]
    m1 = m0 + 2
    start = date(yr, m0, 1)
    end = (date(yr, 12, 31) if m1 == 12
           else date(yr, m1 + 1, 1) - timedelta(days=1))
    return start, end


@app.get("/api/analytics/quarter-scorecard")
def analytics_quarter_scorecard(quarter: int = Query(default=None),
                                year: int = Query(default=None)):
    today = date.today()
    yr = int(year) if year else today.year
    q = int(quarter) if quarter else (today.month - 1) // 3 + 1
    if q not in (1, 2, 3, 4):
        raise HTTPException(status_code=400, detail="quarter must be 1..4")

    q_start, q_end = _quarter_bounds(yr, q)
    ly_start, ly_end = _quarter_bounds(yr - 1, q)
    as_of = min(today, q_end)          # quarter-to-date cutoff
    started = today >= q_start
    days_total = (q_end - q_start).days + 1
    days_elapsed = (0 if today < q_start
                    else days_total if today > q_end
                    else (as_of - q_start).days + 1)
    days_left = max(0, days_total - days_elapsed)
    frac = days_elapsed / days_total if days_total else 0.0
    # LY same-period-to-date cutoff (equal number of elapsed days) so the "vs LY"
    # delta is apples-to-apples with the quarter-to-date actual. The FULL LY
    # quarter stays the derivation basis for the targets.
    ly_asof = (ly_start + timedelta(days=days_elapsed - 1)) if days_elapsed > 0 else ly_start

    def _win(a, b):
        return "s.sale_date BETWEEN '" + str(a) + "' AND '" + str(b) + "'"

    # ── Revenue: budget targets + to-date & LY actuals per bucket ──────────
    budget = {}
    for r in run_query(
        "SELECT name, SUM(target_kes)::numeric AS tgt FROM targets_monthly "
        "WHERE scope = 'region' AND source = 'budget' "
        "AND EXTRACT(YEAR FROM month) = " + str(yr) + " "
        "AND EXTRACT(QUARTER FROM month)::int = " + str(q) + " GROUP BY 1"
    ):
        budget[r["name"]] = float(r["tgt"] or 0)

    def rev_by_bucket(a, b):
        m = {}
        for r in run_query(
            "SELECT " + _ACTUAL_BUCKET_CASE + " AS bucket, ROUND(" + _TARGET_REVENUE + ") AS net "
            "FROM all_sales s WHERE " + _win(a, b) +
            " AND s.sale_kind IN ('sale','order','return') AND " + BASE_FILTERS + " GROUP BY 1"
        ):
            m[r["bucket"]] = float(r["net"] or 0)
        return m

    cur_rev = rev_by_bucket(q_start, as_of) if started else {}
    ly_rev = rev_by_bucket(ly_start, ly_end)
    ly_rev_td = rev_by_bucket(ly_start, ly_asof) if started else {}

    tt_target = sum(budget.get(n, 0) for n in _TARGET_BUCKETS)
    tt_ly = sum(ly_rev.get(n, 0) for n in _TARGET_BUCKETS)
    # Implied growth factor at the group level (rev target ÷ LY rev actual),
    # fall back to the +15% stretch convention when LY revenue is missing.
    growth = (tt_target / tt_ly) if tt_ly > 0 else 1.15

    # Buckets that differ slightly between the leadership summary sheet and the
    # seeded budget — surfaced (not "fixed") so leadership knows the page reads
    # the budget as the single source of truth.
    _SHEET_GAP = {"Kenya - Online", "Rwanda"}
    revenue = []
    for n in _TARGET_BUCKETS:
        tgt = round(budget.get(n, 0))
        act = round(cur_rev.get(n, 0))
        ly = round(ly_rev.get(n, 0))
        ly_td = round(ly_rev_td.get(n, 0))
        revenue.append({
            "bucket": n, "target": tgt, "actual": act, "ly": ly, "ly_to_date": ly_td,
            "pct": round(100.0 * act / tgt, 1) if tgt else 0.0,
            "yoy_pct": round(100.0 * (act - ly_td) / ly_td, 1) if ly_td else None,
            "sheet_gap": n in _SHEET_GAP,
        })
    tt_ly_td = sum(ly_rev_td.get(n, 0) for n in _TARGET_BUCKETS)
    rev_total = {
        "bucket": "Total", "target": round(tt_target),
        "actual": round(sum(cur_rev.get(n, 0) for n in _TARGET_BUCKETS)),
        "ly": round(tt_ly), "ly_to_date": round(tt_ly_td),
    }
    rev_total["pct"] = (round(100.0 * rev_total["actual"] / rev_total["target"], 1)
                        if rev_total["target"] else 0.0)
    rev_total["yoy_pct"] = (round(100.0 * (rev_total["actual"] - tt_ly_td) / tt_ly_td, 1)
                            if tt_ly_td else None)

    # ── Footfall / conversion / turn-in (group total) ──────────────────────
    # Mirrors get_footfall's day-level clean-conversion logic (excludes
    # sensor-gap days) but aggregated to a single company total.
    def footfall_metrics(a, b):
        rows = run_query("""
            WITH ff_daily AS (
                SELECT """ + ff_canon_sql() + """ AS loc, f.time::date AS d,
                    SUM(f.a01_footfall_in) AS ff, SUM(f.a05_outside_traffic) AS outside
                FROM footfall f
                WHERE f.time BETWEEN '""" + str(a) + """' AND '""" + str(b) + """'
                  AND """ + ff_store_master_predicate() + """
                GROUP BY 1, 2
            ),
            sales_daily AS (
                SELECT s.pos_location_name AS loc, s.sale_date::date AS d,
                    COUNT(DISTINCT CASE WHEN s.sale_kind IN ('sale','order') THEN s.order_id END) AS orders
                FROM all_sales s
                WHERE """ + _win(a, b) + """ AND """ + BASE_FILTERS + """
                GROUP BY 1, 2
            ),
            ff_locs AS (SELECT DISTINCT loc FROM ff_daily),
            joined AS (
                SELECT COALESCE(ff.loc, sd.loc) AS loc,
                    COALESCE(ff.ff, 0) AS ff, COALESCE(ff.outside, 0) AS outside,
                    COALESCE(sd.orders, 0) AS orders
                FROM ff_daily ff
                FULL OUTER JOIN sales_daily sd ON sd.loc = ff.loc AND sd.d = ff.d
                WHERE COALESCE(ff.loc, sd.loc) IN (SELECT loc FROM ff_locs)
            ),
            -- WS5/T503: a store whose window turn-in exceeds 100% has a broken
            -- pavement counter (partial-sample outside traffic). Exclude it from
            -- the GROUP turn-in numerator AND denominator (conversion unaffected).
            good_outside AS (
                SELECT loc FROM joined GROUP BY loc
                HAVING SUM(outside) > 0 AND SUM(ff) <= SUM(outside)
            )
            SELECT COALESCE(SUM(ff), 0) AS footfall,
                ROUND(SUM(ff) FILTER (WHERE loc IN (SELECT loc FROM good_outside)) * 100.0
                      / NULLIF(SUM(outside) FILTER (WHERE loc IN (SELECT loc FROM good_outside)), 0), 1) AS turn_in,
                ROUND(SUM(orders) FILTER (WHERE ff > 0) * 100.0 / NULLIF(SUM(ff), 0), 1) AS conversion
            FROM joined
        """, date_to=str(b))
        r = rows[0] if rows else {}
        return {
            "footfall": float(r.get("footfall") or 0),
            "turn_in": (float(r["turn_in"]) if r.get("turn_in") is not None else None),
            "conversion": (float(r["conversion"]) if r.get("conversion") is not None else None),
        }

    # Same clean-conversion/turn-in logic, but resolved PER MARKET (bucket) so a
    # store inherits its own market's LY rate — a company-wide rate would be
    # materially wrong for markets whose LY conversion/turn-in differ. Each
    # footfall location is mapped to the market of its dominant selling name.
    def footfall_metrics_by_bucket(a, b):
        rows = run_query("""
            WITH loc_bucket AS (
                SELECT DISTINCT ON (loc) loc, bucket FROM (
                    SELECT s.pos_location_name AS loc, """ + _ACTUAL_BUCKET_CASE + """ AS bucket,
                        COUNT(*) AS c
                    FROM all_sales s
                    WHERE """ + _win(a, b) + """ AND """ + BASE_FILTERS + """
                    GROUP BY 1, 2
                ) t ORDER BY loc, c DESC
            ),
            ff_daily AS (
                SELECT """ + ff_canon_sql() + """ AS loc, f.time::date AS d,
                    SUM(f.a01_footfall_in) AS ff, SUM(f.a05_outside_traffic) AS outside
                FROM footfall f
                WHERE f.time BETWEEN '""" + str(a) + """' AND '""" + str(b) + """'
                  AND """ + ff_store_master_predicate() + """
                GROUP BY 1, 2
            ),
            sales_daily AS (
                SELECT s.pos_location_name AS loc, s.sale_date::date AS d,
                    COUNT(DISTINCT CASE WHEN s.sale_kind IN ('sale','order') THEN s.order_id END) AS orders
                FROM all_sales s
                WHERE """ + _win(a, b) + """ AND """ + BASE_FILTERS + """
                GROUP BY 1, 2
            ),
            ff_locs AS (SELECT DISTINCT loc FROM ff_daily),
            joined AS (
                SELECT COALESCE(ff.loc, sd.loc) AS loc,
                    COALESCE(ff.ff, 0) AS ff, COALESCE(ff.outside, 0) AS outside,
                    COALESCE(sd.orders, 0) AS orders
                FROM ff_daily ff
                FULL OUTER JOIN sales_daily sd ON sd.loc = ff.loc AND sd.d = ff.d
                WHERE COALESCE(ff.loc, sd.loc) IN (SELECT loc FROM ff_locs)
            ),
            good_outside AS (
                SELECT loc FROM joined GROUP BY loc
                HAVING SUM(outside) > 0 AND SUM(ff) <= SUM(outside)
            )
            SELECT lb.bucket AS bucket,
                COALESCE(SUM(j.ff), 0) AS footfall,
                ROUND(SUM(j.ff) FILTER (WHERE j.loc IN (SELECT loc FROM good_outside)) * 100.0
                      / NULLIF(SUM(j.outside) FILTER (WHERE j.loc IN (SELECT loc FROM good_outside)), 0), 1) AS turn_in,
                ROUND(SUM(j.orders) FILTER (WHERE j.ff > 0) * 100.0 / NULLIF(SUM(j.ff), 0), 1) AS conversion
            FROM joined j LEFT JOIN loc_bucket lb ON lb.loc = j.loc
            WHERE lb.bucket IS NOT NULL
            GROUP BY 1
        """, date_to=str(b))
        out = {}
        for r in rows:
            out[r["bucket"]] = {
                "footfall": float(r.get("footfall") or 0),
                "turn_in": (float(r["turn_in"]) if r.get("turn_in") is not None else None),
                "conversion": (float(r["conversion"]) if r.get("conversion") is not None else None),
            }
        return out

    cur_ff = footfall_metrics(q_start, as_of) if started else {"footfall": 0, "turn_in": None, "conversion": None}
    ly_ff = footfall_metrics(ly_start, ly_end)
    ly_ff_td = footfall_metrics(ly_start, ly_asof) if started else {"footfall": 0, "turn_in": None, "conversion": None}
    ly_ff_bucket = footfall_metrics_by_bucket(ly_start, ly_end)

    # ── New / returning customers (group total) ────────────────────────────
    def cust_metrics(a, b):
        rows = run_query("WITH " + _unified_first_purchase_ctes() + """,
            seg AS (
                SELECT
                    COUNT(DISTINCT s.customer_id) FILTER (
                        WHERE fp.first_purchase_date BETWEEN '""" + str(a) + """'::date AND '""" + str(b) + """'::date) AS new_c,
                    COUNT(DISTINCT s.customer_id) FILTER (
                        WHERE fp.first_purchase_date < '""" + str(a) + """'::date) AS ret_c
                FROM all_sales s
                JOIN first_purchase fp ON fp.customer_id = s.customer_id
                WHERE """ + _win(a, b) + """
                  AND s.sale_kind = 'order'
                  AND LOWER(s.customer_type) IN ('new','returning','registered')
            )
            SELECT COALESCE(new_c, 0) AS new_c, COALESCE(ret_c, 0) AS ret_c FROM seg
        """)
        r = rows[0] if rows else {}
        return {"new": float(r.get("new_c") or 0), "ret": float(r.get("ret_c") or 0)}

    # Per-market new/returning so each store's count target is derived from its
    # OWN market's LY actual (× growth × the store's within-market share).
    def cust_metrics_by_bucket(a, b):
        rows = run_query("WITH " + _unified_first_purchase_ctes() + """,
            seg AS (
                SELECT """ + _ACTUAL_BUCKET_CASE + """ AS bucket,
                    COUNT(DISTINCT s.customer_id) FILTER (
                        WHERE fp.first_purchase_date BETWEEN '""" + str(a) + """'::date AND '""" + str(b) + """'::date) AS new_c,
                    COUNT(DISTINCT s.customer_id) FILTER (
                        WHERE fp.first_purchase_date < '""" + str(a) + """'::date) AS ret_c
                FROM all_sales s
                JOIN first_purchase fp ON fp.customer_id = s.customer_id
                WHERE """ + _win(a, b) + """
                  AND s.sale_kind = 'order'
                  AND LOWER(s.customer_type) IN ('new','returning','registered')
                GROUP BY 1
            )
            SELECT bucket, COALESCE(new_c, 0) AS new_c, COALESCE(ret_c, 0) AS ret_c FROM seg
        """)
        return {r["bucket"]: {"new": float(r.get("new_c") or 0), "ret": float(r.get("ret_c") or 0)}
                for r in rows}

    cur_cust = cust_metrics(q_start, as_of) if started else {"new": 0, "ret": 0}
    ly_cust = cust_metrics(ly_start, ly_end)
    ly_cust_td = cust_metrics(ly_start, ly_asof) if started else {"new": 0, "ret": 0}
    ly_cust_bucket = cust_metrics_by_bucket(ly_start, ly_end)

    # ── Made in Africa units (Vivo brand, group total) ─────────────────────
    def mia_units(a, b):
        rows = run_query(
            "SELECT COALESCE(SUM(CASE WHEN s.sale_kind IN ('sale','order') "
            "THEN s.ordered_item_quantity::numeric ELSE 0 END), 0) AS units "
            "FROM all_sales s JOIN all_products_clean p ON p.sku = s.variant_sku "
            "WHERE p.brand = 'Vivo' AND " + _win(a, b) + " AND " + BASE_FILTERS
        )
        return float(rows[0]["units"] or 0) if rows else 0.0

    # Per-market made-in-Africa units for the same market-share split.
    def mia_units_by_bucket(a, b):
        rows = run_query(
            "SELECT " + _ACTUAL_BUCKET_CASE + " AS bucket, "
            "COALESCE(SUM(CASE WHEN s.sale_kind IN ('sale','order') "
            "THEN s.ordered_item_quantity::numeric ELSE 0 END), 0) AS units "
            "FROM all_sales s JOIN all_products_clean p ON p.sku = s.variant_sku "
            "WHERE p.brand = 'Vivo' AND " + _win(a, b) + " AND " + BASE_FILTERS + " GROUP BY 1"
        )
        return {r["bucket"]: float(r["units"] or 0) for r in rows}

    cur_mia = mia_units(q_start, as_of) if started else 0.0
    ly_mia = mia_units(ly_start, ly_end)
    ly_mia_td = mia_units(ly_start, ly_asof) if started else 0.0
    ly_mia_bucket = mia_units_by_bucket(ly_start, ly_end)

    # ── Assemble derived metric scorecard ──────────────────────────────────
    def count_metric(key, label, cur, ly, ly_td, note=""):
        avail = ly > 0
        return {
            "key": key, "label": label, "kind": "count",
            "available": avail,
            "target": round(ly * growth) if avail else None,
            "actual": round(cur), "ly": round(ly), "ly_to_date": round(ly_td),
            "pct": (round(100.0 * cur / (ly * growth), 1) if avail and ly * growth else 0.0),
            "yoy_pct": (round(100.0 * (cur - ly_td) / ly_td, 1) if ly_td else None),
            "basis": "LY " + ("Q%d" % q) + " \u00d7 growth" if avail else "no historical actual",
            "note": note,
        }

    def rate_metric(key, label, cur, ly, ly_td, note=""):
        avail = ly is not None
        # Hold the LY rate, allow a small +5% relative uplift capped at +2.0pp.
        target = None
        if avail:
            target = round(ly + min(2.0, max(0.0, ly * 0.05)), 1)
        return {
            "key": key, "label": label, "kind": "rate",
            "available": avail,
            "target": target,
            "actual": (round(cur, 1) if cur is not None else None),
            "ly": (round(ly, 1) if ly is not None else None),
            "ly_to_date": (round(ly_td, 1) if ly_td is not None else None),
            "pct": (round(100.0 * cur / target, 1) if avail and target and cur is not None else None),
            "yoy_pct": (round(cur - ly_td, 1) if cur is not None and ly_td is not None else None),
            "basis": "LY " + ("Q%d" % q) + " rate + capped uplift" if avail else "no historical rate",
            "note": note,
        }

    def na_metric(key, label, note):
        return {"key": key, "label": label, "kind": "count", "available": False,
                "target": None, "actual": None, "ly": None, "ly_to_date": None,
                "pct": 0.0, "yoy_pct": None,
                "basis": "no reliable historical actual", "note": note}

    metrics = [
        rate_metric("conversion", "Conversion Rate", cur_ff["conversion"], ly_ff["conversion"], ly_ff_td["conversion"]),
        count_metric("footfall", "Footfall", cur_ff["footfall"], ly_ff["footfall"], ly_ff_td["footfall"]),
        count_metric("new_customers", "New Customers", cur_cust["new"], ly_cust["new"], ly_cust_td["new"]),
        count_metric("return_customers", "Return Customers", cur_cust["ret"], ly_cust["ret"], ly_cust_td["ret"]),
        rate_metric("turn_in", "Turn-In Rate", cur_ff["turn_in"], ly_ff["turn_in"], ly_ff_td["turn_in"]),
        count_metric("made_in_africa_qty", "Made in Africa Qty", cur_mia, ly_mia, ly_mia_td,
                     note="Units sold of Vivo-brand (made-in-Africa) product."),
        na_metric("qty_to_buy", "Qty to Buy",
                  "Forward-looking buying plan \u2014 no historical quarterly actual to derive a target from."),
        na_metric("qty_to_produce", "Qty to Produce",
                  "Production board only carries recent buying orders \u2014 no reliable last-year Q%d actual." % q),
    ]

    # ── Per-store breakdown ────────────────────────────────────────────────
    # Historical share = each store's trailing-12-month net revenue as a share
    # of its market (bucket) — so per-store revenue targets add back up to the
    # market total. Count-metric targets are split by the store's share of the
    # GROUP-wide trailing-12-month revenue. Rate targets apply at the company
    # level to each store. Warehouses / non-selling locations are excluded.
    hist_start = as_of - timedelta(days=365)
    _NOT_STORE = ("AND s.pos_location_name NOT ILIKE '%warehouse%' "
                  "AND s.pos_location_name NOT ILIKE '%stock location%'")
    store_hist = {}
    for r in run_query(
        "SELECT s.pos_location_name AS pos, " + _ACTUAL_BUCKET_CASE + " AS bucket, "
        "ROUND(" + _TARGET_REVENUE + ") AS net FROM all_sales s "
        "WHERE " + _win(hist_start, as_of) + " AND s.sale_kind IN ('sale','order','return') "
        "AND " + BASE_FILTERS + " " + _NOT_STORE + " GROUP BY 1, 2"
    ):
        net = float(r["net"] or 0)
        if net <= 0 or r["bucket"] not in _TARGET_BUCKETS:
            continue
        store_hist[r["pos"]] = {"bucket": r["bucket"], "hist": net}

    store_cur = {}
    if started:
        for r in run_query(
            "SELECT s.pos_location_name AS pos, ROUND(" + _TARGET_REVENUE + ") AS net "
            "FROM all_sales s WHERE " + _win(q_start, as_of) +
            " AND s.sale_kind IN ('sale','order','return') AND " + BASE_FILTERS +
            " " + _NOT_STORE + " GROUP BY 1"
        ):
            store_cur[r["pos"]] = float(r["net"] or 0)

    bucket_hist_total = {n: 0.0 for n in _TARGET_BUCKETS}
    group_hist_total = 0.0
    for v in store_hist.values():
        bucket_hist_total[v["bucket"]] += v["hist"]
        group_hist_total += v["hist"]

    conv_target = metrics[0]["target"]
    turn_target = metrics[4]["target"]

    # Per-market rate targets: hold each market's OWN LY rate + the same capped
    # uplift used for the group metric, falling back to the group target when a
    # market has no LY footfall history.
    def _rate_target(ly):
        if ly is None:
            return None
        return round(ly + min(2.0, max(0.0, ly * 0.05)), 1)

    # Per-market COUNT targets = that market's LY actual × the group growth
    # factor. A store then takes its within-market share of its OWN market's
    # target, so store goals are allocated inside the market (not across
    # markets) and the market totals reconcile to the group metric target.
    market_ff_target = {}
    market_new_target = {}
    market_ret_target = {}
    market_mia_target = {}
    market_conv_target = {}
    market_turn_target = {}
    for _b in _TARGET_BUCKETS:
        _mb = ly_ff_bucket.get(_b, {})
        market_ff_target[_b] = _mb.get("footfall", 0.0) * growth
        _mc = ly_cust_bucket.get(_b, {})
        market_new_target[_b] = _mc.get("new", 0.0) * growth
        market_ret_target[_b] = _mc.get("ret", 0.0) * growth
        market_mia_target[_b] = ly_mia_bucket.get(_b, 0.0) * growth
        _ct = _rate_target(_mb.get("conversion"))
        _tt = _rate_target(_mb.get("turn_in"))
        market_conv_target[_b] = _ct if _ct is not None else conv_target
        market_turn_target[_b] = _tt if _tt is not None else turn_target

    stores = []
    for pos, v in store_hist.items():
        b = v["bucket"]
        within = v["hist"] / bucket_hist_total[b] if bucket_hist_total[b] else 0.0
        rev_tgt = budget.get(b, 0) * within
        rev_act = store_cur.get(pos, 0.0)
        pace_expected = rev_tgt * frac
        stores.append({
            "store": pos, "market": b,
            "share_pct": round(100.0 * within, 2),
            "rev_target": round(rev_tgt),
            "rev_actual": round(rev_act),
            "pct": round(100.0 * rev_act / rev_tgt, 1) if rev_tgt else 0.0,
            "pace_expected": round(pace_expected),
            "required_run_rate": round(max(0.0, rev_tgt - rev_act) / days_left) if days_left else 0,
            "status": ("ahead" if rev_act >= pace_expected else "behind") if started else "not_started",
            "footfall_target": round(market_ff_target.get(b, 0.0) * within),
            "new_customers_target": round(market_new_target.get(b, 0.0) * within),
            "return_customers_target": round(market_ret_target.get(b, 0.0) * within),
            "made_in_africa_target": round(market_mia_target.get(b, 0.0) * within),
            "conversion_target": market_conv_target.get(b, conv_target),
            "turn_in_target": market_turn_target.get(b, turn_target),
        })
    stores.sort(key=lambda s: s["rev_target"], reverse=True)

    return {
        "quarter": "Q%d" % q, "year": yr,
        "quarter_start": q_start.isoformat(), "quarter_end": q_end.isoformat(),
        "as_of": as_of.isoformat(), "started": started,
        "days_total": days_total, "days_elapsed": days_elapsed, "days_left": days_left,
        "completion_pct": round(100.0 * days_elapsed / days_total, 1) if days_total else 0.0,
        "growth_factor": round(growth, 4),
        "revenue": revenue, "revenue_total": rev_total,
        "metrics": metrics, "stores": stores,
        "revenue_note": ("Revenue targets read directly from the seeded 2026 leadership "
                         "budget (single source of truth). Kenya-Online and Rwanda differ "
                         "slightly from the leadership summary sheet; the budget value is "
                         "shown as-is rather than overwritten."),
    }


# ── Target requirements — the "what it takes" reverse funnel ───────────────
# Works BACKWARDS from each market's annual revenue target so leadership can
# read, at a glance, the operational inputs a target implies:
#
#   revenue target ÷ average basket value (ABV)      → orders required
#   orders required ÷ conversion rate                → store visitors required
#   orders required ÷ orders-per-customer            → customers required
#
# The conversion rate ties orders to footfall (retail only — Online has no
# store traffic). Rates are this-year YTD run-rates, so the requirement
# reflects how the business ACTUALLY converts today rather than an arbitrary
# assumption. It also returns the STILL-needed remainder (target − achieved)
# and the per-day run-rate over the days left in the year, so the same card
# doubles as an actionable pace tool. Targets + achieved are sourced from
# /analytics/annual-targets so the funnel reconciles exactly with the tiles
# above it. Read-only; same auth as annual-targets (leadership page).
_TR_LABELS = {"Kenya - Retail": "Kenya", "Rwanda": "Rwanda",
              "Uganda": "Uganda", "Kenya - Online": "Online"}
_TR_ONLINE = {"Kenya - Online"}


@app.get("/api/analytics/target-requirements")
def analytics_target_requirements(year: int = Query(default=None)):
    yr = int(year) if year else date.today().year
    base = analytics_annual_targets(yr)
    today = date.today()
    y_end = date(yr, 12, 31)
    days_left = max(0, (y_end - today).days) if today <= y_end else 0
    y0 = str(date(yr, 1, 1))
    y1 = str(min(today, y_end))

    # Sales run-rate by bucket (YTD): net revenue, orders, and identified
    # orders/customers for ABV and orders-per-customer.
    sales = {}
    for r in run_query(
        "SELECT " + _ACTUAL_BUCKET_CASE + " AS bucket, "
        "ROUND(" + _TARGET_REVENUE + ") AS net, "
        "COUNT(DISTINCT CASE WHEN s.sale_kind IN ('sale','order') THEN s.order_id END) AS orders, "
        "COUNT(DISTINCT CASE WHEN s.sale_kind = 'order' AND LOWER(s.customer_type) "
        "  IN ('new','returning','registered') THEN s.order_id END) AS id_orders, "
        "COUNT(DISTINCT CASE WHEN s.sale_kind = 'order' AND LOWER(s.customer_type) "
        "  IN ('new','returning','registered') THEN s.customer_id END) AS customers "
        "FROM all_sales s WHERE s.sale_date BETWEEN '" + y0 + "' AND '" + y1 + "' "
        "AND s.sale_kind IN ('sale','order','return') AND " + BASE_FILTERS + " GROUP BY 1"
    ):
        sales[r["bucket"]] = {
            "net": float(r["net"] or 0), "orders": float(r["orders"] or 0),
            "id_orders": float(r["id_orders"] or 0), "customers": float(r["customers"] or 0),
        }

    # Footfall + clean conversion by bucket (YTD). Mirrors the quarter
    # scorecard's canonical footfall→sales join (ff_canon_sql + store master),
    # each footfall location mapped to the market of its dominant selling name.
    ff = {}
    for r in run_query("""
        WITH loc_bucket AS (
            SELECT DISTINCT ON (loc) loc, bucket FROM (
                SELECT s.pos_location_name AS loc, """ + _ACTUAL_BUCKET_CASE + """ AS bucket, COUNT(*) AS c
                FROM all_sales s
                WHERE s.sale_date BETWEEN '""" + y0 + """' AND '""" + y1 + """' AND """ + BASE_FILTERS + """
                GROUP BY 1, 2
            ) t ORDER BY loc, c DESC
        ),
        ff_daily AS (
            SELECT """ + ff_canon_sql() + """ AS loc, f.time::date AS d, SUM(f.a01_footfall_in) AS ff
            FROM footfall f
            WHERE f.time BETWEEN '""" + y0 + """' AND '""" + y1 + """'
              AND """ + ff_store_master_predicate() + """
            GROUP BY 1, 2
        ),
        sales_daily AS (
            SELECT s.pos_location_name AS loc, s.sale_date::date AS d,
                COUNT(DISTINCT CASE WHEN s.sale_kind IN ('sale','order') THEN s.order_id END) AS orders
            FROM all_sales s
            WHERE s.sale_date BETWEEN '""" + y0 + """' AND '""" + y1 + """' AND """ + BASE_FILTERS + """
            GROUP BY 1, 2
        ),
        ff_locs AS (SELECT DISTINCT loc FROM ff_daily),
        joined AS (
            SELECT COALESCE(ff.loc, sd.loc) AS loc,
                COALESCE(ff.ff, 0) AS ff, COALESCE(sd.orders, 0) AS orders
            FROM ff_daily ff
            FULL OUTER JOIN sales_daily sd ON sd.loc = ff.loc AND sd.d = ff.d
            WHERE COALESCE(ff.loc, sd.loc) IN (SELECT loc FROM ff_locs)
        )
        SELECT lb.bucket AS bucket,
            COALESCE(SUM(j.ff), 0) AS footfall,
            ROUND(SUM(j.orders) FILTER (WHERE j.ff > 0) * 100.0 / NULLIF(SUM(j.ff), 0), 2) AS conversion
        FROM joined j LEFT JOIN loc_bucket lb ON lb.loc = j.loc
        WHERE lb.bucket IS NOT NULL
        GROUP BY 1
    """, date_to=y1):
        ff[r["bucket"]] = {
            "footfall": float(r["footfall"] or 0),
            "conversion": (float(r["conversion"]) if r["conversion"] is not None else None),
        }

    def _funnel(name, target, achieved):
        s = sales.get(name, {})
        net, orders = s.get("net", 0.0), s.get("orders", 0.0)
        id_orders, customers = s.get("id_orders", 0.0), s.get("customers", 0.0)
        abv = (net / orders) if (orders > 0 and net > 0) else None
        opc = (id_orders / customers) if (customers > 0 and id_orders > 0) else None  # orders per customer
        conv = ff.get(name, {}).get("conversion")
        has_ff = (name not in _TR_ONLINE) and conv is not None and conv > 0
        remaining = max(0.0, target - achieved)

        def _req(rev):
            o = (rev / abv) if abv else None
            fo = (o / (conv / 100.0)) if (has_ff and o is not None) else None
            c = (o / opc) if (opc and o is not None) else None
            return o, fo, c

        o_t, f_t, c_t = _req(target)
        o_r, f_r, c_r = _req(remaining)
        _pd = lambda x: round(x / days_left) if (x is not None and days_left > 0) else None
        _rn = lambda x: round(x) if x is not None else None
        return {
            "bucket": name, "label": _TR_LABELS.get(name, name),
            "target": round(target), "achieved": round(achieved), "remaining": round(remaining),
            "pct_achieved": round(100.0 * achieved / target, 1) if target else 0.0,
            "abv": _rn(abv), "conversion": (round(conv, 1) if conv is not None else None),
            "orders_per_customer": (round(opc, 2) if opc else None),
            "has_footfall": has_ff,
            "orders_needed": _rn(o_t), "footfall_needed": _rn(f_t), "customers_needed": _rn(c_t),
            "orders_remaining": _rn(o_r), "footfall_remaining": _rn(f_r), "customers_remaining": _rn(c_r),
            "orders_per_day": _pd(o_r), "footfall_per_day": _pd(f_r), "customers_per_day": _pd(c_r),
        }

    buckets = [_funnel(b["bucket"], b.get("target_annual", 0), b.get("actual_ytd", 0))
               for b in base["buckets"]]

    def _sum(key):
        vals = [b[key] for b in buckets if b.get(key) is not None]
        return round(sum(vals)) if vals else None

    tt = base["total"]
    net_all = sum(v.get("net", 0.0) for v in sales.values())
    orders_all = sum(v.get("orders", 0.0) for v in sales.values())
    id_orders_all = sum(v.get("id_orders", 0.0) for v in sales.values())
    customers_all = sum(v.get("customers", 0.0) for v in sales.values())
    tt_target, tt_achieved = tt["target_annual"], tt["actual_ytd"]
    overall = {
        "bucket": "Overall", "label": "Overall",
        "target": round(tt_target), "achieved": round(tt_achieved),
        "remaining": round(max(0.0, tt_target - tt_achieved)),
        "pct_achieved": round(100.0 * tt_achieved / tt_target, 1) if tt_target else 0.0,
        "abv": round(net_all / orders_all) if orders_all else None,
        "conversion": None,  # a single blended rate would mislead across markets
        "orders_per_customer": round(id_orders_all / customers_all, 2) if customers_all else None,
        "has_footfall": True,
        "orders_needed": _sum("orders_needed"), "footfall_needed": _sum("footfall_needed"),
        "customers_needed": _sum("customers_needed"),
        "orders_remaining": _sum("orders_remaining"), "footfall_remaining": _sum("footfall_remaining"),
        "customers_remaining": _sum("customers_remaining"),
        "orders_per_day": _sum("orders_per_day"), "footfall_per_day": _sum("footfall_per_day"),
        "customers_per_day": _sum("customers_per_day"),
    }
    return {
        "year": yr, "as_of": y1, "days_left": days_left,
        "buckets": buckets, "overall": overall,
        "rate_basis": "This-year YTD run-rate (average basket, conversion, orders per customer).",
    }


@app.get("/api/analytics/target-store-breakdown")
def analytics_target_store_breakdown(year: int = Query(default=None),
                                     bucket: str = Query(default=None)):
    """Per-POS-location drill-down for a market target tile.

    Targets are set at MARKET level only (no official per-store budget). To
    answer "how is each store doing vs target", we split the market's annual
    target across its stores by each store's SHARE OF LAST YEAR'S sales over
    the same Jan-1→today window (an independent basis — allocating by THIS
    year's share would make every store read as exactly on the market pace).
    The resulting per-store target is clearly labelled "implied".

    Returns, per store: this-year achieved, the implied target + pace-expected,
    ahead/behind %, projected landing, remaining KES + per-day, orders still to
    ring up (remaining ÷ the store's own average basket), and YoY vs last year.
    `bucket` (a _TARGET_BUCKETS name) scopes to one market; omit / "Overall"
    for every budgeted market.
    """
    yr = int(year) if year else date.today().year
    base = analytics_annual_targets(yr)
    today = date.today()
    y_start, y_end = date(yr, 1, 1), date(yr, 12, 31)
    total = (y_end - y_start).days + 1
    elapsed = 0 if today < y_start else min((today - y_start).days + 1, total)
    days_left = max(0, total - elapsed)
    cy0, cy1 = str(y_start), str(min(today, y_end))
    # Prior-year same window: Jan 1 → same month/day (clamp Feb 29 → Feb 28).
    py = yr - 1
    try:
        py1d = date(py, today.month, today.day)
    except ValueError:
        py1d = date(py, today.month, today.day - 1)
    py0, py1 = str(date(py, 1, 1)), str(py1d)

    if bucket and bucket not in ("Overall", "") and bucket not in _TARGET_BUCKETS:
        raise HTTPException(status_code=400,
                            detail=f"invalid bucket '{bucket}'; expected 'Overall' or one of {list(_TARGET_BUCKETS)}")
    wanted = ([bucket] if (bucket and bucket not in ("Overall", ""))
              else list(_TARGET_BUCKETS))
    tmap = {b["bucket"]: b for b in base["buckets"]}
    market_target = sum(float(tmap.get(bn, {}).get("target_annual", 0) or 0) for bn in wanted)
    market_achieved = sum(float(tmap.get(bn, {}).get("actual_ytd", 0) or 0) for bn in wanted)
    market_label = (_TR_LABELS.get(bucket, bucket) if bucket and bucket not in ("Overall", "")
                    else "Overall")

    def _stores(d0, d1):
        # Keyed by (bucket, store) — NOT store name alone. In "Overall" mode
        # (all 4 buckets) a store name could recur across markets; keying by
        # name only would let the last row overwrite the earlier one and
        # corrupt the prior-share basis + per-store math.
        out = {}
        for r in run_query(
            "SELECT s.pos_location_name AS store, " + _ACTUAL_BUCKET_CASE + " AS bucket, "
            "ROUND(" + _TARGET_REVENUE + ") AS net, "
            "COUNT(DISTINCT CASE WHEN s.sale_kind IN ('sale','order') THEN s.order_id END) AS orders "
            "FROM all_sales s WHERE s.sale_date BETWEEN '" + d0 + "' AND '" + d1 + "' "
            "AND s.sale_kind IN ('sale','order','return') AND " + BASE_FILTERS + " "
            "GROUP BY 1, 2", date_to=d1,
        ):
            if r["bucket"] not in wanted:
                continue
            key = (r["bucket"], r["store"] or "(unknown)")
            out[key] = {"net": float(r["net"] or 0), "orders": float(r["orders"] or 0)}
        return out

    cur = _stores(cy0, cy1)
    pri = _stores(py0, py1)

    # Prior-year basis for the pro-rata split. Only positive prior nets count.
    prior_total = sum(v["net"] for v in pri.values() if v["net"] > 0)
    keys = sorted(set(cur) | set(pri))
    pace_frac = (elapsed / total) if total else 0

    rows = []
    for key in keys:
        bkt, name = key
        c = cur.get(key, {})
        p = pri.get(key, {})
        achieved = float(c.get("net", 0.0))
        c_orders = float(c.get("orders", 0.0))
        prior_net = float(p.get("net", 0.0))
        share = (prior_net / prior_total) if (prior_total > 0 and prior_net > 0) else None
        # New store (no positive prior sales) → no implied target basis.
        implied = (market_target * share) if share is not None else None
        pace_expected = (implied * pace_frac) if implied is not None else None
        delta_pct = (round((achieved / pace_expected - 1) * 100, 1)
                     if (pace_expected and pace_expected > 0) else None)
        projected = round(achieved / elapsed * total) if elapsed > 0 else 0
        remaining = max(0.0, implied - achieved) if implied is not None else None
        abv = (achieved / c_orders) if (c_orders > 0 and achieved > 0) else None
        orders_to_go = round(remaining / abv) if (remaining is not None and abv) else None
        per_day = round(remaining / days_left) if (remaining is not None and days_left > 0) else None
        yoy_pct = (round((achieved - prior_net) / prior_net * 100, 1)
                   if prior_net > 0 else None)
        pct_of_target = (round(100.0 * achieved / implied, 1)
                         if (implied and implied > 0) else None)
        rows.append({
            "store": name,
            "market": _TR_LABELS.get(bkt, bkt),
            "achieved": round(achieved),
            "prior": round(prior_net),
            "implied_target": (round(implied) if implied is not None else None),
            "pace_expected": (round(pace_expected) if pace_expected is not None else None),
            "delta_pct": delta_pct,
            "projected": projected,
            "remaining": (round(remaining) if remaining is not None else None),
            "orders_to_go": orders_to_go,
            "per_day": per_day,
            "abv": (round(abv) if abv is not None else None),
            "yoy_pct": yoy_pct,
            "pct_of_target": pct_of_target,
            "is_new": share is None,
        })
    # Biggest contributors first.
    rows.sort(key=lambda r: r["achieved"], reverse=True)

    return {
        "year": yr, "as_of": cy1, "days_left": days_left,
        "elapsed": elapsed, "total": total,
        "bucket": (bucket if bucket and bucket not in ("Overall", "") else "Overall"),
        "label": market_label,
        "market_target": round(market_target),
        "market_achieved": round(market_achieved),
        "market_remaining": round(max(0.0, market_target - market_achieved)),
        "store_count": len(rows),
        "basis": ("Store targets are IMPLIED — the market target split by each store's share of "
                  "last year's sales over the same period. Not official per-store budgets."),
        "stores": rows,
    }


@app.get("/api/analytics/monthly-targets")
def analytics_monthly_targets(month: str = Query(default=None)):
    # Per-STORE daily target tracker (pos_location_name). The monthly target
    # is the typed leadership number (targets_monthly, scope='store', manual
    # preferred over budget); when none is stored for a store we fall back to
    # prior-year same-month actual + a 15% stretch so the tracker still works.
    # The "Suggested Daily Need" on remaining days is the gap re-weighted by
    # the store's trailing-6-month day-of-week sales pattern (not flat), and
    # suggested quantity / basket size derive from the store's ASP + orders pace.
    try:
        mstart = (date.fromisoformat(month[:10]).replace(day=1) if month
                  else date.today().replace(day=1))
    except ValueError:
        raise HTTPException(status_code=400, detail="invalid month (expected YYYY-MM-DD)")
    nstart = (date(mstart.year + 1, 1, 1) if mstart.month == 12
              else date(mstart.year, mstart.month + 1, 1))
    mend = nstart - timedelta(days=1)
    days_in_month = mend.day
    today = date.today()
    growth = 1.15
    py_start = mstart.replace(year=mstart.year - 1)
    py_end = mend.replace(year=mend.year - 1)
    pat_start = mstart - timedelta(days=183)

    def _pgdow(d):  # Python weekday() (Mon=0) -> Postgres DOW (Sun=0..Sat=6)
        return (d.weekday() + 1) % 7

    # Stored per-store targets for the month (manual wins over budget).
    target_map = {}
    for r in run_query(
        "SELECT name, source, target_kes::numeric AS t FROM targets_monthly "
        "WHERE scope = 'store' AND month = '" + str(mstart) + "'"
    ):
        nm, src, t = r["name"], r["source"], float(r["t"] or 0)
        cur = target_map.get(nm)
        if cur is None or (cur[1] != "manual" and src == "manual"):
            target_map[nm] = (t, src)

    # Prior-year same-month per-store actuals (fallback target basis). Canonical
    # revenue basis (total_sales_kes net of returns), matching the headline KPIs.
    py_map = {r["store"]: float(r["net"] or 0) for r in run_query("""
        SELECT s.pos_location_name AS store,
            ROUND(""" + _TARGET_REVENUE + """) AS net
        FROM all_sales s
        WHERE s.sale_date BETWEEN '""" + str(py_start) + """' AND '""" + str(py_end) + """'
          AND s.sale_kind IN ('sale','order','return') AND """ + BASE_FILTERS + """
        GROUP BY 1
    """)}

    # This-month per-store daily actuals. "net" is canonical revenue
    # (total_sales_kes net of returns); units/orders stay sale/order-only.
    dmap = {}
    for r in run_query("""
        SELECT s.pos_location_name AS store, s.sale_date::date AS d,
            ROUND(""" + _TARGET_REVENUE + """) AS net,
            SUM(CASE WHEN s.sale_kind IN ('sale','order') THEN s.net_quantity ELSE 0 END) AS units,
            COUNT(DISTINCT CASE WHEN s.sale_kind IN ('sale','order') THEN s.order_id END) AS orders
        FROM all_sales s
        WHERE s.sale_date BETWEEN '""" + str(mstart) + """' AND '""" + str(mend) + """'
          AND s.sale_kind IN ('sale','order','return') AND """ + BASE_FILTERS + """
        GROUP BY 1, 2
    """):
        dmap.setdefault(r["store"], {})[str(r["d"])] = {
            "net": float(r["net"] or 0), "units": float(r["units"] or 0), "orders": float(r["orders"] or 0)}

    # Trailing-6-month per-store day-of-week pattern → average net + orders per
    # weekday (for suggested-need weighting + basket pace) and a stable ASP.
    pat_net, pat_ord, asp_acc = {}, {}, {}
    for r in run_query("""
        SELECT s.pos_location_name AS store,
            EXTRACT(DOW FROM s.sale_date::date)::int AS dow,
            SUM(CASE WHEN s.sale_kind IN ('sale','order') THEN s.net_sales_kes::numeric ELSE 0 END) AS net,
            SUM(CASE WHEN s.sale_kind IN ('sale','order') THEN s.net_quantity ELSE 0 END) AS units,
            COUNT(DISTINCT s.order_id) AS orders,
            COUNT(DISTINCT s.sale_date::date) AS ndays
        FROM all_sales s
        WHERE s.sale_date >= '""" + str(pat_start) + """' AND s.sale_date < '""" + str(mstart) + """'
          AND s.sale_kind IN ('sale','order') AND """ + BASE_FILTERS + """
        GROUP BY 1, 2
    """):
        st, dow, nd = r["store"], int(r["dow"]), float(r["ndays"] or 0)
        net, units, orders = float(r["net"] or 0), float(r["units"] or 0), float(r["orders"] or 0)
        if nd > 0:
            pat_net.setdefault(st, {})[dow] = net / nd
            pat_ord.setdefault(st, {})[dow] = orders / nd
        a = asp_acc.setdefault(st, [0.0, 0.0]); a[0] += net; a[1] += units

    if mstart.year == today.year and mstart.month == today.month:
        days_complete = today.day
    elif today < mstart:
        days_complete = 0
    else:
        days_complete = days_in_month
    days_remaining = days_in_month - days_complete

    # Store universe: every store with a stored target, plus every store with
    # actuals this month (so no live store's sales are hidden).
    store_names = set(target_map.keys()) | set(dmap.keys())
    stores = []
    for st in store_names:
        if st in target_map:
            sales_target, tgt_source = round(target_map[st][0]), target_map[st][1]
        else:
            sales_target, tgt_source = round(py_map.get(st, 0) * growth), "derived"
        daily_target = sales_target / days_in_month if days_in_month else 0
        ch_daily = dmap.get(st, {})

        # Month-to-date actuals.
        mtd_actual = mtd_units = mtd_orders = 0.0
        for dd in range(1, days_complete + 1):
            a = ch_daily.get(str(date(mstart.year, mstart.month, dd)))
            if a:
                mtd_actual += a["net"]; mtd_units += a["units"]; mtd_orders += a["orders"]
        gap = sales_target - round(mtd_actual)
        gap_pos = max(0, gap)

        # Stable per-store ASP (6-month) for suggested quantity; MTD fallback.
        a = asp_acc.get(st, [0.0, 0.0])
        store_asp = (a[0] / a[1]) if a[1] else (mtd_actual / mtd_units if mtd_units else 0)

        # Future-day weights from the DOW net-sales pattern.
        future_days = [date(mstart.year, mstart.month, dd) for dd in range(1, days_in_month + 1)
                       if date(mstart.year, mstart.month, dd) > today]
        wsum = sum(pat_net.get(st, {}).get(_pgdow(d), 0.0) for d in future_days)

        days, cum_var = [], 0.0
        for dd in range(1, days_in_month + 1):
            day = date(mstart.year, mstart.month, dd)
            a = ch_daily.get(str(day))
            actual = a["net"] if a else 0.0
            is_future = day > today
            dt = round(daily_target)
            ksh_var = round(actual - dt)
            cum_var += ksh_var
            row = {
                "date": str(day), "day_of_week": day.strftime("%a"),
                "ratio": round(100.0 / days_in_month, 1),
                "daily_target": dt,
                "suggested_daily_target": None,
                "suggested_daily_quantity": None,
                "suggested_basket_size": None,
                "actual": round(actual),
                "variance_pct": round(100.0 * (actual - dt) / dt, 1) if dt else 0.0,
                "ksh_variance": ksh_var, "ksh_variance_cumulative": round(cum_var),
                "is_future": is_future, "is_today": day == today,
            }
            if is_future:
                dow = _pgdow(day)
                w = pat_net.get(st, {}).get(dow, 0.0)
                if gap_pos <= 0:
                    sdt = 0
                elif wsum > 0:
                    sdt = gap_pos * (w / wsum)
                elif future_days:
                    sdt = gap_pos / len(future_days)
                else:
                    sdt = 0
                sdt = max(0, round(sdt))
                row["suggested_daily_target"] = sdt
                row["suggested_daily_quantity"] = round(sdt / store_asp) if store_asp > 0 else None
                opace = pat_ord.get(st, {}).get(dow, 0.0)
                row["suggested_basket_size"] = round(sdt / opace) if opace > 0 else None
            days.append(row)

        mtd_target = round(daily_target * days_complete)
        projected = round(mtd_actual / days_complete * days_in_month) if days_complete else 0
        stores.append({
            "channel": st, "sales_target": sales_target, "mtd_actual": round(mtd_actual),
            "mtd_target": mtd_target, "projected_landing": projected,
            "pct_of_target_projected": round(100.0 * projected / sales_target, 1) if sales_target else 0.0,
            "ksh_variance_total": round(mtd_actual) - mtd_target,
            "days_complete": days_complete, "days_in_month": days_in_month,
            "days_remaining": days_remaining,
            "avg_suggested_remaining": round(gap / days_remaining) if days_remaining > 0 else 0,
            "gap_to_target": gap,
            "asp": round(mtd_actual / mtd_units) if mtd_units else round(store_asp),
            "basket_kes": round(mtd_actual / mtd_orders) if mtd_orders else 0,
            "target_source": tgt_source,
            "daily": days,
        })
    stores.sort(key=lambda x: x["sales_target"], reverse=True)
    return {"month": str(mstart), "stores": stores}

# ── Executive Summary ─────────────────────────────────────────────────────────
# One heavy composite endpoint that powers ExecutiveSummary.jsx. It assembles
# YTD + MTD scorecards (each metric current vs same-period-last-year), a
# per-country breakdown, store performance, category/subcategory deltas,
# yearly-target pacing, and a stock-mix table — all internally consistent because
# every block is aggregated off the same BASE_FILTERS sales base via the existing
# helper functions (get_kpis / get_customers / _country_summary_q /
# get_sales_summary / get_subcategory_sales). Targets reuse the prior-year-actual
# + 15% stretch convention from /analytics/{annual,monthly}-targets.

_ES_KPI_KEYS = ["revenue", "avg_sales_per_day", "units", "footfall",
                "avg_basket", "asp", "total_customers", "new_customers",
                "returning_customers"]

def _es_pct(cur, ly):
    # Percent delta cur-vs-ly. None when ly is missing/zero so the frontend
    # DeltaPill renders an em-dash instead of a misleading 0 / infinity.
    if cur is None or ly is None:
        return None
    cur = float(cur); ly = float(ly)
    if ly == 0:
        return None
    return (cur - ly) / ly * 100.0

def _es_cmp(cur, ly):
    return {"cur": float(cur or 0), "ly": float(ly or 0), "delta_pct": _es_pct(cur, ly)}

def _es_shift_year(d, years):
    # d with year reduced by `years`, guarding the Feb-29 -> Feb-28 edge.
    try:
        return d.replace(year=d.year - years)
    except ValueError:
        return d.replace(year=d.year - years, day=28)

def _es_footfall_by_country(date_from, date_to):
    rows = run_query("""
        SELECT COALESCE(pl.country, 'Other') AS country,
            SUM(f.a01_footfall_in) AS footfall
        FROM footfall f
        LEFT JOIN pos_locations pl ON """ + ff_canon_sql() + """ = pl.location_name
        WHERE f.time BETWEEN \'""" + date_from + """\' AND \'""" + date_to + """\'
        GROUP BY COALESCE(pl.country, 'Other')
    """, date_to=date_to)
    ff_map = {r["country"]: float(r["footfall"] or 0) for r in rows}
    total_row = run_query("""
        SELECT SUM(a01_footfall_in) AS total
        FROM footfall
        WHERE time BETWEEN \'""" + date_from + """\' AND \'""" + date_to + """\'
    """, date_to=date_to)
    ff_map["__total__"] = float((total_row[0]["total"] if total_row else 0) or 0)
    return ff_map


def _es_footfall_total(ff_map, country):
    if country:
        wanted = {c.strip().lower() for c in country.split(",")}
        return sum(v for kc, v in ff_map.items()
                   if kc != "__total__" and kc.lower() in wanted)
    return ff_map.get("__total__", sum(v for k, v in ff_map.items() if k != "__total__"))


def _es_customer_windows(span_from, span_to, windows, country):
    # total / new / returning customer counts for several windows in ONE pass.
    # Mirrors get_customers exactly (validated): first_ever_purchase is GLOBAL
    # (no base/country filter), period membership applies BASE_FILTERS + country.
    # new = customer whose first-EVER purchase falls in the window; returning =
    # customer whose first purchase predates it. EVERY identified customer with
    # an order in the window is exactly one of the two (first_ever is always
    # <= the window end), so new + returning = total. Do NOT re-introduce an
    # order-count (oc = 1) restriction on new/returning: that was an old bug
    # that dropped multi-order customers from both buckets, leaving total
    # un-reconciled (audit F08 — New + Returning silently fell short of Total).
    country_filter = ("AND s.country IN (" + csv_to_sql(country) + ")") if country else ""
    pc_cols, sel = [], []
    for k, (a, b) in windows.items():
        pc_cols.append("COUNT(DISTINCT s.order_id) FILTER (WHERE s.sale_date BETWEEN '"
                       + a + "' AND '" + b + "') AS oc_" + k)
        sel.append("COUNT(*) FILTER (WHERE oc_" + k + " > 0) AS total_" + k)
        sel.append("COUNT(*) FILTER (WHERE oc_" + k + " > 0 AND a.first_ever BETWEEN '"
                   + a + "' AND '" + b + "') AS new_" + k)
        sel.append("COUNT(*) FILTER (WHERE oc_" + k + " > 0 AND a.first_ever < '"
                   + a + "') AS ret_" + k)
    # First-ever purchase per customer: serve from the hourly-refreshed
    # rollup_customer_first_purchase when fresh (a 173k-row PK read) instead of
    # full-scanning all_sales (~1.5M rows, was 17-18s cold — the single biggest
    # exec-summary cost). Boundary semantics are identical: sale_date is TEXT but
    # uniformly 'YYYY-MM-DD' (verified min/max length 10), and the rollup's DATE
    # column compares against the same quoted literals with the same ordering.
    # The rollup is built from _unified_first_purchase_ctes (Kenya id bridge),
    # matching the get_customers canon. Fall back to the live scan when stale.
    #
    # IMPORTANT: the stale fallback MUST use _unified_first_purchase_ctes too —
    # not a raw MIN(sale_date). The bridge collapses post-2026-03-20 Odoo IDs
    # onto their legacy Shopify IDs, so a returning Kenya shopper appearing under
    # a new Odoo ID after the cutover is not mislabelled "New". The old MIN()
    # fallback lacked the bridge and diverged from the rollup's classification.
    if _rollup_fresh("customer_first_purchase"):
        prefix_ctes = ""
        at_cte = """at AS (
            SELECT customer_id, first_purchase_date AS first_ever
            FROM rollup_customer_first_purchase
        )"""
    else:
        prefix_ctes = _unified_first_purchase_ctes() + ","
        at_cte = """at AS (
            SELECT customer_id, first_purchase_date AS first_ever
            FROM first_purchase
        )"""
    # Exclude walk-in / pseudo-accounts so exec-summary customer counts match
    # the Customers page universe (_not_walkin_pseudo_sql mirrors the same gate
    # applied in get_customers). Without this, pseudo-accounts with a customer_id
    # inflated exec-summary totals vs the Customers page for the same period.
    pseudo_excl = "AND " + _not_walkin_pseudo_sql("s")
    rows = run_query("""
        WITH """ + prefix_ctes + at_cte + """,
        pc AS (
            SELECT s.customer_id, """ + ",\n".join(pc_cols) + """
            FROM all_sales s
            WHERE s.sale_kind IN ('sale','order') AND s.customer_id IS NOT NULL
              AND s.customer_id NOT IN ('None','null','')
              AND s.sale_date BETWEEN '""" + span_from + """' AND '""" + span_to + """'
              AND """ + BASE_FILTERS + " " + country_filter + " " + pseudo_excl + """
            GROUP BY s.customer_id
        )
        SELECT """ + ",\n".join(sel) + """
        FROM pc JOIN at a ON pc.customer_id = a.customer_id
    """, date_to=span_to)
    r = rows[0] if rows else {}
    return {k: {"total": float(r.get("total_" + k) or 0),
                "new": float(r.get("new_" + k) or 0),
                "returning": float(r.get("ret_" + k) or 0)} for k in windows}

def _es_customer_by_country(span_from, span_to, windows, country):
    # Same logic as _es_customer_windows but grouped by s.country so
    # each country card can show Total / New / Returning customers with a
    # vs-LY delta. A customer who bought in two countries in the same
    # period appears in both — that's correct for "who shopped in Kenya".
    country_filter = ("AND s.country IN (" + csv_to_sql(country) + ")") if country else ""
    pc_cols, sel = [], []
    for k, (a, b) in windows.items():
        pc_cols.append("COUNT(DISTINCT s.order_id) FILTER (WHERE s.sale_date BETWEEN '"
                       + a + "' AND '" + b + "') AS oc_" + k)
        sel.append("COUNT(*) FILTER (WHERE oc_" + k + " > 0) AS total_" + k)
        sel.append("COUNT(*) FILTER (WHERE oc_" + k + " > 0 AND a.first_ever BETWEEN '"
                   + a + "' AND '" + b + "') AS new_" + k)
        sel.append("COUNT(*) FILTER (WHERE oc_" + k + " > 0 AND a.first_ever < '"
                   + a + "') AS ret_" + k)
    if _rollup_fresh("customer_first_purchase"):
        prefix_ctes = ""
        at_cte = """at AS (
            SELECT customer_id, first_purchase_date AS first_ever
            FROM rollup_customer_first_purchase
        )"""
    else:
        prefix_ctes = _unified_first_purchase_ctes() + ","
        at_cte = """at AS (
            SELECT customer_id, first_purchase_date AS first_ever
            FROM first_purchase
        )"""
    pseudo_excl = "AND " + _not_walkin_pseudo_sql("s")
    rows = run_query("""
        WITH """ + prefix_ctes + at_cte + """,
        pc AS (
            SELECT s.customer_id, s.country, """ + ",\n".join(pc_cols) + """
            FROM all_sales s
            WHERE s.sale_kind IN ('sale','order') AND s.customer_id IS NOT NULL
              AND s.customer_id NOT IN ('None','null','')
              AND s.sale_date BETWEEN '""" + span_from + """' AND '""" + span_to + """'
              AND """ + BASE_FILTERS + " " + country_filter + " " + pseudo_excl + """
            GROUP BY s.customer_id, s.country
        )
        SELECT pc.country, """ + ",\n".join(sel) + """
        FROM pc JOIN at a ON pc.customer_id = a.customer_id
        GROUP BY pc.country
    """, date_to=span_to)
    result = {}
    for r in rows:
        c = r.get("country") or "Unknown"
        result[c] = {k: {"total": float(r.get("total_" + k) or 0),
                         "new":   float(r.get("new_"   + k) or 0),
                         "returning": float(r.get("ret_" + k) or 0)}
                     for k in windows}
    return result

def _es_kpi_block(frm, to, country, days, footfall, cust):
    # Raw headline scalars for one window. revenue/units/basket/ASP come from
    # get_kpis; footfall + customer counts are precomputed and passed in.
    k = get_kpis(frm, to, country, None) or {}
    revenue = float(k.get("total_sales") or 0)
    return {
        "revenue": revenue,
        "avg_sales_per_day": revenue / days if days else 0.0,
        "units": float(k.get("total_units") or 0),
        "footfall": footfall,
        "avg_basket": float(k.get("avg_basket_size") or 0),
        "asp": float(k.get("avg_selling_price") or 0),
        "total_customers": cust.get("total", 0.0),
        "new_customers": cust.get("new", 0.0),
        "returning_customers": cust.get("returning", 0.0),
    }

def _es_kpis(cur_blk, ly_blk):
    return {key: _es_cmp(cur_blk[key], ly_blk[key]) for key in _ES_KPI_KEYS}

def _es_countries(cur_from, cur_to, ly_from, ly_to, country, days_cur, days_ly, ff_cur, ff_ly,
                  cust_cur=None, cust_ly=None):
    cur = {r["country"]: r for r in _country_summary_q(cur_from, cur_to, country)}
    ly = {r["country"]: r for r in _country_summary_q(ly_from, ly_to, country)}
    names = [c for c in ["Kenya", "Uganda", "Rwanda", "Online"] if c in cur or c in ly]
    for c in list(cur.keys()) + list(ly.keys()):
        if c and c not in names:
            names.append(c)
    out = []
    for c in names:
        rc = cur.get(c, {}); rl = ly.get(c, {})
        rev_c = float(rc.get("total_sales") or 0); rev_l = float(rl.get("total_sales") or 0)
        u_c = float(rc.get("units_sold") or 0); u_l = float(rl.get("units_sold") or 0)
        o_c = float(rc.get("orders") or 0); o_l = float(rl.get("orders") or 0)
        ff_c = float(ff_cur.get(c, 0)); ff_l = float(ff_ly.get(c, 0))
        apd = _es_cmp(rev_c / days_cur if days_cur else 0, rev_l / days_ly if days_ly else 0)
        apd["days"] = days_cur
        cc = (cust_cur or {}).get(c, {})
        cl = (cust_ly or {}).get(c, {})
        out.append({
            "country": c,
            "revenue": _es_cmp(rev_c, rev_l),
            "avg_sales_per_day": apd,
            "units": _es_cmp(u_c, u_l),
            "orders": _es_cmp(o_c, o_l),
            "footfall": _es_cmp(ff_c, ff_l),
            "avg_basket": _es_cmp(rev_c / o_c if o_c else 0, rev_l / o_l if o_l else 0),
            "asp": _es_cmp(rev_c / u_c if u_c else 0, rev_l / u_l if u_l else 0),
            "customers":          _es_cmp(cc.get("total", 0),     cl.get("total", 0)),
            "new_customers":      _es_cmp(cc.get("new", 0),       cl.get("new", 0)),
            "returning_customers":_es_cmp(cc.get("returning", 0), cl.get("returning", 0)),
        })
    return out

def _es_store_targets(ytd_ly_from, ytd_ly_to, year_ly):
    # Per-channel targets via the prior-year-actual + 15% stretch convention:
    # target_ytd = prior-year same YTD period; target_annual = prior full year.
    # Revenue basis MUST match get_sales_summary (total − discounts − returns,
    # VAT-inclusive) so that actuals and targets use the same denominator and
    # the attainment % is meaningful. The old net_sales_kes column is ex-VAT
    # (reads ~15% lower) and made store-level attainment look systematically
    # inflated when actuals came from get_sales_summary's canonical formula.
    growth = 1.15
    ytd_rows = run_query("""
        SELECT s.pos_location_name AS channel,
            ROUND(""" + _TARGET_REVENUE + """) AS net
        FROM all_sales s
        WHERE s.sale_date BETWEEN '""" + ytd_ly_from + """' AND '""" + ytd_ly_to + """'
          AND s.sale_kind IN ('sale','order','return') AND """ + BASE_FILTERS + """
        GROUP BY s.pos_location_name
    """, date_to=ytd_ly_to)
    ann_rows = run_query("""
        SELECT s.pos_location_name AS channel,
            ROUND(""" + _TARGET_REVENUE + """) AS net
        FROM all_sales s
        WHERE s.sale_date BETWEEN '""" + str(year_ly) + """-01-01' AND '""" + str(year_ly) + """-12-31'
          AND s.sale_kind IN ('sale','order','return') AND """ + BASE_FILTERS + """
        GROUP BY s.pos_location_name
    """)
    out = {}
    for r in ytd_rows:
        out.setdefault(r["channel"], {})["ytd"] = round(float(r["net"] or 0) * growth)
    for r in ann_rows:
        out.setdefault(r["channel"], {})["annual"] = round(float(r["net"] or 0) * growth)
    return out

def _es_stores(cur_from, cur_to, ly_from, ly_to, country, store_targets):
    # Physical stores only — drop Online / Staff channels (the StorePerformance
    # table is store-level). cur/ly are window revenue; targets are fixed YTD.
    cur = get_sales_summary(cur_from, cur_to, country, None)
    ly = {r["channel"]: r for r in get_sales_summary(ly_from, ly_to, country, None)}
    out = []
    for r in cur:
        ch = r.get("channel") or ""
        co = r.get("country") or ""
        low = ch.lower()
        if "online" in low or "staff" in low or co == "Online":
            continue
        l = ly.get(ch, {})
        cur_v = float(r.get("total_sales") or 0)
        ly_v = float(l.get("total_sales") or 0)
        tgt = store_targets.get(ch, {})
        out.append({
            "channel": ch, "country": co,
            "cur": cur_v, "ly": ly_v, "delta_pct": _es_pct(cur_v, ly_v),
            "target_annual": tgt.get("annual", 0), "target_ytd": tgt.get("ytd", 0),
        })
    out.sort(key=lambda x: x["cur"], reverse=True)
    return out

def _es_categories(cur_from, cur_to, ly_from, ly_to, country):
    # Per-subcategory revenue + units, current vs LY. The frontend rolls these
    # up to high-level categories via productCategory.js.
    cur = {r["subcategory"]: r for r in get_subcategory_sales(cur_from, cur_to, country, None)}
    ly = {r["subcategory"]: r for r in get_subcategory_sales(ly_from, ly_to, country, None)}
    subs = []
    for sc in set(list(cur.keys()) + list(ly.keys())):
        if not sc:
            continue
        rc = cur.get(sc, {}); rl = ly.get(sc, {})
        rev_c = float(rc.get("total_sales") or 0); rev_l = float(rl.get("total_sales") or 0)
        u_c = float(rc.get("units_sold") or 0); u_l = float(rl.get("units_sold") or 0)
        subs.append({
            "subcategory": sc,
            "cur": rev_c, "ly": rev_l,
            "cur_units": u_c,
            "ly_units": u_l,
            "delta_pct": _es_pct(rev_c, rev_l),
            # WS4 T403: per-subcategory ASP (revenue/units) — previously never
            # emitted, so the frontend fell back to "KES 0" on every row.
            "asp": _es_cmp(rev_c / u_c if u_c else 0, rev_l / u_l if u_l else 0),
        })
    subs.sort(key=lambda x: x["cur"], reverse=True)
    return {"subcategories": subs}

# Panel row -> stored-budget bucket name. The finance budget workbook splits
# Kenya into Retail vs Online; the Exec-Summary panel surfaces these as the
# "Kenya" and "Online" rows (matching _es_countries' country names, which is
# what the frontend joins the YTD actuals on). Uganda / Rwanda pass through.
_ES_TARGET_BUCKET_MAP = [
    ("Kenya", "Kenya - Retail"),
    ("Online", "Kenya - Online"),
    ("Uganda", "Uganda"),
    ("Rwanda", "Rwanda"),
]


def _es_targets(as_of, country):
    # YTD-vs-yearly-target pacing per market, fed from the stored finance
    # budget (targets_monthly, scope='region', source='budget') for as_of's
    # year — the SAME source the Annual Targets page / /api/analytics/
    # annual-targets reads. annual = sum of the 12 monthly budget rows;
    # ytd = full elapsed months + (current month x day_in_month/days_in_month).
    # The YTD actual the panel compares against is supplied by the frontend
    # from _es_countries / the YTD KPIs (total_sales_kes net of returns, the
    # canonical _TARGET_REVENUE basis), so target and actual share a basis and
    # a country at true budget pace reads ~100%. When no budget exists for the
    # year we fall back to prior-year actuals x 1.15 on that same net-of-returns
    # basis (a clearly-labelled stretch) so the panel still renders.
    yr = as_of.year
    cur_month = as_of.month
    dim = calendar.monthrange(yr, cur_month)[1]
    month_frac = as_of.day / dim if dim else 1.0

    # Monthly stored budget per bucket: {bucket_name: {month_int: target_kes}}.
    budget = {}
    for r in run_query(
        "SELECT name, EXTRACT(MONTH FROM month)::int AS m, "
        "SUM(target_kes)::numeric AS tgt FROM targets_monthly "
        "WHERE scope = 'region' AND source = 'budget' "
        "AND EXTRACT(YEAR FROM month) = " + str(yr) + " GROUP BY 1, 2"
    ):
        m = int(r["m"]) if r["m"] else 0
        if 1 <= m <= 12:
            budget.setdefault(r["name"], {})[m] = float(r["tgt"] or 0)

    has_budget = bool(budget)

    # Fallback: prior-year actuals x 1.15 (same net-of-returns basis as the
    # actuals) when there is no stored budget for the year.
    fallback = {}
    if not has_budget:
        growth = 1.15
        for r in run_query("""
            SELECT """ + _ACTUAL_BUCKET_CASE + """ AS bucket,
                EXTRACT(MONTH FROM s.sale_date::date)::int AS m,
                ROUND(""" + _TARGET_REVENUE + """) AS net
            FROM all_sales s
            WHERE s.sale_date BETWEEN '""" + str(yr - 1) + """-01-01' AND '""" + str(yr - 1) + """-12-31'
              AND s.sale_kind IN ('sale','order','return') AND """ + BASE_FILTERS + """
            GROUP BY 1, 2
        """):
            m = int(r["m"]) if r["m"] else 0
            if 1 <= m <= 12:
                fallback.setdefault(r["bucket"], {})[m] = float(r["net"] or 0) * growth

    source = budget if has_budget else fallback

    def country_target(panel_name, budget_bucket):
        months = source.get(budget_bucket, {})
        annual = round(sum(months.values()))
        ytd = 0.0
        for m in range(1, cur_month):
            ytd += months.get(m, 0)
        ytd += months.get(cur_month, 0) * month_frac
        return {"country": panel_name, "ytd": round(ytd), "annual": annual}

    rows = list(_ES_TARGET_BUCKET_MAP)
    if country:
        cset = {c.strip() for c in country.split(",")}
        rows = [(p, b) for (p, b) in rows if p in cset]
    countries = [country_target(p, b) for (p, b) in rows]
    return {
        "countries": countries,
        "total": {"ytd": sum(c["ytd"] for c in countries),
                  "annual": sum(c["annual"] for c in countries)},
        "source": "budget" if has_budget else "prior_year_stretch",
        "year": yr,
    }

def _es_stock_mix(sold_from, sold_to, window_days, country):
    # Stock-vs-sales mix: on-hand units (warehouse vs stores) against units sold
    # over the window, rolled up to categories with weeks-of-cover and gap.
    subcat_list = "'" + "','".join(PRODUCT_SUBCATS) + "'"
    inv_country = ("AND LOWER(i.country) IN (" + csv_to_sql(country.lower()) + ")") if country else ""
    sales_country = ("AND s.country IN (" + csv_to_sql(country) + ")") if country else ""
    inv = run_query("""
        SELECT p.product_type AS subcategory,
            SUM(CASE WHEN i.pos_location_name = 'Warehouse Finished Goods' THEN i.available ELSE 0 END) AS wh_units,
            SUM(CASE WHEN i.pos_location_name IN (""" + WAREHOUSE_LOCATIONS + """) AND i.pos_location_name <> 'Finished Goods Production' THEN i.available ELSE 0 END) AS pipeline_units,
            SUM(CASE WHEN i.pos_location_name NOT IN (""" + WAREHOUSE_LOCATIONS + """) THEN i.available ELSE 0 END) AS st_units
        FROM all_inventory i
        JOIN all_products_clean p ON i.sku = p.sku
        WHERE i.available > 0 AND p.product_type IN (""" + subcat_list + """) """ + inv_country + """
        GROUP BY p.product_type
    """)
    sales = run_query("""
        SELECT p.product_type AS subcategory,
            SUM(s.ordered_item_quantity) AS sold_units,
            ROUND(SUM((s.total_sales_kes::numeric - COALESCE(s.discounts_kes, 0)::numeric)), 0) AS sold_rev
        FROM all_sales s
        LEFT JOIN all_products_clean p ON s.variant_sku = p.sku
        WHERE s.sale_date BETWEEN '""" + sold_from + """' AND '""" + sold_to + """'
          AND s.sale_kind IN ('sale','order') AND s.ordered_item_quantity > 0
          AND """ + BASE_FILTERS + " " + sales_country + """
          AND p.product_type IN (""" + subcat_list + """)
        GROUP BY p.product_type
    """, date_to=sold_to)
    inv_map = {r["subcategory"]: r for r in inv}
    sales_map = {r["subcategory"]: r for r in sales}
    weeks = (window_days / 7.0) if window_days else 1.0

    raw = []
    for sc in set(list(inv_map.keys()) + list(sales_map.keys())):
        if not sc:
            continue
        iv = inv_map.get(sc, {}); sv = sales_map.get(sc, {})
        wh = float(iv.get("wh_units") or 0); st = float(iv.get("st_units") or 0)
        pipe = float(iv.get("pipeline_units") or 0)
        raw.append({
            "subcategory": sc, "category": SUBCATEGORY_TO_CATEGORY.get(sc, "Other"),
            "wh": wh, "st": st, "pipe": pipe, "stock": wh + st,
            "sold": float(sv.get("sold_units") or 0), "rev": float(sv.get("sold_rev") or 0),
        })
    tot_stock = sum(r["stock"] for r in raw)
    tot_wh = sum(r["wh"] for r in raw)
    tot_st = sum(r["st"] for r in raw)
    tot_pipe = sum(r.get("pipe", 0.0) for r in raw)
    tot_sold = sum(r["sold"] for r in raw)

    def cover(stock, sold):
        if sold <= 0:
            return None
        weekly = sold / weeks if weeks else 0
        return round(stock / weekly, 2) if weekly else None

    def asp(rev, sold):
        return round(rev / sold) if sold else None

    def make_row(d):
        stock = d["stock"]; sold = d["sold"]; rev = d["rev"]
        stock_pct = stock / tot_stock * 100 if tot_stock else 0
        sold_pct = sold / tot_sold * 100 if tot_sold else 0
        a = asp(rev, sold)
        return {
            "stock_units": stock, "stock_pct": round(stock_pct, 2),
            "stock_units_warehouse": d["wh"],
            "stock_pct_warehouse": round(d["wh"] / tot_wh * 100, 2) if tot_wh else 0,
            "stock_units_stores": d["st"],
            "stock_pct_stores": round(d["st"] / tot_st * 100, 2) if tot_st else 0,
            "stock_units_pipeline": d.get("pipe", 0.0),
            "sold_units": sold, "sold_pct": round(sold_pct, 2),
            "gap_pct": round(stock_pct - sold_pct, 2),
            "weeks_of_cover": cover(stock, sold),
            "asp_mtd": a, "tied_up_kes": round(stock * a) if a else 0,
        }

    cats = {}
    for d in raw:
        c = cats.setdefault(d["category"], {"category": d["category"], "wh": 0.0,
                                            "st": 0.0, "pipe": 0.0, "stock": 0.0, "sold": 0.0,
                                            "rev": 0.0, "subs": []})
        c["wh"] += d["wh"]; c["st"] += d["st"]; c["pipe"] += d.get("pipe", 0.0); c["stock"] += d["stock"]
        c["sold"] += d["sold"]; c["rev"] += d["rev"]; c["subs"].append(d)
    categories = []
    for c in cats.values():
        row = make_row(c)
        row["category"] = c["category"]
        row["subcategories"] = sorted(
            [dict(make_row(s), subcategory=s["subcategory"]) for s in c["subs"]],
            key=lambda x: x["stock_units"], reverse=True)
        categories.append(row)
    categories.sort(key=lambda x: x["stock_units"], reverse=True)

    return {
        "window_days": window_days, "weeks_in_window": round(weeks, 2),
        "sold_window": {"from": sold_from, "to": sold_to},
        "total_stock_units": tot_stock,
        "total_stock_units_warehouse": tot_wh,
        "total_stock_units_stores": tot_st,
        "total_stock_units_pipeline": tot_pipe,
        "total_stock_pct_warehouse": round(tot_wh / tot_stock * 100, 2) if tot_stock else 0,
        "total_stock_pct_stores": round(tot_st / tot_stock * 100, 2) if tot_stock else 0,
        "total_sold_units_mtd": tot_sold,
        "total_weeks_of_cover": cover(tot_stock, tot_sold),
        "categories": categories,
    }

@app.get("/api/exec-summary")
def exec_summary(
    country:     str = Query(default=None),
    window_days: int = Query(default=30),
    date_from:   str = Query(default=None),
    date_to:     str = Query(default=None),
    style_status: str = Query(default="all"),
):
    # Whole-response cache: the page is ~35s cold (a dozen whole-history
    # aggregations; the customer-windows CTE alone is ~18s) and the per-query
    # caches lapse on the default smart_ttl, so the first user of every cycle
    # ate the full cost. HEAVY_DASH_TTL + the prewarmer (default view) keep it
    # permanently warm; filtered variants stay warm 15 min after first compute.
    _es_ck = "execsum:%s|%s|%s|%s|%s" % (country or "", window_days or 30,
                                         date_from or "", date_to or "",
                                         style_status or "all")
    _es_cached, _es_fresh = cache_get_swr(_es_ck)
    if _es_cached is not None:
        if not _es_fresh:
            swr_refresh(_es_ck, lambda: exec_summary(
                country=country, window_days=window_days, date_from=date_from,
                date_to=date_to, style_status=style_status), label="execsum")
        return _es_cached
    # Anchor "as of" to yesterday, but never past the latest sale in the data.
    mx = run_query("SELECT MAX(s.sale_date) AS mx FROM all_sales s WHERE s.sale_kind IN ('sale','order')")
    max_date = None
    if mx and mx[0].get("mx"):
        try:
            max_date = date.fromisoformat(str(mx[0]["mx"])[:10])
        except ValueError:
            max_date = None
    as_of = date.today() - timedelta(days=1)
    if max_date and max_date < as_of:
        as_of = max_date

    ytd_cur = (date(as_of.year, 1, 1), as_of)
    ytd_ly = (date(as_of.year - 1, 1, 1), _es_shift_year(as_of, 1))
    mtd_cur = (as_of.replace(day=1), as_of)
    mtd_ly = (_es_shift_year(as_of.replace(day=1), 1), _es_shift_year(as_of, 1))

    def ds(t):
        return (t[0].isoformat(), t[1].isoformat())
    ytd_cur_s, ytd_ly_s = ds(ytd_cur), ds(ytd_ly)
    mtd_cur_s, mtd_ly_s = ds(mtd_cur), ds(mtd_ly)

    days_ytd = (ytd_cur[1] - ytd_cur[0]).days + 1
    days_ytd_ly = (ytd_ly[1] - ytd_ly[0]).days + 1
    days_mtd = (mtd_cur[1] - mtd_cur[0]).days + 1
    days_mtd_ly = (mtd_ly[1] - mtd_ly[0]).days + 1

    # Footfall-by-country for each window: computed once and reused by both the
    # KPI blocks (totals) and the country breakdowns below.
    ff = {
        "yc": _es_footfall_by_country(ytd_cur_s[0], ytd_cur_s[1]),
        "yl": _es_footfall_by_country(ytd_ly_s[0], ytd_ly_s[1]),
        "mc": _es_footfall_by_country(mtd_cur_s[0], mtd_cur_s[1]),
        "ml": _es_footfall_by_country(mtd_ly_s[0], mtd_ly_s[1]),
    }
    ff_total = {k: _es_footfall_total(v, country) for k, v in ff.items()}

    # total/new/returning customers for all four windows in a single query span.
    _cust_wins = {"yc": ytd_cur_s, "yl": ytd_ly_s, "mc": mtd_cur_s, "ml": mtd_ly_s}
    cust = _es_customer_windows(ytd_ly_s[0], ytd_cur_s[1], _cust_wins, country)
    # Per-country customer breakdown (same windows, grouped by s.country).
    cust_ctry = _es_customer_by_country(ytd_ly_s[0], ytd_cur_s[1], _cust_wins, country)
    def _cust_win(win_key):
        return {c: v.get(win_key, {}) for c, v in cust_ctry.items()}

    ytd_kpis = _es_kpis(
        _es_kpi_block(ytd_cur_s[0], ytd_cur_s[1], country, days_ytd, ff_total["yc"], cust["yc"]),
        _es_kpi_block(ytd_ly_s[0], ytd_ly_s[1], country, days_ytd_ly, ff_total["yl"], cust["yl"]))
    mtd_kpis = _es_kpis(
        _es_kpi_block(mtd_cur_s[0], mtd_cur_s[1], country, days_mtd, ff_total["mc"], cust["mc"]),
        _es_kpi_block(mtd_ly_s[0], mtd_ly_s[1], country, days_mtd_ly, ff_total["ml"], cust["ml"]))

    store_targets = _es_store_targets(ytd_ly_s[0], ytd_ly_s[1], as_of.year - 1)

    if date_from and date_to:
        sold_from, sold_to = date_from, date_to
        wd = (date.fromisoformat(date_to[:10]) - date.fromisoformat(date_from[:10])).days + 1
    else:
        wd = window_days or 30
        sold_from = (as_of - timedelta(days=wd - 1)).isoformat()
        sold_to = as_of.isoformat()

    resp = {
        "as_of": as_of.isoformat(),
        "windows": {
            "ytd": {"current": list(ytd_cur_s), "ly": list(ytd_ly_s)},
            "mtd": {"current": list(mtd_cur_s), "ly": list(mtd_ly_s)},
        },
        "ytd": {
            "kpis": ytd_kpis,
            "countries": _es_countries(ytd_cur_s[0], ytd_cur_s[1], ytd_ly_s[0], ytd_ly_s[1], country, days_ytd, days_ytd_ly, ff["yc"], ff["yl"], _cust_win("yc"), _cust_win("yl")),
            "stores": _es_stores(ytd_cur_s[0], ytd_cur_s[1], ytd_ly_s[0], ytd_ly_s[1], country, store_targets),
            "categories": _es_categories(ytd_cur_s[0], ytd_cur_s[1], ytd_ly_s[0], ytd_ly_s[1], country),
        },
        "mtd": {
            "kpis": mtd_kpis,
            "countries": _es_countries(mtd_cur_s[0], mtd_cur_s[1], mtd_ly_s[0], mtd_ly_s[1], country, days_mtd, days_mtd_ly, ff["mc"], ff["ml"], _cust_win("mc"), _cust_win("ml")),
            "stores": _es_stores(mtd_cur_s[0], mtd_cur_s[1], mtd_ly_s[0], mtd_ly_s[1], country, store_targets),
            "categories": _es_categories(mtd_cur_s[0], mtd_cur_s[1], mtd_ly_s[0], mtd_ly_s[1], country),
        },
        "targets": _es_targets(as_of, country),
        "stock_mix": _es_stock_mix(sold_from, sold_to, wd, country),
        "kpis": {"units": ytd_kpis["units"]},
    }
    cache_set(_es_ck, resp, ttl=HEAVY_DASH_TTL)
    return resp
# IBT (Inter-Branch Transfer) endpoints — see PART A region below for the
# real implementations (ibt_suggestions / ibt_sku_breakdown /
# ibt_warehouse_to_store). Kept out of the stub block intentionally.
@app.get("/api/analytics/insights")
def stub_analytics_insights(): return []
@app.get("/api/analytics/re-order-list")
def stub_analytics_re_order_list(): return []
@app.get("/api/analytics/recently-unchurned")
def analytics_recently_unchurned(
    date_from: str = Query(default=None),
    date_to:   str = Query(default=None),
    min_gap_days: int = Query(default=90),
    limit: int = Query(default=100),
):
    # Win-back signal: customers whose latest purchase follows a long dormant
    # gap (>= min_gap_days) and landed in the last 60 days.
    return run_query("""
        WITH purch AS (
            SELECT s.customer_id, s.sale_date::date AS d
            FROM all_sales s
            WHERE s.sale_kind IN ('sale','order')
              AND s.customer_id IS NOT NULL AND s.customer_id <> ''
              AND s.sale_date ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}'
        ),
        gaps AS (
            SELECT customer_id, d,
                LAG(d) OVER (PARTITION BY customer_id ORDER BY d) AS prev_d
            FROM purch
        ),
        winback AS (
            SELECT customer_id, d AS return_date, (d - prev_d) AS gap_days
            FROM gaps
            WHERE prev_d IS NOT NULL
              AND (d - prev_d) >= """ + str(int(min_gap_days)) + """
              AND d >= CURRENT_DATE - INTERVAL '60 days'
        )
        SELECT w.customer_id,
            NULLIF(TRIM(COALESCE(c.first_name,'') || ' ' || COALESCE(c.last_name,'')), '') AS name,
            c.phone, c.email,
            MAX(w.return_date) AS last_order_date,
            MAX(w.gap_days) AS gap_days,
            COALESCE(MAX(c.total_orders), 0) AS total_orders,
            COALESCE(ROUND(MAX(c.total_spend_kes)), 0) AS total_spend,
            (CURRENT_DATE - MAX(w.return_date)) AS days_since_last
        FROM winback w
        LEFT JOIN all_customers c ON c.customer_id = w.customer_id
        GROUP BY w.customer_id, c.first_name, c.last_name, c.phone, c.email
        ORDER BY last_order_date DESC, gap_days DESC
        LIMIT """ + str(int(limit)))
# ── Phase 2 A3 — size-curve replenishment helpers ─────────────────────────────
_SIZE_ORDER = {s: i for i, s in enumerate(
    ["XXXS", "XXS", "XS", "S", "S/M", "M", "M/L", "L", "L/XL",
     "XL", "XXL", "XXXL", "2XL", "3XL", "4XL", "5XL"])}


def _size_sort_key(sz):
    u = (sz or "").strip().upper()
    if u in _SIZE_ORDER:
        return (0, _SIZE_ORDER[u], "")
    try:
        return (1, float(u), "")
    except (TypeError, ValueError):
        return (2, 0.0, u)


def _split_recommended(weights, total):
    # Split `total` across buckets proportionally to `weights` using the
    # largest-remainder method so the per-size parts always sum to exactly
    # `total` (no rounding drift).
    n = len(weights)
    if n == 0 or total <= 0:
        return [0] * n
    tot_w = sum(weights)
    if tot_w <= 0:
        weights = [1] * n
        tot_w = n
    raw = [total * w / tot_w for w in weights]
    floors = [int(x) for x in raw]
    remainder = int(total - sum(floors))
    order = sorted(range(n), key=lambda i: raw[i] - floors[i], reverse=True)
    for k in range(max(0, remainder)):
        floors[order[k % n]] += 1
    return floors


def _size_mix_rows(style_filter_sql, sales_extra, inv_country):
    """Per (style, size) 28d/56d units sold + current store SOH, used by both
    the size-breakdown endpoint and the replenish-by-color size_mix block.
    `style_filter_sql` is an already-escaped `AND p.style_name ...` predicate."""
    return run_query("""
        WITH sized_sales AS (
            SELECT p.style_name AS style, NULLIF(TRIM(p.size), '') AS size,
                SUM(s.net_quantity) FILTER (
                    WHERE s.sale_date >= (CURRENT_DATE - INTERVAL '28 days')::text) AS units_28,
                SUM(s.net_quantity) AS units_56
            FROM all_sales s
            JOIN all_products_clean p ON p.sku = s.variant_sku
            WHERE s.sale_kind IN ('sale','order')
              AND s.sale_date >= (CURRENT_DATE - INTERVAL '56 days')::text
              AND """ + BASE_FILTERS + sales_extra + """
              AND p.style_name IS NOT NULL """ + style_filter_sql + """
              AND NULLIF(TRIM(p.size), '') IS NOT NULL
            GROUP BY 1, 2
        ),
        sized_soh AS (
            SELECT p.style_name AS style, NULLIF(TRIM(p.size), '') AS size,
                SUM(i.available) AS soh
            FROM all_inventory i
            JOIN all_products_clean p ON p.sku = i.sku
            WHERE i.pos_location_name NOT IN (""" + WAREHOUSE_LOCATIONS + """)
              AND p.style_name IS NOT NULL """ + style_filter_sql + """
              AND NULLIF(TRIM(p.size), '') IS NOT NULL""" + inv_country + """
            GROUP BY 1, 2
        )
        SELECT COALESCE(ss.style, sh.style) AS style,
            COALESCE(ss.size, sh.size) AS size,
            COALESCE(ss.units_28, 0)::int AS units_28,
            COALESCE(ss.units_56, 0)::int AS units_56,
            COALESCE(sh.soh, 0)::int AS soh
        FROM sized_sales ss
        FULL OUTER JOIN sized_soh sh ON sh.style = ss.style AND sh.size = ss.size
        WHERE COALESCE(ss.style, sh.style) IS NOT NULL
    """)


def _build_size_mix(rows, total_recommended, cap=None):
    """Turn raw (size, units_28, units_56, soh) rows for ONE style into an
    ordered size_mix list, splitting `total_recommended` proportionally to 28d
    sales (falling back to 56d, then even) so the parts sum to the style total.
    When `cap` is set, each size's recommended_qty is clamped to it (per-store
    per-line ceiling)."""
    rows = sorted(rows, key=lambda r: _size_sort_key(r.get("size")))
    weights = [int(r.get("units_28") or 0) for r in rows]
    if sum(weights) == 0:
        weights = [int(r.get("units_56") or 0) for r in rows]
    tot_w = sum(weights) or len(rows) or 1
    qtys = _split_recommended(weights, total_recommended)
    # When `cap` is set, clamp each size's recommended_qty to the per-line
    # ceiling so a per-store size curve never shows more than the cap for a
    # single style+colour+size SKU (keeps the breakdown in step with the pick
    # list). Chain-wide callers pass cap=None and keep the proportional split.
    if cap is not None:
        qtys = [min(q, int(cap)) for q in qtys]
    out = []
    for r, w, q in zip(rows, weights, qtys):
        out.append({
            "size": r.get("size"),
            "units_28": int(r.get("units_28") or 0),
            "units_56": int(r.get("units_56") or 0),
            "soh": int(r.get("soh") or 0),
            "size_share_pct": round(100.0 * w / tot_w, 1) if tot_w else 0.0,
            "recommended_qty": q,
        })
    return out


@app.get("/api/replenishment/size-breakdown")
def replenishment_size_breakdown(
    style_name: str = Query(...),
    country:    str = Query(default=None),
    channel:    str = Query(default=None),
):
    # Phase 2 A3 — split a single style's recommended replenishment across its
    # size run, proportional to the last-28-day size mix (recency-weighted
    # velocity over the 56d window, identical to replenish-by-color).
    sales_extra = ""
    if country:
        sales_extra += " AND s.country = '" + _sql_str(country) + "'"
    if channel:
        sales_extra += " AND s.pos_location_name IN (" + csv_to_sql(channel) + ")"
    inv_country = (" AND i.country = '" + _sql_str(country) + "'") if country else ""
    style_filter = " AND p.style_name = '" + _sql_str(style_name) + "'"
    rows = _size_mix_rows(style_filter, sales_extra, inv_country)
    total_28 = sum(int(r.get("units_28") or 0) for r in rows)
    total_56 = sum(int(r.get("units_56") or 0) for r in rows)
    total_soh = sum(int(r.get("soh") or 0) for r in rows)
    weekly = ((total_28 * 2) + max(total_56 - total_28, 0)) / 12.0
    target = int(round(weekly * 4.0))
    total_recommended = max(0, target - total_soh)
    sizes = _build_size_mix(rows, total_recommended)
    return {
        "style_name": style_name,
        "weekly_units": round(weekly, 2),
        "weeks_target": 4.0,
        "total_units_28d": total_28,
        "total_units_56d": total_56,
        "total_soh": total_soh,
        "total_recommended_qty": total_recommended,
        "velocity_method": "ewma_56d",
        "sizes": sizes,
    }


@app.get("/api/replenishment/calendar")
def replenishment_calendar(
    country:      str = Query(default=None),
    weeks_ahead:  int = Query(default=8),
):
    # Phase 2 B3 — forward-looking replenishment calendar. For every style we
    # project when its weeks-of-cover will fall to the lead-time + safety-stock
    # reorder threshold, then bucket the styles by the ISO week in which an order
    # must be placed so it arrives before stockout. Velocity is the standardized
    # recency-weighted weekly run-rate (28d ×2 over a 12-week denominator on the
    # trailing 56d window), identical to /weeks-of-cover and /replenish-by-color.
    from datetime import datetime, timedelta
    weeks_ahead = max(1, min(int(weeks_ahead), 52))
    subcat_list = "'" + "','".join(PRODUCT_SUBCATS) + "'"
    sales_extra = ""
    inv_extra = ""
    if country:
        sales_extra = " AND s.country IN (" + csv_to_sql(country) + ")"
        # Scope stock to the same country so weeks_of_cover / reorder_point /
        # priority compare local demand against local stock (architect review).
        inv_extra = " AND i.country IN (" + csv_to_sql(country) + ")"
    rows = run_query("""
        WITH sales AS (
            SELECT p.product_type AS subcategory, p.style_name, p.brand,
                SUM(s.ordered_item_quantity) FILTER (
                    WHERE s.sale_date::date >= CURRENT_DATE - INTERVAL '28 days') AS units_28,
                SUM(s.ordered_item_quantity) AS units_56
            FROM all_sales s
            LEFT JOIN all_products_clean p ON s.variant_sku = p.sku
            WHERE s.sale_kind IN ('sale','order')
            AND s.sale_date::date >= CURRENT_DATE - INTERVAL '56 days'
            AND """ + BASE_FILTERS + sales_extra + """
            AND p.product_type IN (""" + subcat_list + """)
            GROUP BY p.product_type, p.style_name, p.brand
        ),
        stock AS (
            SELECT p.product_type AS subcategory, p.style_name,
                SUM(i.available) AS available
            FROM all_inventory i
            LEFT JOIN all_products_clean p ON i.sku = p.sku
            WHERE i.pos_location_name NOT IN (""" + WAREHOUSE_LOCATIONS + """)""" + inv_extra + """
            AND p.product_type IN (""" + subcat_list + """)
            GROUP BY p.product_type, p.style_name
        ),
        base AS (
            SELECT COALESCE(st.subcategory, sa.subcategory) AS subcategory,
                COALESCE(st.style_name, sa.style_name) AS style_name,
                MAX(sa.brand) AS brand,
                COALESCE(st.available, 0) AS available,
                ((COALESCE(sa.units_28, 0) * 2)
                  + GREATEST(COALESCE(sa.units_56, 0) - COALESCE(sa.units_28, 0), 0)) / 12.0
                  AS weekly_units
            FROM stock st
            FULL OUTER JOIN sales sa
                ON st.subcategory = sa.subcategory AND st.style_name = sa.style_name
            WHERE COALESCE(st.style_name, sa.style_name) IS NOT NULL
            GROUP BY st.subcategory, sa.subcategory, st.style_name, sa.style_name,
                st.available, sa.units_28, sa.units_56
        )
        SELECT subcategory, style_name, brand, available,
            ROUND(weekly_units, 2) AS weekly_units,
            ROUND(available / NULLIF(weekly_units, 0), 1) AS weeks_of_cover,
            ROUND(weekly_units * """ + str(REORDER_COVER_WEEKS) + """)::int AS reorder_point
        FROM base
        WHERE weekly_units > 0
        ORDER BY weeks_of_cover ASC NULLS LAST
        LIMIT 5000
    """)

    today = date.today()
    # Monday of the current ISO week — every bucket is anchored on a Monday.
    current_monday = today - timedelta(days=today.weekday())
    horizon_end = current_monday + timedelta(weeks=weeks_ahead)

    buckets = {}  # week_start ISO date -> bucket dict

    def _bucket(week_start):
        key = week_start.isoformat()
        if key not in buckets:
            iso_year, iso_week, _ = week_start.isocalendar()
            buckets[key] = {
                "week_start": key,
                "iso_year": iso_year,
                "iso_week": iso_week,
                "week_label": "%d-W%02d" % (iso_year, iso_week),
                "critical": 0, "high": 0, "medium": 0,
                "styles": [],
            }
        return buckets[key]

    for r in rows:
        weekly = float(r.get("weekly_units") or 0)
        if weekly <= 0:
            continue
        available = float(r.get("available") or 0)
        woc = available / weekly  # raw weeks of cover
        # Weeks from now until cover decays to the reorder threshold.
        weeks_until = woc - REORDER_COVER_WEEKS

        if woc < LEAD_TIME_WEEKS:
            priority = "CRITICAL"
            action_monday = current_monday
            trigger_reason = (
                "Only %.1f weeks of cover — below the %.0f-week production lead "
                "time. Stockout imminent; expedite now." % (woc, LEAD_TIME_WEEKS)
            )
        elif weeks_until <= 0:
            priority = "HIGH"
            action_monday = current_monday
            trigger_reason = (
                "Below reorder point (%.1f wks cover < %.0f-wk threshold). "
                "Place the reorder this week." % (woc, REORDER_COVER_WEEKS)
            )
        else:
            # Will cross the reorder threshold in `weeks_until` weeks.
            action_monday = current_monday + timedelta(weeks=int(weeks_until // 1))
            if action_monday >= horizon_end:
                continue  # beyond the requested horizon — not actionable yet
            priority = "MEDIUM"
            trigger_reason = (
                "Projected to hit the reorder point in ~%d week(s) "
                "(%.1f wks cover now)." % (int(weeks_until // 1), woc)
            )

        b = _bucket(action_monday)
        b[priority.lower()] += 1
        b["styles"].append({
            "style_name": r.get("style_name"),
            "subcategory": r.get("subcategory"),
            "brand": r.get("brand"),
            "available": int(available),
            "weekly_units": round(weekly, 2),
            "weeks_of_cover": round(woc, 1),
            "reorder_point": int(r.get("reorder_point") or 0),
            "priority": priority,
            "trigger_reason": trigger_reason,
            "velocity_method": "ewma_56d",
        })

    _prio_rank = {"CRITICAL": 0, "HIGH": 1, "MEDIUM": 2}
    for b in buckets.values():
        b["styles"].sort(key=lambda s: (_prio_rank.get(s["priority"], 9),
                                        s["weeks_of_cover"]))
        b["count"] = len(b["styles"])

    ordered = [buckets[k] for k in sorted(buckets.keys())]
    return {
        "country": country,
        "weeks_ahead": weeks_ahead,
        "lead_time_weeks": LEAD_TIME_WEEKS,
        "safety_weeks": SAFETY_WEEKS,
        "reorder_cover_weeks": REORDER_COVER_WEEKS,
        "generated_at": today.isoformat(),
        "total_styles": sum(b["count"] for b in ordered),
        "velocity_method": "ewma_56d",
        "buckets": ordered,
    }


@app.get("/api/analytics/replenish-by-color")
def analytics_replenish_by_color(
    country: str = Query(default=None),
    channel: str = Query(default=None),
    max_weeks_of_cover: float = Query(default=6.0),
    min_sor_percent: float = Query(default=40.0),
):
    sales_extra = ""
    if country:
        sales_extra += " AND s.country = '" + country.replace("'", "''") + "'"
    if channel:
        sales_extra += " AND s.pos_location_name IN (" + csv_to_sql(channel) + ")"
    inv_country = ""
    if country:
        inv_country = " AND i.country = '" + country.replace("'", "''") + "'"
    rows = run_query("""
        WITH sales30 AS (
            SELECT p.style_name, MAX(p.brand) AS brand, MAX(p.product_type) AS subcategory,
                COALESCE(NULLIF(TRIM(p.color_print), ''), 'Unspecified') AS color,
                SUM(s.net_quantity) FILTER (
                    WHERE s.sale_date >= (CURRENT_DATE - INTERVAL '28 days')::text) AS units_28,
                SUM(s.net_quantity) AS units_56
            FROM all_sales s
            JOIN all_products_clean p ON p.sku = s.variant_sku
            WHERE s.sale_kind IN ('sale','order')
              AND s.sale_date >= (CURRENT_DATE - INTERVAL '56 days')::text
              AND """ + BASE_FILTERS + sales_extra + """
              AND p.style_name IS NOT NULL
            GROUP BY p.style_name, color
        ),
        soh AS (
            SELECT p.style_name,
                COALESCE(NULLIF(TRIM(i.color_print), ''), 'Unspecified') AS color,
                SUM(i.available) AS soh_total
            FROM all_inventory i
            JOIN all_products_clean p ON p.sku = i.sku
            WHERE i.pos_location_name NOT IN (""" + WAREHOUSE_LOCATIONS + """)
              AND p.style_name IS NOT NULL""" + inv_country + """
            GROUP BY p.style_name, color
        )
        SELECT COALESCE(s.style_name, h.style_name) AS style_name,
            COALESCE(s.color, h.color) AS color,
            MAX(s.brand) AS brand, MAX(s.subcategory) AS subcategory,
            COALESCE(SUM(s.units_28), 0) AS units_28,
            COALESCE(SUM(s.units_56), 0) AS units_56,
            COALESCE(SUM(h.soh_total), 0) AS soh_total
        FROM sales30 s
        FULL OUTER JOIN soh h ON h.style_name = s.style_name AND h.color = s.color
        GROUP BY COALESCE(s.style_name, h.style_name), COALESCE(s.color, h.color)
    """)
    styles = {}
    for r in rows:
        sn = r.get("style_name")
        if not sn:
            continue
        st = styles.setdefault(sn, {"brand": None, "subcategory": None, "colors": []})
        if r.get("brand"):
            st["brand"] = r["brand"]
        if r.get("subcategory"):
            st["subcategory"] = r["subcategory"]
        st["colors"].append({
            "color": r["color"],
            "units_28": int(float(r["units_28"] or 0)),
            "units_56": int(float(r["units_56"] or 0)),
            "soh_total": int(float(r["soh_total"] or 0)),
        })
    out = []
    weeks_target = 4.0

    def _weekly(u28, u56):
        # Recency-weighted weekly velocity (Phase 1 audit A1): the last 28 days
        # are double-weighted over a 12-week-equivalent denominator. Identical to
        # /analytics/weeks-of-cover so cover figures agree across the app.
        return ((u28 * 2) + max(u56 - u28, 0)) / 12.0

    for sn, st in styles.items():
        total_u28 = sum(c["units_28"] for c in st["colors"])
        total_u56 = sum(c["units_56"] for c in st["colors"])
        total_soh = sum(c["soh_total"] for c in st["colors"])
        for c in st["colors"]:
            weekly = _weekly(c["units_28"], c["units_56"])
            target = int(round(weekly * weeks_target))
            c["units_30d"] = c["units_28"]
            c["weekly_units"] = round(weekly, 2)
            c["weeks_of_cover"] = round(c["soh_total"] / weekly, 1) if weekly else 999.0
            c["reorder_point"] = int(round(weekly * REORDER_COVER_WEEKS))
            c["at_risk"] = c["soh_total"] < c["reorder_point"]
            c["target_qty"] = target
            c["recommended_qty"] = max(0, target - c["soh_total"])
            c["pct_of_style_sales"] = round(100.0 * c["units_28"] / total_u28, 1) if total_u28 else 0.0
        style_weekly = _weekly(total_u28, total_u56)
        style_reorder = int(round(style_weekly * REORDER_COVER_WEEKS))
        woc = round(total_soh / style_weekly, 1) if style_weekly else 999.0
        sor = round(100.0 * total_u28 / (total_u28 + total_soh), 1) if (total_u28 + total_soh) else 0.0
        total_rec = sum(c["recommended_qty"] for c in st["colors"])
        if sor < min_sor_percent or woc > max_weeks_of_cover or total_rec <= 0:
            continue
        st["colors"].sort(key=lambda c: c["recommended_qty"], reverse=True)
        out.append({
            "style_name": sn, "brand": st["brand"], "subcategory": st["subcategory"],
            "sor_percent": sor, "weeks_of_cover": woc,
            "weekly_units": round(style_weekly, 2),
            "reorder_point": style_reorder, "at_risk": total_soh < style_reorder,
            "total_units_30d": total_u28, "total_soh": total_soh,
            "total_recommended_qty": total_rec, "colors": st["colors"],
            "size_mix": [],
        })
    out.sort(key=lambda x: x["total_recommended_qty"], reverse=True)
    # Phase 2 A3 — attach a per-style size_mix (recommended qty split across the
    # size run by 28d sales mix). One query for every style that made the cut.
    if out:
        names = [o["style_name"] for o in out]
        style_filter = (" AND p.style_name IN ("
                        + ",".join("'" + _sql_str(n) + "'" for n in names) + ")")
        size_rows = _size_mix_rows(style_filter, sales_extra, inv_country)
        by_style = {}
        for r in size_rows:
            by_style.setdefault(r["style"], []).append(r)
        for o in out:
            o["size_mix"] = _build_size_mix(
                by_style.get(o["style_name"], []), o["total_recommended_qty"],
                cap=REPLEN_MAX_UNITS_PER_LINE)
    return out
@app.get("/api/analytics/replenishment-completed")
def analytics_replenishment_completed(days: int = Query(default=30)):
    rows = _users_exec(
        "SELECT rec_key, actual_units, acted_by, acted_at, transfer_ref "
        "FROM recommendation_actions "
        "WHERE rec_type='replenish' AND status='done' "
        "AND acted_at >= now() - (%s || ' days')::interval "
        "ORDER BY acted_at DESC LIMIT 2000",
        (str(int(days)),), fetch=True) or []
    out = []
    for r in rows:
        parts = (r["rec_key"] or "").split("|", 2)
        if len(parts) != 3:
            continue
        pos_location, kind, value = parts
        out.append({
            "pos_location": pos_location,
            "barcode": value if kind == "barcode" else None,
            "sku": value if kind == "sku" else None,
            "replenished": True,
            "actual_units_replenished": int(r["actual_units"] or 0),
            "transfer_ref": r.get("transfer_ref") or "",
            "completed_by": r["acted_by"],
            "completed_at": r["acted_at"].isoformat() if r.get("acted_at") else None,
        })
    return {"rows": out, "total": sum(x["actual_units_replenished"] for x in out)}


@app.get("/api/analytics/replenishment-transfer-report")
def analytics_replenishment_transfer_report(
    days:      int = Query(default=60),
    date_from: str = Query(default=None),
    date_to:   str = Query(default=None),
    rec_type:  str = Query(default="replenish"),
):
    """DONE recommendations grouped by POS location + day, for tracking what was
    marked done against the actual Odoo transfer document.

    Shared by two surfaces via `rec_type`: 'replenish' (Replenishments /
    Replenishment-by-style) and 'warehouse_return' (the Warehouse Returns page).
    Once an item is marked done it lands in `recommendation_actions`
    (status='done'); this report rolls those rows up into one bucket per
    (POS location, day) so an operator can record the single Odoo transfer
    number that physically moved that store's items that day.

    Window: by default the trailing `days` days; pass `date_from`/`date_to`
    (YYYY-MM-DD, inclusive) to use a custom EAT calendar range instead. Days
    bucket by Africa/Nairobi (EAT) so a late-evening mark is not pushed to the
    next UTC day. Items are enriched with product name/size/colour from
    all_products_clean (same DB) and de-duplicated: a replenish mark writes BOTH
    a 'sku' and a 'barcode' keyed row for the same physical item, so we collapse
    them to one canonical SKU (warehouse returns write a single sku row)."""
    from fastapi import HTTPException
    rt = rec_type if rec_type in _TRANSFER_REC_TYPES else "replenish"
    df = (date_from or "").strip()
    dt = (date_to or "").strip()
    params = [rt]
    if df and dt:
        try:
            date.fromisoformat(df); date.fromisoformat(dt)
        except ValueError:
            raise HTTPException(status_code=400,
                                detail="date_from/date_to must be YYYY-MM-DD")
        win_sql = ("    AND (acted_at AT TIME ZONE 'Africa/Nairobi')::date "
                   "BETWEEN %s::date AND %s::date")
        params += [df, dt]
    else:
        win_sql = "    AND acted_at >= now() - (%s || ' days')::interval"
        params.append(str(int(days)))
    rows = _users_exec(
        "WITH done AS ("
        "  SELECT split_part(rec_key,'|',1) AS pos_location,"
        "         split_part(rec_key,'|',2) AS kind,"
        "         split_part(rec_key,'|',3) AS value,"
        "         (acted_at AT TIME ZONE 'Africa/Nairobi')::date AS day,"
        "         COALESCE(actual_units,0) AS actual_units,"
        "         COALESCE(transfer_ref,'') AS transfer_ref,"
        "         acted_by, acted_at"
        "  FROM recommendation_actions"
        "  WHERE rec_type=%s AND status='done'"
        + win_sql +
        ") "
        "SELECT d.pos_location, d.kind, d.value, d.day, d.actual_units,"
        "       d.transfer_ref, d.acted_by, d.acted_at,"
        "       CASE WHEN d.kind='sku' THEN d.value ELSE p.sku END AS canon_sku,"
        "       COALESCE(p.product_name,'') AS product_name,"
        "       COALESCE(p.size,'') AS size,"
        "       COALESCE(p.color_print,'') AS color_print,"
        "       CASE WHEN d.kind='barcode' THEN d.value ELSE COALESCE(p.barcode,'') END AS barcode,"
        "       CASE WHEN d.kind='sku' THEN d.value ELSE COALESCE(p.sku,'') END AS sku "
        "FROM done d "
        "LEFT JOIN all_products_clean p "
        "  ON (d.kind='sku' AND p.sku = d.value) "
        "  OR (d.kind='barcode' AND p.barcode = d.value) "
        "ORDER BY d.day DESC, d.pos_location ASC, d.acted_at DESC",
        tuple(params), fetch=True) or []

    groups = {}
    for r in rows:
        pos = r.get("pos_location") or ""
        day = r["day"].isoformat() if r.get("day") else ""
        gkey = (pos, day)
        g = groups.get(gkey)
        if g is None:
            g = {"pos_location": pos, "day": day, "items": [],
                 "_seen": set(), "_refs": set()}
            groups[gkey] = g
        # Collapse the twin sku/barcode rows written for one physical item.
        canon = (r.get("canon_sku") or "").strip()
        itemkey = canon if canon else f"{r.get('kind')}:{r.get('value')}"
        if itemkey in g["_seen"]:
            continue
        g["_seen"].add(itemkey)
        ref = (r.get("transfer_ref") or "").strip()
        if ref:
            g["_refs"].add(ref)
        g["items"].append({
            "sku": r.get("sku") or "",
            "barcode": r.get("barcode") or "",
            "product_name": r.get("product_name") or "",
            "size": r.get("size") or "",
            "color_print": r.get("color_print") or "",
            "actual_units": int(r.get("actual_units") or 0),
            "transfer_ref": ref,
            "completed_by": r.get("acted_by") or "",
            "completed_at": r["acted_at"].isoformat() if r.get("acted_at") else None,
        })

    out_groups = []
    for g in groups.values():
        refs = sorted(g.pop("_refs"))
        g.pop("_seen", None)
        g["transfer_ref"] = refs[0] if len(refs) == 1 else ""
        g["transfer_ref_mixed"] = len(refs) > 1
        g["transfer_refs"] = refs
        g["item_count"] = len(g["items"])
        g["total_units"] = sum(i["actual_units"] for i in g["items"])
        out_groups.append(g)
    # Most recent day first, then POS name.
    out_groups.sort(key=lambda g: (g["day"], g["pos_location"]), reverse=True)
    out_groups.sort(key=lambda g: g["pos_location"])
    out_groups.sort(key=lambda g: g["day"], reverse=True)
    return {
        "groups": out_groups,
        "group_count": len(out_groups),
        "total_units": sum(g["total_units"] for g in out_groups),
        "rec_type": rt,
    }


@app.post("/api/analytics/replenishment-transfer-report/assign")
async def analytics_replenishment_transfer_assign(request: Request):
    """Stamp ONE Odoo transfer number onto every done recommendation for a given
    (POS location, day) bucket, so the marked-done items can be reconciled
    against the physical transfer document. Day is the EAT calendar day used by
    the report above. `rec_type` selects the surface ('replenish' default, or
    'warehouse_return')."""
    from fastapi import HTTPException
    body = await request.json()
    pos_location = (body.get("pos_location") or "").strip()
    day = (body.get("day") or "").strip()
    transfer_ref = (body.get("transfer_ref") or "").strip()
    rec_type = (body.get("rec_type") or "replenish").strip()
    rt = rec_type if rec_type in _TRANSFER_REC_TYPES else "replenish"
    if not pos_location or not day:
        raise HTTPException(status_code=400, detail="pos_location and day are required")
    try:
        date.fromisoformat(day)
    except ValueError:
        raise HTTPException(status_code=400, detail="day must be YYYY-MM-DD")
    updated = _users_exec(
        "UPDATE recommendation_actions "
        "SET transfer_ref = %s "
        "WHERE rec_type=%s AND status='done' "
        "  AND split_part(rec_key,'|',1) = %s "
        "  AND (acted_at AT TIME ZONE 'Africa/Nairobi')::date = %s::date "
        "RETURNING 1",
        ((transfer_ref or None), rt, pos_location, day), fetch=True) or []
    return {
        "ok": True, "pos_location": pos_location, "day": day,
        "transfer_ref": transfer_ref, "updated": len(updated), "rec_type": rt,
    }


def _replen_in_transit_rows():
    """Phase 3 step 3 — per (pos_location, sku) in-transit quarantine: dispatched
    units (done replenish lines stamped with a transfer_ref) MINUS confirmed
    store receipts. Counts only the canonical 'sku' twin row so the sku+barcode
    pair written per item isn't double-counted. Best-effort: returns [] on any
    error so neither the SOR engine nor the endpoint ever breaks."""
    try:
        _ensure_replen_tables()
        return _users_exec(
            "WITH dispatched AS ("
            "  SELECT split_part(rec_key,'|',1) AS pos_location,"
            "         split_part(rec_key,'|',3) AS sku,"
            "         SUM(COALESCE(actual_units,0)) AS dispatched"
            "  FROM recommendation_actions"
            "  WHERE rec_type='replenish' AND status='done'"
            "    AND COALESCE(transfer_ref,'') <> ''"
            "    AND split_part(rec_key,'|',2)='sku'"
            "  GROUP BY 1,2"
            "), received AS ("
            "  SELECT pos_location, sku, SUM(COALESCE(qty_received,0)) AS received"
            "  FROM fact_store_receipt GROUP BY 1,2"
            ") "
            "SELECT d.pos_location, d.sku, d.dispatched,"
            "       COALESCE(r.received,0) AS received,"
            "       (d.dispatched - COALESCE(r.received,0)) AS in_transit "
            "FROM dispatched d LEFT JOIN received r"
            "  ON r.pos_location=d.pos_location AND r.sku=d.sku "
            "WHERE d.dispatched > COALESCE(r.received,0) "
            "ORDER BY in_transit DESC", fetch=True) or []
    except Exception:
        return []


def _replen_in_transit_total():
    """Σ in-transit units across all store-SKUs, for the SOR-denominator clamp."""
    try:
        return sum(max(0, int(r.get("in_transit") or 0))
                   for r in _replen_in_transit_rows())
    except Exception:
        return 0


_REPLEN_CALIB_MIN = 0.25
_REPLEN_CALIB_MAX = 2.0
_REPLEN_CALIB_KEEP = 10  # rolling-median window of recent reconciliation samples


def _replen_proj_calibration():
    """Active projection calibration factor (rolling median of realised/projected,
    clamped [0.25, 2.0]). Defaults to 1.0 until reconciliation has run. Never
    raises — a config read hiccup falls back to neutral 1.0."""
    try:
        rows = _users_exec(
            "SELECT value FROM app_config WHERE key='replen_proj_calibration'",
            fetch=True)
        if rows:
            val = rows[0].get("value")
            if isinstance(val, str):
                val = json.loads(val)
            if isinstance(val, dict) and val.get("value") is not None:
                c = float(val["value"])
                return min(_REPLEN_CALIB_MAX, max(_REPLEN_CALIB_MIN, c))
    except Exception:
        pass
    return 1.0


def _replen_record_calibration(sample, run_id=None):
    """Append one realised/projected sample to the rolling window and persist the
    new median as the active calibration. Best-effort: returns the resulting
    median (or the prior/neutral value on failure).

    Idempotent per replenishment run: each `run_id` contributes AT MOST one
    sample. The reconciliation endpoint is read on every page load/refresh, so
    without this guard the rolling median would be dominated by page traffic
    rather than by distinct replenishment runs. When `run_id` matches the last
    recorded run, the existing calibration is returned unchanged."""
    try:
        sample = min(_REPLEN_CALIB_MAX, max(_REPLEN_CALIB_MIN, float(sample)))
    except (TypeError, ValueError):
        return _replen_proj_calibration()
    samples = []
    try:
        rows = _users_exec(
            "SELECT value FROM app_config WHERE key='replen_proj_calibration'",
            fetch=True)
        if rows:
            val = rows[0].get("value")
            if isinstance(val, str):
                val = json.loads(val)
            if isinstance(val, dict):
                # One sample per run: skip if this run is already recorded.
                if (run_id is not None and val.get("last_run_id") == run_id
                        and val.get("value") is not None):
                    return min(_REPLEN_CALIB_MAX,
                               max(_REPLEN_CALIB_MIN, float(val["value"])))
                if isinstance(val.get("samples"), list):
                    samples = [float(x) for x in val["samples"]]
    except Exception:
        samples = []
    samples.append(round(sample, 4))
    samples = samples[-_REPLEN_CALIB_KEEP:]
    ssorted = sorted(samples)
    n = len(ssorted)
    med = (ssorted[n // 2] if n % 2
           else (ssorted[n // 2 - 1] + ssorted[n // 2]) / 2.0)
    med = round(min(_REPLEN_CALIB_MAX, max(_REPLEN_CALIB_MIN, med)), 4)
    try:
        _users_exec(
            "INSERT INTO app_config (key, value, updated_at) "
            "VALUES ('replen_proj_calibration', %s::jsonb, now()) "
            "ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, "
            "updated_at = now()",
            (json.dumps({"samples": samples, "value": med,
                         "last_run_id": run_id}),))
    except Exception:
        pass
    return med


@app.get("/api/analytics/replenishment-in-transit")
def analytics_replenishment_in_transit():
    """Dispatched-but-not-yet-received replenishment stock per store-SKU, enriched
    with product name/size/colour. These units are quarantined from the SOR
    denominator until a store confirms receipt (POST .../replenishment-store-
    receipt)."""
    rows = _replen_in_transit_rows()
    skus = sorted({(r.get("sku") or "").strip() for r in rows if r.get("sku")})
    meta = {}
    if skus:
        _in = ",".join("'" + _sql_str(s) + "'" for s in skus)
        for m in (run_query(
                "SELECT sku, MAX(product_name) AS product_name, MAX(size) AS size, "
                "MAX(color_print) AS color_print, MAX(barcode) AS barcode "
                "FROM all_products_clean WHERE sku IN (" + _in + ") "
                "GROUP BY sku") or []):
            meta[m["sku"]] = m
    out = []
    for r in rows:
        m = meta.get((r.get("sku") or "").strip(), {})
        out.append({
            "pos_location": r.get("pos_location") or "",
            "sku": r.get("sku") or "",
            "barcode": (m.get("barcode") or ""),
            "product_name": (m.get("product_name") or ""),
            "size": (m.get("size") or ""),
            "color_print": (m.get("color_print") or ""),
            "dispatched": int(r.get("dispatched") or 0),
            "received": int(r.get("received") or 0),
            "in_transit": max(0, int(r.get("in_transit") or 0)),
        })
    return {
        "rows": out,
        "store_count": len({r["pos_location"] for r in out}),
        "in_transit_units": sum(r["in_transit"] for r in out),
    }


@app.post("/api/analytics/replenishment-store-receipt")
async def analytics_replenishment_store_receipt(request: Request):
    """Confirm physical receipt of dispatched replenishment stock at a store
    (Phase 3 step 3). Writes fact_store_receipt, which nets the units out of the
    in-transit quarantine so the SOR denominator reflects only stock actually on
    the floor. The transfer_ref must match a real dispatch stamped on that store's
    done lines, so a receipt can never reference a phantom transfer."""
    from fastapi import HTTPException
    _ensure_replen_tables()
    body = await request.json()
    pos = (body.get("pos_location") or "").strip()
    sku = (body.get("sku") or "").strip()
    transfer_ref = (body.get("transfer_ref") or "").strip()
    try:
        qty = int(body.get("qty_received") if body.get("qty_received") is not None
                  else body.get("qty") or 0)
    except (TypeError, ValueError):
        raise HTTPException(status_code=400, detail="qty_received must be an integer")
    if not pos or not sku:
        raise HTTPException(status_code=400, detail="pos_location and sku are required")
    if qty <= 0:
        raise HTTPException(status_code=400, detail="qty_received must be > 0")
    if not transfer_ref:
        raise HTTPException(status_code=400, detail="transfer_ref is required")
    matched = _users_exec(
        "SELECT 1 FROM recommendation_actions "
        "WHERE rec_type='replenish' AND status='done' "
        "  AND COALESCE(transfer_ref,'')=%s "
        "  AND split_part(rec_key,'|',1)=%s LIMIT 1",
        (transfer_ref, pos), fetch=True) or []
    if not matched:
        raise HTTPException(
            status_code=400,
            detail="transfer_ref does not match any dispatched transfer for this store")
    u = (request.state.user or {}) if request else {}
    received_by = u.get("email") or u.get("name") or u.get("user_id") or "staff"
    _users_exec(
        "INSERT INTO fact_store_receipt "
        "(odoo_transfer_id, pos_location, sku, qty_received, received_by) "
        "VALUES (%s,%s,%s,%s,%s)",
        (transfer_ref, pos, sku, qty, received_by))
    return {"ok": True, "pos_location": pos, "sku": sku,
            "qty_received": qty, "transfer_ref": transfer_ref}


@app.get("/api/analytics/replenishment-sor-reconciliation")
def analytics_replenishment_sor_reconciliation(
        weeks: int = Query(default=REPLEN_DEMAND_WEEKS_DEFAULT)):
    """Post-replenishment "did SOR rise?" reconciliation (Phase 3 step 4). Picks
    the most-recent suggestion run that is at least dispatch_days old (so the
    dispatched stock has had time to sell), then compares over that run's exact
    store-SKU scope:
      * SOR_at_calc   — snapshot: Σunits_sold / (Σunits_sold + Σshelf_qty_at_calc)
      * realised SOR  — recomputed NOW (same net_quantity + available basis as the
                        canonical summary, in-transit quarantined)
      * projected SOR — snapshot + Σ min(suggested_qty, v_at_calc × dispatch/7)
    The realised/projected incremental-units ratio (clamped [0.25, 2.0]) is
    recorded as a rolling-median calibration sample that scales the engine's
    projection. Read-only except for the calibration sample; never raises into the
    page."""
    _ensure_replen_tables()
    dispatch_days = REPLEN_DISPATCH_DAYS
    age_days = int(dispatch_days) + (1 if dispatch_days > int(dispatch_days) else 0)
    days = int(weeks) * 7
    run = _users_exec(
        "SELECT run_id, business_date, store_scope, ruleset_version "
        "FROM fact_replen_suggestion "
        "WHERE business_date <= (CURRENT_DATE - %s) "
        "ORDER BY business_date DESC, run_ts_eat DESC LIMIT 1",
        (age_days,), fetch=True) or []
    if not run:
        return {"available": False,
                "reason": "no suggestion run at least %d days old yet" % age_days,
                "calibration": _replen_proj_calibration()}
    run = run[0]
    rows = _users_exec(
        "SELECT pos_location, sku, COALESCE(units_sold,0) AS units_sold, "
        "COALESCE(shelf_qty_at_calc,0) AS shelf_qty_at_calc, "
        "COALESCE(v_at_calc,0) AS v_at_calc, "
        "COALESCE(suggested_qty,0) AS suggested_qty "
        "FROM fact_replen_suggestion WHERE run_id=%s",
        (run["run_id"],), fetch=True) or []
    if not rows:
        return {"available": False, "reason": "run has no snapshot rows",
                "calibration": _replen_proj_calibration()}

    units_calc = sum(int(r["units_sold"]) for r in rows)
    shelf_calc = sum(int(r["shelf_qty_at_calc"]) for r in rows)
    proj_inc = sum(min(int(r["suggested_qty"]),
                       float(r["v_at_calc"]) * dispatch_days / 7.0)
                   for r in rows if float(r["v_at_calc"]) > 0)

    pairs = sorted({((r.get("pos_location") or "").strip(),
                     (r.get("sku") or "").strip())
                    for r in rows if r.get("pos_location") and r.get("sku")})
    units_now = stock_now_gross = 0.0
    if pairs:
        vals = ",".join("('" + _sql_str(p) + "','" + _sql_str(s) + "')"
                        for p, s in pairs)
        ur = run_query(
            "SELECT COALESCE(SUM(s.net_quantity),0) AS u "
            "FROM all_sales s "
            "JOIN (VALUES " + vals + ") AS t(pos,sku) "
            "  ON t.pos = s.pos_location_name AND t.sku = s.variant_sku "
            "WHERE s.sale_kind IN ('sale','order') "
            "  AND s.sale_date >= (CURRENT_DATE - INTERVAL '" + str(days) +
            " days')::text "
            "  AND " + BASE_FILTERS +
            "  AND s.pos_location_name NOT IN (" + WAREHOUSE_LOCATIONS + ") "
            "  AND (s.pos_location_name NOT ILIKE '%online%' "
            "       OR s.pos_location_name = 'Online - Shop Zetu')") or [{}]
        units_now = float((ur[0] or {}).get("u") or 0)
        sr = run_query(
            "SELECT COALESCE(SUM(i.available),0) AS soh "
            "FROM all_inventory i "
            "JOIN (VALUES " + vals + ") AS t(pos,sku) "
            "  ON t.pos = i.pos_location_name AND t.sku = i.sku "
            "WHERE i.pos_location_name NOT IN (" + WAREHOUSE_LOCATIONS + ")") or [{}]
        stock_now_gross = float((sr[0] or {}).get("soh") or 0)

    # Quarantine in-transit for THIS scope from the realised denominator.
    pairset = set(pairs)
    set_in_transit = sum(
        max(0, int(it.get("in_transit") or 0))
        for it in _replen_in_transit_rows()
        if ((it.get("pos_location") or "").strip(),
            (it.get("sku") or "").strip()) in pairset)
    stock_now = max(0.0, stock_now_gross - set_in_transit)

    def _sor(num, denom_stock):
        d = num + denom_stock
        return round(100.0 * num / d, 1) if d > 0 else 0.0

    sor_at_calc = _sor(units_calc, shelf_calc)
    realised_sor = _sor(units_now, stock_now)
    projected_sor = _sor(units_calc + proj_inc, shelf_calc)

    realised_inc = max(0.0, units_now - units_calc)
    sample = (realised_inc / proj_inc) if proj_inc > 0 else None
    calibration = (_replen_record_calibration(sample, run_id=run["run_id"])
                   if sample is not None else _replen_proj_calibration())

    return {
        "available": True,
        "run_id": run["run_id"],
        "business_date": (run["business_date"].isoformat()
                          if run.get("business_date") else None),
        "store_scope": run.get("store_scope"),
        "dispatch_days": dispatch_days,
        "demand_weeks": int(weeks),
        "store_sku_count": len(rows),
        "units_at_calc": int(units_calc),
        "units_now": int(units_now),
        "shelf_at_calc": int(shelf_calc),
        "store_stock_now": int(stock_now),
        "in_transit_units": int(set_in_transit),
        "projected_incremental_units": round(proj_inc, 1),
        "realised_incremental_units": round(realised_inc, 1),
        "sor_at_calc": sor_at_calc,
        "realised_sor": realised_sor,
        "projected_sor": projected_sor,
        "realised_uplift_pts": round(realised_sor - sor_at_calc, 2),
        "projected_uplift_pts": round(projected_sor - sor_at_calc, 2),
        "calibration_sample": (round(sample, 4) if sample is not None else None),
        "calibration": calibration,
    }


def _replen_clean_text(s, maxlen=80):
    # Free-text search/value sanitiser for inlined SQL literals: strip the
    # chars that could break out of a string literal. Values are matched with
    # doubled single-quotes at the call site for exact-match literals.
    return (str(s or "")).replace("\\", "").replace(";", "").strip()[:maxlen]


@app.get("/api/analytics/replenish-options")
def analytics_replenish_options(mode: str = Query(default="style"),
                                q: str = Query(default="")):
    # Typeahead options for the Replenish-by-Item picker. mode='style' returns
    # distinct style names; mode='sku' returns sku + product name + barcode.
    qq = _replen_clean_text(q, 60).lower().replace("'", "")
    like = "%" + qq + "%"
    if mode == "sku":
        rows = run_query(
            "SELECT sku AS value, "
            "COALESCE(NULLIF(product_name, ''), sku) AS label, "
            "COALESCE(barcode, '') AS barcode, "
            "COALESCE(style_name, '') AS style_name "
            "FROM all_products_clean "
            "WHERE LOWER(sku) LIKE '" + like + "' "
            "OR LOWER(COALESCE(product_name, '')) LIKE '" + like + "' "
            "OR LOWER(COALESCE(barcode, '')) LIKE '" + like + "' "
            "ORDER BY product_name NULLS LAST, sku LIMIT 50")
    else:
        rows = run_query(
            "SELECT style_name AS value, style_name AS label, "
            "COUNT(*) AS sku_count "
            "FROM all_products_clean "
            "WHERE style_name IS NOT NULL AND style_name <> '' "
            "AND brand IN ('Vivo', 'Safari', 'Zoya') "
            "AND LOWER(style_name) LIKE '" + like + "' "
            "GROUP BY style_name ORDER BY style_name LIMIT 50")
    return {"mode": "sku" if mode == "sku" else "style", "options": rows}


def _cap_replenish_to_warehouse(rows, *, need_key, out_key,
                                sku_key="sku", wh_key="soh_wh",
                                sold_key="units_sold", loc_key="pos_location"):
    """Cap suggested replenishment so the units recommended for a SKU across all
    stores never exceed that SKU's warehouse stock-on-hand (soh_wh).

    A SKU's finite warehouse units are a shared pool: independently suggesting
    ``need`` for every understocked store double-counts that pool, so the page can
    recommend sending more than the warehouse physically holds. Here each SKU's
    warehouse SOH is ALLOCATED to the TOP-PERFORMING stores first (most units sold
    in the window), then by largest unmet need, then store name for a stable,
    deterministic split. Mutates ``rows`` in place (sets ``out_key``) and returns
    them. Single-store SKUs simply get min(need, soh_wh)."""
    from collections import defaultdict
    groups = defaultdict(list)
    for r in rows:
        groups[r.get(sku_key)].append(r)
    for grp in groups.values():
        # soh_wh is a per-SKU figure (every row in the group should carry the same
        # value); take the max defensively so an upstream NULL/anomaly on one row
        # can't shrink the pool below the SKU's true warehouse stock.
        remaining = max((int(r.get(wh_key) or 0) for r in grp), default=0)
        grp.sort(key=lambda r: (
            -(int(r.get(sold_key) or 0)),
            -(int(r.get(need_key) or 0)),
            str(r.get(loc_key) or ""),
        ))
        for r in grp:
            need = max(0, int(r.get(need_key) or 0))
            alloc = min(need, remaining) if remaining > 0 else 0
            r[out_key] = alloc
            remaining -= alloc
    return rows


def _largest_remainder(weights, total):
    """Apportion ``total`` integer units across keys proportional to their weight
    using the largest-remainder (Hamilton) method. Returns {key: units}. Caps are
    NOT applied here — callers that need per-key headroom use _weighted_capped_alloc."""
    total = int(total)
    out = {k: 0 for k in weights}
    if total <= 0:
        return out
    sw = sum(max(0.0, float(v)) for v in weights.values())
    if sw <= 0:
        return out
    raw = {k: (max(0.0, float(v)) / sw) * total for k, v in weights.items()}
    out = {k: int(v) for k, v in raw.items()}
    leftover = total - sum(out.values())
    for k in sorted(raw.keys(), key=lambda k: -(raw[k] - out[k]))[:max(0, leftover)]:
        out[k] += 1
    return out


def _weighted_capped_alloc(rows, weights, remaining, out_key):
    """Distribute ``remaining`` units across ``rows`` proportional to each row's
    weight, capped at each row's residual headroom, iterating until the pool is
    exhausted or every claimant is at its cap. weights[id(r)] = (weight, cap).
    Mutates out_key on each row; returns the unspent remainder."""
    remaining = int(remaining)
    caps = {id(r): max(0, int(weights[id(r)][1])) for r in rows}
    ws = {id(r): max(0.0, float(weights[id(r)][0])) for r in rows}
    alloc = {id(r): 0 for r in rows}
    active = [r for r in rows if caps[id(r)] > 0 and ws[id(r)] > 0]
    while remaining > 0 and active:
        tot_w = sum(ws[id(r)] for r in active)
        if tot_w <= 0:
            break
        share = _largest_remainder({id(r): ws[id(r)] for r in active}, remaining)
        progressed = 0
        for r in active:
            give = min(share.get(id(r), 0), caps[id(r)] - alloc[id(r)])
            if give > 0:
                alloc[id(r)] += give
                remaining -= give
                progressed += give
        active = [r for r in active if caps[id(r)] - alloc[id(r)] > 0]
        if progressed == 0:
            # Rounding stalled (every proportional share floored to 0 below its
            # cap): hand one unit to the highest-weight claimant with headroom so
            # the loop always makes progress.
            if active and remaining > 0:
                top = max(active, key=lambda r: ws[id(r)])
                alloc[id(top)] += 1
                remaining -= 1
            else:
                break
    for r in rows:
        r[out_key] = alloc[id(r)]
    return remaining


def _allocate_replenishment_fair_share(rows, cfg, margin_map, *,
                                       sku_key="sku", wh_key="soh_wh",
                                       need_key="need", out_key="replenish"):
    """Phase 3 step 1 — one fair-share allocation pass per SKU, replacing the
    legacy greedy top-seller rationing for the SOR pick list.

    Each SKU's finite warehouse pool (soh_wh, shared across every claimant) is
    allocated in two tiers:

      Tier 1 — physical STORES only (Online has no shelf facing): protect each
        store's presentation minimum (class floor gap) and its need-to-next-
        dispatch cover, capped by the line's total need. If the pool can't even
        cover the summed Tier-1 demand, it is split fair-share by Tier-1 weight
        (largest-remainder) and EVERY line is flagged a buying/IBT shortfall.
      Tier 2 — whatever's left is distributed across ALL claimants (stores AND
        Online) by weight = demand_share x margin x sub_factor, capped at each
        line's residual need. Online competes ONLY here, so it can never pre-empt
        a store's presentation minimum.

    demand_share is the line's recency-weighted velocity (units_sold fallback);
    margin = (price-cost)/price from the product master (neutral 1.0 when
    unknown — note it is per-SKU so it is constant within a pool and only shifts
    weights when a future cross-SKU budget is added; the live channel lever is
    sub_factor). Mutates each row: out_key, wh_constrained, shortfall_units,
    route_to_buying, tier1_shortfall, alloc_tier1, alloc_tier2."""
    from collections import defaultdict
    sub_factor = max(0.0, float(cfg.get("sub_factor", 1.0) or 0.0))
    online_sub = max(0.0, float(cfg.get("online_sub_factor", sub_factor) or 0.0))
    dispatch_wk = REPLEN_DISPATCH_DAYS / 7.0
    groups = defaultdict(list)
    for r in rows:
        groups[r.get(sku_key)].append(r)
    for sku, grp in groups.items():
        remaining = max((int(r.get(wh_key) or 0) for r in grp), default=0)
        for r in grp:
            r[out_key] = 0
            r["alloc_tier1"] = 0
            r["alloc_tier2"] = 0
        # ---- Tier 1: store presentation minimum + need-to-next-dispatch -------
        store_lines = [r for r in grp if r.get("pos_location") != ONLINE_SHOP_ZETU]
        t1 = {}
        for r in store_lines:
            need = max(0, int(r.get(need_key) or 0))
            floor_gap = max(0, int(r.get("floor") or 0) - int(r.get("soh_store") or 0))
            v = float(r.get("velocity") or 0.0)
            disp_cover = -(-int(round(v * dispatch_wk * 100)) // 100) if v > 0 else 0
            disp_gap = max(0, disp_cover - int(r.get("soh_store") or 0))
            t1[id(r)] = min(need, max(floor_gap, disp_gap))
        total_t1 = sum(t1.values())
        tier1_short = False
        if total_t1 > 0 and remaining >= total_t1:
            for r in store_lines:
                r["alloc_tier1"] = t1[id(r)]
            remaining -= total_t1
        elif total_t1 > 0:
            # Even Tier 1 is under-funded → fair-share by Tier-1 weight; flag all.
            tier1_short = True
            share = _largest_remainder({id(r): t1[id(r)] for r in store_lines},
                                       remaining)
            for r in store_lines:
                r["alloc_tier1"] = min(t1[id(r)], share.get(id(r), 0))
            remaining = 0
        # ---- Tier 2: remainder by demand_share x margin x sub_factor ----------
        if remaining > 0:
            margin = float(margin_map.get(sku, 1.0) or 1.0)
            weights = {}
            claim = []
            for r in grp:
                residual = max(0, int(r.get(need_key) or 0) - int(r["alloc_tier1"]))
                if residual <= 0:
                    continue
                v = float(r.get("velocity") or 0.0)
                ds = v if v > 0 else float(int(r.get("units_sold") or 0))
                sf = online_sub if r.get("pos_location") == ONLINE_SHOP_ZETU else sub_factor
                w = ds * margin * sf
                if w <= 0:
                    continue
                claim.append(r)
                weights[id(r)] = (w, residual)
            if claim:
                remaining = _weighted_capped_alloc(claim, weights, remaining,
                                                   "alloc_tier2")
        # ---- finalize per line -----------------------------------------------
        for r in grp:
            need = max(0, int(r.get(need_key) or 0))
            a = min(need, int(r["alloc_tier1"]) + int(r["alloc_tier2"]))
            r[out_key] = a
            r["wh_constrained"] = a < need
            r["shortfall_units"] = max(0, need - a)
            r["tier1_shortfall"] = bool(tier1_short)
            r["route_to_buying"] = bool(r["shortfall_units"] > 0)
    return rows


@app.get("/api/analytics/replenish-by-item")
def analytics_replenish_by_item(
    mode: str = Query(default="style"),
    value: str = Query(default=""),
    date_from: str = Query(default=None),
    date_to: str = Query(default=None),
    low_threshold: int = Query(default=2),
):
    # Item-centric allocation: pick one style (all its sizes/colours) or one
    # sku, then list the retail stores that are understocked (current store SOH
    # below ``low_threshold``) while the warehouse still has units to send.
    _warehouse_bins_refresh()
    val = _replen_clean_text(value, 120)
    if not val:
        return {"mode": mode, "value": "", "warehouse_soh": 0, "rows": []}
    if not date_from or not date_to:
        date_to = str(date.today())
        date_from = str(date.today() - timedelta(days=90))
    lit = val.replace("'", "''")
    thr = max(0, int(low_threshold))
    sku_pred = ("sku = '" + lit + "'") if mode == "sku" else ("style_name = '" + lit + "'")
    item_skus = "(SELECT sku FROM all_products_clean WHERE " + sku_pred + ")"

    # Per (store, sku) understocked rows carrying the SAME column set as the main
    # Replenishment list (owner, days-lapsed, product, size, barcode, bin, sold,
    # store SOH, WH SOH, suggested + the mark fields) so this view is a drop-in
    # item-filtered equivalent. A store appears when its SOH for an item SKU is
    # below the threshold while the warehouse still holds units to send.
    rows = run_query("""
        WITH sold AS (
            SELECT s.pos_location_name, s.variant_sku AS sku,
                SUM(s.net_quantity) AS units_sold,
                MAX(s.product_title) AS product_name,
                MAX(s.country) AS country,
                MAX(s.sale_date) AS last_sale
            FROM all_sales s
            WHERE s.sale_kind IN ('sale','order')
              AND s.sale_date BETWEEN '""" + date_from + """' AND '""" + date_to + """'
              AND """ + BASE_FILTERS + """
              AND s.pos_location_name NOT IN (""" + WAREHOUSE_LOCATIONS + """)
              AND (s.pos_location_name NOT ILIKE '%online%'
                   OR s.pos_location_name = 'Online - Shop Zetu')
              AND s.variant_sku IN """ + item_skus + """
            GROUP BY 1, 2
        ),
        store_soh AS (
            SELECT i.pos_location_name, i.sku,
                SUM(i.available) AS soh_store, MAX(i.location_name) AS bin
            FROM all_inventory i
            WHERE i.pos_location_name NOT IN (""" + WAREHOUSE_LOCATIONS + """)
              AND i.sku IN """ + item_skus + """
            GROUP BY 1, 2
        ),
        wh_soh AS (
            SELECT i.sku, SUM(i.available) AS soh_wh
            FROM all_inventory i
            WHERE i.pos_location_name = 'Finished Goods Production'
              AND i.sku IN """ + item_skus + """
            GROUP BY 1
        )
        SELECT COALESCE(sold.pos_location_name, ss.pos_location_name) AS pos_location,
            COALESCE(sold.sku, ss.sku) AS sku,
            COALESCE(sold.units_sold, 0) AS units_sold,
            sold.product_name, sold.country, sold.last_sale,
            COALESCE(ss.soh_store, 0) AS soh_store,
            COALESCE(NULLIF(wb.bin, ''), '') AS bin,
            COALESCE(w.soh_wh, 0) AS soh_wh,
            COALESCE(p.size, '') AS size, COALESCE(p.barcode, '') AS barcode,
            COALESCE(p.color_print, '') AS color_print, COALESCE(p.print_plain, '') AS print_plain,
            COALESCE(p.category, '') AS category,
            p.product_name AS pname
        FROM sold
        FULL OUTER JOIN store_soh ss
          ON ss.pos_location_name = sold.pos_location_name AND ss.sku = sold.sku
        LEFT JOIN wh_soh w ON w.sku = COALESCE(sold.sku, ss.sku)
        LEFT JOIN all_products_clean p ON p.sku = COALESCE(sold.sku, ss.sku)
        LEFT JOIN warehouse_bins wb ON wb.barcode = p.barcode
        WHERE COALESCE(ss.soh_store, 0) < """ + str(thr) + """
          AND COALESCE(w.soh_wh, 0) > 0
    """)
    # Warehouse SOH is computed independently of the understock rows so the
    # header signal is correct even when no store is currently understocked.
    wh_rows = run_query("""
        SELECT COALESCE(SUM(i.available), 0) AS soh_wh
        FROM all_inventory i
        WHERE i.pos_location_name = 'Finished Goods Production'
          AND i.sku IN """ + item_skus + """
    """)
    wh_soh = int((wh_rows[0]["soh_wh"] if wh_rows else 0) or 0)
    store_map = _replen_store_owner_map()
    marks_all = _replen_marks()
    today = date.today()
    out = []
    for r in rows:
        st = r.get("pos_location") or ""
        if st.lower().find("online") >= 0 and st != "Online - Shop Zetu":
            continue
        soh = int(r["soh_store"] or 0)
        units = int(r["units_sold"] or 0)
        soh_wh = int(r["soh_wh"] or 0)
        barcode = r.get("barcode") or ""
        sku = r.get("sku")
        days_lapsed = None
        if r.get("last_sale"):
            try:
                days_lapsed = (today - date.fromisoformat(str(r["last_sale"])[:10])).days
            except ValueError:
                days_lapsed = None
        mark = (marks_all.get((st, "sku", sku))
                or marks_all.get((st, "barcode", barcode)) or {})
        out.append({
            "pos_location": st, "sku": sku, "barcode": barcode,
            "product_name": r.get("pname") or r.get("product_name") or "",
            "size": r.get("size") or "", "bin": r.get("bin") or "",
            "color_print": r.get("color_print") or "", "print_plain": r.get("print_plain") or "",
            "category": r.get("category") or "",
            "country": r.get("country"),
            "units_sold": units, "soh_store": soh, "soh_wh": soh_wh,
            "suggested_units": max(thr - soh, 0),
            "days_lapsed": days_lapsed,
            "last_sale": str(r["last_sale"]) if r.get("last_sale") else None,
            "replenished": bool(mark.get("replenished", False)),
            "actual_units_replenished": int(mark.get("actual_units_replenished", 0)),
            "transfer_ref": mark.get("transfer_ref") or "",
        })
    # Demand-aware mark expiry: resurface done lines with a genuine post-mark gap.
    _resurface_stale_marks(out, marks_all)
    # Allocate each SKU's warehouse pool across stores (top sellers first) so the
    # suggested total per SKU never exceeds its warehouse stock.
    _cap_replenish_to_warehouse(out, need_key="suggested_units", out_key="suggested_units")
    # Drop rows the warehouse pool can no longer cover (suggested capped to 0) — a
    # zero-unit suggestion is not actionable and must not appear in the list.
    out = [r for r in out if int(r.get("suggested_units") or 0) > 0]
    _owners = _replen_owners()
    for row in out:
        row["owner"] = _owner_for_store(row.get("pos_location"), store_map, _owners)
    out.sort(key=lambda x: (x["units_sold"], -x["soh_store"]), reverse=True)
    return {"mode": "sku" if mode == "sku" else "style", "value": val,
            "warehouse_soh": wh_soh, "date_from": date_from, "date_to": date_to,
            "low_threshold": thr, "rows": out}


@app.get("/api/analytics/replenish-gaps")
def analytics_replenish_gaps(
    store: str = Query(default=""),
    date_from: str = Query(default=None),
    date_to: str = Query(default=None),
    low_threshold: int = Query(default=2),
    limit: int = Query(default=20000),
):
    # Store-centric gap finder: items a store SOLD in the window but barely
    # stocks now (store SOH below ``low_threshold``) while the warehouse has
    # units to send — i.e. proven local demand the store can't currently serve.
    # ``limit`` is a SAFETY bound only (default 20k covers the full ~3k gap
    # universe with plenty of headroom). The SQL applies the low-stock +
    # warehouse filters BEFORE the LIMIT, but a small cap (the old 300) ranked
    # by units sold silently starved slower-selling yet valid gaps — so the
    # default must stay far above the realistic row count, and any hit of the
    # cap is reported via ``truncated``/``row_cap`` in the response.
    _warehouse_bins_refresh()
    st = _replen_clean_text(store, 120)
    if not st:
        return {"store": "", "rows": [], "truncated": False, "row_cap": 0}
    if not date_from or not date_to:
        date_to = str(date.today())
        date_from = str(date.today() - timedelta(days=90))
    thr = max(0, int(low_threshold))
    lim = max(1, min(int(limit), 50000))
    # "__all__" = every selling store at once (one row per store × sku). Warehouses
    # are excluded and online channels are dropped except Online - Shop Zetu, matching
    # the cross-store replenishment report. A single store name uses an exact match.
    all_stores = (st == "__all__")
    if all_stores:
        rows = run_query("""
            WITH sold AS (
                SELECT s.pos_location_name AS pos_location, s.variant_sku AS sku,
                    SUM(s.net_quantity) AS units_sold,
                    MAX(s.product_title) AS product_name,
                    MAX(s.sale_date) AS last_sale
                FROM all_sales s
                WHERE s.sale_kind IN ('sale','order')
                  AND s.sale_date BETWEEN '""" + date_from + """' AND '""" + date_to + """'
                  AND """ + BASE_FILTERS + """
                  AND s.pos_location_name NOT IN (""" + WAREHOUSE_LOCATIONS + """)
                  AND (s.pos_location_name NOT ILIKE '%online%'
                       OR s.pos_location_name = 'Online - Shop Zetu')
                  AND s.variant_sku IS NOT NULL AND s.variant_sku <> ''
                GROUP BY s.pos_location_name, s.variant_sku
                HAVING SUM(s.net_quantity) > 0
            ),
            store_soh AS (
                SELECT i.pos_location_name, i.sku, SUM(i.available) AS soh, MAX(i.location_name) AS bin
                FROM all_inventory i
                WHERE i.pos_location_name NOT IN (""" + WAREHOUSE_LOCATIONS + """)
                GROUP BY i.pos_location_name, i.sku
            ),
            wh_soh AS (
                SELECT i.sku, SUM(i.available) AS soh_wh
                FROM all_inventory i
                WHERE i.pos_location_name = 'Warehouse Finished Goods'
                GROUP BY i.sku
            )
            SELECT sold.pos_location, sold.sku, COALESCE(NULLIF(p.product_name, ''), sold.product_name) AS product_name, sold.units_sold, sold.last_sale,
                COALESCE(ss.soh, 0) AS soh_store,
                COALESCE(NULLIF(wb.bin, ''), '') AS bin,
                COALESCE(w.soh_wh, 0) AS soh_wh,
                COALESCE(p.style_name, '') AS style_name,
                COALESCE(p.size, '') AS size, COALESCE(p.barcode, '') AS barcode,
                COALESCE(p.color_print, '') AS color_print, COALESCE(p.print_plain, '') AS print_plain,
                COALESCE(p.category, '') AS category
            FROM sold
            LEFT JOIN store_soh ss ON ss.pos_location_name = sold.pos_location AND ss.sku = sold.sku
            LEFT JOIN wh_soh w ON w.sku = sold.sku
            LEFT JOIN all_products_clean p ON p.sku = sold.sku
            LEFT JOIN warehouse_bins wb ON wb.barcode = p.barcode
            WHERE COALESCE(ss.soh, 0) < """ + str(thr) + """ AND COALESCE(w.soh_wh, 0) > 0
            ORDER BY sold.units_sold DESC
            LIMIT """ + str(lim))
    else:
        lit = st.replace("'", "''")
        rows = run_query("""
            WITH sold AS (
                SELECT s.variant_sku AS sku,
                    SUM(s.net_quantity) AS units_sold,
                    MAX(s.product_title) AS product_name,
                    MAX(s.sale_date) AS last_sale
                FROM all_sales s
                WHERE s.sale_kind IN ('sale','order')
                  AND s.sale_date BETWEEN '""" + date_from + """' AND '""" + date_to + """'
                  AND s.pos_location_name = '""" + lit + """'
                  AND """ + BASE_FILTERS + """
                  AND s.variant_sku IS NOT NULL AND s.variant_sku <> ''
                GROUP BY s.variant_sku
                HAVING SUM(s.net_quantity) > 0
            ),
            store_soh AS (
                SELECT i.sku, SUM(i.available) AS soh, MAX(i.location_name) AS bin
                FROM all_inventory i
                WHERE i.pos_location_name = '""" + lit + """'
                GROUP BY i.sku
            ),
            wh_soh AS (
                SELECT i.sku, SUM(i.available) AS soh_wh
                FROM all_inventory i
                WHERE i.pos_location_name = 'Warehouse Finished Goods'
                GROUP BY i.sku
            )
            SELECT sold.sku, COALESCE(NULLIF(p.product_name, ''), sold.product_name) AS product_name, sold.units_sold, sold.last_sale,
                COALESCE(ss.soh, 0) AS soh_store,
                COALESCE(NULLIF(wb.bin, ''), '') AS bin,
                COALESCE(w.soh_wh, 0) AS soh_wh,
                COALESCE(p.style_name, '') AS style_name,
                COALESCE(p.size, '') AS size, COALESCE(p.barcode, '') AS barcode,
                COALESCE(p.color_print, '') AS color_print, COALESCE(p.print_plain, '') AS print_plain,
                COALESCE(p.category, '') AS category
            FROM sold
            LEFT JOIN store_soh ss ON ss.sku = sold.sku
            LEFT JOIN wh_soh w ON w.sku = sold.sku
            LEFT JOIN all_products_clean p ON p.sku = sold.sku
            LEFT JOIN warehouse_bins wb ON wb.barcode = p.barcode
            WHERE COALESCE(ss.soh, 0) < """ + str(thr) + """ AND COALESCE(w.soh_wh, 0) > 0
            ORDER BY sold.units_sold DESC
            LIMIT """ + str(lim))
    store_map = _replen_store_owner_map()
    _owners = _replen_owners()
    marks_all = _replen_marks()
    today = date.today()
    out = []
    for idx, r in enumerate(rows):
        loc = (r.get("pos_location") or "") if all_stores else st
        soh = int(r["soh_store"] or 0)
        soh_wh = int(r["soh_wh"] or 0)
        barcode = r.get("barcode") or ""
        sku = r["sku"]
        days_lapsed = None
        if r.get("last_sale"):
            try:
                days_lapsed = (today - date.fromisoformat(str(r["last_sale"])[:10])).days
            except ValueError:
                days_lapsed = None
        mark = (marks_all.get((loc, "sku", sku))
                or marks_all.get((loc, "barcode", barcode)) or {})
        out.append({
            "pos_location": loc, "owner": _owner_for_store(loc, store_map, _owners),
            "sku": sku, "barcode": barcode,
            "product_name": r.get("product_name") or "",
            "style_name": r.get("style_name") or "", "size": r.get("size") or "",
            "bin": r.get("bin") or "",
            "color_print": r.get("color_print") or "", "print_plain": r.get("print_plain") or "",
            "category": r.get("category") or "",
            "units_sold": int(r["units_sold"] or 0), "soh_store": soh,
            "soh_wh": soh_wh,
            "suggested_units": max(thr - soh, 0),
            "days_lapsed": days_lapsed,
            "last_sale": str(r["last_sale"]) if r.get("last_sale") else None,
            "replenished": bool(mark.get("replenished", False)),
            "actual_units_replenished": int(mark.get("actual_units_replenished", 0)),
            "transfer_ref": mark.get("transfer_ref") or "",
        })
    # Demand-aware mark expiry: resurface done lines with a genuine post-mark gap.
    _resurface_stale_marks(out, marks_all)
    # Allocate each SKU's warehouse pool across stores (top sellers first) so the
    # suggested total per SKU never exceeds its warehouse stock.
    _cap_replenish_to_warehouse(out, need_key="suggested_units", out_key="suggested_units")
    # Drop rows the warehouse pool can no longer cover (suggested capped to 0) — a
    # zero-unit suggestion is not actionable and must not appear in the list.
    out = [r for r in out if int(r.get("suggested_units") or 0) > 0]
    # Truncation is reported when the SQL safety cap was actually hit — the
    # only case where qualifying rows could have been cut before allocation.
    return {"store": st, "date_from": date_from, "date_to": date_to,
            "low_threshold": thr, "rows": out,
            "truncated": len(rows) >= lim, "row_cap": lim}


# Shared XLSX column set for the Replenish by Style / SKU exports — mirrors the
# ReplenTable columns shown in the UI for both the By Item and Store Gaps views.
def _replen_colour_print(r):
    # Colour only — the colour name (color_print) is the meaningful descriptor;
    # the generic print_plain ("Print"/"Plain") is dropped per ops request.
    return (r.get("color_print") or "").strip()


_REPLEN_ITEM_XLSX_COLS = [
    "Owner", "Store", "Days Lapsed", "Last Sold", "Product", "Category", "Size",
    "Barcode", "Bin", "Colour", "Units Sold", "Store SOH", "WH SOH",
    "Suggested", "Actual Replenished", "Transfer Ref",
]


def _replen_item_xlsx_row(r):
    return [
        r.get("owner") or "—", r.get("pos_location") or "",
        r.get("days_lapsed") if r.get("days_lapsed") is not None else "",
        (str(r.get("last_sale"))[:10] if r.get("last_sale") else ""),
        r.get("product_name") or "", r.get("category") or "",
        r.get("size") or "",
        r.get("barcode") or "", r.get("bin") or "",
        _replen_colour_print(r),
        int(r.get("units_sold") or 0), int(r.get("soh_store") or 0),
        int(r.get("soh_wh") or 0), int(r.get("suggested_units") or 0),
        int(r.get("actual_units_replenished") or 0), r.get("transfer_ref") or "",
    ]


@app.get("/api/analytics/replenish-by-item/export")
def analytics_replenish_by_item_export(
    mode: str = Query(default="style"),
    value: str = Query(default=""),
    date_from: str = Query(default=None),
    date_to: str = Query(default=None),
    low_threshold: int = Query(default=2),
):
    # Excel export of the By Item replenishment view. Reuses the JSON endpoint's
    # row builder verbatim (no SQL duplication) and writes the same columns the
    # UI table shows.
    from openpyxl import Workbook
    data = analytics_replenish_by_item(
        mode=mode, value=value, date_from=date_from, date_to=date_to,
        low_threshold=low_threshold)
    rows = data.get("rows", [])
    wb = Workbook()
    ws = wb.active
    ws.title = _xlsx_sheet_title(
        ("SKU " if mode == "sku" else "Style ") + (data.get("value") or "Replenish"),
        set())
    _xlsx_header(ws, _REPLEN_ITEM_XLSX_COLS)
    for r in rows:
        ws.append(_replen_item_xlsx_row(r))
    safe = re.sub(r"[^A-Za-z0-9._-]+", "_", (data.get("value") or "item")).strip("_") or "item"
    label = "SKU" if mode == "sku" else "Style"
    return _xlsx_response(
        wb, f"Replenish_By_{label}_{safe}_{date.today().isoformat()}.xlsx")


@app.get("/api/analytics/replenish-gaps/export")
def analytics_replenish_gaps_export(
    store: str = Query(default=""),
    date_from: str = Query(default=None),
    date_to: str = Query(default=None),
    low_threshold: int = Query(default=2),
    limit: int = Query(default=50000),
):
    # Excel export of the Store Gaps view — same reuse pattern as By Item.
    # The export must always contain the FULL qualifying set, so its default
    # limit is pinned to the endpoint's maximum safety cap (50k), independent
    # of whatever page size the UI displays.
    from openpyxl import Workbook
    data = analytics_replenish_gaps(
        store=store, date_from=date_from, date_to=date_to,
        low_threshold=low_threshold, limit=limit)
    rows = data.get("rows", [])
    st = data.get("store") or "store"
    title = "All Stores" if st == "__all__" else st
    wb = Workbook()
    ws = wb.active
    ws.title = _xlsx_sheet_title("Gaps " + title, set())
    _xlsx_header(ws, _REPLEN_ITEM_XLSX_COLS)
    for r in rows:
        ws.append(_replen_item_xlsx_row(r))
    safe = re.sub(r"[^A-Za-z0-9._-]+", "_", title).strip("_") or "store"
    return _xlsx_response(
        wb, f"Replenish_Gaps_{safe}_{date.today().isoformat()}.xlsx")


def _replen_item_history(q, store="", date_from="", date_to=""):
    """Pick-list history tracker for one item ("why didn't store X get item Y?").

    Given a SKU, barcode or style-name query, returns every appearance of the
    item on the SOR pick-list snapshots (fact_replen_suggestion) — one row per
    (business_date, store, sku), preferring the canonical 4-week demand-window
    run when several runs exist for a day — joined to the done marks from the
    recommendation_actions ledger.

    Done-mark attribution: a mark only keeps its LATEST state (twin sku/barcode
    rows, dedup'd here to the canonical SKU), so it is attributed to the MOST
    RECENT list date on/before the mark's EAT acted-at day for that (store,
    item); earlier appearances are shown as not picked. The item is passed as a
    query parameter (never a path segment) because SKUs contain slashes.
    """
    _ensure_replen_tables()
    qn = _replen_clean_text(q, 120)
    if not qn:
        return {"query": "", "rows": [], "found_item": False, "appeared": False,
                "summary": None}
    like = "%" + qn + "%"
    sugg = _users_exec(
        "SELECT DISTINCT ON (business_date, pos_location, sku) "
        " business_date::text AS business_date, pos_location, sku, "
        " COALESCE(barcode,'') AS barcode, COALESCE(style_name,'') AS style_name, "
        " COALESCE(size,'') AS size, COALESCE(demand_weeks,0) AS demand_weeks, "
        " COALESCE(suggested_qty,0) AS suggested_qty, deploy_now "
        "FROM fact_replen_suggestion "
        "WHERE upper(sku)=upper(%s) "
        "   OR (COALESCE(barcode,'')<>'' AND barcode=%s) "
        "   OR style_name ILIKE %s "
        "ORDER BY business_date, pos_location, sku, "
        " CASE WHEN demand_weeks=4 THEN 0 ELSE 1 END",
        (qn, qn, like), fetch=True) or []

    # Does the item exist in the product master at all? Distinguishes "never on
    # any replenishment list" from "no such item".
    lit = _sql_str(qn)
    prod = run_query(
        "SELECT sku, COALESCE(product_name,'') AS product_name, "
        " COALESCE(style_name,'') AS style_name, COALESCE(barcode,'') AS barcode "
        "FROM all_products_clean "
        "WHERE upper(sku)=upper('" + lit + "') OR barcode='" + lit + "' "
        "   OR style_name ILIKE '%" + lit + "%' LIMIT 200") or []
    found_item = bool(prod) or bool(sugg)
    prod_by_sku = {p["sku"]: p for p in prod}

    if not sugg:
        return {"query": qn, "rows": [], "found_item": found_item,
                "appeared": False,
                "item_label": (prod[0]["style_name"] or prod[0]["product_name"]) if prod else "",
                "summary": None}

    # Group appearances per (store, canonical sku); collect twin rec_keys.
    groups = {}
    rec_keys = set()
    for r in sugg:
        key = (r["pos_location"], r["sku"])
        groups.setdefault(key, []).append(r)
        rec_keys.add(f"{r['pos_location']}|sku|{r['sku']}")
        if r["barcode"]:
            rec_keys.add(f"{r['pos_location']}|barcode|{r['barcode']}")
    marks = {}
    if rec_keys:
        mrows = _users_exec(
            "SELECT rec_key, COALESCE(actual_units,0) AS actual_units, "
            " COALESCE(transfer_ref,'') AS transfer_ref, "
            " COALESCE(acted_by,'') AS acted_by, acted_at, "
            " (acted_at AT TIME ZONE 'Africa/Nairobi')::date::text AS acted_day "
            "FROM recommendation_actions "
            "WHERE rec_type='replenish' AND status='done' AND rec_key = ANY(%s)",
            (list(rec_keys),), fetch=True) or []
        for m in mrows:
            parts = (m["rec_key"] or "").split("|", 2)
            if len(parts) == 3:
                marks[(parts[0], parts[1], parts[2])] = m

    out = []
    for (pos, sku), rows_ in groups.items():
        barcode = next((r["barcode"] for r in rows_ if r["barcode"]), "")
        # Twin-row dedup: prefer the sku-kind mark, fall back to barcode-kind.
        mark = marks.get((pos, "sku", sku)) or (
            marks.get((pos, "barcode", barcode)) if barcode else None)
        done_date = None
        if mark and mark.get("acted_day"):
            qualifying = [r["business_date"] for r in rows_
                          if r["business_date"] <= mark["acted_day"]]
            done_date = max(qualifying) if qualifying else None
        for r in rows_:
            is_done = bool(mark) and r["business_date"] == done_date
            p = prod_by_sku.get(sku) or {}
            out.append({
                "business_date": r["business_date"],
                "pos_location": pos,
                "sku": sku,
                "barcode": barcode,
                "style_name": r["style_name"] or p.get("style_name") or "",
                "product_name": p.get("product_name") or "",
                "size": r["size"],
                "demand_weeks": int(r["demand_weeks"] or 0),
                "suggested_qty": int(r["suggested_qty"] or 0),
                "deploy_now": bool(r["deploy_now"]),
                "done": is_done,
                "actual_units": int(mark["actual_units"]) if is_done else 0,
                "transfer_ref": (mark["transfer_ref"] or "") if is_done else "",
                "acted_by": (mark["acted_by"] or "") if is_done else "",
                "acted_at": str(mark["acted_at"]) if (is_done and mark.get("acted_at")) else "",
            })
    out.sort(key=lambda x: (x["business_date"], x["pos_location"]), reverse=True)
    label = out[0]["style_name"] or out[0]["product_name"] or out[0]["sku"]

    # Full (unfiltered) store list so the frontend dropdown keeps every option
    # even while a store filter is active.
    all_stores = sorted({r["pos_location"] for r in out})

    # Optional post-filters (store dropdown + date range). business_date is an
    # ISO yyyy-mm-dd string, so lexicographic compare is date compare. Dates
    # are validated to the ISO shape; anything else is ignored.
    store = _replen_clean_text(store, 120)
    date_from = date_from if re.fullmatch(r"\d{4}-\d{2}-\d{2}", date_from or "") else ""
    date_to = date_to if re.fullmatch(r"\d{4}-\d{2}-\d{2}", date_to or "") else ""
    if store:
        out = [r for r in out if r["pos_location"] == store]
    if date_from:
        out = [r for r in out if r["business_date"] >= date_from]
    if date_to:
        out = [r for r in out if r["business_date"] <= date_to]

    dates = {r["business_date"] for r in out}
    stores = {r["pos_location"] for r in out}
    done_n = sum(1 for r in out if r["done"])
    summary = {
        "dates": len(dates), "stores": len(stores),
        "store_days": len(out), "done": done_n,
        "not_done": len(out) - done_n,
        "first_date": min(dates) if dates else None,
        "last_date": max(dates) if dates else None,
    } if out else None
    return {"query": qn, "rows": out, "found_item": True, "appeared": True,
            "item_label": label, "all_stores": all_stores, "summary": summary}


@app.get("/api/analytics/replenishment-item-history")
def analytics_replenishment_item_history(
        q: str = Query(default=""), store: str = Query(default=""),
        date_from: str = Query(default=""), date_to: str = Query(default="")):
    return _replen_item_history(q, store=store, date_from=date_from,
                                date_to=date_to)


_REPLEN_HISTORY_XLSX_COLS = [
    "List Date", "Store", "Product / Style", "Size", "SKU", "Barcode",
    "Window (wks)", "Suggested", "Deploy Now", "Done", "Actual Units",
    "Transfer Ref", "Marked By", "Marked At",
]


@app.get("/api/analytics/replenishment-item-history/export")
def analytics_replenishment_item_history_export(
        q: str = Query(default=""), store: str = Query(default=""),
        date_from: str = Query(default=""), date_to: str = Query(default="")):
    # Excel export of the Track-an-item history — reuses the JSON builder
    # verbatim (no SQL duplication, same store/date filters), same pattern as
    # the other replen exports.
    from openpyxl import Workbook
    data = _replen_item_history(q, store=store, date_from=date_from,
                                date_to=date_to)
    wb = Workbook()
    ws = wb.active
    ws.title = _xlsx_sheet_title("Item History", set())
    _xlsx_header(ws, _REPLEN_HISTORY_XLSX_COLS)
    for r in data.get("rows", []):
        ws.append([
            r["business_date"], r["pos_location"],
            r["style_name"] or r["product_name"], r["size"],
            r["sku"], r["barcode"], r["demand_weeks"], r["suggested_qty"],
            "Yes" if r["deploy_now"] else "", "Done" if r["done"] else "Not picked",
            r["actual_units"] if r["done"] else "",
            r["transfer_ref"], r["acted_by"],
            (r["acted_at"][:16] if r["acted_at"] else ""),
        ])
    safe = re.sub(r"[^A-Za-z0-9._-]+", "_", (data.get("query") or "item")).strip("_") or "item"
    return _xlsx_response(
        wb, f"Replen_Item_History_{safe}_{date.today().isoformat()}.xlsx")


# ── Replenishment SOR engine (Phase 1) ───────────────────────────────────────
# Days to the next dispatch slot used to bound the conservative projected-SOR
# uplift (spec §7/§10). Kenya metro runs ~2×/week, so the next slot is ~3.5 days
# out — the shorter the horizon, the smaller (more conservative) the uplift cap.
REPLEN_DISPATCH_DAYS = 3.5


def _replen_run_id(business_date, store_scope, ruleset_version, demand_weeks):
    """run_id = sha1(business_date_EAT | store_scope | ruleset_version | demand_weeks)
    (spec §10), so re-stamping the same day's suggestions upserts onto one immutable
    run rather than duplicating, a ruleset change starts a fresh run, AND each demand
    window (4/8/12w) gets its OWN run so toggling lookback can never overwrite the
    canonical 4w snapshot's rows."""
    import hashlib
    raw = "|".join([str(business_date), str(store_scope),
                    str(ruleset_version), str(demand_weeks)])
    return hashlib.sha1(raw.encode("utf-8")).hexdigest()


def _replen_eat_today():
    from datetime import datetime, timezone
    return (datetime.now(timezone.utc) + timedelta(hours=3)).date()


def _replen_class_floor(vpw, cfg=None):
    """A/B/C velocity class + presentation-minimum facing (spec §4), against the
    configurable cut-offs/floors (defaults from the module constants)."""
    cfg = cfg or _REPLEN_SIZING_DEFAULTS
    if vpw >= cfg["class_a_vpw"]:
        return "A", int(cfg["floor_a"])
    if vpw >= cfg["class_b_vpw"]:
        return "B", int(cfg["floor_b"])
    return "C", int(cfg["floor_c"])


def _replen_holdback_overrides():
    """{(pos_location, sku): action} merch overrides for the Held-back panel."""
    rows = _users_exec(
        "SELECT pos_location, sku, action FROM replen_holdback_override",
        fetch=True) or []
    return {(r["pos_location"], r["sku"]): (r.get("action") or "release")
            for r in rows}


def _replen_sor_summary(weeks, overstock_woc=REPLEN_OVERSTOCK_WOC):
    """Canonical headline SOR + the additive 'saleable SOR' over the named
    trailing demand window (spec §3) — warehouse excluded, unit-weighted across
    pools (a single SUM over every pool IS the unit-weighted roll-up). The base
    formula units_sold*100/(units_sold+store_stock) is UNCHANGED; saleable SOR
    only nets broken-curve orphan stock out of the denominator and is shown
    ALONGSIDE the headline, never replacing it. Also returns the SOR-drag
    (overstock) store units for the KPI strip."""
    days = int(weeks) * 7
    rows = run_query("""
        WITH sold AS (
            SELECT s.variant_sku AS sku, SUM(s.net_quantity) AS u
            FROM all_sales s
            WHERE s.sale_kind IN ('sale','order')
              AND s.sale_date >= (CURRENT_DATE - INTERVAL '""" + str(days) + """ days')::text
              AND """ + BASE_FILTERS + """
              AND s.pos_location_name NOT IN (""" + WAREHOUSE_LOCATIONS + """)
              AND (s.pos_location_name NOT ILIKE '%online%'
                   OR s.pos_location_name = 'Online - Shop Zetu')
              AND s.variant_sku IS NOT NULL AND s.variant_sku <> ''
            GROUP BY 1
            HAVING SUM(s.net_quantity) > 0
        ),
        soh AS (
            SELECT i.pos_location_name, i.sku, p.style_name,
                   SUM(i.available) AS soh
            FROM all_inventory i
            JOIN all_products_clean p ON p.sku = i.sku
            WHERE i.pos_location_name NOT IN (""" + WAREHOUSE_LOCATIONS + """)
              AND COALESCE(p.style_name,'') <> ''
            GROUP BY 1,2,3
            HAVING SUM(i.available) > 0
        ),
        store_style AS (
            SELECT pos_location_name, style_name,
                   COUNT(*) AS in_stock_sizes, SUM(soh) AS soh_style
            FROM soh GROUP BY 1,2
        ),
        catalog AS (
            SELECT style_name, COUNT(DISTINCT NULLIF(size,'')) AS curve_sizes
            FROM all_products_clean WHERE COALESCE(style_name,'') <> ''
            GROUP BY 1
        ),
        store_sku_sold AS (
            SELECT s.pos_location_name, s.variant_sku, SUM(s.net_quantity) AS u
            FROM all_sales s
            WHERE s.sale_kind IN ('sale','order')
              AND s.sale_date >= (CURRENT_DATE - INTERVAL '""" + str(days) + """ days')::text
              AND """ + BASE_FILTERS + """
              AND s.pos_location_name NOT IN (""" + WAREHOUSE_LOCATIONS + """)
              AND s.variant_sku IS NOT NULL AND s.variant_sku <> ''
            GROUP BY 1,2 HAVING SUM(s.net_quantity) > 0
        )
        SELECT
          COALESCE((SELECT SUM(u) FROM sold),0) AS units_sold,
          COALESCE((SELECT SUM(soh) FROM soh),0) AS store_stock,
          COALESCE((SELECT SUM(ss.soh_style)
                    FROM store_style ss JOIN catalog c ON c.style_name = ss.style_name
                    WHERE ss.in_stock_sizes <= 1 AND c.curve_sizes >= 3),0) AS orphan_stock,
          COALESCE((SELECT SUM(sk.soh)
                    FROM soh sk LEFT JOIN store_sku_sold sss
                      ON sss.pos_location_name = sk.pos_location_name
                     AND sss.variant_sku = sk.sku
                    WHERE sk.soh::numeric * """ + str(int(weeks)) + """
                          > """ + str(float(overstock_woc)) + """ * COALESCE(sss.u,0)
                      AND COALESCE(sss.u,0) >= 0
                      AND sk.soh > 0),0) AS drag_stock
    """) or [{}]
    r = rows[0] if rows else {}
    u = float(r.get("units_sold") or 0)
    st_gross = float(r.get("store_stock") or 0)
    orphan = float(r.get("orphan_stock") or 0)
    drag = float(r.get("drag_stock") or 0)
    # Phase 3 step 3 quarantine: subtract dispatched-but-unconfirmed (in-transit)
    # units from the denominator (clamped >= 0). Odoo validates an internal
    # transfer to the destination store on paper, so all_inventory.available can
    # already include stock physically still in a truck; that inflates store_stock
    # and the line can't actually sell until received. The base SOR FORMULA is
    # unchanged — only its store_stock input is refined to on-the-floor units.
    in_transit = float(_replen_in_transit_total())
    st = max(0.0, st_gross - in_transit)

    def _sor(num, denom_stock):
        d = num + denom_stock
        return round(100.0 * num / d, 1) if d > 0 else 0.0

    return {
        "units_sold": int(u), "store_stock": int(st),
        "store_stock_gross": int(st_gross), "in_transit_units": int(in_transit),
        "orphan_stock": int(orphan), "drag_stock": int(drag),
        "current_sor": _sor(u, st),
        "saleable_sor": _sor(u, max(0.0, st - orphan)),
    }


def _compute_replenishment_sor(weeks=REPLEN_DEMAND_WEEKS_DEFAULT, limit=400):
    """SOR-first replenishment engine (spec §4-§6, §10). Returns a dict with the
    ranked pick list, the Held-back (deliberately-not-moving) panel, the
    deploy-from-warehouse-first set, and the SOR KPI strip. Every decision is at
    store-SKU(-size) grain on the canonical demand window; the proven-demand gate
    means only store-SKUs that SOLD at that store in the window are eligible.

    The base SOR formula is untouched — this only decides WHAT to move so the
    numerator rises (heroes back on the floor) and the denominator is protected
    (slow / EOL / broken-curve stock held back)."""
    weeks = int(weeks) if int(weeks) in REPLEN_DEMAND_WEEKS_ALLOWED else REPLEN_DEMAND_WEEKS_DEFAULT
    days = weeks * 7
    _warehouse_bins_refresh()
    overrides = _replen_holdback_overrides()
    cfg = _replen_sizing_config()
    cover_target_weeks = float(cfg["cover_weeks"])
    online_cover_weeks = float(cfg["online_cover_weeks"])
    overstock_woc = float(cfg["overstock_woc"])
    # Velocity uses the dashboard's shared recency-weighted 28d/56d EWMA proxy
    # (_ewma_weekly) — NOT a flat units/lookback average — so we pull u28/u56 over
    # a FIXED trailing window regardless of the proven-demand lookback (4/8/12w).
    vel_days = max(days, 56)

    # Proven-demand candidate universe: store-SKUs that sold here in the window,
    # with snapshots of current shelf qty (this store) and the shared warehouse
    # pool. We DON'T pre-filter to understocked here (unlike the legacy report) so
    # overstock / broken-curve rows can be surfaced in the Held-back panel. The
    # universe gate (HAVING) is still the lookback window; u28/u56 ride along for
    # the recency-weighted velocity + censored-demand correction.
    rows = run_query("""
        WITH sold AS (
            SELECT s.pos_location_name, s.variant_sku,
                MAX(s.country) AS country,
                MAX(s.product_title) AS product_name,
                SUM(s.net_quantity) FILTER (
                    WHERE s.sale_date >= (CURRENT_DATE - INTERVAL '""" + str(days) + """ days')::text
                ) AS units_sold,
                SUM(s.net_quantity) FILTER (
                    WHERE s.sale_date >= (CURRENT_DATE - INTERVAL '28 days')::text
                ) AS u28,
                SUM(s.net_quantity) FILTER (
                    WHERE s.sale_date >= (CURRENT_DATE - INTERVAL '56 days')::text
                ) AS u56,
                MAX(s.sale_date) AS last_sale
            FROM all_sales s
            WHERE s.sale_kind IN ('sale','order')
              AND s.sale_date >= (CURRENT_DATE - INTERVAL '""" + str(vel_days) + """ days')::text
              AND """ + BASE_FILTERS + """
              AND s.pos_location_name NOT IN (""" + WAREHOUSE_LOCATIONS + """)
              AND (s.pos_location_name NOT ILIKE '%online%'
                   OR s.pos_location_name = '""" + ONLINE_SHOP_ZETU + """')
              AND s.variant_sku IS NOT NULL AND s.variant_sku <> ''
            GROUP BY s.pos_location_name, s.variant_sku
            HAVING SUM(s.net_quantity) FILTER (
                WHERE s.sale_date >= (CURRENT_DATE - INTERVAL '""" + str(days) + """ days')::text
            ) > 0
        ),
        -- Last two DISTINCT sale days per store-SKU over a longer 120-day
        -- window (slow-mover guard: gap between last and second-to-last sale).
        -- sale_date is ISO text so lexicographic DESC ordering is date order.
        last2 AS (
            SELECT s.pos_location_name, s.variant_sku,
                (array_agg(DISTINCT s.sale_date ORDER BY s.sale_date DESC))[1] AS d1,
                (array_agg(DISTINCT s.sale_date ORDER BY s.sale_date DESC))[2] AS d2
            FROM all_sales s
            WHERE s.sale_kind IN ('sale','order')
              AND s.sale_date >= (CURRENT_DATE - INTERVAL '120 days')::text
              AND """ + BASE_FILTERS + """
              AND s.pos_location_name NOT IN (""" + WAREHOUSE_LOCATIONS + """)
              AND (s.pos_location_name NOT ILIKE '%online%'
                   OR s.pos_location_name = '""" + ONLINE_SHOP_ZETU + """')
              AND s.variant_sku IS NOT NULL AND s.variant_sku <> ''
              AND s.net_quantity > 0
            GROUP BY s.pos_location_name, s.variant_sku
        ),
        store_soh AS (
            SELECT i.pos_location_name, i.sku,
                SUM(i.available) AS soh_store, MAX(i.location_name) AS bin
            FROM all_inventory i
            WHERE i.pos_location_name NOT IN (""" + WAREHOUSE_LOCATIONS + """)
            GROUP BY i.pos_location_name, i.sku
        ),
        wh_soh AS (
            SELECT i.sku, SUM(i.available) AS soh_wh
            FROM all_inventory i
            WHERE i.pos_location_name IN (""" + WAREHOUSE_LOCATIONS + """)
            GROUP BY i.sku
        )
        SELECT sold.pos_location_name AS pos_location, sold.country,
            COALESCE(NULLIF(p.product_name, ''), sold.product_name) AS product_name,
            sold.variant_sku AS sku, sold.units_sold,
            sold.u28, sold.u56, sold.last_sale,
            l2.d1 AS last_sale_120, l2.d2 AS prev_sale_120,
            p.size AS size, p.barcode, p.style_name AS style_name,
            COALESCE(p.color_print, '') AS color_print,
            COALESCE(ss.soh_store, 0) AS soh_store,
            COALESCE(NULLIF(wb.bin, ''), '') AS bin,
            COALESCE(w.soh_wh, 0) AS soh_wh
        FROM sold
        LEFT JOIN last2 l2 ON l2.pos_location_name = sold.pos_location_name AND l2.variant_sku = sold.variant_sku
        LEFT JOIN store_soh ss ON ss.pos_location_name = sold.pos_location_name AND ss.sku = sold.variant_sku
        LEFT JOIN wh_soh w ON w.sku = sold.variant_sku
        LEFT JOIN all_products_clean p ON p.sku = sold.variant_sku
        LEFT JOIN warehouse_bins wb ON wb.barcode = p.barcode
        ORDER BY sold.units_sold DESC
        LIMIT """ + str(int(limit) * 6))

    # Chain-wide size-curve breadth per style + per-(store,style) in-stock sizes,
    # for the broken-curve test and the size-curve mini-indicator.
    styles = sorted({(r.get("style_name") or "") for r in rows if r.get("style_name")})
    curve_sizes = {}
    instock_sizes = {}
    if styles:
        _in = ",".join("'" + _sql_str(s) + "'" for s in styles)
        for c in (run_query(
                "SELECT style_name, COUNT(DISTINCT NULLIF(size,'')) AS n "
                "FROM all_products_clean WHERE style_name IN (" + _in + ") "
                "GROUP BY style_name") or []):
            curve_sizes[c["style_name"]] = int(c["n"] or 0)
        for c in (run_query(
                "SELECT i.pos_location_name, p.style_name, "
                "COUNT(DISTINCT NULLIF(p.size,'')) AS n "
                "FROM all_inventory i JOIN all_products_clean p ON p.sku = i.sku "
                "WHERE p.style_name IN (" + _in + ") "
                "AND i.pos_location_name NOT IN (" + WAREHOUSE_LOCATIONS + ") "
                "AND i.available > 0 GROUP BY 1,2") or []):
            instock_sizes[(c["pos_location_name"], c["style_name"])] = int(c["n"] or 0)

    # Styles currently flagged for markdown/clearance (spec §3 suppression: do not
    # replenish stock we are about to discount). Computed once per request and
    # reused per row. Never raises — a markdown lookup hiccup must not block the
    # pick list.
    md_styles = set()
    try:
        md_styles = {c.get("style_name") for c in
                     analytics_markdown_candidates(None).get("candidates", [])
                     if c.get("style_name")}
    except Exception:
        md_styles = set()

    marks_all = _replen_marks()
    today = date.today()
    actionable = []
    held_back = []
    deploy_now_rows = []

    # ── Censored-demand correction pre-pass (Phase 2 step 1) ──────────────────
    # Demand is right-censored whenever a store-SKU was OUT OF STOCK at any point
    # in the velocity window — its observed sales then understate true demand. Two
    # signals mark that: (a) the store is at zero shelf stock right now
    # (soh_store == 0), and (b) the Phase-1 stockout facts — the daily
    # fact_replen_suggestion snapshots recorded shelf_qty_at_calc / censored_flag
    # per (pos_location, sku) — show it hit zero / was flagged censored DURING the
    # window even if it has since been refilled (soh_store > 0 now). Without (b) a
    # fast mover that stocked out mid-window but is back in stock would stay
    # understated. We benchmark each SKU's uncensored per-store demand rate against
    # the stores STILL in stock for that SKU (soh_store > 0, online pool included)
    # using the shared recency-weighted EWMA, then lift a censored line to that
    # rate when it is higher. This only ever RAISES a stocked-out hero
    # (Pareto-safe) and only for a store-SKU with proven prior local sale
    # (guaranteed by the universe gate) — never-sold SKUs never enter here.
    hist_censored = set()   # {(pos_location, sku)} out-of-stock during the window per facts
    try:
        _ensure_replen_tables()
        for fr in (run_query(
                "SELECT DISTINCT pos_location, sku FROM fact_replen_suggestion "
                "WHERE business_date >= CURRENT_DATE - INTERVAL '" + str(vel_days) + " days' "
                "  AND (shelf_qty_at_calc = 0 OR censored_flag = TRUE)") or []):
            hist_censored.add((fr.get("pos_location"), fr.get("sku")))
    except Exception:
        hist_censored = set()

    peer_acc = {}   # sku -> [sum_u28_instock, sum_u56_instock, instock_store_count]
    for r in rows:
        if int(r.get("soh_store") or 0) > 0:
            a = peer_acc.setdefault(r.get("sku"), [0.0, 0.0, 0])
            a[0] += float(r.get("u28") or 0)
            a[1] += float(r.get("u56") or 0)
            a[2] += 1

    def _peer_vpw(sku):
        a = peer_acc.get(sku)
        if not a or a[2] <= 0:
            return 0.0
        return _ewma_weekly(a[0], a[1]) / a[2]

    for r in rows:
        units_sold = int(r["units_sold"] or 0)
        soh_store = int(r["soh_store"] or 0)
        soh_wh = int(r["soh_wh"] or 0)
        style = r.get("style_name") or ""
        pos = r.get("pos_location")
        sku = r.get("sku")
        is_online = (pos == ONLINE_SHOP_ZETU)
        # Recency-weighted weekly velocity (shared dashboard EWMA), not a flat
        # units/lookback average.
        own_vpw = _ewma_weekly(float(r.get("u28") or 0), float(r.get("u56") or 0))
        # Censored = currently out of stock OR flagged out-of-stock during the
        # window by the Phase-1 stockout facts (so a since-refilled fast mover is
        # still corrected).
        censored = (soh_store == 0) or ((pos, sku) in hist_censored)
        peer_vpw = _peer_vpw(sku) if censored else 0.0
        vpw = max(own_vpw, peer_vpw) if censored else own_vpw
        censored_corrected = bool(censored and vpw > own_vpw + 1e-9)
        sku_class, floor = _replen_class_floor(vpw, cfg)
        # Online (Shop Zetu) has no shelf facing: NO presentation floor and a
        # shorter cover cycle (spec §4 step 3); stores keep their class floor.
        cw = online_cover_weeks if is_online else cover_target_weeks
        cover_q = -(-int(round(vpw * cw * 100)) // 100) if vpw > 0 else 0
        if is_online:
            floor = 0
            target = cover_q
        else:
            # Class C is pull-to-1 on a sale; A/B size to max(floor, cover).
            target = floor if sku_class == "C" else max(floor, cover_q)
        need = max(0, target - soh_store)
        # Hard per-line ceiling (one store, one SKU): cap need BEFORE fair-share
        # so the two-tier allocation, deploy-from-warehouse and dispatch batching
        # all stay bounded by the cap and a line can never claim more than it.
        need = min(need, REPLEN_MAX_UNITS_PER_LINE)
        woc = (soh_store / vpw) if vpw > 0 else (999.0 if soh_store > 0 else 0.0)
        deploy_now = (soh_store == 0 and units_sold > 0 and soh_wh > 0)

        days_lapsed = 0
        if r.get("last_sale"):
            try:
                days_lapsed = (today - date.fromisoformat(str(r["last_sale"])[:10])).days
            except ValueError:
                days_lapsed = 0
        # Slow-mover guard inputs: gap (days) between the last sale day and the
        # second-to-last sale day at THIS store (120-day lookback). None when
        # only one sale day exists in the window.
        sale_gap_days = None
        try:
            if r.get("last_sale_120") and r.get("prev_sale_120"):
                sale_gap_days = (date.fromisoformat(str(r["last_sale_120"])[:10])
                                 - date.fromisoformat(str(r["prev_sale_120"])[:10])).days
        except ValueError:
            sale_gap_days = None
        # Weeks-of-cover on a plain last-4-weeks-sales basis (user rule: only
        # replenish when this is under 4 weeks). Zero shelf stock = 0 cover.
        u28_raw = float(r.get("u28") or 0)
        if soh_store <= 0:
            woc4 = 0.0
        elif u28_raw > 0:
            woc4 = soh_store / (u28_raw / 4.0)
        else:
            woc4 = 999.0
        mark = (marks_all.get((pos, "sku", sku))
                or marks_all.get((pos, "barcode", r.get("barcode")))
                or {})

        # Suppression (spec §4): hold back EOL/retired, overstock (WOC>16) and
        # broken-curve orphans — UNLESS a merchant has force-released the line.
        released = overrides.get((pos, sku)) == "release"
        reason = None
        if not released:
            if _is_manually_retired(style):
                reason = "retired"
            elif style in md_styles and soh_store > 0:
                reason = "markdown"
            elif soh_store > 0 and woc > overstock_woc:
                reason = "overstock"
            # Slow-mover guard (user rule): if the gap between the last sale and
            # the second-to-last sale at this store exceeds 30 days, don't
            # replenish. A single sale day in 120d only counts as slow when that
            # sale is itself already >30 days old (first-sale benefit of doubt).
            elif ((sale_gap_days is not None and sale_gap_days > 30)
                  or (sale_gap_days is None and days_lapsed > 30)):
                reason = "slow_mover"
            # Cover gate (user rule): only replenish when weeks of cover on a
            # plain last-4-weeks-sales basis is under 4 weeks.
            elif soh_store > 0 and woc4 >= 4.0:
                reason = "cover_ok"
            elif (instock_sizes.get((pos, style), 9) <= 1
                  and curve_sizes.get(style, 0) >= 3 and soh_store > 0):
                reason = "broken_curve"

        base = {
            "country": r.get("country"), "pos_location": pos,
            "product_name": r.get("product_name"), "style_name": style,
            "size": r.get("size") or "", "barcode": r.get("barcode") or "",
            "sku": sku, "bin": r.get("bin") or "",
            "color_print": r.get("color_print") or "",
            "units_sold": units_sold, "soh_store": soh_store, "soh_wh": soh_wh,
            "velocity": round(vpw, 2), "velocity_observed": round(own_vpw, 2),
            "sku_class": sku_class,
            "floor": floor, "target": target, "woc": round(woc, 1),
            "censored": censored, "censored_corrected": censored_corrected,
            "deploy_now": deploy_now,
            "days_lapsed": days_lapsed,
            "sale_gap_days": sale_gap_days,
            "woc_4wk": round(min(woc4, 999.0), 1),
            "in_stock_sizes": instock_sizes.get((pos, style), 0),
            "curve_sizes": curve_sizes.get(style, 0),
            "replenished": bool(mark.get("replenished", False)),
            "actual_units_replenished": int(mark.get("actual_units_replenished", 0)),
            "transfer_ref": mark.get("transfer_ref") or "",
        }
        if reason:
            base["held_reason"] = reason
            held_back.append(base)
            continue
        if need <= 0 or soh_wh <= 0:
            # Nothing to move (fully stocked or no warehouse cover) — not in the
            # pick list and not held back; simply not actionable today.
            continue
        base["need"] = need
        base["replenish"] = need  # capped to the warehouse pool below
        actionable.append(base)

    # Per-SKU gross margin = (price - cost) / price from the product master, used
    # as a Tier-2 fair-share weight term. Best-effort: neutral 1.0 when price/cost
    # are unknown or non-positive. One batched lookup over the candidate SKUs.
    margin_map = {}
    price_map = {}
    cand_skus = sorted({r.get("sku") for r in actionable if r.get("sku")})
    if cand_skus:
        _in = ",".join("'" + _sql_str(s) + "'" for s in cand_skus)
        try:
            for m in (run_query(
                    "SELECT sku, MAX(price) AS price, MAX(cost) AS cost "
                    "FROM all_products_clean WHERE sku IN (" + _in + ") "
                    "GROUP BY sku") or []):
                price = float(m.get("price") or 0)
                cost = float(m.get("cost") or 0)
                if price > 0:
                    price_map[m["sku"]] = price
                if price > 0 and 0 < cost < price:
                    margin_map[m["sku"]] = max(0.05, min(1.0, (price - cost) / price))
        except Exception:
            margin_map = {}
            price_map = {}

    # Phase 3 step 1: ONE two-tier fair-share allocation pass per SKU (replaces the
    # legacy greedy top-seller rationing). Tier 1 protects every store's
    # presentation minimum + need-to-next-dispatch; Tier 2 splits the remainder by
    # demand_share x margin x sub_factor with Online competing only after store
    # floors are safe. Sets replenish / wh_constrained / shortfall_units /
    # route_to_buying / tier1_shortfall in place.
    _allocate_replenishment_fair_share(actionable, cfg, margin_map,
                                       need_key="need", out_key="replenish")
    actionable = [r for r in actionable if int(r.get("replenish") or 0) > 0]
    # Demand-aware mark expiry: resurface done lines with a genuine post-mark gap
    # (flag-only here — need/replenish already come from the velocity targets).
    _resurface_stale_marks(actionable, marks_all)

    # Phase 3 step 2: corridor dispatch cadence + min-transfer gate. Each line is
    # mapped to a dispatch corridor (calendar), its next dispatch date / dispatch-
    # today flag computed, then a STORE-level batch gate: a store dispatches today
    # only if it's a corridor dispatch day AND clears min_transfer_units OR
    # min_transfer_kes. A-class stockouts (deploy_now) always expedite, overriding
    # both the calendar and the min gate (and pull the rest of that store with
    # them, since the truck is already going).
    flow_cfg = _replen_flow_config()
    eat_today = _replen_eat_today()
    min_units = int(flow_cfg.get("min_transfer_units", 0) or 0)
    min_kes = float(flow_cfg.get("min_transfer_kes", 0) or 0)
    _disp_cache = {}
    for r in actionable:
        corridor = _replen_corridor(r.get("pos_location"), r.get("country"), flow_cfg)
        if corridor not in _disp_cache:
            _disp_cache[corridor] = _replen_next_dispatch(corridor, flow_cfg, eat_today)
        nd, today_ok = _disp_cache[corridor]
        r["corridor"] = corridor
        r["next_dispatch"] = nd.isoformat()
        r["dispatch_today"] = bool(today_ok)
        r["expedite"] = bool(r.get("deploy_now") and r.get("sku_class") == "A")
    # Store-level batch accumulation + gate.
    store_units, store_kes, store_expedite = {}, {}, {}
    for r in actionable:
        pos = r.get("pos_location")
        q = int(r.get("replenish") or 0)
        store_units[pos] = store_units.get(pos, 0) + q
        store_kes[pos] = store_kes.get(pos, 0.0) + q * float(price_map.get(r.get("sku"), 0) or 0)
        store_expedite[pos] = store_expedite.get(pos, False) or r["expedite"]
    for r in actionable:
        pos = r.get("pos_location")
        meets_min = (store_units.get(pos, 0) >= min_units) or \
                    (min_kes > 0 and store_kes.get(pos, 0.0) >= min_kes)
        below_min = not meets_min
        r["store_dispatch_units"] = int(store_units.get(pos, 0))
        r["store_dispatch_kes"] = round(store_kes.get(pos, 0.0), 2)
        r["below_min_transfer"] = bool(below_min)
        if r["expedite"]:
            r["dispatch_status"] = "expedite"
        elif store_expedite.get(pos):
            # Truck already going for an A-class stockout in this store — piggyback.
            r["dispatch_status"] = "dispatch"
        elif r.get("dispatch_today") and not below_min:
            r["dispatch_status"] = "dispatch"
        else:
            r["dispatch_status"] = "hold_accumulate"

    # Conservative projected SOR uplift, bounded by what's actually pickable and
    # identical to the metric measured later (spec §10): expected incremental
    # sold = min(replenish, v × days_to_next_dispatch), only over v>0. velocity is
    # per-week, so the horizon is REPLEN_DISPATCH_DAYS/7 of a week.
    incremental = 0.0
    for r in actionable:
        if r["velocity"] > 0:
            incremental += min(int(r["replenish"]),
                               r["velocity"] * REPLEN_DISPATCH_DAYS / 7.0)
        if r.get("deploy_now"):
            deploy_now_rows.append(r)

    # Phase 3 step 4: scale the raw projection by the learned calibration factor
    # (realised/projected, rolling median, clamped [0.25, 2.0]) so the projected-
    # uplift number self-corrects toward what past replenishments actually
    # delivered. Defaults to 1.0 until reconciliation has run.
    proj_calibration = _replen_proj_calibration()
    incremental *= proj_calibration

    summary = _replen_sor_summary(weeks, overstock_woc)
    u = float(summary["units_sold"])
    st = float(summary["store_stock"])
    cur_sor = summary["current_sor"]
    proj_sor = (round(100.0 * (u + incremental) / (u + incremental + st), 1)
                if (u + incremental + st) > 0 else cur_sor)
    deployable_wh_units = sum(int(r["replenish"]) for r in deploy_now_rows)
    sor_at_risk_units = sum(int(r["units_sold"]) for r in actionable
                            if int(r["soh_store"]) == 0)

    # Rank the pick list by honest projected SOR-uplift (deploy-now first — the
    # highest-SOR action — then by expected incremental sold).
    def _rank(r):
        inc = min(int(r["replenish"]), r["velocity"] * REPLEN_DISPATCH_DAYS / 7.0) \
            if r["velocity"] > 0 else 0
        return (0 if r.get("deploy_now") else 1, -inc, -int(r["units_sold"]))
    actionable.sort(key=_rank)
    for r in actionable:
        inc = (min(int(r["replenish"]), r["velocity"] * REPLEN_DISPATCH_DAYS / 7.0)
               if r["velocity"] > 0 else 0.0)
        r["proj_uplift_units"] = round(inc, 2)

    held_back.sort(key=lambda r: -int(r.get("soh_store") or 0))

    # Picker roster owner assignment — SHARED with the by-item Daily report.
    # Resolve the FROZEN per-line owner (recomputed only by the explicit
    # "Save & redistribute" roster action) so the SOR pick list can be split
    # across the team and a reload never reshuffles a picker's lines. This is a
    # pure post-step over the already-sized rows: it does NOT touch the canonical
    # SOR formula or the suggested quantities.
    ret_rows = actionable[:int(limit)]
    _owners = _replen_owners()
    _line_map = _replen_line_owner_map()
    # presort=False: keep the SOR `_rank` priority order the operator sees; only
    # the owner labels + by-owner summary are derived from the balance.
    _assign_replen_owners_frozen_then_balance(ret_rows, _line_map, _owners, presort=False)
    by_owner_list = _replen_by_owner_summary(ret_rows)

    return {
        "as_of": _replen_eat_today().isoformat() + " 06:00 EAT",
        "business_date": _replen_eat_today().isoformat(),
        "demand_weeks": weeks,
        "ruleset_version": REPLEN_RULESET_VERSION,
        "config": cfg,
        "flow_config": flow_cfg,
        "rows": ret_rows,
        "by_owner": by_owner_list,
        "held_back": held_back[:200],
        "deploy_now_count": len(deploy_now_rows),
        "kpi": {
            "current_sor": cur_sor,
            "saleable_sor": summary["saleable_sor"],
            "projected_sor": proj_sor,
            "projected_uplift_pts": round(proj_sor - cur_sor, 2),
            "sor_at_risk_units": int(sor_at_risk_units),
            "deployable_wh_units": int(deployable_wh_units),
            "sor_drag_units": int(summary["drag_stock"]),
        },
    }


def _persist_replen_suggestions(run_id, business_date, store_scope, weeks, rows):
    """Upsert today's pick list into the immutable fact_replen_suggestion (spec
    §10). Keyed on (run_id, pos_location, sku) so a page reload re-stamps the same
    run rather than duplicating. Snapshots shelf qty + velocity AT calc time so a
    later 'did SOR rise' tile is attributable. Best-effort: never raises into the
    request path."""
    if not rows:
        return
    try:
        for r in rows:
            _users_exec(
                "INSERT INTO fact_replen_suggestion "
                "(run_id, business_date, store_scope, ruleset_version, pos_location, "
                " country, sku, barcode, size, style_name, demand_weeks, units_sold, "
                " shelf_qty_at_calc, wh_qty_at_calc, v_at_calc, sku_class, "
                " floor_target, cover_target, suggested_qty, deploy_now, "
                " censored_flag, wh_constrained) "
                "VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s) "
                "ON CONFLICT (run_id, pos_location, sku) DO UPDATE SET "
                " run_ts_eat=now(), shelf_qty_at_calc=EXCLUDED.shelf_qty_at_calc, "
                " wh_qty_at_calc=EXCLUDED.wh_qty_at_calc, v_at_calc=EXCLUDED.v_at_calc, "
                " sku_class=EXCLUDED.sku_class, floor_target=EXCLUDED.floor_target, "
                " cover_target=EXCLUDED.cover_target, suggested_qty=EXCLUDED.suggested_qty, "
                " deploy_now=EXCLUDED.deploy_now, censored_flag=EXCLUDED.censored_flag, "
                " wh_constrained=EXCLUDED.wh_constrained, units_sold=EXCLUDED.units_sold",
                (run_id, business_date, store_scope, REPLEN_RULESET_VERSION,
                 r.get("pos_location"), r.get("country"), r.get("sku"),
                 r.get("barcode") or None, r.get("size") or None,
                 r.get("style_name") or None, int(weeks),
                 int(r.get("units_sold") or 0), int(r.get("soh_store") or 0),
                 int(r.get("soh_wh") or 0), float(r.get("velocity") or 0),
                 r.get("sku_class"), int(r.get("floor") or 0),
                 int(r.get("target") or 0), int(r.get("replenish") or 0),
                 bool(r.get("deploy_now")), bool(r.get("censored")),
                 bool(r.get("wh_constrained"))))
    except Exception as e:
        log.error("Replen suggestion snapshot failed: %s", e)


def _compute_replenishment_report_rows(date_from=None, date_to=None, limit=400):
    """Core of the replenishment pick list: per-(store,SKU) rows with the
    suggested 'replenish' units (warehouse-capped; zero-need rows dropped),
    WITHOUT owner assignment or size-mix enrichment. Shared by the report
    endpoint and the picker-balancing weight calc so both compute identical
    per-store units."""
    if not date_from or not date_to:
        date_to = str(date.today())
        date_from = str(date.today() - timedelta(days=30))
    _warehouse_bins_refresh()
    rows = run_query("""
        WITH sold AS (
            SELECT s.pos_location_name, s.variant_sku,
                MAX(s.country) AS country,
                MAX(s.product_title) AS product_name,
                SUM(s.net_quantity) AS units_sold,
                MAX(s.sale_date) AS last_sale
            FROM all_sales s
            WHERE s.sale_kind IN ('sale','order')
              AND s.sale_date BETWEEN '""" + date_from + """' AND '""" + date_to + """'
              AND """ + BASE_FILTERS + """
              AND s.pos_location_name NOT IN (""" + WAREHOUSE_LOCATIONS + """)
              -- Include Online (Shop Zetu) as a replenishable channel; other
              -- online channels (e.g. Online - vivo-uganda) stay excluded.
              AND (s.pos_location_name NOT ILIKE '%online%'
                   OR s.pos_location_name = 'Online - Shop Zetu')
              AND s.variant_sku IS NOT NULL AND s.variant_sku <> ''
            GROUP BY s.pos_location_name, s.variant_sku
            HAVING SUM(s.net_quantity) > 0
        ),
        store_soh AS (
            SELECT i.pos_location_name, i.sku,
                SUM(i.available) AS soh_store,
                MAX(i.location_name) AS bin
            FROM all_inventory i
            WHERE i.pos_location_name NOT IN (""" + WAREHOUSE_LOCATIONS + """)
            GROUP BY i.pos_location_name, i.sku
        ),
        wh_soh AS (
            SELECT i.sku, SUM(i.available) AS soh_wh
            FROM all_inventory i
            WHERE i.pos_location_name IN (""" + WAREHOUSE_LOCATIONS + """)
            GROUP BY i.sku
        )
        SELECT sold.pos_location_name AS pos_location, sold.country,
            COALESCE(NULLIF(p.product_name, ''), sold.product_name) AS product_name, sold.variant_sku AS sku, sold.units_sold, sold.last_sale,
            p.size AS size, p.barcode,
            COALESCE(p.color_print, '') AS color_print, COALESCE(p.print_plain, '') AS print_plain,
            COALESCE(ss.soh_store, 0) AS soh_store,
            COALESCE(NULLIF(wb.bin, ''), '') AS bin,
            COALESCE(w.soh_wh, 0) AS soh_wh
        FROM sold
        LEFT JOIN store_soh ss ON ss.pos_location_name = sold.pos_location_name AND ss.sku = sold.variant_sku
        LEFT JOIN wh_soh w ON w.sku = sold.variant_sku
        LEFT JOIN all_products_clean p ON p.sku = sold.variant_sku
        LEFT JOIN warehouse_bins wb ON wb.barcode = p.barcode
        WHERE COALESCE(ss.soh_store, 0) < sold.units_sold AND COALESCE(w.soh_wh, 0) > 0
        ORDER BY (sold.units_sold - COALESCE(ss.soh_store, 0)) DESC
        LIMIT """ + str(int(limit)))
    marks_all = _replen_marks()
    today = date.today()
    out_rows = []
    for r in rows:
        units_sold = int(r["units_sold"] or 0)
        soh_store = int(r["soh_store"] or 0)
        soh_wh = int(r["soh_wh"] or 0)
        # Per-store need, with a hard per-line ceiling applied first; the finite
        # warehouse pool is then allocated across stores (top sellers first) by
        # _cap_replenish_to_warehouse below so the SKU's total suggested never
        # exceeds soh_wh. Capping here (before the warehouse split and the per-
        # (store, style) group totals / size_breakdown) keeps every rollup
        # consistent with the capped per-line values.
        replenish = min(max(0, units_sold - soh_store), REPLEN_MAX_UNITS_PER_LINE)
        days_lapsed = 0
        if r.get("last_sale"):
            try:
                days_lapsed = (today - date.fromisoformat(str(r["last_sale"])[:10])).days
            except ValueError:
                days_lapsed = 0
        mark = (marks_all.get((r.get("pos_location"), "sku", r.get("sku")))
                or marks_all.get((r.get("pos_location"), "barcode", r.get("barcode")))
                or {})
        out_rows.append({
            "country": r.get("country"),
            "pos_location": r.get("pos_location"), "product_name": r.get("product_name"),
            "size": r.get("size") or "", "barcode": r.get("barcode") or "",
            "sku": r.get("sku"), "bin": r.get("bin") or "",
            "color_print": r.get("color_print") or "", "print_plain": r.get("print_plain") or "",
            "units_sold": units_sold, "soh_store": soh_store, "soh_wh": soh_wh,
            "replenish": replenish, "replenished": bool(mark.get("replenished", False)),
            "actual_units_replenished": int(mark.get("actual_units_replenished", 0)),
            "transfer_ref": mark.get("transfer_ref") or "",
            "days_lapsed": days_lapsed,
        })
    # Demand-aware mark expiry: a line marked done resurfaces once the store has
    # sold more units SINCE the mark than it currently holds — stores must keep
    # receiving what they are actively selling; a mark is not a permanent hide.
    _resurface_stale_marks(out_rows, marks_all, need_key="replenish",
                           cap=REPLEN_MAX_UNITS_PER_LINE)
    # Allocate each SKU's warehouse pool across stores (top sellers first) so the
    # suggested ("replenish") never exceeds warehouse stock for that SKU.
    _cap_replenish_to_warehouse(out_rows, need_key="replenish", out_key="replenish")
    # Drop rows the warehouse pool can no longer cover (replenish capped to 0) — a
    # zero-unit suggestion is not actionable, so it must not appear in the list nor
    # inflate the per-owner line/unit counts or the size-mix below.
    out_rows = [r for r in out_rows if int(r.get("replenish") or 0) > 0]
    return out_rows


@app.get("/api/analytics/replenishment-report")
def analytics_replenishment_report(
    date_from: str = Query(default=None),
    date_to:   str = Query(default=None),
    limit: int = Query(default=400),
):
    out_rows = _compute_replenishment_report_rows(date_from, date_to, limit)
    # Distribute the pick list so each picker gets as close to EQUAL LINES as
    # possible. Rows are ordered by POS location, so each store's lines stay
    # contiguous and a store is split between two pickers only when the
    # equal-lines boundary lands inside it (one POS may be shared by >1 picker).
    # FROZEN assignment: the equal-lines balance is computed ONLY by the explicit
    # "Save & redistribute" action (see _redistribute_replen_owners) and persisted
    # as a {line_key: owner} map. We read it back here so a page reload never
    # reshuffles a picker's lines — a picker who finished early can refresh without
    # being handed new work. Lines added since the last redistribute fall back to
    # that store's main picker, else a stable hash (also reload-stable).
    owners = _replen_owners()
    line_map = _replen_line_owner_map()
    _assign_replen_owners_frozen_then_balance(out_rows, line_map, owners)
    by_owner_list = _replen_by_owner_summary(out_rows)
    # Phase 3 A3-ext — attach a recommended-qty size curve per (store, style).
    # Two batch queries total: sku->style map, then one size-mix pull for every
    # style on the page (chain-wide curve), split per (store, style) group total.
    _skus = sorted({r["sku"] for r in out_rows if r.get("sku")})
    _sku_style = {}
    if _skus:
        _sku_in = ",".join("'" + _sql_str(x) + "'" for x in _skus)
        for m in (run_query(
                "SELECT sku, style_name FROM all_products_clean WHERE sku IN ("
                + _sku_in + ") AND COALESCE(style_name,'') <> ''") or []):
            _sku_style[m["sku"]] = m["style_name"]
    _styles = sorted({v for v in _sku_style.values() if v})
    _style_rows = {}
    if _styles:
        _style_in = " AND p.style_name IN (" + ",".join("'" + _sql_str(x) + "'" for x in _styles) + ")"
        for sr in (_size_mix_rows(_style_in, "", "") or []):
            _style_rows.setdefault(sr["style"], []).append(sr)
    _grp_total = {}
    for r in out_rows:
        st = _sku_style.get(r.get("sku"))
        if st:
            _grp_total[(r["pos_location"], st)] = _grp_total.get((r["pos_location"], st), 0) + r["replenish"]
    _grp_mix = {}
    for (loc, st), tot in _grp_total.items():
        srows = _style_rows.get(st)
        if srows and tot > 0:
            _grp_mix[(loc, st)] = _build_size_mix(
                srows, tot, cap=REPLEN_MAX_UNITS_PER_LINE)
    for r in out_rows:
        st = _sku_style.get(r.get("sku"))
        mix = _grp_mix.get((r["pos_location"], st)) if st else None
        r["style_name"] = st
        r["size_breakdown"] = mix or []
        r["size_breakdown_available"] = bool(mix)
    return {
        "rows": out_rows,
        "summary": {
            "by_owner": by_owner_list,
            "total_units": sum(r["replenish"] for r in out_rows),
            "total_rows": len(out_rows),
            "completed": sum(1 for r in out_rows if r["replenished"]),
        },
    }


@app.get("/api/analytics/replenishment-sor")
def analytics_replenishment_sor(
    weeks: int = Query(default=REPLEN_DEMAND_WEEKS_DEFAULT),
    limit: int = Query(default=400),
    nocache: int = Query(default=0),
):
    """SOR-first replenishment (Phase 1): ranked pick list + Held-back panel +
    SOR KPI strip over the named trailing demand window (4/8/12w). READ-ONLY —
    this interactive endpoint never writes the immutable fact tables. The single
    writer of the canonical daily snapshot is the internal /snapshot job (driven
    by the sync loop), so toggling lookback / refreshing here cannot mutate the
    attributable baseline. The run_id is returned for reference only.

    The full engine pull runs several heavy velocity/sell-out CTEs (multi-second
    each), so the whole result is memoised per (weeks, limit, EAT business date)
    for 10 min — repeat page loads and lookback toggles return instantly. Any
    mutation (distribute / mark-done / holdback) and the explicit Refresh button
    send `nocache=1`, which bypasses AND refreshes the entry so the list is never
    shown stale after an action."""
    from datetime import datetime as _dt
    weeks_key = int(weeks) if int(weeks) in REPLEN_DEMAND_WEEKS_ALLOWED else REPLEN_DEMAND_WEEKS_DEFAULT
    biz_date = (_dt.utcnow() + timedelta(hours=3)).date().isoformat()  # EAT (UTC+3)
    ck = f"replen_sor:{weeks_key}:{int(limit)}:{biz_date}"
    if not nocache:
        cached, fresh = cache_get_swr(ck)
        if cached is not None:
            # No background refresh here: the key is day-scoped (rolls over at
            # EAT midnight) and mutations already bypass via nocache=1, so a
            # stale-in-grace copy is simply served until the TTL path renews it.
            return cached
    result = _compute_replenishment_sor(weeks_key, limit)
    result["run_id"] = _replen_run_id(
        result["business_date"], "ALL", REPLEN_RULESET_VERSION,
        result["demand_weeks"])
    cache_set(ck, result, ttl=600)
    return result


@app.post("/api/analytics/replenishment-sor/holdback-override")
def analytics_replenishment_sor_holdback_override(payload: dict = Body(...),
                                                  request: Request = None):
    """Merch override for the Held-back panel: force-release a held SKU back into
    the pick list, or re-suppress it. action ∈ {release, suppress}."""
    pos = (payload.get("pos_location") or "").strip()
    sku = (payload.get("sku") or "").strip()
    action = (payload.get("action") or "release").strip()
    if not pos or not sku or action not in ("release", "suppress"):
        raise HTTPException(status_code=400, detail="pos_location, sku, action required")
    # Merch policy override — gate server-side to roles that can manage the
    # replenishment surface (same access as the page itself), not any logged-in
    # user. Hidden client nav is bypassable; this is the real fence.
    actor = None
    role = None
    try:
        u = (request.state.user or {}) if request else {}
        actor = u.get("email")
        role = (u.get("role") or "").strip().lower()
    except Exception:
        actor, role = None, None
    if role != "admin" and "replenishments" not in set(_effective_pages_for_role(role)):
        raise HTTPException(status_code=403,
                            detail="replenishment management not permitted for this role")
    _users_exec(
        "INSERT INTO replen_holdback_override (pos_location, sku, action, acted_by, acted_at) "
        "VALUES (%s,%s,%s,%s, now()) "
        "ON CONFLICT (pos_location, sku) DO UPDATE SET "
        "action=EXCLUDED.action, acted_by=EXCLUDED.acted_by, acted_at=now()",
        (pos, sku, action, actor))
    return {"ok": True, "pos_location": pos, "sku": sku, "action": action}


@app.post("/api/analytics/replenishment-sor/snapshot")
def analytics_replenishment_sor_snapshot(
    weeks: int = Query(default=REPLEN_DEMAND_WEEKS_DEFAULT),
):
    """Internal-only (sync job, X-Internal-Token == SESSION_SECRET): compute and
    persist today's SOR pick-list snapshot to the immutable fact tables so the
    attributability history accrues even on days with no staff page visit. Ensures
    its own schema (so the tables self-bootstrap from the sync loop too) and is
    idempotent on run_id."""
    _ensure_replen_tables()
    result = _compute_replenishment_sor(weeks, 400)
    run_id = _replen_run_id(result["business_date"], "ALL", REPLEN_RULESET_VERSION,
                            result["demand_weeks"])
    _persist_replen_suggestions(
        run_id, result["business_date"], "ALL", result["demand_weeks"],
        result["rows"])
    return {"ok": True, "run_id": run_id,
            "business_date": result["business_date"],
            "suggested_rows": len(result["rows"])}


