@app.get("/api/analytics/replenishment-picker-scorecard")
def analytics_replenishment_picker_scorecard(days: int = Query(default=30)):
    """Picker accountability (Phase 2 step 4) built on the immutable Phase 1
    facts — NOT the completed-audit trail. Per real picker (fact_pick_event
    user_id): lines assigned/done/missed, LINE-based fulfilment % (effort-
    normalised so scattered single-unit lines aren't unfairly ranked), missed-SOR
    units (weekly velocity of skipped suggested lines) and over-picks.

    Attribution: a picker's scope = the stores they actually worked in the window;
    the latest suggestion snapshot for those stores is their assigned set. The
    panel stays GATED (published:false) until the facts are trustworthy — at least
    one suggestion snapshot AND attributable pick events exist in the window."""
    days = max(1, min(int(days or 30), 180))
    _ensure_replen_tables()

    # Latest daily suggestion snapshot within the window (deduped per store-SKU
    # across any lookback runs on that date).
    sugg = run_query(
        "SELECT pos_location, sku, MAX(suggested_qty) AS suggested_qty, "
        "       MAX(v_at_calc) AS v_at_calc "
        "FROM fact_replen_suggestion "
        "WHERE business_date = ("
        "   SELECT MAX(business_date) FROM fact_replen_suggestion "
        "   WHERE business_date >= CURRENT_DATE - INTERVAL '" + str(days) + " days') "
        "GROUP BY pos_location, sku") or []
    picks = run_query(
        "SELECT user_id, MAX(user_name) AS user_name, pos_location, sku, "
        "       SUM(qty_picked) AS qty_picked "
        "FROM fact_pick_event "
        "WHERE picked_ts_eat >= now() - INTERVAL '" + str(days) + " days' "
        "  AND user_id IS NOT NULL AND user_id <> '' "
        "GROUP BY user_id, pos_location, sku") or []

    # Dispatched-but-not-yet-received (in-transit) store-SKUs. A picked line whose
    # dispatched stock the store hasn't confirmed receipt for earns NO full picker
    # credit yet (Phase 3 step 3) — it is held as in-transit, not counted done,
    # and not counted missed. Full credit lands once the receipt is confirmed.
    in_transit_pairs = set()
    try:
        for it in _replen_in_transit_rows():
            ip = (it.get("pos_location") or "").strip()
            isku = (it.get("sku") or "").strip()
            if ip and isku and int(it.get("in_transit") or 0) > 0:
                in_transit_pairs.add((ip, isku))
    except Exception:
        in_transit_pairs = set()

    if not sugg or not picks:
        reason = ("No suggestion snapshots have accrued yet — the daily snapshot "
                  "job populates them after publish."
                  if not sugg else
                  "No attributable pick events yet — they accrue as pickers mark "
                  "replenishment lines done.")
        return {"published": False, "reason": reason, "days": days,
                "snapshot_lines": len(sugg), "pick_lines": len(picks),
                "pickers": []}

    sugg_by_store = {}            # pos -> {sku: {"suggested": q, "v": v}}
    for s in sugg:
        sugg_by_store.setdefault(s["pos_location"], {})[s["sku"]] = {
            "suggested": int(s["suggested_qty"] or 0),
            "v": float(s["v_at_calc"] or 0)}

    pickers = {}                  # user_id -> aggregate
    for p in picks:
        uid = p["user_id"]
        u = pickers.setdefault(uid, {
            "user_id": uid, "user_name": p.get("user_name") or uid,
            "stores": set(), "picked": {}, "units_picked": 0})
        u["stores"].add(p["pos_location"])
        u["picked"][(p["pos_location"], p["sku"])] = int(p["qty_picked"] or 0)
        u["units_picked"] += int(p["qty_picked"] or 0)

    out = []
    for u in pickers.values():
        assigned = done = missed = in_transit = 0
        assigned_units = done_units = missed_units = in_transit_units = 0
        missed_sor_units = 0.0
        over_pick_units = 0
        for pos in u["stores"]:
            for sku, meta in sugg_by_store.get(pos, {}).items():
                assigned += 1
                su = int(meta["suggested"] or 0)
                assigned_units += su
                picked_qty = u["picked"].get((pos, sku))
                if picked_qty is not None:
                    if (pos, sku) in in_transit_pairs:
                        # Picked + dispatched but not yet received → credit held.
                        in_transit += 1
                        in_transit_units += su
                    else:
                        done += 1
                        done_units += su
                    if picked_qty > meta["suggested"]:
                        over_pick_units += picked_qty - meta["suggested"]
                else:
                    missed += 1
                    missed_units += su
                    missed_sor_units += meta["v"]
        # Unit-based headline = suggested units cleared ÷ suggested units assigned.
        # In-transit lines are excluded from full credit until the store confirms
        # receipt. (Line-count aggregates are retained for backward compatibility.)
        fulfilment_pct = round(100.0 * done_units / assigned_units, 1) if assigned_units else 0.0
        out.append({
            "user_id": u["user_id"], "user_name": u["user_name"],
            "stores": sorted(u["stores"]),
            "assigned_lines": assigned, "done_lines": done,
            "in_transit_lines": in_transit,
            "missed_lines": missed,
            "assigned_units": assigned_units, "done_units": done_units,
            "missed_units": missed_units, "in_transit_units": in_transit_units,
            "fulfilment_pct": fulfilment_pct,
            "units_picked": u["units_picked"],
            "missed_sor_units": round(missed_sor_units, 1),
            "over_pick_units": int(over_pick_units),
        })
    out.sort(key=lambda r: (-r["fulfilment_pct"], -r["done_units"]))
    return {"published": True, "days": days, "snapshot_lines": len(sugg),
            "pickers": out}


@app.get("/api/analytics/sales-projection")
def analytics_sales_projection(
    date_from: str = Query(default=str(date.today().replace(day=1))),
    date_to:   str = Query(default=str(date.today())),
    country:   str = Query(default=None),
    channel:   str = Query(default=None),
):
    where = build_filters(date_from, date_to, country, channel)
    rows = run_query("""
        SELECT
            COALESCE(ROUND(SUM(CASE WHEN s.sale_kind IN ('sale','order') THEN s.net_sales_kes::numeric
                                    WHEN s.sale_kind = 'return' THEN -s.returns_kes::numeric ELSE 0 END)), 0) AS actual_sales,
            MAX(s.sale_date) AS last_day
        FROM all_sales s WHERE """ + where + """
    """)
    actual = float(rows[0]["actual_sales"]) if rows and rows[0]["actual_sales"] is not None else 0.0
    last_day = rows[0].get("last_day") if rows else None
    d0 = date.fromisoformat(date_from[:10])
    d1 = date.fromisoformat(date_to[:10])
    total_days = max(1, (d1 - d0).days + 1)
    eff = min(d1, date.today())
    if last_day:
        try:
            ld = date.fromisoformat(str(last_day)[:10])
            if ld < eff:
                eff = ld
        except ValueError:
            pass
    days_elapsed = min(max(1, (eff - d0).days + 1), total_days)
    daily_run_rate = actual / days_elapsed if days_elapsed else 0
    projected = daily_run_rate * total_days
    return {
        "total_days": total_days,
        "days_elapsed": days_elapsed,
        "completion_pct": round(100.0 * days_elapsed / total_days, 1),
        "actual_sales": round(actual),
        "daily_run_rate": round(daily_run_rate),
        "projected_sales": round(projected),
    }
def _rollup_country_where(country):
    """Standalone WHERE clause filtering a rollup table's `country` column by the
    same csv/lowercase contract as _style_filters' country branch. Returns "" when
    no country is selected (the All scope)."""
    if not country:
        return ""
    cs = [c.strip().lower() for c in country.split(",") if c.strip()]
    if not cs:
        return ""
    return " WHERE LOWER(country) IN (" + ",".join(
        "'" + c.replace("'", "''") + "'" for c in cs) + ")"


def _style_filters(country=None, channel=None, alias="s"):
    cf = chf = ""
    if country:
        cs = [c.strip().lower() for c in country.split(",") if c.strip()]
        if cs:
            cf = " AND LOWER(" + alias + ".country) IN (" + ",".join(
                "'" + c.replace("'", "''") + "'" for c in cs) + ")"
    if channel:
        chs = [c.strip() for c in channel.split(",") if c.strip()]
        if chs:
            chf = " AND " + alias + ".pos_location_name IN (" + ",".join(
                "'" + c.replace("'", "''") + "'" for c in chs) + ")"
    return cf, chf


def _sku_breakdown(style_names, country=None, channel=None):
    names = [n for n in style_names if n]
    if not names:
        return {}
    names_sql = ",".join("'" + n.replace("'", "''") + "'" for n in names)
    cf, chf = _style_filters(country, channel, "s")
    inv_cf, _ = _style_filters(country, None, "i")
    six = str(date.today() - timedelta(days=182))
    three = str(date.today() - timedelta(days=21))
    sales = run_query("""
        SELECT p.style_name, p.sku, p.color_print AS color, p.size,
            SUM(CASE WHEN s.sale_kind IN ('sale','order') THEN s.net_quantity ELSE 0 END) AS units_6m,
            SUM(CASE WHEN s.sale_kind IN ('sale','order') THEN s.net_sales_kes::numeric ELSE 0 END) AS sales_6m,
            SUM(CASE WHEN s.sale_kind IN ('sale','order') AND s.sale_date >= '""" + three + """' THEN s.net_quantity ELSE 0 END) AS units_3w
        FROM all_products_clean p
        LEFT JOIN all_sales s ON s.variant_sku = p.sku
            AND s.sale_date BETWEEN '""" + six + """' AND '""" + str(date.today()) + """'
            AND """ + BASE_FILTERS + cf + chf + """
        WHERE p.style_name IN (""" + names_sql + """)
        GROUP BY p.style_name, p.sku, p.color_print, p.size
    """)
    inv = run_query("""
        SELECT p.sku,
            SUM(CASE WHEN i.pos_location_name NOT IN (""" + PIPELINE_LOCATIONS + """) THEN i.available ELSE 0 END) AS soh_total,
            SUM(CASE WHEN i.pos_location_name IN (""" + WAREHOUSE_LOCATIONS + """)
                      AND i.pos_location_name NOT IN (""" + PIPELINE_LOCATIONS + """)
                     THEN i.available ELSE 0 END) AS soh_wh,
            SUM(CASE WHEN i.pos_location_name IN (""" + PIPELINE_LOCATIONS + """) THEN i.available ELSE 0 END) AS soh_pipeline
        FROM all_products_clean p
        LEFT JOIN all_inventory i ON i.sku = p.sku""" + inv_cf + """
        WHERE p.style_name IN (""" + names_sql + """)
        GROUP BY p.sku
    """)
    inv_map = {r["sku"]: r for r in inv}
    out = {}
    for r in sales:
        soh = inv_map.get(r["sku"], {})
        soh_total = float(soh.get("soh_total") or 0)
        soh_wh = float(soh.get("soh_wh") or 0)
        soh_pipeline = float(soh.get("soh_pipeline") or 0)
        u6 = float(r["units_6m"] or 0)
        u3 = float(r["units_3w"] or 0)
        if u6 == 0 and u3 == 0 and soh_total == 0 and soh_pipeline == 0:
            continue
        out.setdefault(r["style_name"], []).append({
            "color": r["color"] or "—", "size": r["size"] or "—", "sku": r["sku"],
            "units_6m": int(u6), "units_3w": int(u3),
            "sales_6m": round(float(r["sales_6m"] or 0)),
            "soh_total": int(soh_total), "soh_wh": int(soh_wh),
            "soh_pipeline": int(soh_pipeline),
            "pct_in_wh": round(100.0 * soh_wh / soh_total, 1) if soh_total else 0.0,
        })
    return out


