def _ensure_thumbnail_overrides():
    """Idempotently create the admin thumbnail-override table.

    Overrides come in two flavours: a pasted external ``image_url`` (https://…)
    or a file uploaded straight from the admin's device. Uploaded files are
    stored durably as bytes in ``image_data`` (+ ``content_type``) and served
    back through ``GET /api/thumbnails/{style}/image``; for those rows
    ``image_url`` holds that internal serving path so the lookup resolves them
    identically to URL overrides."""
    _users_exec("""
        CREATE TABLE IF NOT EXISTS thumbnail_overrides (
            style_name TEXT PRIMARY KEY,
            image_url  TEXT NOT NULL,
            updated_by TEXT,
            updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
        )""")
    _users_exec("ALTER TABLE thumbnail_overrides ADD COLUMN IF NOT EXISTS image_data BYTEA")
    _users_exec("ALTER TABLE thumbnail_overrides ADD COLUMN IF NOT EXISTS content_type TEXT")


@app.get("/api/thumbnails")
def list_thumbnail_overrides(request: Request):
    """Admin management view: list all admin-set thumbnail overrides."""
    _require_admin(request)
    _ensure_thumbnail_overrides()
    rows = _users_exec(
        "SELECT style_name, image_url, updated_by, updated_at "
        "FROM thumbnail_overrides ORDER BY updated_at DESC", fetch=True) or []
    for r in rows:
        ua = r.get("updated_at")
        if ua is not None:
            r["updated_at"] = ua.isoformat()
    return rows


# ── Admin activity log ────────────────────────────────────────────────────────
# Audit trail surfaced on the admin Activity Logs page (/api/admin/activity-logs).
# Rows are written by explicit audit calls (currently the SOP document library:
# upload / replace / delete / grant / revoke) rather than by blanket request
# logging, so each entry can carry a human-readable detail string (which file,
# which department, which user was granted). The row shape matches what the
# frontend table renders: ts / email / method / path / query(detail) / status /
# ip. Writes are best-effort and never fail the calling request.
_ACTIVITY_LOG_READY = False


def _ensure_activity_log():
    global _ACTIVITY_LOG_READY
    if _ACTIVITY_LOG_READY:
        return
    _users_exec("""
        CREATE TABLE IF NOT EXISTS app_activity_log (
            id          BIGSERIAL PRIMARY KEY,
            ts          TIMESTAMPTZ NOT NULL DEFAULT now(),
            user_id     TEXT,
            email       TEXT,
            method      TEXT,
            path        TEXT,
            query       TEXT,
            status_code INT,
            duration_ms INT,
            ip          TEXT
        )""")
    _users_exec("CREATE INDEX IF NOT EXISTS idx_app_activity_log_ts "
                "ON app_activity_log (ts DESC)")
    _ACTIVITY_LOG_READY = True


def _client_ip(request):
    try:
        fwd = (request.headers.get("x-forwarded-for") or "").split(",")[0].strip()
        if fwd:
            return fwd[:64]
        client = getattr(request, "client", None)
        return (getattr(client, "host", None) or "")[:64] or None
    except Exception:
        return None


def _log_activity(request, method, path, detail, status_code=200):
    """Best-effort audit insert for the Activity Logs page. Never raises —
    an unavailable log store must not fail the underlying action."""
    try:
        _ensure_activity_log()
        user = getattr(request.state, "user", None) or {}
        _users_exec(
            "INSERT INTO app_activity_log "
            "(user_id, email, method, path, query, status_code, ip) "
            "VALUES (%s, %s, %s, %s, %s, %s, %s)",
            (user.get("user_id"), user.get("email"),
             (method or "")[:10], (path or "")[:300], (detail or "")[:500],
             int(status_code), _client_ip(request)))
    except Exception as e:
        log.warning("activity log write failed: %s", e)


# ── SOP document library ──────────────────────────────────────────────────────
# Each department keeps its Standard Operating Procedure documents in its own
# folder. Every signed-in active user can browse/view/download; uploading and
# deleting is restricted server-side to admins plus users holding an explicit
# per-department grant (managed by admins). Files live as bytes in Postgres so
# production keeps its own library in its own DB (no dev→prod migration needed).
SOP_DEPARTMENTS = [
    {"slug": "brand-marketing-ecommerce", "name": "Brand, Marketing & E-Commerce"},
    {"slug": "finance-operations", "name": "Finance & Operations"},
    {"slug": "hr-admin", "name": "HR & Admin"},
    {"slug": "product-development", "name": "Product Development"},
    {"slug": "production", "name": "Production"},
    {"slug": "retail-cx", "name": "Retail & Customer Experience"},
    {"slug": "warehouse", "name": "Warehouse"},
]
_SOP_DEPT_SLUGS = {d["slug"] for d in SOP_DEPARTMENTS}
_SOP_MAX_BYTES = 20 * 1024 * 1024  # 20 MB per file — generous for SOP docs
# Document + image formats only; anything executable/archive is refused.
_SOP_ALLOWED_EXTS = {
    ".pdf", ".doc", ".docx", ".xls", ".xlsx", ".ppt", ".pptx",
    ".png", ".jpg", ".jpeg", ".gif", ".webp",
}


def _ensure_sop_tables():
    _users_exec("""
        CREATE TABLE IF NOT EXISTS sop_files (
            id            SERIAL PRIMARY KEY,
            department    TEXT NOT NULL,
            filename      TEXT NOT NULL,
            content_type  TEXT,
            size_bytes    BIGINT NOT NULL DEFAULT 0,
            data          BYTEA NOT NULL,
            uploaded_by   TEXT,
            uploaded_by_email TEXT,
            uploaded_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
            UNIQUE (department, filename)
        )""")
    _users_exec("""
        CREATE TABLE IF NOT EXISTS sop_upload_grants (
            user_id     TEXT NOT NULL,
            department  TEXT NOT NULL,
            granted_by  TEXT,
            granted_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
            PRIMARY KEY (user_id, department)
        )""")


@_deferred_startup
def _init_sop_tables():
    try:
        _ensure_sop_tables()
    except Exception as e:
        log.error("SOP tables ensure failed: %s", e)


@_deferred_startup
def _seed_fabric_field_grants():
    """Seed the initial named fabric field-edit grantees.  Idempotent:
    uses ON CONFLICT DO NOTHING and skips any email not yet in app_users.
    Must run AFTER the DB-touching startup steps so fabric_field_grants
    already exists (created by _ensure_receiving_tables on first request
    OR by whatever startup step runs the fabric schema)."""
    INITIAL_GRANTS = [
        ("hagai@vivofashiongroup.com",  "width_edit"),
        ("bedan@vivofashiongroup.com",  "roll_no_edit"),
        ("bedan@vivofashiongroup.com",  "width_edit"),
    ]
    try:
        from fabric_router import _ensure_receiving_tables, _get_conn
        with _get_conn() as conn:
            _ensure_receiving_tables(conn)
            with conn.cursor() as cur:
                for email, field_name in INITIAL_GRANTS:
                    cur.execute(
                        "SELECT user_id FROM app_users "
                        "WHERE email = %s LIMIT 1",
                        (email,))
                    row = cur.fetchone()
                    if row:
                        cur.execute("""
                            INSERT INTO fabric_field_grants
                              (user_id, field_name, granted_by, granted_at)
                            VALUES (%s, %s, 'system (initial seed)', now())
                            ON CONFLICT (user_id, field_name) DO NOTHING
                        """, (row[0], field_name))
            conn.commit()
    except Exception as e:
        log.error("seed_fabric_field_grants failed: %s", e)


def _sop_user_grants(user_id):
    try:
        rows = _users_exec(
            "SELECT department FROM sop_upload_grants WHERE user_id=%s",
            (user_id,), fetch=True) or []
        return {r["department"] for r in rows}
    except Exception:
        # Fail closed — no grants readable means no upload rights.
        return set()


def _sop_can_upload(user, department):
    if (user or {}).get("role") == "admin":
        return True
    return department in _sop_user_grants((user or {}).get("user_id") or "")


def _sop_safe_filename(name):
    # Basename only, strip path separators + control chars, bound length.
    base = os.path.basename((name or "").replace("\\", "/")).strip()
    base = "".join(c for c in base if c.isprintable() and c not in '<>:"|?*')
    return base[:200]


@app.get("/api/sops/departments")
def sops_departments(request: Request):
    """Folder grid: every department with its file count + whether the caller
    may upload into it. Readable by any signed-in active user."""
    _ensure_sop_tables()
    user = getattr(request.state, "user", None) or {}
    counts = {}
    try:
        for r in _users_exec(
                "SELECT department, COUNT(*) AS n FROM sop_files GROUP BY department",
                fetch=True) or []:
            counts[r["department"]] = int(r["n"])
    except Exception:
        pass
    is_admin = user.get("role") == "admin"
    grants = set() if is_admin else _sop_user_grants(user.get("user_id") or "")
    return [{
        "slug": d["slug"], "name": d["name"],
        "file_count": counts.get(d["slug"], 0),
        "can_upload": is_admin or d["slug"] in grants,
    } for d in SOP_DEPARTMENTS]


@app.get("/api/sops/files")
def sops_files(request: Request, department: str = Query(...)):
    if department not in _SOP_DEPT_SLUGS:
        raise HTTPException(status_code=400, detail="Unknown department")
    _ensure_sop_tables()
    user = getattr(request.state, "user", None) or {}
    rows = _users_exec(
        "SELECT id, department, filename, content_type, size_bytes, "
        "uploaded_by, uploaded_by_email, uploaded_at "
        "FROM sop_files WHERE department=%s ORDER BY lower(filename)",
        (department,), fetch=True) or []
    for r in rows:
        ua = r.get("uploaded_at")
        if ua is not None:
            r["uploaded_at"] = ua.isoformat()
    return {"department": department,
            "can_upload": _sop_can_upload(user, department),
            "files": rows}


@app.get("/api/sops/files/{file_id}/download")
def sops_download(file_id: int, request: Request, inline: int = Query(0)):
    _ensure_sop_tables()
    rows = _users_exec(
        "SELECT filename, content_type, data FROM sop_files WHERE id=%s",
        (file_id,), fetch=True)
    if not rows:
        raise HTTPException(status_code=404, detail="File not found")
    row = rows[0]
    data = bytes(row["data"])
    fname = row["filename"] or f"sop-{file_id}"
    # RFC 5987 filename* for non-ASCII names, with an ASCII fallback.
    ascii_name = fname.encode("ascii", "replace").decode("ascii").replace('"', "")
    disp = "inline" if inline else "attachment"
    headers = {
        "Content-Disposition":
            f"{disp}; filename=\"{ascii_name}\"; filename*=UTF-8''{quote(fname)}",
        # SOP docs change rarely, but a replace must show up immediately.
        "Cache-Control": "no-cache",
    }
    return Response(content=data,
                    media_type=row["content_type"] or "application/octet-stream",
                    headers=headers)


@app.post("/api/sops/upload")
async def sops_upload(request: Request,
                      department: str = Form(...),
                      file: UploadFile = File(...)):
    if department not in _SOP_DEPT_SLUGS:
        raise HTTPException(status_code=400, detail="Unknown department")
    user = getattr(request.state, "user", None) or {}
    if not _sop_can_upload(user, department):
        raise HTTPException(
            status_code=403,
            detail="You don't have upload rights for this department")
    _ensure_sop_tables()
    fname = _sop_safe_filename(file.filename)
    if not fname:
        raise HTTPException(status_code=400, detail="Missing filename")
    ext = os.path.splitext(fname)[1].lower()
    if ext not in _SOP_ALLOWED_EXTS:
        raise HTTPException(
            status_code=400,
            detail="Unsupported file type — allowed: PDF, Word, Excel, "
                   "PowerPoint and images")
    data = await file.read()
    if not data:
        raise HTTPException(status_code=400, detail="File is empty")
    if len(data) > _SOP_MAX_BYTES:
        raise HTTPException(
            status_code=413,
            detail=f"File too large — the limit is {_SOP_MAX_BYTES // (1024 * 1024)} MB")
    # Upsert on (department, filename): uploading the same name REPLACES the
    # document, which is the natural "new revision" flow for SOPs.
    existing = _users_exec(
        "SELECT id FROM sop_files WHERE department=%s AND filename=%s",
        (department, fname), fetch=True)
    rows = _users_exec("""
        INSERT INTO sop_files (department, filename, content_type, size_bytes,
                               data, uploaded_by, uploaded_by_email)
        VALUES (%s, %s, %s, %s, %s, %s, %s)
        ON CONFLICT (department, filename) DO UPDATE SET
            content_type = EXCLUDED.content_type,
            size_bytes   = EXCLUDED.size_bytes,
            data         = EXCLUDED.data,
            uploaded_by  = EXCLUDED.uploaded_by,
            uploaded_by_email = EXCLUDED.uploaded_by_email,
            uploaded_at  = now()
        RETURNING id, filename, size_bytes
    """, (department, fname, file.content_type or "application/octet-stream",
          len(data), psycopg2.Binary(data),
          user.get("name") or user.get("email"), user.get("email")),
        fetch=True)
    action = "replace" if existing else "upload"
    _log_activity(
        request, "POST", "/api/sops/upload",
        f"SOP {action}: {fname} · department={department} "
        f"· {len(data):,} bytes")
    return {"ok": True, "file": rows[0] if rows else None}


@app.delete("/api/sops/files/{file_id}")
def sops_delete(file_id: int, request: Request):
    _ensure_sop_tables()
