def _fmt_bucket_label(d, bucket):
    if bucket == "week":
        return "Wk " + d.strftime("%b %d")
    if bucket == "month":
        return d.strftime("%b %Y")
    if bucket == "quarter":
        return "Q%d %d" % ((d.month - 1) // 3 + 1, d.year)
    if bucket == "year":
        return d.strftime("%Y")
    return d.strftime("%b %d")

# ── Prior-period restatement tracking (WS7) ─────────────────────────────────
# Historical months are supposed to be immutable, but the pipeline CAN rewrite
# history (re-extracts, re-netting, recovery backfills). When that happens the
# comparison bases on Overview/Trend silently shift with no notice. We snapshot
# each CLOSED month's canonical headline figures (same SQL as /api/kpis, all
# countries/channels, BASE_FILTERS) once a night; when a closed month's figure
# drifts from its snapshot beyond tolerance we record a RESTATEMENT (old→new +
# date) and update the snapshot. The frontend shows a "restated on DATE"
# marker whenever a compare base overlaps a restated month.

_RESTATE_REL_TOL = 0.001   # 0.1% relative drift on money
_RESTATE_MONTHS_BACK = 24


def _ensure_restatement_tables(conn):
    with conn.cursor() as cur:
        cur.execute("""
            CREATE TABLE IF NOT EXISTS kpi_month_snapshots (
                month        date PRIMARY KEY,
                total_sales  numeric NOT NULL,
                net_sales    numeric NOT NULL,
                units        bigint  NOT NULL,
                orders       bigint  NOT NULL,
                captured_at  timestamptz NOT NULL DEFAULT now()
            )""")
        cur.execute("""
            CREATE TABLE IF NOT EXISTS kpi_restatements (
                id            serial PRIMARY KEY,
                month         date NOT NULL,
                restated_on   date NOT NULL,
                old_total_sales numeric, new_total_sales numeric,
                old_net_sales   numeric, new_net_sales   numeric,
                old_units       bigint,  new_units       bigint,
                old_orders      bigint,  new_orders      bigint,
                created_at    timestamptz NOT NULL DEFAULT now(),
                UNIQUE (month, restated_on)
            )""")
    conn.commit()


@_deferred_startup
def _apply_product_master_overrides_boot():
    # WS8 T810 — durable product-master corrections (Safari brand, Soko
    # earrings/Maxi-skirt subcategory fixes). Idempotent; also runs at the end
    # of transform_all_products_clean.py. Boot application means prod heals on
    # the next publish without a rebuild.
    try:
        from product_master_overrides import apply_overrides
        conn = get_conn()
        try:
            n = apply_overrides(conn, log)
            conn.commit()
            if n:
                log.info("Product-master overrides: %d rows corrected", n)
        finally:
            conn.close()
    except Exception as e:
        log.error("Product-master override boot apply failed: %s", e)


@_deferred_startup
def _init_restatement_tables():
    try:
        conn = get_conn()
        try:
            _ensure_restatement_tables(conn)
        finally:
            conn.close()
    except Exception as e:
        log.error("Restatement table init failed: %s", e)


def _restatement_month_figures():
    """Canonical per-month headline figures for CLOSED months (same formulas
    and BASE_FILTERS as /api/kpis and /api/analytics/kpi-trend, all countries
    and channels), limited to the trailing window."""
    return run_query("""
        SELECT date_trunc('month', s.sale_date::date)::date AS month,
            ROUND(SUM(CASE WHEN s.sale_kind IN ('sale','order') THEN (s.total_sales_kes::numeric - COALESCE(s.discounts_kes, 0)::numeric) ELSE 0 END)
                - SUM(CASE WHEN s.sale_kind = 'return' THEN s.returns_kes::numeric ELSE 0 END), 0) AS total_sales,
            ROUND(""" + NET_SALES_CANON + """, 0) AS net_sales,
            SUM(CASE WHEN s.sale_kind IN ('sale','order') THEN s.ordered_item_quantity ELSE 0 END) AS units,
            COUNT(DISTINCT CASE WHEN s.sale_kind IN ('sale','order') THEN s.order_id END) AS orders
        FROM all_sales s
        WHERE """ + BASE_FILTERS + """
          AND s.sale_date::date >= date_trunc('month', CURRENT_DATE) - INTERVAL '""" + str(_RESTATE_MONTHS_BACK) + """ months'
          AND s.sale_date::date < date_trunc('month', CURRENT_DATE)
        GROUP BY 1 ORDER BY 1
    """)


def _restatement_drifted(old, new):
    """True when a closed month's figures moved beyond tolerance."""
    try:
        o, n = float(old["total_sales"] or 0), float(new["total_sales"] or 0)
        if abs(n - o) > max(abs(o) * _RESTATE_REL_TOL, 1000):
            return True
        o, n = float(old["net_sales"] or 0), float(new["net_sales"] or 0)
        if abs(n - o) > max(abs(o) * _RESTATE_REL_TOL, 1000):
            return True
        if int(old["units"] or 0) != int(new["units"] or 0):
            return True
        if int(old["orders"] or 0) != int(new["orders"] or 0):
            return True
    except (TypeError, ValueError, KeyError):
        return True
    return False


def _restatement_check_impl():
    """Idempotent: first run seeds snapshots (no restatement rows); later runs
    record a restatement only when a closed month drifted from its snapshot,
    then re-baseline the snapshot. Safe to call any number of times a day
    (a second same-day drift updates the same (month, restated_on) row)."""
    current = _restatement_month_figures()
    conn = get_conn()
    try:
        _ensure_restatement_tables(conn)
        seeded = restated = unchanged = 0
        with conn.cursor() as cur:
            cur.execute("SELECT month, total_sales, net_sales, units, orders FROM kpi_month_snapshots")
            snaps = {r[0]: {"total_sales": r[1], "net_sales": r[2], "units": r[3], "orders": r[4]}
                     for r in cur.fetchall()}
            for row in current:
                m = row["month"]
                snap = snaps.get(m)
                if snap is None:
                    cur.execute(
                        "INSERT INTO kpi_month_snapshots (month, total_sales, net_sales, units, orders) "
                        "VALUES (%s,%s,%s,%s,%s) ON CONFLICT (month) DO NOTHING",
                        (m, row["total_sales"], row["net_sales"], row["units"], row["orders"]))
                    seeded += 1
                elif _restatement_drifted(snap, row):
                    cur.execute("""
                        INSERT INTO kpi_restatements
                            (month, restated_on, old_total_sales, new_total_sales,
                             old_net_sales, new_net_sales, old_units, new_units,
                             old_orders, new_orders)
                        VALUES (%s, CURRENT_DATE, %s,%s,%s,%s,%s,%s,%s,%s)
                        ON CONFLICT (month, restated_on) DO UPDATE SET
                            new_total_sales = EXCLUDED.new_total_sales,
                            new_net_sales   = EXCLUDED.new_net_sales,
                            new_units       = EXCLUDED.new_units,
                            new_orders      = EXCLUDED.new_orders
                    """, (m, snap["total_sales"], row["total_sales"],
                          snap["net_sales"], row["net_sales"],
                          snap["units"], row["units"],
                          snap["orders"], row["orders"]))
                    cur.execute(
                        "UPDATE kpi_month_snapshots SET total_sales=%s, net_sales=%s, "
                        "units=%s, orders=%s, captured_at=now() WHERE month=%s",
                        (row["total_sales"], row["net_sales"], row["units"], row["orders"], m))
                    restated += 1
                else:
                    unchanged += 1
        conn.commit()
        return {"ok": True, "months_checked": len(current), "seeded": seeded,
                "restated": restated, "unchanged": unchanged}
    finally:
        conn.close()


@app.post("/api/internal/restatement-check")
def internal_restatement_check(request: Request):
    # Dual-auth: the nightly sync loop calls with X-Internal-Token; an admin
    # session can also trigger it manually.
    _sec = os.environ.get("SESSION_SECRET") or ""
    _tok = request.headers.get("x-internal-token") or ""
    if not (_sec and _tok and hmac.compare_digest(_tok, _sec)):
        u = getattr(request.state, "user", None)
        if not u or u.get("role") != "admin":
            raise HTTPException(status_code=403, detail="admin only")
    return _restatement_check_impl()


@app.get("/api/analytics/restatements")
def analytics_restatements(
    date_from: str = Query(default=None),
    date_to:   str = Query(default=None),
    months:    int = Query(default=13),
):
    """Restatement log. With date_from/date_to, returns restatements whose MONTH
    overlaps the window (used by Overview/Trend to badge affected bases);
    otherwise the trailing `months` months of log entries."""
    conn = get_conn()
    try:
        _ensure_restatement_tables(conn)
        with conn.cursor() as cur:
            if date_from and date_to:
                cur.execute("""
                    SELECT month, restated_on, old_total_sales, new_total_sales,
                           old_net_sales, new_net_sales, old_units, new_units,
                           old_orders, new_orders
                    FROM kpi_restatements
                    WHERE month >= date_trunc('month', %s::date)
                      AND month <= date_trunc('month', %s::date)
                    ORDER BY month, restated_on
                """, (date_from, date_to))
            else:
                cur.execute("""
                    SELECT month, restated_on, old_total_sales, new_total_sales,
                           old_net_sales, new_net_sales, old_units, new_units,
                           old_orders, new_orders
                    FROM kpi_restatements
                    WHERE month >= date_trunc('month', CURRENT_DATE) - make_interval(months => %s)
                    ORDER BY month, restated_on
                """, (months,))
            cols = [d[0] for d in cur.description]
            return [dict(zip(cols, (str(v) if hasattr(v, "isoformat") else v for v in r)))
                    for r in cur.fetchall()]
    finally:
        conn.close()


@app.get("/api/analytics/kpi-trend")
def get_kpi_trend(
    date_from: str = Query(default=str(date.today().replace(day=1))),
    date_to:   str = Query(default=str(date.today())),
    country:   str = Query(default=None),
    bucket:    str = Query(default="day"),
):
    bucket = bucket if bucket in ("day", "week", "month", "quarter") else "day"
    where = build_filters(date_from, date_to, country)
    rows = run_query("""
        SELECT
            date_trunc('""" + bucket + """', s.sale_date::date)::date AS bucket_date,
            ROUND(SUM(CASE WHEN s.sale_kind IN ('sale','order') THEN s.total_sales_kes::numeric ELSE 0 END) - SUM(CASE WHEN s.sale_kind IN ('sale','order') THEN s.discounts_kes::numeric ELSE 0 END) - SUM(CASE WHEN s.sale_kind = 'return' THEN s.returns_kes::numeric ELSE 0 END), 0) AS total_sales,
            ROUND(""" + NET_SALES_CANON + """, 0) AS net_sales,
            SUM(CASE WHEN s.sale_kind IN ('sale','order') THEN s.ordered_item_quantity ELSE 0 END) AS units_sold,
            COUNT(DISTINCT CASE WHEN s.sale_kind IN ('sale','order') THEN s.order_id END) AS orders,
            ROUND((SUM(CASE WHEN s.sale_kind IN ('sale','order') THEN (s.total_sales_kes::numeric - COALESCE(s.discounts_kes, 0)::numeric) ELSE 0 END) - SUM(CASE WHEN s.sale_kind = 'return' THEN s.returns_kes::numeric ELSE 0 END)) / NULLIF(COUNT(DISTINCT CASE WHEN s.sale_kind IN ('sale','order') THEN s.order_id END), 0), 0) AS avg_basket_size,
            ROUND(SUM(CASE WHEN s.sale_kind IN ('sale','order') THEN s.discounts_kes::numeric ELSE 0 END), 0) AS discount,
            ROUND(SUM(CASE WHEN s.sale_kind = 'return' THEN s.returns_kes::numeric ELSE 0 END), 0) AS returns
        FROM all_sales s
        WHERE """ + where + """
        GROUP BY 1
        ORDER BY 1
    """, date_to=date_to)
    # run_query returns CACHED row dicts — never mutate them in place (a pop()
    # here made the second call within the cache TTL 500 with KeyError).
    out = []
    for r in rows:
        r = dict(r)
        d = r.pop("bucket_date")
        r["date"] = str(d)
        r["label"] = _fmt_bucket_label(d, bucket)
        out.append(r)
    return out

# ── Trend Analysis ────────────────────────────────────────────────────────────
# A dedicated, richer time-series used by the Trend Analysis page. Unlike
# /api/analytics/kpi-trend it (a) supports a "year" bucket, (b) can scope to a
# single store (pos_location_name), and (c) folds in FOOTFALL and CONVERSION by
# joining the footfall sensor table per bucket. Metric definitions deliberately
# MIRROR /api/kpis so a trend ties out to the Overview KPI cards:
#   total_sales = net of returns; net_sales = canonical (total − discounts − returns);
#   units = canonical GROSS ordered_item_quantity on sale/order rows (same as
#   /api/kpis total_units — net_quantity is velocity-only, never a headline);
#   ABV = total_sales / orders; ASP = total_sales / ordered_item_quantity.
@app.get("/api/analytics/trend-series")
def get_trend_series(
    date_from: str = Query(default=str(date.today().replace(month=1, day=1))),
    date_to:   str = Query(default=str(date.today())),
    country:   str = Query(default=None),
    store:     str = Query(default=None),
    bucket:    str = Query(default="month"),
):
    bucket = bucket if bucket in ("day", "week", "month", "quarter", "year") else "month"
    # `store` is a pos_location_name; reuse build_filters' channel arg which
    # filters s.pos_location_name. Absent => overall (all stores).

# ── Partner Brands Report ──────────────────────────────────────────────────────
# Dedicated sales drill-down for three external partner brands identified by
# product_title patterns:
#   Soko    → ILIKE '%soko%'
#   TIE     → ILIKE '%this is ess%'  (This is Ess)
#   Ythera  → ILIKE '%ythera%'
# Returns one row per (store × SKU) with price, discount, returns, units sold
# and canonical net sales (ex-VAT, after discounts and returns).

@app.get("/api/partner-brands")
def partner_brands_report(
    date_from: str = Query(default=str(date.today() - timedelta(days=30))),
    date_to:   str = Query(default=str(date.today())),
    country:   str = Query(default=""),
    locations: str = Query(default=""),
):
    try:
        df = date.fromisoformat(date_from)
        dt = date.fromisoformat(date_to)
    except Exception:
        df = date.today() - timedelta(days=30)
        dt = date.today()
    country_f = ("AND s.country IN (" + csv_to_sql(country)   + ")") if country   else ""
    loc_f     = ("AND s.pos_location_name IN (" + csv_to_sql(locations) + ")") if locations else ""
    rows = run_query("""
        SELECT
            s.pos_location_name                                          AS pos_location,
            CASE
                WHEN LOWER(s.product_title) LIKE '%soko%'               THEN 'Soko'
                WHEN LOWER(s.product_title) LIKE '%this is ess%'        THEN 'TIE'
                WHEN LOWER(s.product_title) LIKE '%ythera%'             THEN 'Ythera'
            END                                                          AS vendor,
            COALESCE(NULLIF(p.product_type, ''), '')                    AS subcategory,
            COALESCE(NULLIF(p.product_name, ''), s.product_title, '')   AS product_title,
            COALESCE(NULLIF(s.variant_sku,  ''), '')                    AS sku,
            ROUND(
                SUM(CASE WHEN s.sale_kind IN ('sale','order')
                         THEN s.total_sales_kes::numeric ELSE 0 END)
                / NULLIF(SUM(CASE WHEN s.sale_kind IN ('sale','order')
                                  THEN COALESCE(s.ordered_item_quantity, 0) ELSE 0 END), 0)
            , 0)                                                         AS price,
            ROUND(SUM(COALESCE(s.discounts_kes::numeric, 0)), 0)        AS discount,
            -ROUND(SUM(CASE WHEN s.sale_kind = 'return'
                          THEN COALESCE(s.returns_kes::numeric, 0) ELSE 0 END), 0) AS returns,
            SUM(CASE WHEN s.sale_kind IN ('sale','order')
                     THEN COALESCE(s.ordered_item_quantity, 0) ELSE 0 END) AS units_sold,
            ROUND(COALESCE(""" + NET_SALES_CANON + """, 0), 0)          AS net_sales
        FROM all_sales s
        LEFT JOIN all_products_clean p ON s.variant_sku = p.sku
        WHERE s.sale_date::date BETWEEN '""" + str(df) + """' AND '""" + str(dt) + """'
          AND (
              LOWER(s.product_title) LIKE '%soko%'
              OR LOWER(s.product_title) LIKE '%this is ess%'
              OR LOWER(s.product_title) LIKE '%ythera%'
          )
          AND """ + BASE_FILTERS + country_f + """
          """ + loc_f + """
        GROUP BY 1, 2, 3, 4, 5
        ORDER BY vendor, net_sales DESC NULLS LAST
    """, date_to=dt)
    return {"rows": rows, "date_from": str(df), "date_to": str(dt)}

# (end of partner-brands endpoint; the retail-desk trend endpoint continues below)
    where = build_filters(date_from, date_to, country, store)
    sales_rows = run_query("""
        SELECT
            date_trunc('""" + bucket + """', s.sale_date::date)::date AS bucket_date,
            ROUND(SUM(CASE WHEN s.sale_kind IN ('sale','order') THEN (s.total_sales_kes::numeric - COALESCE(s.discounts_kes, 0)::numeric) ELSE 0 END)
                - SUM(CASE WHEN s.sale_kind = 'return' THEN s.returns_kes::numeric ELSE 0 END), 0) AS total_sales,
            ROUND(""" + NET_SALES_CANON + """, 0) AS net_sales,
            SUM(CASE WHEN s.sale_kind IN ('sale','order') THEN s.ordered_item_quantity ELSE 0 END) AS units_sold,
            COUNT(DISTINCT CASE WHEN s.sale_kind IN ('sale','order') THEN s.order_id END) AS orders,
            ROUND((SUM(CASE WHEN s.sale_kind IN ('sale','order') THEN (s.total_sales_kes::numeric - COALESCE(s.discounts_kes, 0)::numeric) ELSE 0 END)
                - SUM(CASE WHEN s.sale_kind = 'return' THEN s.returns_kes::numeric ELSE 0 END))
                / NULLIF(COUNT(DISTINCT CASE WHEN s.sale_kind IN ('sale','order') THEN s.order_id END), 0), 0) AS avg_basket_size,
            ROUND((SUM(CASE WHEN s.sale_kind IN ('sale','order') THEN (s.total_sales_kes::numeric - COALESCE(s.discounts_kes, 0)::numeric) ELSE 0 END)
                - SUM(CASE WHEN s.sale_kind = 'return' THEN s.returns_kes::numeric ELSE 0 END))
                / NULLIF(SUM(CASE WHEN s.sale_kind IN ('sale','order') THEN s.ordered_item_quantity ELSE 0 END), 0), 0) AS avg_selling_price
        FROM all_sales s
        WHERE """ + where + """
        GROUP BY 1
        ORDER BY 1
    """, date_to=date_to)

    # Footfall per bucket from the sensor table. Footfall has no country column,
    # so a country filter cannot be applied here; when a single store is chosen
    # we scope footfall to that store via the canonical name (post-rename safe).
    ff_where = "f.time BETWEEN '" + date_from + "' AND '" + date_to + "'"
    if store:
        ff_where += " AND " + ff_canon_sql() + " IN (" + csv_to_sql(store) + ")"
    ff_rows = run_query("""
        SELECT date_trunc('""" + bucket + """', f.time::date)::date AS bucket_date,
            SUM(f.a01_footfall_in) AS footfall
        FROM footfall f
        WHERE """ + ff_where + """
        GROUP BY 1
    """, date_to=date_to)
    ff_by_bucket = {str(r["bucket_date"]): (r["footfall"] or 0) for r in ff_rows}

    out = []
    for r in sales_rows:
        r = dict(r)  # run_query rows are CACHED — never mutate in place
        d = r.pop("bucket_date")
        key = str(d)
        ff = ff_by_bucket.pop(key, 0) or 0
        orders = r.get("orders") or 0
        r["date"] = key
        r["label"] = _fmt_bucket_label(d, bucket)
        r["footfall"] = int(ff)
        r["conversion_rate"] = (round(orders * 100.0 / ff, 2) if ff else None)
        out.append(r)
    # Buckets that have footfall but no sales rows (rare — e.g. a store with a
    # sensor but no qualifying sales in the window). Surface them so the
    # footfall/conversion trend isn't silently truncated.
    for key, ff in ff_by_bucket.items():
        if not ff:
            continue
        d = date.fromisoformat(key)
        out.append({
            "date": key, "label": _fmt_bucket_label(d, bucket),
            "total_sales": 0, "net_sales": 0, "units_sold": 0, "orders": 0,
            "avg_basket_size": 0, "avg_selling_price": 0,
            "footfall": int(ff), "conversion_rate": 0.0,
        })
    out.sort(key=lambda x: x["date"])
    return out


def _trend_ai_core(body):
    """Generate a short, grounded narrative for a single KPI trend. The client
    sends the metric, its unit, the granularity, the scope label, and the
    plotted points; we compute deterministic summary stats and ask the LLM to
    describe what the trend says (direction, momentum, peaks/troughs, a
    pointer) in plain business English. Output is plain text, never JSON."""
    metric_label = str(body.get("metric_label") or "the metric").strip()[:80]
    unit = str(body.get("unit") or "").strip().lower()  # "kes" | "count" | "pct"
    bucket = str(body.get("bucket") or "period").strip()[:16]
    scope_label = str(body.get("scope_label") or "overall").strip()[:80]
    points = body.get("points") or []
    series = []
    for p in points:
        try:
            v = p.get("value")
            if v is None:
                continue
            series.append((str(p.get("label") or "")[:24], float(v)))
        except (TypeError, ValueError, AttributeError):
            continue
    if len(series) < 2:
        return {"available": False, "reason": "not_enough_points"}

    vals = [v for _, v in series]
    first_lbl, first_v = series[0]
    last_lbl, last_v = series[-1]
    max_lbl, max_v = max(series, key=lambda s: s[1])
    min_lbl, min_v = min(series, key=lambda s: s[1])
    avg_v = sum(vals) / len(vals)
    pct_change = ((last_v - first_v) / abs(first_v) * 100) if first_v else None

    def _fmt(v):
        if unit == "kes":
            return "KES %s" % format(round(v), ",")
        if unit == "pct":
            return "%.1f%%" % v
        return format(round(v), ",")

    direction = "flat"
    if pct_change is not None:
        if pct_change > 3:
            direction = "rising"
        elif pct_change < -3:
            direction = "declining"
    facts = (
        "Metric: %s. Granularity: per %s. Scope: %s.\n"
        "Points (%d): %s.\n"
        "First (%s): %s. Last (%s): %s. Overall change: %s.\n"
        "Peak (%s): %s. Trough (%s): %s. Average: %s. Direction: %s."
    ) % (
        metric_label, bucket, scope_label, len(series),
        ", ".join("%s=%s" % (lbl, _fmt(v)) for lbl, v in series[:40]),
        first_lbl, _fmt(first_v), last_lbl, _fmt(last_v),
        ("%+.1f%%" % pct_change if pct_change is not None else "n/a"),
        max_lbl, _fmt(max_v), min_lbl, _fmt(min_v), _fmt(avg_v), direction,
    )
    sys = (
        "You are a retail BI analyst for Vivo Fashion Group, a multi-brand "
        "fashion retailer in East Africa (Kenya/Uganda/Rwanda + Online). All "
        "money is in Kenyan Shillings (KES). You are given a single KPI's trend "
        "over time with summary statistics. Write a concise, decision-useful "
        "narrative (3-5 sentences, <=120 words) describing what the trend "
        "shows: overall direction and momentum, notable peaks/troughs or "
        "turning points, and one practical implication or thing to watch. Use "
        "the exact figures provided; do not invent numbers. Plain prose, no "
        "markdown headers, no bullet lists, no emojis."
    )
    narrative = _chat_llm(
        [{"role": "system", "content": sys},
         {"role": "user", "content": facts}],
        max_tokens=320,
    )
    narrative = (narrative or "").strip()
    if not narrative:
        return {"available": False, "reason": "empty"}
    return {
        "available": True,
        "narrative": narrative,
        "direction": direction,
        "pct_change": (round(pct_change, 1) if pct_change is not None else None),
    }


@app.post("/api/analytics/trend-ai")
async def trend_ai_post(request: Request):
    """AI narrative for a Trend Analysis chart. The AI key is server-only, so
    the client posts the plotted series + metadata and we run the LLM here.
    Always returns gracefully — a narrative is an enhancement, never a blocker."""
    try:
        body = await request.json()
    except Exception:
        body = {}
    if not (os.environ.get("AI_INTEGRATIONS_OPENAI_BASE_URL")
            and os.environ.get("AI_INTEGRATIONS_OPENAI_API_KEY")):
        return {"available": False, "reason": "ai_not_configured"}
    try:
        return await _chat_run_in_threadpool(_trend_ai_core, body or {})
    except Exception:
        return {"available": False, "reason": "ai_error"}

