# Warehouse bins (barcode -> bin) mirrored from a daily-updated Google Sheet; the
# Replenishment + IBT endpoints LEFT JOIN this by barcode. Idempotent table is
# created on boot (safe on the separate prod DB); refresh is lazy + best-effort so
# an unset sheet id / missing connector simply leaves the prior bins in place.
import warehouse_bins


@_deferred_startup
def _init_warehouse_bins():
    try:
        pool = _get_pool()
        conn = pool.getconn()
        try:
            warehouse_bins.ensure_table(conn)
        finally:
            pool.putconn(conn)
        # Force ONE full re-sync of the bin map on boot (background, best-effort).
        # Prod is a SEPARATE DB whose bins may have been written by older, capped
        # code; without this the hourly staleness gate would keep serving the
        # stale rows for up to an hour after a deploy. force=True re-fetches the
        # whole sheet now so a freshly deployed prod is immediately correct.
        log.info("warehouse_bins: triggering one-shot forced refresh on startup")
        _warehouse_bins_refresh(force=True)
    except Exception as e:
        log.error("warehouse_bins table init failed: %s", e)


@app.get("/api/inventory/shopping-bags")
def inventory_shopping_bags():
    """Shopping bag stock per store, broken down by size and brand."""
    rows = _users_exec("""
        SELECT pos_location_name AS store,
               COALESCE(SUM(qty_available) FILTER (WHERE sku LIKE 'VB001S%'), 0) AS vivo_small,
               COALESCE(SUM(qty_available) FILTER (WHERE sku LIKE 'VB001M%'), 0) AS vivo_medium,
               COALESCE(SUM(qty_available) FILTER (WHERE sku LIKE 'VB001L%'), 0) AS vivo_large,
               COALESCE(SUM(qty_available) FILTER (WHERE brand = 'Zoya'), 0) AS zoya,
               COALESCE(SUM(qty_available) FILTER (WHERE brand = 'Safari'), 0) AS safari,
               ROUND(SUM(qty_available)) AS total
        FROM shopping_bags
        WHERE pos_location_name NOT IN (
            'Shopping Bags/Stock','WND/Stock','WHREC/Stock','RCALL/Stock',
            'Wash/Stock','Studi/Stock','Repai/Stock','Defects/Stock',
            'SALE/Stock','HWHFN/Stock','CUTT/Stock','PDDEV/Stock',
            'Staff purchases','Warehouse Finished Goods')
        GROUP BY pos_location_name
        ORDER BY total DESC
    """, fetch=True)
    warehouse = _users_exec("""
        SELECT ROUND(SUM(qty_available) FILTER (WHERE sku LIKE 'VB001S%')) AS vivo_small,
               ROUND(SUM(qty_available) FILTER (WHERE sku LIKE 'VB001M%')) AS vivo_medium,
               ROUND(SUM(qty_available) FILTER (WHERE sku LIKE 'VB001L%')) AS vivo_large,
               ROUND(SUM(qty_available) FILTER (WHERE brand = 'Zoya')) AS zoya,
               ROUND(SUM(qty_available) FILTER (WHERE brand = 'Safari')) AS safari,
               ROUND(SUM(qty_available)) AS total
        FROM shopping_bags
        WHERE location_code = 'Shopping Bags'
           OR pos_location_name = 'Shopping Bags/Stock'
    """, fetch=True)
    return {
        "stores": rows,
        "warehouse": warehouse[0] if warehouse else {},
        "grand_total": sum(int(r.get("total") or 0) for r in rows)
    }


from fastapi.staticfiles import StaticFiles
import pathlib

# Standalone Fabric BI dashboard, served full-page at /fabric. Registered HERE,
# OUTSIDE the `if build_dir.exists()` guard below, because `dashboard/build` is
# gitignored and never ships to production. Previously the only /fabric handler
# lived inside that guard (the SPA catch-all), so in prod the route either did
# not exist or fell through to FileResponse on a missing index.html — raising
# during response streaming and surfacing as a 500. The page source
# (fabric_dashboard_live.html) is git-tracked at the repo root, so serve it
# directly and 404 cleanly if it is somehow absent (never fall through).
def _serve_fabric_page():
    from fastapi.responses import HTMLResponse
    here = pathlib.Path(__file__).parent
    fabric = here / "fabric_dashboard_live.html"
    if not fabric.exists():
        fabric = here / "dashboard" / "build" / "fabric.html"
    if not fabric.exists():
        return JSONResponse({"detail": "Fabric dashboard not available"}, status_code=404)
    # Return an in-memory HTMLResponse, NOT a FileResponse. Under GZipMiddleware a
    # FileResponse can emit the ASGI `http.response.pathsend` zero-copy extension,
    # which GZipMiddleware does not understand and raises on mid-stream — surfacing
    # as a 500 ONLY on the deployed server (whose uvicorn negotiates pathsend; the
    # dev server did not, so /fabric was 200 in dev but 500 in prod). A plain
    # in-memory body compresses cleanly on every server/uvicorn version.
    html = fabric.read_text(encoding="utf-8")
    resp = HTMLResponse(content=html)
    resp.headers["Cache-Control"] = "no-cache, no-store, must-revalidate"
    resp.headers["Pragma"] = "no-cache"
    resp.headers["Expires"] = "0"
    return resp


@app.get("/fabric")
async def serve_fabric_page():
    return _serve_fabric_page()


@app.get("/fabric/{sub_path:path}")
async def serve_fabric_subpath(sub_path: str):
    return _serve_fabric_page()


# Standalone Odoo Reconciliation cockpit, served full-page at /reconcile — the
# same pattern as /fabric above (git-tracked HTML at the repo root, registered
# OUTSIDE the build_dir guard so it exists in production, in-memory HTMLResponse
# so GZipMiddleware never hits the pathsend extension). Auth: the page itself
# signs in via /api/auth/* (Bearer vivo_token shared with the other apps +
# cookie fallback); /api/recon/* is gated to admin/leadership in clerk_auth_gate.
def _serve_recon_page():
    from fastapi.responses import HTMLResponse
    page = pathlib.Path(__file__).parent / "recon_dashboard.html"
    if not page.exists():
        return JSONResponse({"detail": "Reconciliation cockpit not available"}, status_code=404)
    resp = HTMLResponse(content=page.read_text(encoding="utf-8"))
    resp.headers["Cache-Control"] = "no-cache, no-store, must-revalidate"
    resp.headers["Pragma"] = "no-cache"
    resp.headers["Expires"] = "0"
    return resp


@app.get("/reconcile")
async def serve_recon_page():
    return _serve_recon_page()


@app.get("/reconcile/{sub_path:path}")
async def serve_recon_subpath(sub_path: str):
    return _serve_recon_page()


# ── Loyalty PWA — full-page iframe redirect to loyalty.vivofashionbrands.com ──
# No separate process or port — the API server owns /loyalty-app/* directly.
# The page embeds the live external app in a full-screen iframe; a meta-refresh
# fallback fires if the browser blocks the iframe (X-Frame-Options).
_LOYALTY_IFRAME_HTML = """<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <meta http-equiv="refresh" content="3; url=https://loyalty.vivofashionbrands.com">
  <title>Vivo Loyalty</title>
  <style>
    * { margin: 0; padding: 0; box-sizing: border-box; }
    html, body { width: 100%; height: 100%; overflow: hidden; }
    iframe { display: block; width: 100%; height: 100%; border: none; }
    .fallback { display: none; position: fixed; inset: 0; align-items: center;
      justify-content: center; font-family: sans-serif; font-size: 14px;
      color: #555; background: #faf7f4; text-align: center; }
    iframe.blocked + .fallback { display: flex; flex-direction: column; gap: 8px; }
  </style>
</head>
<body>
  <iframe src="https://loyalty.vivofashionbrands.com"
          title="Vivo Loyalty"
          allow="forms"
          onerror="this.classList.add('blocked')"></iframe>
  <div class="fallback">
    <p>Opening Vivo Loyalty&hellip;</p>
    <a href="https://loyalty.vivofashionbrands.com" target="_blank"
       style="color:#1a5c38">loyalty.vivofashionbrands.com</a>
  </div>
</body>
</html>"""


def _serve_loyalty_page():
    from fastapi.responses import HTMLResponse
    resp = HTMLResponse(content=_LOYALTY_IFRAME_HTML)
    resp.headers["Cache-Control"] = "no-cache, no-store, must-revalidate"
    return resp


